    protected override void OnStartup(StartupEventArgs e)
    {
        SQLitePCL.Batteries_V2.Init();
        bool automationInvocation = IsAutomationInvocation(e.Args);
        AibosOperationLog.Enabled = !automationInvocation;
        if (!automationInvocation)
        {
            try
            {
                _singleInstanceCoordinator =
                    SingleInstanceCoordinator.CreateForCurrentUser();
                if (!_singleInstanceCoordinator.IsPrimary)
                {
                    _ = _singleInstanceCoordinator.SignalPrimary();
                    _singleInstanceCoordinator.Dispose();
                    _singleInstanceCoordinator = null;
                    Environment.ExitCode = 0;
                    base.OnStartup(e);
                    Shutdown(0);
                    return;
                }
            }
            catch (Exception ex) when (ex is
                IOException or
                UnauthorizedAccessException or
                System.Security.SecurityException or
                InvalidOperationException)
            {
                MessageBox.Show(
                    "Aibos Image could not safely establish its single-instance guard. "
                        + "No additional window was opened. Restart Windows or close the existing Aibos Image process, then try again.",
                    "Aibos Image startup blocked",
                    MessageBoxButton.OK,
                    MessageBoxImage.Error);
                Environment.ExitCode = 1;
                base.OnStartup(e);
                Shutdown(1);
                return;
            }
        }
        int parityContractSmokeIdx = Array.IndexOf(e.Args, "--parity-contract-smoke");
        int h25EnhancementCompanionSmokeIdx = Array.IndexOf(e.Args, "--h25-enhancement-companion-smoke");
        int videoV2ReaderSmokeIdx = Array.IndexOf(e.Args, "--video-v2-reader-smoke");
        int sharedRootLocatorSmokeIdx = Array.IndexOf(e.Args, "--shared-root-locator-smoke");
        int sharedRootActivationSmokeIdx = Array.IndexOf(e.Args, "--shared-root-activation-smoke");
        int sharedRootLeaseHolderSmokeIdx = Array.IndexOf(e.Args, "--shared-root-lease-holder-smoke");
        int sharedRootLeaseWriterSmokeIdx = Array.IndexOf(e.Args, "--shared-root-lease-writer-smoke");
        int externalOpenTargetSmokeIdx = Array.IndexOf(
            e.Args,
            "--external-open-target-smoke");
        int photorealFavoriteRestoreIdx = Array.IndexOf(
            e.Args,
            "--restore-photoreal-favorites");
        if (externalOpenTargetSmokeIdx >= 0)
        {
            base.OnStartup(e);
            int exitCode = ExternalImageOpenTargetSmokeRunner.Run();
            Environment.ExitCode = exitCode;
            Shutdown(exitCode);
            return;
        }
        if (videoV2ReaderSmokeIdx >= 0
            && videoV2ReaderSmokeIdx + 1 < e.Args.Length)
        {
            try
            {
                ConfigureVideoV2ReaderSmokeStorage(
                    e.Args[videoV2ReaderSmokeIdx + 1]);
            }
            catch (ArgumentException ex)
            {
                Trace.TraceError(ex.Message);
                Environment.ExitCode = 1;
                Shutdown(1);
                return;
            }
        }
        else if (parityContractSmokeIdx < 0
            && h25EnhancementCompanionSmokeIdx < 0
            && sharedRootLocatorSmokeIdx < 0
            && sharedRootActivationSmokeIdx < 0
            && sharedRootLeaseHolderSmokeIdx < 0
            && sharedRootLeaseWriterSmokeIdx < 0
            && photorealFavoriteRestoreIdx < 0
            && IsAutomationInvocation(e.Args))
        {
            try
            {
                ConfigureAutomationStorage(e.Args);
            }
            catch (ArgumentException ex)
            {
                Trace.TraceError(ex.Message);
                Environment.ExitCode = 1;
                Shutdown(1);
                return;
            }
        }

        var startupWatch = Stopwatch.StartNew();
        if (parityContractSmokeIdx < 0
            && h25EnhancementCompanionSmokeIdx < 0
            && videoV2ReaderSmokeIdx < 0
            && sharedRootLocatorSmokeIdx < 0
            && sharedRootActivationSmokeIdx < 0
            && sharedRootLeaseHolderSmokeIdx < 0
            && sharedRootLeaseWriterSmokeIdx < 0
            && photorealFavoriteRestoreIdx < 0)
        {
            SharedDataRootActivationResult activation =
                SharedDataRootActivation.ActivateForCurrentProcess(
                    ResolveLegacySharedDataRootForActivation());
            if (!activation.IsAvailable)
            {
                string errorCode = activation.ErrorCode ?? "shared-root-unavailable";
                Trace.TraceError($"Shared data root activation failed: {errorCode}");
                if (!IsAutomationInvocation(e.Args))
                {
                    MessageBox.Show(
                        $"Aibos Image could not safely resolve its shared data ({errorCode}). "
                            + "No durable state was changed. Repair or remove the invalid shared-root locator, then restart.",
                        "Aibos Image shared data unavailable",
                        MessageBoxButton.OK,
                        MessageBoxImage.Error);
                }

                Environment.ExitCode = 1;
                Shutdown(1);
                return;
            }
        }

        base.OnStartup(e);
        if (photorealFavoriteRestoreIdx >= 0)
        {
            int exitCode = PhotorealFavoriteHistoryRestorer.Run(e.Args);
            Environment.ExitCode = exitCode;
            Shutdown(exitCode);
            return;
        }
        UiLanguageResources.Apply(UiLanguageResources.English);
        InitializeAccessibilityPalette(e.Args.Contains("--force-high-contrast", StringComparer.OrdinalIgnoreCase));

        int singleInstanceSmokeIdx = Array.IndexOf(
            e.Args,
            "--single-instance-coordinator-smoke");
        if (singleInstanceSmokeIdx >= 0
            && singleInstanceSmokeIdx + 1 < e.Args.Length)
        {
            int exitCode = SingleInstanceCoordinatorSmokeRunner.Run(
                e.Args[singleInstanceSmokeIdx + 1]);
            Environment.ExitCode = exitCode;
            Shutdown(exitCode);
            return;
        }

        if (videoV2ReaderSmokeIdx >= 0
            && videoV2ReaderSmokeIdx + 1 < e.Args.Length)
        {
            CaptureVideoV2ReaderSmoke(
                e.Args[videoV2ReaderSmokeIdx + 1],
                e.Args);
            return;
        }

        int i2iReaderSmokeIdx = Array.IndexOf(e.Args, "--i2i-reader-smoke");
        if (i2iReaderSmokeIdx >= 0 && i2iReaderSmokeIdx + 1 < e.Args.Length)
        {
            CaptureI2iReaderSmoke(e.Args[i2iReaderSmokeIdx + 1]);
            return;
