        }

        if (sharedRootLeaseWriterSmokeIdx >= 0
            && sharedRootLeaseWriterSmokeIdx + 1 < e.Args.Length)
        {
            int exitCode = SharedDataRootLeaseSmokeRunner.RunWriter(
                ArgValue(e.Args, "--mode"),
