        int albumStoreSmokeIdx = Array.IndexOf(e.Args, "--album-store-smoke");
        if (albumStoreSmokeIdx >= 0 && albumStoreSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumStoreSmoke(e.Args[albumStoreSmokeIdx + 1], e.Args);
