        }

        int albumConcurrentWriterSmokeIdx = Array.IndexOf(e.Args, "--album-concurrent-writer-smoke");
        if (albumConcurrentWriterSmokeIdx >= 0 && albumConcurrentWriterSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumConcurrentWriterSmoke(e.Args[albumConcurrentWriterSmokeIdx + 1], e.Args);
            return;
        }

        int albumMemberWriterSmokeIdx = Array.IndexOf(e.Args, "--album-member-writer-smoke");
        if (albumMemberWriterSmokeIdx >= 0 && albumMemberWriterSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumMemberWriterSmoke(e.Args[albumMemberWriterSmokeIdx + 1], e.Args);
            return;
        }

        int albumLockHolderSmokeIdx = Array.IndexOf(e.Args, "--album-lock-holder-smoke");
        if (albumLockHolderSmokeIdx >= 0 && albumLockHolderSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumLockHolderSmoke(e.Args[albumLockHolderSmokeIdx + 1], e.Args);
            return;
        }

        int albumUiSmokeIdx = Array.IndexOf(e.Args, "--album-ui-smoke");
        if (albumUiSmokeIdx >= 0 && albumUiSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumUiSmoke(e.Args[albumUiSmokeIdx + 1], e.Args);
            return;
        }

        int albumLibraryHardeningSmokeIdx = Array.IndexOf(e.Args, "--album-library-hardening-smoke");
        if (albumLibraryHardeningSmokeIdx >= 0 && albumLibraryHardeningSmokeIdx + 1 < e.Args.Length)
        {
            CaptureAlbumLibraryHardeningSmoke(e.Args[albumLibraryHardeningSmokeIdx + 1], e.Args);
            return;
        }

        int albumLibraryShotIdx = Array.IndexOf(e.Args, "--album-library-shot");
        if (albumLibraryShotIdx >= 0 && albumLibraryShotIdx + 1 < e.Args.Length)
        {
            CaptureAlbumLibraryShot(e.Args[albumLibraryShotIdx + 1], e.Args);
            return;
        }

        var mainWindow = new MainWindow();
        mainWindow.Show();
        _ = Dispatcher.BeginInvoke(
            mainWindow.ActivateFromSecondaryInstance,
            DispatcherPriority.ApplicationIdle);
        _singleInstanceCoordinator?.StartListening(() =>
            Dispatcher.BeginInvoke(
                mainWindow.ActivateFromSecondaryInstance,
                DispatcherPriority.Send));
        AibosOperationLog.Write(
            "app_start",
            "window_shown",
            startupWatch.ElapsedMilliseconds);
    }

    protected override void OnExit(ExitEventArgs e)
    {
        try
        {
            _singleInstanceCoordinator?.Dispose();
            _singleInstanceCoordinator = null;
            if (_accessibilityPaletteInitialized)
                SystemParameters.StaticPropertyChanged -= SystemParameters_StaticPropertyChanged;
            base.OnExit(e);
        }
        finally
        {
            SharedDataRootActivation.DisposeProcessLease();
        }
    }

    protected override void OnActivated(EventArgs e)
    {
        base.OnActivated(e);
        if (_accessibilityPaletteInitialized)
            ApplyAccessibilityPreferences();
    }

    private void InitializeAccessibilityPalette(bool forceHighContrast)
    {
        if (_accessibilityPaletteInitialized)
            return;

        foreach (string key in ThemeColorResourceKeys)
        {
            if (Resources[key] is not Color color)
                throw new InvalidOperationException($"Theme color resource is missing: {key}");
            _standardColorPalette[key] = color;
        }

        _forceHighContrast = forceHighContrast;
        _accessibilityPaletteInitialized = true;
        SystemParameters.StaticPropertyChanged += SystemParameters_StaticPropertyChanged;
        ApplyAccessibilityPreferences();
    }

    private void SystemParameters_StaticPropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (!string.Equals(e.PropertyName, nameof(SystemParameters.HighContrast), StringComparison.Ordinal)
            && !string.Equals(e.PropertyName, nameof(SystemParameters.ClientAreaAnimation), StringComparison.Ordinal))
        {
            return;
        }
        Dispatcher.BeginInvoke(
            () => ApplyAccessibilityPreferences(),
            DispatcherPriority.Send);
    }

    internal void SetAccessibilityOverrides(bool? reducedMotion, bool? reducedTransparency)
    {
        _reducedMotionOverride = reducedMotion;
        _reducedTransparencyOverride = reducedTransparency;
        ApplyAccessibilityPreferences();
    }

    internal void RefreshAccessibilityPreferencesFromSystem()
        => ApplyAccessibilityPreferences();

    private void ApplyAccessibilityPreferences()
    {
        if (!_accessibilityPaletteInitialized)
            return;

        bool highContrast = _highContrastForSmoke
            ?? (_forceHighContrast || SystemParameters.HighContrast);
        bool reducedMotion = highContrast
            || (_reducedMotionOverride
                ?? _systemReducedMotionForSmoke
                ?? !SystemParameters.ClientAreaAnimation);
        bool reducedTransparency = highContrast
            || (_reducedTransparencyOverride
                ?? _systemReducedTransparencyForSmoke
                ?? SystemPrefersReducedTransparency());
        bool changed = highContrast != _highContrastPaletteApplied
            || reducedMotion != _reducedMotionEnabled
            || reducedTransparency != _reducedTransparencyEnabled;

        _highContrastPaletteApplied = highContrast;
        _reducedMotionEnabled = reducedMotion;
        _reducedTransparencyEnabled = reducedTransparency;

        RestoreStandardPalette();
        if (reducedTransparency && !highContrast)
            ApplyReducedTransparencyPalette();
        if (highContrast)
            ApplySystemHighContrastPalette();

        if (changed)
            AccessibilityPaletteChanged?.Invoke(this, EventArgs.Empty);
    }

    private void RestoreStandardPalette()
    {
        foreach ((string key, Color color) in _standardColorPalette)
            SetThemeColor(key, color);
    }

    private void ApplyReducedTransparencyPalette()
    {
        Color backdrop = CompositeOpaque(
            _standardColorPalette["BgPrimaryColor"],
            Colors.Black);
        foreach ((string key, Color color) in _standardColorPalette)
        {
            if (color.A < byte.MaxValue)
                SetThemeColor(key, CompositeOpaque(color, backdrop));
        }
    }

    private void ApplySystemHighContrastPalette()
    {
        SetThemeColors(SystemColors.ControlColor, ThemeColorResourceKeys);
        SetThemeColors(SystemColors.WindowColor, "BgPrimaryColor");
        SetThemeColors(SystemColors.ControlColor,
            "BgSecondaryColor", "BgTertiaryColor", "BgElevatedColor", "HeaderBgColor",
            "GlassChromeTopColor", "GlassChromeBottomColor",
            "HoverFillColor", "PressedFillColor", "SoftFillColor", "AccentSoftColor", "AccentGlassColor",
            "FavoriteSoftColor", "SuccessSoftColor",
            "PhotorealFavoriteBackgroundColor", "VideoFavoriteBackgroundColor",
            "OverlaySoftColor", "OverlayStrongColor", "DropOverlayColor",
            "ThumbnailCaptionStartColor", "ThumbnailCaptionEndColor", "AiBadgeBackgroundColor");
        SetThemeColors(SystemColors.WindowTextColor,
            "TextPrimaryColor", "TextSecondaryColor", "TextTertiaryColor",
            "FavoriteTextColor", "SuccessColor", "DangerTextColor", "LogoColor",
            "ThumbnailCaptionTextColor", "PhotorealFavoriteTextColor", "VideoFavoriteTextColor");
        SetThemeColors(SystemColors.GrayTextColor, "TextDisabledColor");
        SetThemeColors(SystemColors.HighlightTextColor, "SelectionTextColor");
        SetThemeColors(SystemColors.HotTrackColor,
            "AccentColor", "AccentLightColor", "AccentFillColor", "AccentFillHoverColor", "FavoriteColor",
            "PhotorealFavoriteColor", "VideoFavoriteColor",
            "FavoriteThumbnailStatusBorderColor", "EnhancedThumbnailStatusBorderColor",
            "WarningColor", "DangerColor", "DangerFillColor", "DangerFillHoverColor",
            "SuccessBorderColor", "FavStepColor",
            "CompactFavoriteBackgroundColor");
        SetThemeColors(SystemColors.HighlightColor, "FocusColor");
        SetThemeColors(
            SystemColors.ActiveBorderColor,
            "GlassBorderColor", "DividerSubtleColor", "DividerMediumColor",
            "ScrollThumbColor");
        SetThemeColors(
            SystemColors.WindowTextColor,
            "GlassBorderHoverColor", "BorderStrongColor", "DividerStrongColor",
            "ScrollThumbHoverColor");
    }

    private static Color CompositeOpaque(Color foreground, Color background)
    {
        double alpha = foreground.A / 255d;
        static byte Blend(byte front, byte back, double alphaValue)
            => (byte)Math.Clamp(
                Math.Round((front * alphaValue) + (back * (1 - alphaValue))),
                byte.MinValue,
                byte.MaxValue);
        return Color.FromArgb(
            byte.MaxValue,
            Blend(foreground.R, background.R, alpha),
            Blend(foreground.G, background.G, alpha),
            Blend(foreground.B, background.B, alpha));
    }

    private static bool SystemPrefersReducedTransparency()
    {
        const string personalizePath =
            @"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize";
        try
        {
            using RegistryKey? personalize = Registry.CurrentUser.OpenSubKey(personalizePath);
            object? raw = personalize?.GetValue("EnableTransparency");
            return raw is not null
                && Convert.ToInt32(raw, CultureInfo.InvariantCulture) == 0;
        }
        catch (Exception ex) when (ex is UnauthorizedAccessException
            or System.Security.SecurityException
            or IOException
            or FormatException
            or InvalidCastException
            or OverflowException)
        {
            return false;
        }
    }

    private void ApplyHighContrastPalette(bool enabled)
    {
        _highContrastForSmoke = enabled;
        ApplyAccessibilityPreferences();
    }

    private void SetThemeColors(Color color, params string[] keys)
    {
        foreach (string key in keys)
            SetThemeColor(key, color);
    }

    private void SetThemeColor(string colorKey, Color color)
    {
        Resources[colorKey] = color;
        if (!ThemeBrushResourceByColorKey.TryGetValue(colorKey, out string? brushKey)
            || Resources[brushKey] is not SolidColorBrush brush)
        {
            return;
        }

        if (brush.IsFrozen)
            Resources[brushKey] = new SolidColorBrush(color);
        else
            brush.Color = color;
    }

    private void CaptureHighContrastSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        Dispatcher.InvokeAsync(async () =>
        {
            object result;
            bool succeeded = false;
            MainWindow? window = null;
            bool? previousHighContrastForSmoke = _highContrastForSmoke;
            bool? previousSystemReducedMotionForSmoke = _systemReducedMotionForSmoke;
            bool? previousSystemReducedTransparencyForSmoke = _systemReducedTransparencyForSmoke;
            bool? previousReducedMotionOverride = _reducedMotionOverride;
            bool? previousReducedTransparencyOverride = _reducedTransparencyOverride;
            try
            {
                _systemReducedMotionForSmoke = false;
                _systemReducedTransparencyForSmoke = false;
                _reducedMotionOverride = null;
                _reducedTransparencyOverride = null;
                Dictionary<string, Color> standard = ThemeColorResourceKeys.ToDictionary(
                    static key => key,
                    key => _standardColorPalette[key],
                    StringComparer.Ordinal);
                ApplyHighContrastPalette(true);
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);

                window = HiddenWindow();
                window.Show();
                await window.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);

                bool colorResources = ResourceColor("BgPrimaryColor") == SystemColors.WindowColor
                    && ResourceColor("BgSecondaryColor") == SystemColors.ControlColor
                    && ResourceColor("TextPrimaryColor") == SystemColors.WindowTextColor
                    && ResourceColor("TextDisabledColor") == SystemColors.GrayTextColor
                    && ResourceColor("AccentColor") == SystemColors.HotTrackColor
                    && ResourceColor("FocusColor") == SystemColors.HighlightColor
                    && ResourceColor("GlassBorderColor") == SystemColors.ActiveBorderColor;
                bool liveBrushes = ResourceBrushColor("BgPrimary") == SystemColors.WindowColor
                    && ResourceBrushColor("TextPrimary") == SystemColors.WindowTextColor
                    && ResourceBrushColor("Accent") == SystemColors.HotTrackColor
                    && ResourceBrushColor("Focus") == SystemColors.HighlightColor;
                bool paletteFlag = _highContrastPaletteApplied;
                bool actionAccessibility = window.RightPreviewActionAccessibilityForSmoke;
                bool dialogFocusContracts = window.SettingsFocusTrapConfiguredForSmoke
                    && window.DeleteFocusTrapConfiguredForSmoke
                    && window.ModalFocusTrapConfiguredForSmoke;

                ApplyHighContrastPalette(false);
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.ContextIdle);
                string[] unrestoredColors = standard
                    .Where(pair => ResourceColor(pair.Key) != pair.Value)
                    .Select(static pair => pair.Key)
                    .ToArray();
                bool brushesRestored = ResourceBrushColor("BgPrimary") == standard["BgPrimaryColor"]
                    && ResourceBrushColor("TextPrimary") == standard["TextPrimaryColor"];
                bool restored = unrestoredColors.Length == 0 && brushesRestored && !_highContrastPaletteApplied;
                bool ok = colorResources
                    && liveBrushes
                    && paletteFlag
                    && actionAccessibility
                    && dialogFocusContracts
                    && restored;
                succeeded = ok;
                result = new
                {
                    ok,
                    message = ok
                        ? "system high-contrast palette, live brushes, action accessibility, and focus traps passed"
                        : "high-contrast or keyboard accessibility contract did not match expectations",
                    colorResources,
                    liveBrushes,
                    paletteFlag,
                    actionAccessibility,
                    dialogFocusContracts,
                    restored,
                    brushesRestored,
                    unrestoredColors,
                    restoredBackgroundBrush = ResourceBrushColor("BgPrimary").ToString(),
                    restoredForegroundBrush = ResourceBrushColor("TextPrimary").ToString(),
                    systemHighContrast = SystemParameters.HighContrast,
                    background = ResourceColor("BgPrimaryColor").ToString(),
                    foreground = ResourceColor("TextPrimaryColor").ToString(),
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.Message };
            }
            finally
            {
                window?.Close();
                _highContrastForSmoke = previousHighContrastForSmoke;
                _systemReducedMotionForSmoke = previousSystemReducedMotionForSmoke;
                _systemReducedTransparencyForSmoke = previousSystemReducedTransparencyForSmoke;
                _reducedMotionOverride = previousReducedMotionOverride;
                _reducedTransparencyOverride = previousReducedTransparencyOverride;
                ApplyAccessibilityPreferences();
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            Shutdown(succeeded ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureAccessibilityFallbackSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string root = CreateManagedAutomationRoot();
        string statePath = Path.Combine(root, "state.json");
        string settingsPath = Path.Combine(root, "settings.json");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousSettingsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH");
        bool? previousHighContrastForSmoke = _highContrastForSmoke;
        bool? previousSystemReducedMotionForSmoke = _systemReducedMotionForSmoke;
        bool? previousSystemReducedTransparencyForSmoke = _systemReducedTransparencyForSmoke;
        bool? previousReducedMotionOverride = _reducedMotionOverride;
        bool? previousReducedTransparencyOverride = _reducedTransparencyOverride;
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", settingsPath);
        Directory.CreateDirectory(root);
        File.WriteAllText(
            statePath,
            """
            {
              "Version": 2,
              "futureOwner": { "keep": true }
            }
            """);
        File.WriteAllText(
            settingsPath,
            """
            {
              "version": 1,
              "futureSharedOwner": { "keep": true }
            }
            """);
        string sharedSettingsBefore = FileFingerprint(settingsPath);
        Dictionary<string, Color> standard = ThemeColorResourceKeys.ToDictionary(
            static key => key,
            key => _standardColorPalette[key],
            StringComparer.Ordinal);
        string[] translucentKeys = standard
            .Where(static pair => pair.Value.A < byte.MaxValue)
            .Select(static pair => pair.Key)
            .ToArray();

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var windows = new List<MainWindow>();
        Dispatcher.InvokeAsync(async () =>
        {
            object result;
            bool ok = false;
            try
            {
                _highContrastForSmoke = false;
                _systemReducedMotionForSmoke = true;
                _systemReducedTransparencyForSmoke = true;
                _reducedMotionOverride = null;
                _reducedTransparencyOverride = null;
                ApplyAccessibilityPreferences();

                var window = HiddenWindow();
                windows.Add(window);
                window.Show();
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.ContextIdle);

                bool followsSystem = window.ReducedMotionOverrideForSmoke is null
                    && window.ReducedTransparencyOverrideForSmoke is null
                    && window.ReducedMotionEffectiveForSmoke
                    && window.ReducedTransparencyEffectiveForSmoke
                    && window.ReducedMotionPopupContractForSmoke;

                bool fullOverrideSaved = window.SetAccessibilityPreferencesForSmoke(
                    reducedMotion: false,
                    reducedTransparency: false);
                window.FlushStateForSmoke();
                bool fullOverrideEffective = !window.ReducedMotionEffectiveForSmoke
                    && !window.ReducedTransparencyEffectiveForSmoke
                    && !window.ReducedMotionPopupContractForSmoke
                    && ResourceColor("BgSecondaryColor") == standard["BgSecondaryColor"];

                bool modalOpened = window.SelectIndexForSmoke(0)
                    && window.OpenModalForSmoke();
                bool standardZoomed = modalOpened
                    && window.ModalZoomShortcutForSmoke("plus");
                bool standardMotionActive = standardZoomed
                    && window.ModalTransformAnimationActiveForSmoke;

                bool reduceOverrideSaved = window.SetAccessibilityPreferencesForSmoke(
                    reducedMotion: true,
                    reducedTransparency: true);
                window.FlushStateForSmoke();
                bool activeMotionCanceled = !window.ModalTransformAnimationActiveForSmoke
                    && !window.ModalTransientChromeAnimationActiveForSmoke;
                bool reducedZoomed = window.ModalZoomShortcutForSmoke("plus");
                window.SetModalChromeVisibleForSmoke(false);
                window.RevealModalChromeTransientForSmoke();
                bool reducedMotionInstant = reducedZoomed
                    && !window.ModalTransformAnimationActiveForSmoke
                    && !window.ModalTransientChromeAnimationActiveForSmoke
                    && window.ReducedMotionPopupContractForSmoke;
                string[] nonOpaqueKeys = translucentKeys
                    .Where(key => ResourceColor(key).A != byte.MaxValue)
                    .ToArray();
                bool reducedTransparencyOpaque = nonOpaqueKeys.Length == 0
                    && ResourceBrushColor("BgSecondary").A == byte.MaxValue
                    && ResourceBrushColor("GlassBorder").A == byte.MaxValue;

                using JsonDocument persisted = JsonDocument.Parse(File.ReadAllText(statePath));
                bool localOverridesPersisted = persisted.RootElement.TryGetProperty(
                        "ReducedMotionOverride",
                        out JsonElement motionOverride)
                    && motionOverride.ValueKind == JsonValueKind.True
                    && persisted.RootElement.TryGetProperty(
                        "ReducedTransparencyOverride",
                        out JsonElement transparencyOverride)
                    && transparencyOverride.ValueKind == JsonValueKind.True;
                bool unknownLocalPreserved = persisted.RootElement.TryGetProperty(
                        "futureOwner",
                        out JsonElement futureOwner)
                    && futureOwner.TryGetProperty("keep", out JsonElement keep)
                    && keep.GetBoolean();

                var reloaded = HiddenWindow();
                windows.Add(reloaded);
                reloaded.Show();
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);
                bool localOverridesReloaded = reloaded.ReducedMotionOverrideForSmoke == true
                    && reloaded.ReducedTransparencyOverrideForSmoke == true
                    && reloaded.ReducedMotionEffectiveForSmoke
                    && reloaded.ReducedTransparencyEffectiveForSmoke;

                bool systemModeSelected = reloaded.SetAccessibilityPreferencesForSmoke(
                    reducedMotion: null,
                    reducedTransparency: null,
                    persist: false);
                bool nullFollowsInjectedSystem = systemModeSelected
                    && reloaded.ReducedMotionEffectiveForSmoke
                    && reloaded.ReducedTransparencyEffectiveForSmoke;
                bool fullModeSelected = reloaded.SetAccessibilityPreferencesForSmoke(
                    reducedMotion: false,
                    reducedTransparency: false,
                    persist: false);
                bool explicitFullOverridesSystem = fullModeSelected
                    && !reloaded.ReducedMotionEffectiveForSmoke
                    && !reloaded.ReducedTransparencyEffectiveForSmoke;

                _highContrastForSmoke = true;
                ApplyAccessibilityPreferences();
                bool highContrastWins = HighContrastPaletteApplied
                    && reloaded.ReducedMotionEffectiveForSmoke
                    && reloaded.ReducedTransparencyEffectiveForSmoke
                    && ResourceColor("BgPrimaryColor") == SystemColors.WindowColor
                    && ResourceColor("TextPrimaryColor") == SystemColors.WindowTextColor;
                _highContrastForSmoke = false;
                ApplyAccessibilityPreferences();
                bool highContrastExitRestoresOverride = !HighContrastPaletteApplied
                    && !reloaded.ReducedMotionEffectiveForSmoke
                    && !reloaded.ReducedTransparencyEffectiveForSmoke
                    && ResourceColor("BgSecondaryColor") == standard["BgSecondaryColor"];

                bool sharedSettingsUntouched = string.Equals(
                    sharedSettingsBefore,
                    FileFingerprint(settingsPath),
                    StringComparison.Ordinal);
                ok = followsSystem
                    && fullOverrideSaved
                    && fullOverrideEffective
                    && modalOpened
                    && standardMotionActive
                    && reduceOverrideSaved
                    && activeMotionCanceled
                    && reducedMotionInstant
                    && reducedTransparencyOpaque
                    && localOverridesPersisted
                    && unknownLocalPreserved
                    && localOverridesReloaded
                    && nullFollowsInjectedSystem
                    && explicitFullOverridesSystem
                    && highContrastWins
                    && highContrastExitRestoresOverride
                    && sharedSettingsUntouched;
                result = new
                {
                    ok,
                    message = ok
                        ? "Windows-following accessibility fallbacks, WPF-local overrides, instant motion, opaque tokens, and high-contrast precedence passed"
                        : "accessibility fallback contract did not match expectations",
                    followsSystem,
                    fullOverrideSaved,
                    fullOverrideEffective,
                    modalOpened,
                    standardMotionActive,
                    reduceOverrideSaved,
                    activeMotionCanceled,
                    reducedMotionInstant,
                    reducedTransparencyOpaque,
                    nonOpaqueKeys,
                    localOverridesPersisted,
                    unknownLocalPreserved,
                    localOverridesReloaded,
                    nullFollowsInjectedSystem,
                    explicitFullOverridesSystem,
                    highContrastWins,
                    highContrastExitRestoresOverride,
                    sharedSettingsUntouched,
                    statePath,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString() };
            }
            finally
            {
                foreach (MainWindow window in windows)
                {
                    try { window.Close(); } catch { }
                }
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", previousSettingsPath);
                _highContrastForSmoke = previousHighContrastForSmoke;
                _systemReducedMotionForSmoke = previousSystemReducedMotionForSmoke;
                _systemReducedTransparencyForSmoke = previousSystemReducedTransparencyForSmoke;
                _reducedMotionOverride = previousReducedMotionOverride;
                _reducedTransparencyOverride = previousReducedTransparencyOverride;
                ApplyAccessibilityPreferences();
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(
                resultFullPath,
                JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            try { if (Directory.Exists(root)) Directory.Delete(root, recursive: true); } catch { }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private Color ResourceColor(string key)
        => Resources[key] is Color color
            ? color
            : throw new InvalidOperationException($"Theme color resource is unavailable: {key}");

    private Color ResourceBrushColor(string key)
        => Resources[key] is SolidColorBrush brush
            ? brush.Color
            : throw new InvalidOperationException($"Theme brush resource is unavailable: {key}");

    internal static bool IsAutomationInvocation(IReadOnlyList<string> args)
        => args.Any(static arg => arg.StartsWith("--", StringComparison.Ordinal)
            && (string.Equals(arg, "--shot", StringComparison.OrdinalIgnoreCase)
                || string.Equals(arg, "--album-library-shot", StringComparison.OrdinalIgnoreCase)
                || string.Equals(arg, "--startup-smoke", StringComparison.OrdinalIgnoreCase)
                 || arg.EndsWith("-smoke", StringComparison.OrdinalIgnoreCase)));

    private void CaptureSharedProjectRootSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string start = ArgValue(args.ToArray(), "--start-root") ?? Environment.CurrentDirectory;
        string? expected = ArgValue(args.ToArray(), "--expected-root");
        object result;
        bool ok = false;
        try
        {
            string resolved = PhotoViewer.Wpf.MainWindow.ResolveSharedProjectRootForSmoke(start);
            ok = string.IsNullOrWhiteSpace(expected)
                || string.Equals(Path.GetFullPath(resolved), Path.GetFullPath(expected), StringComparison.OrdinalIgnoreCase);
            result = new
            {
                ok,
                start = Path.GetFullPath(start),
                resolved = Path.GetFullPath(resolved),
                expected = string.IsNullOrWhiteSpace(expected) ? null : Path.GetFullPath(expected),
                favoritesPath = Path.Combine(resolved, ".cache", "favorites.json"),
                seenPath = Path.Combine(resolved, ".cache", "seen.json"),
                enhancementJobsPath = Path.Combine(resolved, ".cache", "enhance", "jobs.json"),
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message, start };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Shutdown(ok ? 0 : 1);
    }

    private void CaptureAlbumStoreSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        object result;
        bool ok = false;
        try
        {
            if (string.IsNullOrWhiteSpace(albumPathValue))
                throw new ArgumentException("album store smoke requires --album-path");
            string albumPath = Path.GetFullPath(albumPathValue);
            string memberPath = Path.GetFullPath(
                ArgValue(args.ToArray(), "--member-path")
                ?? Path.Combine(Path.GetDirectoryName(albumPath)!, "outside-member.jpg"));
            string cleanupMemberPath = Path.Combine(Path.GetDirectoryName(albumPath)!, $"cleanup-{Guid.NewGuid():N}.jpg");
            AlbumReadResult initial = AlbumStore.Read(albumPath);
            if (!initial.Supported || initial.Document is null)
                throw new InvalidDataException(initial.Error ?? "initial Album document was protected");

            string albumId = $"wpf-smoke-{Guid.NewGuid():N}";
            AlbumMutationResult created = AlbumStore.Create(
                albumPath,
                "WPF shared Album",
                initial.Document.Revision,
                albumId);
            AlbumMutationResult added = AlbumStore.AddMembers(
                albumPath,
                albumId,
                [memberPath, cleanupMemberPath],
                created.Document?.Revision);
            string? memberId = added.Album?.Members.SingleOrDefault(member => string.Equals(member.ImagePath, memberPath, StringComparison.OrdinalIgnoreCase))?.Id;
            AlbumMutationResult updated = AlbumStore.Update(
                albumPath,
                albumId,
                added.Document?.Revision,
                pinned: true,
                coverMemberId: memberId,
                updateCover: true);
            AlbumMutationResult cleaned = AlbumStore.CleanupPaths(
                albumPath,
                [cleanupMemberPath],
                updated.Document?.Revision);
            AlbumMutationResult stale = AlbumStore.Create(
                albumPath,
                "Must conflict",
                initial.Document.Revision,
                $"stale-{Guid.NewGuid():N}");
            AlbumReadResult final = AlbumStore.Read(albumPath);
            using JsonDocument stored = JsonDocument.Parse(File.ReadAllText(albumPath));
            bool unknownRootPreserved = stored.RootElement.TryGetProperty("futureRoot", out JsonElement futureRoot)
                && futureRoot.ValueKind == JsonValueKind.Object
                && futureRoot.TryGetProperty("keep", out JsonElement futureRootKeep)
                && futureRootKeep.ValueKind == JsonValueKind.True;
            AlbumLegacyMigrationSmoke legacyMigration = CaptureAlbumLegacyMigrationSmoke();
            string lockPath = albumPath + ".lock";
            string ownerPath = Path.Combine(lockPath, "owner.json");
            string liveOwnerToken = Guid.NewGuid().ToString("N");
            string liveOwnerPayload = JsonSerializer.Serialize(new
            {
                protocol = "photoviewer.shared-directory-lock/v1",
                token = liveOwnerToken,
                pid = Environment.ProcessId,
                createdAtUtc = DateTimeOffset.UtcNow.AddMinutes(-1).ToString("O"),
            });
            Directory.CreateDirectory(lockPath);
            File.WriteAllText(ownerPath, liveOwnerPayload);
            File.SetLastWriteTimeUtc(ownerPath, DateTime.UtcNow.AddMinutes(-1));
            Directory.SetLastWriteTimeUtc(lockPath, DateTime.UtcNow.AddMinutes(-1));
            AlbumMutationResult liveOwnerContention = AlbumStore.Create(
                albumPath,
                "Must remain busy",
                final.Document?.Revision,
                $"live-owner-{Guid.NewGuid():N}",
                timeoutMilliseconds: 75);
            bool liveOwnerLockPreserved = liveOwnerContention.Status == AlbumMutationStatus.Busy
                && Directory.Exists(lockPath)
                && File.Exists(ownerPath)
                && string.Equals(File.ReadAllText(ownerPath), liveOwnerPayload, StringComparison.Ordinal);
            try { Directory.Delete(lockPath, recursive: true); } catch { }
            bool noResidue = !File.Exists(albumPath + ".lock")
                && !Directory.Exists(albumPath + ".lock")
                && !Directory.EnumerateFiles(Path.GetDirectoryName(albumPath)!, "*.tmp", SearchOption.TopDirectoryOnly)
                    .Any(path => Path.GetFileName(path).StartsWith(".albums.json.", StringComparison.OrdinalIgnoreCase)
                        || Path.GetFileName(path).StartsWith("albums-", StringComparison.OrdinalIgnoreCase));
            ok = created.Ok
                && added.Ok
                && updated.Ok
                && cleaned.Ok
                && updated.Album?.Pinned == true
                && updated.Album?.CoverMemberId == memberId
                && stale.Status == AlbumMutationStatus.Conflict
                && final.Supported
                && final.Document?.Revision == initial.Document.Revision + 4
                && final.Document.Albums.Any(album => album.Id == albumId && album.Members.Count == 1)
                && unknownRootPreserved
                && legacyMigration.Ok
                && liveOwnerLockPreserved
                && noResidue;
            result = new
            {
                ok,
                albumPath,
                albumId,
                memberPath,
                initialRevision = initial.Document.Revision,
                finalRevision = final.Document?.Revision,
                created = created.Status.ToString(),
                createdError = created.Error,
                added = added.Status.ToString(),
                addedError = added.Error,
                updated = updated.Status.ToString(),
                updatedError = updated.Error,
                cleaned = cleaned.Status.ToString(),
                cleanedError = cleaned.Error,
                stale = stale.Status.ToString(),
                staleError = stale.Error,
                unknownRootPreserved,
                legacyMigration,
                liveOwnerContention = liveOwnerContention.Status.ToString(),
                liveOwnerLockPreserved,
                noResidue,
                albumCount = final.Document?.Albums.Count,
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message, albumPath = albumPathValue };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Shutdown(ok ? 0 : 1);
    }

    private static AlbumLegacyMigrationSmoke CaptureAlbumLegacyMigrationSmoke()
    {
        string probeRoot = Path.Combine(Path.GetTempPath(), $"PhotoViewer.Wpf.AlbumLegacySmoke.{Guid.NewGuid():N}");
        Directory.CreateDirectory(probeRoot);
        try
        {
            string legacyPath = Path.Combine(probeRoot, "legacy-empty.json");
            const string legacyRaw = "{\"albums\":[],\"futureRoot\":{\"keep\":true}}";
            File.WriteAllText(legacyPath, legacyRaw);
            byte[] legacyBeforeRead = File.ReadAllBytes(legacyPath);
            AlbumReadResult legacyRead = AlbumStore.Read(legacyPath);
            bool readOnly = legacyRead.Supported
                && legacyRead.Document?.Revision == 0
                && legacyRead.Document.Albums.Count == 0
                && legacyBeforeRead.SequenceEqual(File.ReadAllBytes(legacyPath));
            AlbumMutationResult upgraded = AlbumStore.Create(
                legacyPath,
                "Migrated by WPF",
                0,
                "wpf-legacy-upgrade");
            using JsonDocument upgradedDocument = JsonDocument.Parse(File.ReadAllText(legacyPath));
            JsonElement upgradedRoot = upgradedDocument.RootElement;
            bool unknownRootPreserved = upgradedRoot.TryGetProperty("futureRoot", out JsonElement upgradedFutureRoot)
                && upgradedFutureRoot.TryGetProperty("keep", out JsonElement upgradedKeep)
                && upgradedKeep.ValueKind == JsonValueKind.True;
            bool upgradedOnFirstMutation = upgraded.Ok
                && upgraded.Changed
                && upgraded.Document?.Version == AlbumStore.Version
                && upgraded.Document.Revision == 1
                && upgradedRoot.GetProperty("version").GetInt32() == AlbumStore.Version
                && upgradedRoot.GetProperty("revision").GetInt64() == 1
                && unknownRootPreserved;

            string ambiguousPath = Path.Combine(probeRoot, "legacy-non-empty.json");
            const string ambiguousRaw = "{\"albums\":[{\"id\":\"unknown-legacy-shape\"}],\"futureRoot\":{\"keep\":true}}";
            File.WriteAllText(ambiguousPath, ambiguousRaw);
            byte[] ambiguousBefore = File.ReadAllBytes(ambiguousPath);
            AlbumReadResult ambiguousRead = AlbumStore.Read(ambiguousPath);
            AlbumMutationResult ambiguousMutation = AlbumStore.Create(ambiguousPath, "Must stay protected", albumId: "must-not-publish");
            bool ambiguousProtected = !ambiguousRead.Supported
                && ambiguousRead.Malformed
                && ambiguousMutation.Status == AlbumMutationStatus.Protected
                && ambiguousBefore.SequenceEqual(File.ReadAllBytes(ambiguousPath));

            string partialPath = Path.Combine(probeRoot, "legacy-partial.json");
            const string partialRaw = "{\"albums\":[],\"revision\":0}";
            File.WriteAllText(partialPath, partialRaw);
            byte[] partialBefore = File.ReadAllBytes(partialPath);
            AlbumReadResult partialRead = AlbumStore.Read(partialPath);
            AlbumMutationResult partialMutation = AlbumStore.Create(partialPath, "Must stay protected", albumId: "must-not-publish");
            bool partialProtected = !partialRead.Supported
                && partialRead.Malformed
                && partialMutation.Status == AlbumMutationStatus.Protected
                && partialBefore.SequenceEqual(File.ReadAllBytes(partialPath));

            string malformedPath = Path.Combine(probeRoot, "malformed.json");
            const string malformedRaw = "{\"albums\":";
            File.WriteAllText(malformedPath, malformedRaw);
            byte[] malformedBefore = File.ReadAllBytes(malformedPath);
            AlbumReadResult malformedRead = AlbumStore.Read(malformedPath);
            AlbumMutationResult malformedMutation = AlbumStore.Create(malformedPath, "Must stay protected", albumId: "must-not-publish");
            bool malformedProtected = !malformedRead.Supported
                && malformedRead.Malformed
                && malformedMutation.Status == AlbumMutationStatus.Protected
                && malformedBefore.SequenceEqual(File.ReadAllBytes(malformedPath));

            string futurePath = Path.Combine(probeRoot, "future.json");
            const string futureRaw = "{\"version\":2,\"revision\":0,\"updatedAtUtc\":\"1970-01-01T00:00:00.0000000+00:00\",\"albums\":[],\"recentAlbumIds\":[],\"futureRoot\":true}";
            File.WriteAllText(futurePath, futureRaw);
            byte[] futureBefore = File.ReadAllBytes(futurePath);
            AlbumReadResult futureRead = AlbumStore.Read(futurePath);
            AlbumMutationResult futureMutation = AlbumStore.Create(futurePath, "Must stay protected", albumId: "must-not-publish");
            bool futureProtected = !futureRead.Supported
                && futureRead.FutureVersion
                && futureMutation.Status == AlbumMutationStatus.Protected
                && futureBefore.SequenceEqual(File.ReadAllBytes(futurePath));

            bool ok = readOnly
                && upgradedOnFirstMutation
                && ambiguousProtected
                && partialProtected
                && malformedProtected
                && futureProtected;
            return new AlbumLegacyMigrationSmoke(
                ok,
                readOnly,
                upgradedOnFirstMutation,
                unknownRootPreserved,
                ambiguousProtected,
                partialProtected,
                malformedProtected,
                futureProtected,
                upgraded.Status.ToString(),
                upgraded.Document?.Revision);
        }
        finally
        {
            try { Directory.Delete(probeRoot, recursive: true); } catch { }
        }
    }

    private sealed record AlbumLegacyMigrationSmoke(
        bool Ok,
        bool ReadOnly,
        bool UpgradedOnFirstMutation,
        bool UnknownRootPreserved,
        bool AmbiguousProtected,
        bool PartialProtected,
        bool MalformedProtected,
        bool FutureProtected,
        string UpgradeStatus,
        long? UpgradedRevision);

    private void CaptureAlbumConcurrentWriterSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        string? readyPathValue = ArgValue(args.ToArray(), "--ready-path");
        string? goPathValue = ArgValue(args.ToArray(), "--go-path");
        string prefix = ArgValue(args.ToArray(), "--prefix") ?? "wpf-concurrent";
        bool countValid = int.TryParse(ArgValue(args.ToArray(), "--count"), out int count) && count is >= 1 and <= 100;
        object result;
        bool ok = false;
        try
        {
            if (string.IsNullOrWhiteSpace(albumPathValue) || !countValid)
                throw new ArgumentException("Album concurrent writer smoke requires --album-path and --count 1-100");
            string albumPath = Path.GetFullPath(albumPathValue);
            if (!string.IsNullOrWhiteSpace(readyPathValue))
            {
                string readyPath = Path.GetFullPath(readyPathValue);
                Directory.CreateDirectory(Path.GetDirectoryName(readyPath)!);
                File.WriteAllText(readyPath, "ready");
            }
            if (!string.IsNullOrWhiteSpace(goPathValue))
            {
                string goPath = Path.GetFullPath(goPathValue);
                var wait = Stopwatch.StartNew();
                while (!File.Exists(goPath) && wait.Elapsed < TimeSpan.FromSeconds(15))
                    Thread.Sleep(10);
                if (!File.Exists(goPath))
                    throw new TimeoutException("Album concurrent writer start barrier timed out");
            }

            var statuses = new List<string>(count);
            for (int index = 0; index < count; index++)
            {
                AlbumMutationResult mutation = AlbumStore.Create(
                    albumPath,
                    $"WPF concurrent {index}",
                    expectedRevision: null,
                    albumId: $"{prefix}-{index:D3}");
                statuses.Add(mutation.Status.ToString());
            }
            AlbumReadResult final = AlbumStore.Read(albumPath);
            ok = statuses.All(static status => status == AlbumMutationStatus.Succeeded.ToString())
                && final.Supported
                && final.Document is not null
                && Enumerable.Range(0, count).All(index => final.Document.Albums.Any(album => album.Id == $"{prefix}-{index:D3}"));
            result = new
            {
                ok,
                count,
                statuses,
                finalRevision = final.Document?.Revision,
                albumCount = final.Document?.Albums.Count,
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Shutdown(ok ? 0 : 1);
    }

    private void CaptureAlbumMemberWriterSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        string? albumId = ArgValue(args.ToArray(), "--album-id");
        string? memberPathValue = ArgValue(args.ToArray(), "--member-path");
        string? readyPathValue = ArgValue(args.ToArray(), "--ready-path");
        string? goPathValue = ArgValue(args.ToArray(), "--go-path");
        object result;
        bool ok = false;
        try
        {
            if (string.IsNullOrWhiteSpace(albumPathValue)
                || string.IsNullOrWhiteSpace(albumId)
                || string.IsNullOrWhiteSpace(memberPathValue))
            {
                throw new ArgumentException("Album member writer smoke requires --album-path, --album-id, and --member-path");
            }
            string albumPath = Path.GetFullPath(albumPathValue);
            string memberPath = Path.GetFullPath(memberPathValue);
            if (!string.IsNullOrWhiteSpace(readyPathValue))
            {
                string readyPath = Path.GetFullPath(readyPathValue);
                Directory.CreateDirectory(Path.GetDirectoryName(readyPath)!);
                File.WriteAllText(readyPath, "ready");
            }
            if (!string.IsNullOrWhiteSpace(goPathValue))
            {
                string goPath = Path.GetFullPath(goPathValue);
                var wait = Stopwatch.StartNew();
                while (!File.Exists(goPath) && wait.Elapsed < TimeSpan.FromSeconds(15))
                    Thread.Sleep(10);
                if (!File.Exists(goPath))
                    throw new TimeoutException("Album member writer start barrier timed out");
            }

            AlbumMutationResult mutation = AlbumStore.RemoveMembers(
                albumPath,
                albumId,
                memberIds: null,
                paths: [memberPath],
                expectedRevision: null);
            AlbumReadResult final = AlbumStore.Read(albumPath);
            AlbumEntry? finalAlbum = final.Document?.Albums.FirstOrDefault(candidate => candidate.Id == albumId);
            bool removed = finalAlbum is not null
                && finalAlbum.Members.All(member => !string.Equals(member.ImagePath, memberPath, StringComparison.OrdinalIgnoreCase));
            ok = mutation.Ok && final.Supported && removed;
            result = new
            {
                ok,
                status = mutation.Status.ToString(),
                changed = mutation.Changed,
                removed,
                finalRevision = final.Document?.Revision,
                finalAlbumRevision = finalAlbum?.Revision,
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Shutdown(ok ? 0 : 1);
    }

    private void CaptureAlbumLockHolderSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        string? readyPathValue = ArgValue(args.ToArray(), "--ready-path");
        string? releasePathValue = ArgValue(args.ToArray(), "--release-path");
        string? releaseMissingReadyPathValue = ArgValue(args.ToArray(), "--release-missing-ready-path");
        string? releaseMissingContinuePathValue = ArgValue(args.ToArray(), "--release-missing-continue-path");
        object result;
        bool ok = false;
        try
        {
            if (string.IsNullOrWhiteSpace(albumPathValue)
                || string.IsNullOrWhiteSpace(readyPathValue)
                || string.IsNullOrWhiteSpace(releasePathValue))
            {
                throw new ArgumentException("Album lock holder smoke requires --album-path, --ready-path, and --release-path");
            }
            string albumPath = Path.GetFullPath(albumPathValue);
            string readyPath = Path.GetFullPath(readyPathValue);
            string releasePath = Path.GetFullPath(releasePathValue);
            Action? releaseOwnerMissingHook = null;
            if (!string.IsNullOrWhiteSpace(releaseMissingReadyPathValue)
                || !string.IsNullOrWhiteSpace(releaseMissingContinuePathValue))
            {
                if (string.IsNullOrWhiteSpace(releaseMissingReadyPathValue)
                    || string.IsNullOrWhiteSpace(releaseMissingContinuePathValue))
                {
                    throw new ArgumentException("Release-missing smoke requires both ready and continue paths.");
                }
                string releaseMissingReadyPath = Path.GetFullPath(releaseMissingReadyPathValue);
                string releaseMissingContinuePath = Path.GetFullPath(releaseMissingContinuePathValue);
                releaseOwnerMissingHook = () =>
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(releaseMissingReadyPath)!);
                    File.WriteAllText(releaseMissingReadyPath, "ready");
                    var wait = Stopwatch.StartNew();
                    while (!File.Exists(releaseMissingContinuePath) && wait.Elapsed < TimeSpan.FromSeconds(15))
                        Thread.Sleep(10);
                    if (!File.Exists(releaseMissingContinuePath))
                        throw new TimeoutException("Timed out waiting for release-missing continuation.");
                };
            }
            ok = AlbumStore.HoldSharedLockForSmoke(albumPath, readyPath, releasePath, releaseOwnerMissingHook);
            result = new
            {
                ok,
                albumPath,
                readyPath,
                releasePath,
                residueFree = !File.Exists(albumPath + ".lock") && !Directory.Exists(albumPath + ".lock"),
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Shutdown(ok ? 0 : 1);
    }

    private void CaptureAlbumUiSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        string? previousAlbumPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH");
        if (string.IsNullOrWhiteSpace(albumPathValue))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(new { ok = false, message = "album UI smoke requires --album-path" }));
            Shutdown(1);
            return;
        }

        string albumPath = Path.GetFullPath(albumPathValue);
        string smokeRoot = Path.GetDirectoryName(albumPath)!;
        string catalog = Path.Combine(smokeRoot, "catalog");
        string outside = Path.Combine(smokeRoot, "outside");
        Directory.CreateDirectory(catalog);
        Directory.CreateDirectory(outside);
        string currentPath = Path.Combine(catalog, "current-a.png");
        string secondCurrentPath = Path.Combine(catalog, "current-b.png");
        string outsidePath = Path.Combine(outside, "outside.png");
        string missingPath = Path.Combine(smokeRoot, "missing.png");
        WriteSmokePng(currentPath, 72, 54, Color.FromRgb(70, 125, 205));
        WriteSmokePng(secondCurrentPath, 72, 54, Color.FromRgb(90, 145, 225));
        WriteSmokePng(outsidePath, 72, 54, Color.FromRgb(195, 95, 125));
        string catalogBefore = FolderFingerprint(catalog);
        string outsideBefore = FolderFingerprint(outside);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", albumPath);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var window = HiddenWindow();
        window.Show();
        window.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            try
            {
                AlbumMutationResult created = AlbumStore.Create(albumPath, "WPF UI Album", 0, "album-ui");
                AlbumMutationResult added = AlbumStore.AddMembers(albumPath, "album-ui", [secondCurrentPath, currentPath, outsidePath, missingPath], created.Document?.Revision);
                AlbumMutationResult slowCreated = AlbumStore.Create(albumPath, "Slow active source", added.Document?.Revision, "album-ui-slow");
                string[] slowPaths = Enumerable.Range(0, 64)
                    .Select(index => Path.Combine(smokeRoot, "slow-active", $"missing-{index:D3}.png"))
                    .ToArray();
                AlbumMutationResult slowSeeded = AlbumStore.AddMembers(albumPath, "album-ui-slow", slowPaths, slowCreated.Document?.Revision);
                await window.LoadFolderAsync(catalog);
                window.ConfigureActiveAlbumAvailabilityDelayForSmoke(10);
                int activeScanStartedBefore = window.ActiveAlbumAvailabilityStartedCountForSmoke;
                int activeScanCanceledBefore = window.ActiveAlbumAvailabilityCanceledCountForSmoke;
                int sourceApplyCountBefore = window.ActiveAlbumSourceApplyCountForSmoke;
                int activeHeartbeats = 0;
                var activeHeartbeat = new DispatcherTimer(DispatcherPriority.Send, window.Dispatcher)
                {
                    Interval = TimeSpan.FromMilliseconds(10),
                };
                activeHeartbeat.Tick += (_, _) => activeHeartbeats++;
                activeHeartbeat.Start();
                Task<bool> slowActivation = window.ActivateAlbumForSmokeAsync("album-ui-slow");
                await window.WaitForActiveAlbumAvailabilityStartedForSmokeAsync(activeScanStartedBefore);
                Task<bool> latestActivation = window.ActivateAlbumForSmokeAsync("album-ui");
                bool activated = await slowActivation && await latestActivation;
                await window.WaitForActiveAlbumAvailabilityIdleForSmokeAsync();
                activeHeartbeat.Stop();
                bool activeAvailabilityCancellation = activated
                    && window.ActiveAlbumAvailabilityCanceledCountForSmoke > activeScanCanceledBefore
                    && window.ActiveAlbumAvailabilityMaxConcurrentCountForSmoke == 1
                    && window.ActiveAlbumAvailabilityActiveCountForSmoke == 0
                    && window.ActiveAlbumAvailabilityPendingCountForSmoke == 0
                    && window.ActiveAlbumAvailabilityRanOffDispatcherForSmoke
                    && window.ActiveAlbumSourceApplyCountForSmoke == sourceApplyCountBefore + 2
                    && activeHeartbeats >= 2;
                window.ConfigureActiveAlbumAvailabilityDelayForSmoke(0);
                bool currentOnly = window.FilteredFileNamesForSmoke().SequenceEqual(["current-b.png", "current-a.png"], StringComparer.OrdinalIgnoreCase);
                bool unavailableExplicit = window.ActiveAlbumOutsideCountForSmoke == 1
                    && window.ActiveAlbumMissingCountForSmoke == 1
                    && window.HeaderStatsForSmoke.Contains("outside unavailable", StringComparison.OrdinalIgnoreCase)
                    && window.HeaderStatsForSmoke.Contains("missing", StringComparison.OrdinalIgnoreCase);
                string cleanupLockPath = albumPath + ".lock";
                File.WriteAllText(cleanupLockPath, "active writer");
                bool cleanupInitiallyPending;
                try
                {
                    cleanupInitiallyPending = !window.QueueAlbumMembershipCleanupForSmoke(missingPath)
                        && window.PendingAlbumCleanupCountForSmoke == 1
                        && window.DeleteStatusRetryVisibleForSmoke
                        && window.DeleteStatusForSmoke.Contains("pending", StringComparison.OrdinalIgnoreCase);
                }
                finally
                {
                    try { File.Delete(cleanupLockPath); } catch { }
                }
                window.ConfigureActiveAlbumAvailabilityDelayForSmoke(100);
                int cleanupRefreshStartedBefore = window.ActiveAlbumAvailabilityStartedCountForSmoke;
                var cleanupRefreshWatch = Stopwatch.StartNew();
                window.RetryStatusForSmoke();
                cleanupRefreshWatch.Stop();
                await window.WaitForActiveAlbumAvailabilityStartedForSmokeAsync(cleanupRefreshStartedBefore);
                bool recycleReconciliationDoesNotWaitForAvailability = cleanupRefreshWatch.ElapsedMilliseconds < 500
                    && window.ActiveAlbumAvailabilityActiveCountForSmoke == 1;
                AlbumReadResult cleanupRetriedDocument = AlbumStore.Read(albumPath);
                bool cleanupRetrySucceeded = cleanupRetriedDocument.Supported
                    && window.PendingAlbumCleanupCountForSmoke == 0
                    && !window.DeleteStatusRetryVisibleForSmoke
                    && window.DeleteStatusForSmoke.Contains("No source Recycle action was repeated", StringComparison.OrdinalIgnoreCase)
                    && cleanupRetriedDocument.Document?.Albums
                        .First(album => album.Id == "album-ui")
                        .Members.All(member => !string.Equals(member.ImagePath, missingPath, StringComparison.OrdinalIgnoreCase)) == true;
                window.ReturnToCatalogForSmoke();
                await window.WaitForActiveAlbumAvailabilityIdleForSmokeAsync();
                window.ConfigureActiveAlbumAvailabilityDelayForSmoke(0);
                bool uiContract = window.AlbumUiContractForSmoke;
                bool defaultShortcut = window.KeyBindingTextForSmoke("addToAlbum", draft: false) == "B";

                using JsonDocument legacyDocument = JsonDocument.Parse("{\"toggleModalFilmstrip\":\"B\",\"futureAction\":\"G\"}");
                var legacyBindings = legacyDocument.RootElement.EnumerateObject()
                    .ToDictionary(static property => property.Name, static property => property.Value.Clone(), StringComparer.Ordinal);
                Dictionary<ViewerKeyAction, KeyChord> migrated = KeyBindingSettings.NormalizePersisted(legacyBindings, out _);
                bool collisionAwareShortcut = migrated[ViewerKeyAction.ToggleModalFilmstrip].DisplayText == "B"
                    && migrated[ViewerKeyAction.AddToAlbum].IsBound
                    && migrated[ViewerKeyAction.AddToAlbum].DisplayText != "B"
                    && KeyBindingSettings.FindConflicts(migrated).Count == 0;

                window.ReturnToCatalogForSmoke();
                bool catalogRestored = window.ActiveAlbumIdForSmoke is null && window.FilteredCountForSmoke == 2;
                bool sourceUntouched = string.Equals(catalogBefore, FolderFingerprint(catalog), StringComparison.Ordinal)
                    && string.Equals(outsideBefore, FolderFingerprint(outside), StringComparison.Ordinal);
                bool noResidue = !File.Exists(albumPath + ".lock")
                    && !Directory.Exists(albumPath + ".lock")
                    && !Directory.EnumerateFiles(smokeRoot, "*.tmp", SearchOption.TopDirectoryOnly).Any();
                ok = created.Ok && added.Ok && slowCreated.Ok && slowSeeded.Ok
                    && activated && activeAvailabilityCancellation && recycleReconciliationDoesNotWaitForAvailability
                    && currentOnly && unavailableExplicit && uiContract
                    && cleanupInitiallyPending && cleanupRetrySucceeded
                    && defaultShortcut && collisionAwareShortcut && catalogRestored && sourceUntouched && noResidue;
                result = new
                {
                    ok,
                    activated,
                    activeAvailabilityCancellation,
                    activeAvailabilityCanceledCount = window.ActiveAlbumAvailabilityCanceledCountForSmoke,
                    activeAvailabilityMaxConcurrent = window.ActiveAlbumAvailabilityMaxConcurrentCountForSmoke,
                    activeAvailabilityRanOffDispatcher = window.ActiveAlbumAvailabilityRanOffDispatcherForSmoke,
                    activeAvailabilityHeartbeatCount = activeHeartbeats,
                    recycleReconciliationDoesNotWaitForAvailability,
                    cleanupRefreshReturnedMs = cleanupRefreshWatch.ElapsedMilliseconds,
                    currentOnly,
                    unavailableExplicit,
                    cleanupInitiallyPending,
                    cleanupRetrySucceeded,
                    uiContract,
                    defaultShortcut,
                    collisionAwareShortcut,
                    catalogRestored,
                    sourceUntouched,
                    noResidue,
                    header = window.HeaderStatsForSmoke,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.Message };
            }
            finally
            {
                try { window.Close(); } catch { }
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", previousAlbumPath);
            }
            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureAlbumLibraryHardeningSmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? albumPathValue = ArgValue(args.ToArray(), "--album-path");
        string? previousAlbumPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH");
        if (string.IsNullOrWhiteSpace(albumPathValue))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(new { ok = false, message = "album library hardening smoke requires --album-path" }));
            Shutdown(1);
            return;
        }

        string albumPath = Path.GetFullPath(albumPathValue);
        string smokeRoot = Path.GetDirectoryName(albumPath)!;
        string catalog = Path.Combine(smokeRoot, "catalog");
        string currentPng = Path.Combine(catalog, "current.png");
        string unsupportedBmp = Path.Combine(catalog, "unsupported.bmp");
        string seedGif = Path.Combine(catalog, "availability-seed.gif");
        Directory.CreateDirectory(catalog);
        WriteSmokePng(currentPng, 48, 36, Color.FromRgb(75, 145, 215));
        File.WriteAllBytes(unsupportedBmp, [0x42, 0x4d, 0x00, 0x00]);
        File.WriteAllBytes(seedGif, [0x47, 0x49, 0x46, 0x38, 0x39, 0x61]);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", albumPath);

        AlbumMutationResult mixedCreated = AlbumStore.Create(albumPath, "Mixed selection", 0, "mixed-selection");
        AlbumMutationResult mixedSeeded = AlbumStore.AddMembers(albumPath, "mixed-selection", [seedGif], mixedCreated.Document?.Revision);
        AlbumMutationResult busyCreated = AlbumStore.Create(albumPath, "Busy probe", mixedSeeded.Document?.Revision, "busy-probe");
        AlbumMutationResult slowCreated = AlbumStore.Create(albumPath, "Slow availability", busyCreated.Document?.Revision, "slow-availability");
        string[] slowMembers = Enumerable.Range(0, 64)
            .Select(index => Path.Combine(smokeRoot, "slow-members", $"missing-{index:D3}.png"))
            .ToArray();
        AlbumMutationResult slowSeeded = AlbumStore.AddMembers(albumPath, "slow-availability", slowMembers, slowCreated.Document?.Revision);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var owner = new Window
        {
            Width = 2,
            Height = 2,
            Left = -10_000,
            Top = -10_000,
            ShowInTaskbar = false,
            WindowStyle = WindowStyle.None,
            ShowActivated = false,
            Opacity = 0,
        };
        owner.Show();
        int activatedAlbumCount = 0;
        string? activatedAlbumId = null;
        int libraryReconciliationCount = 0;
        var library = new AlbumLibraryWindow(
            owner,
            [currentPng, unsupportedBmp],
            [currentPng, unsupportedBmp, seedGif],
            album =>
            {
                Interlocked.Increment(ref activatedAlbumCount);
                activatedAlbumId = album?.Id;
                return Task.CompletedTask;
            },
            () =>
            {
                Interlocked.Increment(ref libraryReconciliationCount);
                return Task.CompletedTask;
            });
        library.WindowStartupLocation = WindowStartupLocation.Manual;
        library.Left = -20_000;
        library.Top = -20_000;
        library.ShowActivated = false;
        library.Opacity = 0;
        library.Show();
        library.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            string lockPath = albumPath + ".lock";
            try
            {
                await library.WaitForIdleForSmokeAsync();
                string[] expectedActionLabels =
                [
                    "作成",
                    "更新",
                    "Galleryで開く",
                    "選択画像を追加",
                    "名前を変更",
                    "ピン留め / 解除",
                    "Catalogへ戻る",
                    "Albumを削除",
                    "Coverに設定",
                    "Albumから外す",
                ];
                IReadOnlyDictionary<string, string> actionHelpText =
                    library.ActionHelpTextByLabelForSmoke;
                bool presentationContract = string.Equals(
                        library.Title,
                        "Albums · Aibos",
                        StringComparison.Ordinal)
                    && string.Equals(
                        library.HeaderSubtitleForSmoke,
                        "画像をまとめ、Galleryへすぐ呼び出せます",
                        StringComparison.Ordinal)
                    && string.Equals(
                        library.StatusLabelForSmoke,
                        "ALBUM STORE",
                        StringComparison.Ordinal)
                    && library.ActionLabelsForSmoke.SequenceEqual(expectedActionLabels)
                    && !library.HeaderSubtitleForSmoke.Contains(
                        "Browser",
                        StringComparison.OrdinalIgnoreCase);
                bool sourceSafetyPlacementContract =
                    actionHelpText.TryGetValue("Albumを削除", out string? deleteHelp)
                    && string.Equals(
                        deleteHelp,
                        "Albumだけを削除します。元画像は削除されません。",
                        StringComparison.Ordinal)
                    && actionHelpText.TryGetValue("Albumから外す", out string? removeHelp)
                    && string.Equals(
                        removeHelp,
                        "選択した画像をAlbumから外します。元画像は削除されません。",
                        StringComparison.Ordinal)
                    && actionHelpText
                        .Where(pair => pair.Key is not "Albumを削除" and not "Albumから外す")
                        .All(pair => !pair.Value.Contains(
                            "元画像は削除されません",
                            StringComparison.Ordinal));
                bool mixedSelected = library.SelectAlbumForSmoke("mixed-selection");
                bool mixedAccepted = await library.AddSelectionForSmokeAsync();
                AlbumReadResult mixedRead = AlbumStore.Read(albumPath);
                AlbumEntry? mixedAlbum = mixedRead.Document?.Albums.FirstOrDefault(album => album.Id == "mixed-selection");
                bool mixedFormatFiltered = mixedAccepted
                    && mixedAlbum?.Members.Any(member => string.Equals(member.ImagePath, currentPng, StringComparison.OrdinalIgnoreCase)) == true
                    && mixedAlbum.Members.All(member => !string.Equals(member.ImagePath, unsupportedBmp, StringComparison.OrdinalIgnoreCase));
                string addStatus = library.StatusForSmoke;
                bool addStatusCounts = addStatus.Contains("追加 1件", StringComparison.Ordinal)
                    && addStatus.Contains("スキップ 1件", StringComparison.Ordinal);
                bool statusLanguageContract = addStatusCounts
                    && !addStatus.Contains("Added", StringComparison.OrdinalIgnoreCase)
                    && !addStatus.Contains("skipped", StringComparison.OrdinalIgnoreCase);
                bool actionToolTips = library.ActionButtonsHaveToolTipsForSmoke;
                bool actionAutomationHelpText = library.ActionButtonsHaveAutomationHelpTextForSmoke;
                bool actionFocusVisuals = library.ActionButtonsHaveFocusVisualForSmoke;

                library.ConfigureMemberAvailabilityDelayForSmoke(8);
                int memberStartedBefore = library.MemberAvailabilityStartedCountForSmoke;
                int memberCanceledBefore = library.MemberAvailabilityCanceledCountForSmoke;
                bool slowSelected = library.SelectAlbumForSmoke("slow-availability");
                await library.WaitForMemberAvailabilityStartedForSmokeAsync(memberStartedBefore);
                bool latestMemberSelected = library.SelectAlbumForSmoke("busy-probe");
                await library.WaitForMemberAvailabilityIdleForSmokeAsync();
                bool availabilityCancellation = slowSelected
                    && latestMemberSelected
                    && library.MemberAvailabilityCanceledCountForSmoke > memberCanceledBefore
                    && library.MemberAvailabilityMaxConcurrentCountForSmoke == 1
                    && library.MemberAvailabilityActiveCountForSmoke == 0
                    && library.MemberAvailabilityPendingCountForSmoke == 0
                    && string.Equals(library.SelectedAlbumIdForSmoke, "busy-probe", StringComparison.Ordinal)
                    && string.Equals(library.MemberHeadingForSmoke, "Busy probe", StringComparison.Ordinal)
                    && library.MemberItemCountForSmoke == 0;
                library.ConfigureMemberAvailabilityDelayForSmoke(0);

                bool openSelected = library.SelectAlbumForSmoke("mixed-selection");
                await library.WaitForMemberAvailabilityIdleForSmokeAsync();
                AlbumReadResult beforeExternalAdvance = AlbumStore.Read(albumPath);
                AlbumMutationResult externalAdvance = AlbumStore.Create(
                    albumPath,
                    "External revision advance",
                    beforeExternalAdvance.Document?.Revision,
                    "external-revision-advance");
                int activationCountBeforeOpen = activatedAlbumCount;
                int reconciliationCountBeforeOpen = libraryReconciliationCount;
                bool openAccepted = await library.OpenSelectedAlbumForSmokeAsync();
                AlbumReadResult afterOpenRead = AlbumStore.Read(albumPath);
                bool openUsesLatestRevision = openSelected
                    && externalAdvance.Ok
                    && openAccepted
                    && activatedAlbumCount == activationCountBeforeOpen + 1
                    && string.Equals(activatedAlbumId, "mixed-selection", StringComparison.Ordinal)
                    && libraryReconciliationCount == reconciliationCountBeforeOpen
                    && afterOpenRead.Document?.Albums.Any(album => album.Id == "external-revision-advance") == true
                    && string.Equals(afterOpenRead.Document.RecentAlbumIds.FirstOrDefault(), "mixed-selection", StringComparison.Ordinal);

                bool busySelected = library.SelectAlbumForSmoke("busy-probe");
                string liveOwnerPayload = JsonSerializer.Serialize(new
                {
                    pid = Environment.ProcessId,
                    createdAtUtc = DateTimeOffset.UtcNow.AddMinutes(-1).ToString("O"),
                });
                File.WriteAllText(lockPath, liveOwnerPayload);
                File.SetLastWriteTimeUtc(lockPath, DateTime.UtcNow.AddMinutes(-1));
                int heartbeats = 0;
                var heartbeat = new DispatcherTimer(DispatcherPriority.Send, library.Dispatcher)
                {
                    Interval = TimeSpan.FromMilliseconds(20),
                };
                heartbeat.Tick += (_, _) => heartbeats++;
                heartbeat.Start();
                int mutationInvocationCountBeforeHeldLock = library.MutationInvocationCountForSmoke;
                Task<bool> heldLockAttempt = library.AddSelectionForSmokeAsync();
                await Task.Delay(35);
                bool duplicateAccepted = await library.AddSelectionForSmokeAsync();
                bool heldLockAccepted = await heldLockAttempt;
                heartbeat.Stop();
                bool liveLockPreserved = File.Exists(lockPath)
                    && string.Equals(File.ReadAllText(lockPath), liveOwnerPayload, StringComparison.Ordinal);
                bool dispatcherHeartbeat = heartbeats >= 10;
                bool doubleSubmissionBlocked = heldLockAccepted
                    && !duplicateAccepted
                    && library.MutationInvocationCountForSmoke == mutationInvocationCountBeforeHeldLock + 1;
                bool busyRecovered = !library.IsBusyForSmoke
                    && library.LastMutationStatusForSmoke == AlbumMutationStatus.Busy;
                try { File.Delete(lockPath); } catch { }

                bool generationGuard = await library.VerifyReloadGenerationGuardForSmokeAsync();
                bool ioOffDispatcher = library.ReadRanOffDispatcherForSmoke
                    && library.MutationRanOffDispatcherForSmoke
                    && library.AvailabilityRanOffDispatcherForSmoke;

                var availabilityCloseLibrary = new AlbumLibraryWindow(
                    owner,
                    [],
                    [currentPng, unsupportedBmp, seedGif],
                    _ => Task.CompletedTask,
                    () => Task.CompletedTask)
                {
                    WindowStartupLocation = WindowStartupLocation.Manual,
                    Left = -20_000,
                    Top = -20_000,
                    ShowActivated = false,
                    Opacity = 0,
                };
                availabilityCloseLibrary.Show();
                await availabilityCloseLibrary.WaitForIdleForSmokeAsync();
                availabilityCloseLibrary.ConfigureMemberAvailabilityDelayForSmoke(8);
                int closeScanStartedBefore = availabilityCloseLibrary.MemberAvailabilityStartedCountForSmoke;
                int closeScanCanceledBefore = availabilityCloseLibrary.MemberAvailabilityCanceledCountForSmoke;
                bool closeScanSelected = availabilityCloseLibrary.SelectAlbumForSmoke("slow-availability");
                await availabilityCloseLibrary.WaitForMemberAvailabilityStartedForSmokeAsync(closeScanStartedBefore);
                int closeApplyCount = availabilityCloseLibrary.MemberAvailabilityApplyCountForSmoke;
                availabilityCloseLibrary.Close();
                await availabilityCloseLibrary.WaitForMemberAvailabilityIdleForSmokeAsync();
                bool closeCancelsAvailability = closeScanSelected
                    && availabilityCloseLibrary.MemberAvailabilityCanceledCountForSmoke > closeScanCanceledBefore
                    && availabilityCloseLibrary.MemberAvailabilityActiveCountForSmoke == 0
                    && availabilityCloseLibrary.MemberAvailabilityPendingCountForSmoke == 0
                    && availabilityCloseLibrary.MemberAvailabilityApplyCountForSmoke == closeApplyCount;

                int ownerReconciliationCount = 0;
                var closeRaceLibrary = new AlbumLibraryWindow(
                    owner,
                    [],
                    [currentPng, unsupportedBmp, seedGif],
                    _ => Task.CompletedTask,
                    () =>
                    {
                        Interlocked.Increment(ref ownerReconciliationCount);
                        return Task.CompletedTask;
                    })
                {
                    WindowStartupLocation = WindowStartupLocation.Manual,
                    Left = -20_000,
                    Top = -20_000,
                    ShowActivated = false,
                    Opacity = 0,
                };
                closeRaceLibrary.Show();
                await closeRaceLibrary.WaitForIdleForSmokeAsync();
                var mutationStarted = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
                using var releaseMutation = new ManualResetEventSlim(false);
                Task<bool> closeRaceMutation = closeRaceLibrary.RunMutationForSmokeAsync(() =>
                {
                    mutationStarted.TrySetResult(true);
                    releaseMutation.Wait(TimeSpan.FromSeconds(5));
                    return AlbumStore.Create(albumPath, "Close race", null, "close-race");
                }, "close-race");
                await mutationStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
                closeRaceLibrary.Close();
                releaseMutation.Set();
                bool closeRaceAccepted = await closeRaceMutation;
                AlbumReadResult closeRaceRead = AlbumStore.Read(albumPath);
                bool committedCloseReconciled = closeRaceAccepted
                    && closeRaceRead.Document?.Albums.Any(album => album.Id == "close-race") == true
                    && ownerReconciliationCount == 1;

                bool sourceFilesUntouched = File.Exists(currentPng) && File.Exists(unsupportedBmp) && File.Exists(seedGif);
                bool noResidue = !File.Exists(lockPath)
                    && !Directory.Exists(lockPath)
                    && !Directory.EnumerateFiles(smokeRoot, "*.tmp", SearchOption.TopDirectoryOnly).Any();
                ok = mixedCreated.Ok && mixedSeeded.Ok && busyCreated.Ok && slowCreated.Ok && slowSeeded.Ok
                    && presentationContract && sourceSafetyPlacementContract
                    && mixedSelected && mixedFormatFiltered && addStatusCounts && statusLanguageContract
                    && availabilityCancellation && closeCancelsAvailability && openUsesLatestRevision
                    && busySelected && liveLockPreserved && dispatcherHeartbeat
                    && doubleSubmissionBlocked && busyRecovered && generationGuard
                    && committedCloseReconciled
                    && ioOffDispatcher && actionToolTips && actionAutomationHelpText && actionFocusVisuals
                    && sourceFilesUntouched && noResidue;
                result = new
                {
                    ok,
                    presentationContract,
                    sourceSafetyPlacementContract,
                    mixedSelected,
                    mixedFormatFiltered,
                    addStatusCounts,
                    statusLanguageContract,
                    availabilityCancellation,
                    memberAvailabilityCanceledCount = library.MemberAvailabilityCanceledCountForSmoke,
                    memberAvailabilityMaxConcurrent = library.MemberAvailabilityMaxConcurrentCountForSmoke,
                    closeCancelsAvailability,
                    openUsesLatestRevision,
                    activatedAlbumCount,
                    libraryReconciliationCount,
                    busySelected,
                    readOffDispatcher = library.ReadRanOffDispatcherForSmoke,
                    mutationOffDispatcher = library.MutationRanOffDispatcherForSmoke,
                    availabilityOffDispatcher = library.AvailabilityRanOffDispatcherForSmoke,
                    generationGuard,
                    committedCloseReconciled,
                    ownerReconciliationCount,
                    dispatcherHeartbeat,
                    heartbeatCount = heartbeats,
                    doubleSubmissionBlocked,
                    mutationInvocationCount = library.MutationInvocationCountForSmoke,
                    busyRecovered,
                    lastMutationStatus = library.LastMutationStatusForSmoke?.ToString(),
                    liveLockPreserved,
                    actionToolTips,
                    actionAutomationHelpText,
                    actionFocusVisuals,
                    sourceFilesUntouched,
                    noResidue,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString() };
            }
            finally
            {
                try { File.Delete(lockPath); } catch { }
                try { library.Close(); } catch { }
                try { owner.Close(); } catch { }
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", previousAlbumPath);
            }
            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureScanBoundarySmoke(string resultPath, IReadOnlyList<string> args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? root = ArgValue(args.ToArray(), "--folder");
        object result;
        bool ok = false;
        try
        {
            if (string.IsNullOrWhiteSpace(root) || !Directory.Exists(root))
                throw new ArgumentException("scan boundary smoke requires an existing --folder");
            ScanBoundarySmokeSnapshot snapshot = PhotoViewer.Wpf.MainWindow.EnumerateImageFilesForSmoke(root);
            ok = true;
            result = new
            {
                ok = true,
                root = Path.GetFullPath(root),
                images = snapshot.Images,
                accessFailures = snapshot.AccessFailures,
                boundarySkips = snapshot.BoundarySkips,
                elapsedMs = snapshot.ElapsedMs,
            };
        }
        catch (Exception ex)
        {
            result = new { ok = false, message = ex.Message };
        }

        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
        Environment.ExitCode = ok ? 0 : 1;
        Shutdown(Environment.ExitCode);
    }

    private void CapturePartialScanSmoke(string resultPath)
    {
        static async Task<bool> WaitForPhaseAsync(MainWindow window, string phase, int timeoutMilliseconds = 4000)
        {
            var watch = Stopwatch.StartNew();
            while (watch.ElapsedMilliseconds < timeoutMilliseconds)
            {
                if (string.Equals(window.LoadPhaseForSmoke, phase, StringComparison.Ordinal))
                    return true;
                await Task.Delay(10);
            }
            return false;
        }

        static bool JsonContainsString(string path, string expected)
        {
            if (!File.Exists(path))
                return false;
            try
            {
                using JsonDocument document = JsonDocument.Parse(File.ReadAllText(path));
                return Contains(document.RootElement);
            }
            catch
            {
                return false;
            }

            bool Contains(JsonElement element)
            {
                if (element.ValueKind == JsonValueKind.String)
                    return string.Equals(element.GetString(), expected, StringComparison.OrdinalIgnoreCase);
                if (element.ValueKind == JsonValueKind.Object)
                    return element.EnumerateObject().Any(property => Contains(property.Value));
                if (element.ValueKind == JsonValueKind.Array)
                    return element.EnumerateArray().Any(Contains);
                return false;
            }
        }

        string resultFullPath = Path.GetFullPath(resultPath);
        string statePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH")
            ?? throw new InvalidOperationException("automation state path was not configured");
        string favoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH")
            ?? throw new InvalidOperationException("automation favorites path was not configured");
        string seenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH")
            ?? throw new InvalidOperationException("automation seen path was not configured");
        string recentPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH")
            ?? throw new InvalidOperationException("automation recent path was not configured");
        string jobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH")
            ?? throw new InvalidOperationException("automation jobs path was not configured");
        string smokeRoot = Path.GetDirectoryName(Path.GetFullPath(statePath))
            ?? throw new InvalidOperationException("automation root was unavailable");
        string sourcesRoot = Path.Combine(smokeRoot, "sources");
        string validRoot = Path.Combine(sourcesRoot, "01 valid root");
        string disappearingRoot = Path.Combine(sourcesRoot, "02 disappears during scan");
        string missingRoot = Path.Combine(sourcesRoot, "03 missing root");
        string canceledRoot = Path.Combine(sourcesRoot, "04 canceled root");
        string canceledMissingRoot = Path.Combine(sourcesRoot, "05 canceled missing root");
        string newerRoot = Path.Combine(sourcesRoot, "06 newer root");
        string newerMissingRoot = Path.Combine(sourcesRoot, "07 newer missing root");
        foreach (string folder in new[] { validRoot, disappearingRoot, canceledRoot, newerRoot })
            Directory.CreateDirectory(folder);
        Directory.CreateDirectory(Path.GetDirectoryName(jobsPath)!);

        WriteSmokePng(Path.Combine(validRoot, "valid-a.png"), 128, 96, Color.FromRgb(75, 120, 175));
        WriteSmokePng(Path.Combine(validRoot, "valid-b.png"), 128, 96, Color.FromRgb(95, 135, 185));
        WriteSmokePng(Path.Combine(disappearingRoot, "gone-before-enumeration.png"), 128, 96, Color.FromRgb(115, 145, 195));
        WriteSmokePng(Path.Combine(canceledRoot, "must-not-publish.png"), 128, 96, Color.FromRgb(135, 155, 205));
        WriteSmokePng(Path.Combine(newerRoot, "newer-wins.png"), 128, 96, Color.FromRgb(155, 165, 215));
        File.WriteAllText(statePath, "{\"Version\":2,\"partialScanMarker\":\"preserve\"}");
        File.WriteAllText(favoritesPath, "{}");
        File.WriteAllText(seenPath, "{}");
        File.WriteAllText(recentPath, "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"updatedAtUtc\":\"\",\"partialRecentMarker\":\"preserve\"}");
        File.WriteAllText(jobsPath, "{\"version\":1,\"jobs\":[]}");

        var sourceFingerprints = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            [validRoot] = FolderFingerprint(validRoot),
            [canceledRoot] = FolderFingerprint(canceledRoot),
            [newerRoot] = FolderFingerprint(newerRoot),
        };
        string favoritesBefore = FileFingerprint(favoritesPath);
        string jobsBefore = FileFingerprint(jobsPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var window = HiddenWindow();
        window.Show();
        window.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            try
            {
                string[] partialSet = [validRoot, disappearingRoot, missingRoot];
                window.ConfigureScanPhaseDelaysForSmoke(enumerationMilliseconds: 500, metadataMilliseconds: 0);
                Task partialTask = window.LoadFolderSetAsync(partialSet);
                bool partialEnumerationPhase = await WaitForPhaseAsync(window, "enumeration");
                Directory.Delete(disappearingRoot, recursive: true);
                await partialTask;

                List<string> partialNames = window.AllFileNamesForSmoke;
                bool validImagesPublished = !window.LandingVisibleForSmoke
                    && partialNames.Count == 2
                    && partialNames.Contains("valid-a.png", StringComparer.OrdinalIgnoreCase)
                    && partialNames.Contains("valid-b.png", StringComparer.OrdinalIgnoreCase)
                    && !partialNames.Contains("gone-before-enumeration.png", StringComparer.OrdinalIgnoreCase);
                bool requestedSetOwned = window.CurrentFolderSetForSmoke.SequenceEqual(partialSet, StringComparer.OrdinalIgnoreCase)
                    && window.LandingFolderSetForSmoke.SequenceEqual(partialSet, StringComparer.OrdinalIgnoreCase);
                string partialStatus = window.DeleteStatusForSmoke;
                bool recoverableStatus = partialStatus.Contains("unavailable", StringComparison.OrdinalIgnoreCase)
                    && partialStatus.Contains("could not be scanned", StringComparison.OrdinalIgnoreCase);
                bool partialStateOwned = partialSet.All(path => JsonContainsString(statePath, path));
                bool partialRecentOwned = partialSet.All(path => JsonContainsString(recentPath, path));
                bool oneRecentCommit = window.SharedRecentCommitAttemptCountForSmoke == 1
                    && window.SharedRecentCommitSuccessCountForSmoke == 1;

                string stateAfterPartial = FileFingerprint(statePath);
                string recentAfterPartial = FileFingerprint(recentPath);
                window.ConfigureScanPhaseDelaysForSmoke(enumerationMilliseconds: 700, metadataMilliseconds: 0);
                Task canceledTask = window.LoadFolderSetAsync([canceledRoot, canceledMissingRoot]);
                bool canceledEnumerationPhase = await WaitForPhaseAsync(window, "enumeration");
                bool cancelAccepted = window.CancelActiveScanForSmoke();
                bool canceledImmediateIsolation = string.Equals(stateAfterPartial, FileFingerprint(statePath), StringComparison.Ordinal)
                    && string.Equals(recentAfterPartial, FileFingerprint(recentPath), StringComparison.Ordinal)
                    && window.CurrentFolderSetForSmoke.SequenceEqual(partialSet, StringComparer.OrdinalIgnoreCase)
                    && window.AllFileNamesForSmoke.SequenceEqual(partialNames, StringComparer.OrdinalIgnoreCase);

                string[] newerSet = [newerRoot, newerMissingRoot];
                window.ConfigureScanPhaseDelaysForSmoke(enumerationMilliseconds: 0, metadataMilliseconds: 0);
                await window.LoadFolderSetAsync(newerSet);
                await canceledTask;
                bool newerRunWon = !window.LandingVisibleForSmoke
                    && window.CurrentFolderSetForSmoke.SequenceEqual(newerSet, StringComparer.OrdinalIgnoreCase)
                    && window.LandingFolderSetForSmoke.SequenceEqual(newerSet, StringComparer.OrdinalIgnoreCase)
                    && window.AllFileNamesForSmoke.SequenceEqual(["newer-wins.png"], StringComparer.OrdinalIgnoreCase)
                    && window.DeleteStatusForSmoke.Contains("unavailable", StringComparison.OrdinalIgnoreCase);
                bool canceledRunNeverPersisted = !JsonContainsString(statePath, canceledRoot)
                    && !JsonContainsString(statePath, canceledMissingRoot)
                    && !JsonContainsString(recentPath, canceledRoot)
                    && !JsonContainsString(recentPath, canceledMissingRoot);
                bool successfulSetsPersisted = partialSet.All(path => JsonContainsString(recentPath, path))
                    && newerSet.All(path => JsonContainsString(statePath, path) && JsonContainsString(recentPath, path));
                bool exactRecentOwnership = window.SharedRecentCommitAttemptCountForSmoke == 2
                    && window.SharedRecentCommitSuccessCountForSmoke == 2;
                bool unknownFieldsPreserved = JsonContainsString(statePath, "preserve")
                    && JsonContainsString(recentPath, "preserve");
                bool sourceUntouched = sourceFingerprints.All(pair => string.Equals(pair.Value, FolderFingerprint(pair.Key), StringComparison.Ordinal));
                bool unrelatedCacheUntouched = string.Equals(favoritesBefore, FileFingerprint(favoritesPath), StringComparison.Ordinal)
                    && string.Equals(jobsBefore, FileFingerprint(jobsPath), StringComparison.Ordinal);
                bool missingRootsStayedMissing = !Directory.Exists(missingRoot)
                    && !Directory.Exists(canceledMissingRoot)
                    && !Directory.Exists(newerMissingRoot);
                bool loadCtsBalanced = window.LoadCtsCreatedCountForSmoke == 3
                    && window.LoadCtsRetiredCountForSmoke == window.LoadCtsCreatedCountForSmoke;
                bool isolated = new[] { statePath, favoritesPath, seenPath, recentPath, jobsPath }
                    .All(path => Path.GetFullPath(path).StartsWith(Path.GetFullPath(smokeRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase));
                bool residueFree = NoPersistenceResidue(smokeRoot);
                ok = partialEnumerationPhase && validImagesPublished && requestedSetOwned && recoverableStatus
                    && partialStateOwned && partialRecentOwned && oneRecentCommit
                    && canceledEnumerationPhase && cancelAccepted && canceledImmediateIsolation
                    && newerRunWon && canceledRunNeverPersisted && successfulSetsPersisted && exactRecentOwnership
                    && unknownFieldsPreserved && sourceUntouched && unrelatedCacheUntouched
                    && missingRootsStayedMissing && loadCtsBalanced && isolated && residueFree;
                result = new
                {
                    ok,
                    message = ok
                        ? "partial multi-root scans retained valid images and requested roots; canceled/stale work never took ownership"
                        : "partial multi-root scan publication, recovery, or ownership contract failed",
                    partialEnumerationPhase,
                    validImagesPublished,
                    requestedSetOwned,
                    recoverableStatus,
                    partialStatus,
                    finalStatus = window.DeleteStatusForSmoke,
                    partialStateOwned,
                    partialRecentOwned,
                    oneRecentCommit,
                    canceledEnumerationPhase,
                    cancelAccepted,
                    canceledImmediateIsolation,
                    newerRunWon,
                    canceledRunNeverPersisted,
                    successfulSetsPersisted,
                    exactRecentOwnership,
                    unknownFieldsPreserved,
                    sourceUntouched,
                    unrelatedCacheUntouched,
                    missingRootsStayedMissing,
                    loadCtsBalanced,
                    isolated,
                    residueFree,
                    partialNames,
                    currentFolderSet = window.CurrentFolderSetForSmoke,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString(), smokeRoot };
            }
            finally
            {
                try { if (window.IsLoaded) window.Close(); } catch { }
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            try { if (Directory.Exists(smokeRoot)) Directory.Delete(smokeRoot, recursive: true); } catch { }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureScanMaterializationRaceSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string statePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH")
            ?? throw new InvalidOperationException("automation state path was not configured");
        string favoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH")
            ?? throw new InvalidOperationException("automation favorites path was not configured");
        string seenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH")
            ?? throw new InvalidOperationException("automation seen path was not configured");
        string recentPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH")
            ?? throw new InvalidOperationException("automation recent path was not configured");
        string jobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH")
            ?? throw new InvalidOperationException("automation jobs path was not configured");
        string smokeRoot = Path.GetDirectoryName(Path.GetFullPath(statePath))
            ?? throw new InvalidOperationException("automation root was unavailable");
        string folder = Path.Combine(smokeRoot, "sources", "materialization race");
        string alphaPath = Path.Combine(folder, "alpha.png");
        string bravoPath = Path.Combine(folder, "bravo.png");
        string charliePath = Path.Combine(folder, "charlie.png");
        Directory.CreateDirectory(folder);
        Directory.CreateDirectory(Path.GetDirectoryName(jobsPath)!);
        WriteSmokePng(alphaPath, 96, 72, Color.FromRgb(65, 125, 195));
        WriteSmokePng(bravoPath, 96, 72, Color.FromRgb(195, 95, 85));
        WriteSmokePng(charliePath, 96, 72, Color.FromRgb(85, 175, 115));
        DateTime fixtureTime = new(2026, 7, 18, 2, 0, 0, DateTimeKind.Utc);
        File.SetLastWriteTimeUtc(alphaPath, fixtureTime.AddMinutes(2));
        File.SetLastWriteTimeUtc(bravoPath, fixtureTime.AddMinutes(1));
        File.SetLastWriteTimeUtc(charliePath, fixtureTime);
        File.WriteAllText(statePath, "{\"Version\":2,\"materializationRaceMarker\":\"preserve\"}");
        File.WriteAllText(favoritesPath, "{}");
        File.WriteAllText(seenPath, "{}");
        File.WriteAllText(recentPath, "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"updatedAtUtc\":\"\",\"raceRecentMarker\":\"preserve\"}");
        File.WriteAllText(jobsPath, "{\"version\":1,\"jobs\":[]}");

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var window = HiddenWindow();
        window.Show();
        window.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            string sourceAfterInjectedDelete = "";
            bool enhancementStateInjectedAfterSnapshot = false;
            try
            {
                await window.LoadFolderAsync(folder);
                window.SetSortByForSmoke("name");
                foreach (string name in new[] { "alpha.png", "charlie.png", "bravo.png" })
                {
                    if (!window.SelectFileNameForSmoke(name))
                        throw new InvalidOperationException($"could not select {name} before the race");
                }
                bool surfacePrepared = window.OpenSelectedPreviewTabForSmoke()
                    && window.TogglePreviewTabPinForSmoke("bravo.png")
                    && window.OpenModalForSmoke()
                    && window.FocusModalCloseForSmoke();
                File.WriteAllText(favoritesPath, "{\"broken\":[]}");
                string favoritesBefore = FileFingerprint(favoritesPath);
                string seenBefore = FileFingerprint(seenPath);
                string recentBefore = FileFingerprint(recentPath);
                string jobsBefore = FileFingerprint(jobsPath);

                window.SetBeforeMaterializeFilesForSmoke(() =>
                {
                    enhancementStateInjectedAfterSnapshot =
                        window.InjectCatalogEnhancedStateForSmoke("alpha.png");
                    File.Delete(bravoPath);
                    sourceAfterInjectedDelete = FolderFingerprint(folder);
                });
                await window.RefreshActiveFolderForSmokeAsync();
                await window.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.ContextIdle);

                List<string> catalog = window.AllFileNamesForSmoke;
                string? selectedPath = window.SelectedPathForSmoke;
                ViewerState? state = ReadPersistedState(statePath);
                bool vanishedSourceSkipped = !File.Exists(bravoPath)
                    && catalog.SequenceEqual(["alpha.png", "charlie.png"], StringComparer.OrdinalIgnoreCase)
                    && window.LastLoadMetrics?.FileCount == 2;
                bool recoverableWarning = window.DeleteStatusVisibleForSmoke
                    && window.DeleteStatusForSmoke.Contains("became unavailable", StringComparison.OrdinalIgnoreCase)
                    && window.DeleteStatusForSmoke.Contains("Favorites", StringComparison.OrdinalIgnoreCase)
                    && window.DeleteStatusForSmoke.Contains("invalid or newer", StringComparison.OrdinalIgnoreCase);
                bool validSelectionAndModal = surfacePrepared
                    && !string.IsNullOrWhiteSpace(selectedPath)
                    && File.Exists(selectedPath)
                    && catalog.Contains(Path.GetFileName(selectedPath), StringComparer.OrdinalIgnoreCase)
                    && window.ModalVisibleForSmoke
                    && string.Equals(window.ModalSourcePathForSmoke, selectedPath, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(window.ModalDisplayPathForSmoke, selectedPath, StringComparison.OrdinalIgnoreCase)
                    && window.IsModalDialogFocusedForSmoke
                    && window.ModalFocusTrapConfiguredForSmoke;
                bool stateReconciled = state is not null
                    && string.Equals(state.SelectedPath, selectedPath, StringComparison.OrdinalIgnoreCase)
                    && state.PreviewTabPaths?.All(path => !string.Equals(path, bravoPath, StringComparison.OrdinalIgnoreCase)) != false
                    && state.PinnedPreviewPaths?.All(path => !string.Equals(path, bravoPath, StringComparison.OrdinalIgnoreCase)) != false
                    && !string.Equals(state.ActivePreviewTabPath, bravoPath, StringComparison.OrdinalIgnoreCase)
                    && state.ExtensionData?.ContainsKey("materializationRaceMarker") == true;
                bool storesUnchanged = string.Equals(favoritesBefore, FileFingerprint(favoritesPath), StringComparison.Ordinal)
                    && string.Equals(seenBefore, FileFingerprint(seenPath), StringComparison.Ordinal)
                    && string.Equals(recentBefore, FileFingerprint(recentPath), StringComparison.Ordinal)
                    && string.Equals(jobsBefore, FileFingerprint(jobsPath), StringComparison.Ordinal);
                bool sourcesReadOnly = !string.IsNullOrWhiteSpace(sourceAfterInjectedDelete)
                    && string.Equals(sourceAfterInjectedDelete, FolderFingerprint(folder), StringComparison.Ordinal);
                bool enhancementSnapshotDetached = enhancementStateInjectedAfterSnapshot
                    && window.EnhancedStoreCountForSmoke == 1
                    && !window.EnhancedForFileForSmoke("alpha.png");
                bool isolated = new[] { statePath, favoritesPath, seenPath, recentPath, jobsPath, alphaPath, bravoPath, charliePath }
                    .All(path => Path.GetFullPath(path).StartsWith(Path.GetFullPath(smokeRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase));
                bool residueFree = NoPersistenceResidue(smokeRoot);
                ok = vanishedSourceSkipped && recoverableWarning && validSelectionAndModal
                    && stateReconciled && storesUnchanged && sourcesReadOnly
                    && enhancementSnapshotDetached && isolated && residueFree;
                result = new
                {
                    ok,
                    message = ok
                        ? "a source disappearing after the existence snapshot was skipped without crashing; warning, selection, modal, state, and ownership stayed coherent"
                        : "scan materialization race recovery contract failed",
                    vanishedSourceSkipped,
                    recoverableWarning,
                    warning = window.DeleteStatusForSmoke,
                    validSelectionAndModal,
                    stateReconciled,
                    storesUnchanged,
                    sourcesReadOnly,
                    enhancementSnapshotDetached,
                    isolated,
                    residueFree,
                    catalog,
                    selectedPath,
                    modalSourcePath = window.ModalSourcePathForSmoke,
                    modalDisplayPath = window.ModalDisplayPathForSmoke,
                    fileCountMetric = window.LastLoadMetrics?.FileCount,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString(), smokeRoot };
            }
            finally
            {
                try { if (window.IsLoaded) window.Close(); } catch { }
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            try { if (Directory.Exists(smokeRoot)) Directory.Delete(smokeRoot, recursive: true); } catch { }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureWindowWorkAreaSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var compactStartupWorkArea = new Rect(80, 40, 760, 480);
        var window = HiddenWindow();
        window.SetCurrentMonitorWorkAreaForSmoke(compactStartupWorkArea);
        window.Show();
        MainWindow? wideProbe = null;
        window.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            try
            {
                static bool SameRect(Rect left, Rect right)
                    => Math.Abs(left.Left - right.Left) < 0.01
                        && Math.Abs(left.Top - right.Top) < 0.01
                        && Math.Abs(left.Width - right.Width) < 0.01
                        && Math.Abs(left.Height - right.Height) < 0.01;
                static bool Contains(Rect outer, Rect inner)
                    => inner.Left >= outer.Left - 0.01
                        && inner.Top >= outer.Top - 0.01
                        && inner.Right <= outer.Right + 0.01
                        && inner.Bottom <= outer.Bottom + 0.01;
                Rect desktopWorkArea = SystemParameters.WorkArea;
                Rect LiveWorkArea(double maxWidth, double maxHeight, double margin)
                {
                    double width = Math.Min(maxWidth, Math.Max(1, desktopWorkArea.Width - (margin * 2)));
                    double height = Math.Min(maxHeight, Math.Max(1, desktopWorkArea.Height - (margin * 2)));
                    return new Rect(
                        desktopWorkArea.Left + ((desktopWorkArea.Width - width) / 2),
                        desktopWorkArea.Top + ((desktopWorkArea.Height - height) / 2),
                        width,
                        height);
                }

                async Task SettleLayoutAsync()
                {
                    await window.Dispatcher.InvokeAsync(window.UpdateLayout, DispatcherPriority.Render);
                    await window.Dispatcher.InvokeAsync(window.UpdateLayout, DispatcherPriority.ContextIdle);
                }

                // Arrange the wide visual contract independently of the CI
                // desktop resolution. The shown window below remains bound to
                // the real desktop for monitor/maximize behavior.
                wideProbe = HiddenWindow();
                wideProbe.SuppressStatePersistence();
                wideProbe.Show();
                wideProbe.SetUiLanguageForSmoke("ja");
                wideProbe.ApplyWorkbenchLayoutWidthForSmoke(1280);
                if (wideProbe.Content is FrameworkElement wideRoot)
                {
                    var wideSize = new Size(1280, 820);
                    wideRoot.Measure(wideSize);
                    wideRoot.Arrange(new Rect(new Point(), wideSize));
                    wideRoot.UpdateLayout();
                }
                bool wideAdaptiveOff = !wideProbe.AdaptiveWorkbenchForSmoke;
                bool wideSettingsPinned = wideProbe.SidebarSettingsPinnedForSmoke;
                bool wideScrollContained = wideProbe.SidebarScrollContractForSmoke;
                bool wideButtonTextFits = wideProbe.SidebarButtonTextFitsForSmoke;
                List<string> wideClippedButtons = wideProbe.SidebarClippedButtonNamesForSmoke;
                bool wideChromeContained = wideProbe.VisibleWorkbenchChromeContainedForSmoke;
                double wideDragRegionWidth = wideProbe.HeaderDragRegionWidthForSmoke;
                bool wideDragRegions = wideProbe.WindowDragRegionsContractForSmoke;
                bool wideSidebarLayout = wideAdaptiveOff
                    && wideSettingsPinned
                    && wideScrollContained
                    && wideButtonTextFits
                    && wideChromeContained
                    && wideDragRegions
                    && wideDragRegionWidth >= 95;
                wideProbe.SetUiLanguageForSmoke("en");

                // Startup must normalize the initial design size before the
                // user can reach custom maximize controls on a compact work area.
                await SettleLayoutAsync();
                Rect compactStartupBounds = window.WindowBoundsForSmoke;
                Size compactStartupMinimum = window.EffectiveWindowMinimumForSmoke;
                bool compactStartupContained = !window.FakeMaximizedForSmoke
                    && SameRect(compactStartupBounds, compactStartupWorkArea)
                    && SameRect(
                        new Rect(0, 0, compactStartupMinimum.Width, compactStartupMinimum.Height),
                        new Rect(0, 0, compactStartupWorkArea.Width, compactStartupWorkArea.Height))
                    && window.AdaptiveWorkbenchForSmoke
                    && window.HeaderDragRegionWidthForSmoke >= 95
                    && window.WindowDragRegionsContractForSmoke
                    && window.VisibleWorkbenchChromeContainedForSmoke;

                // Keep the injected secondary work area inside the CI desktop's
                // physical bounds so Windows does not clamp an intentionally
                // nonexistent monitor. Its offset/size still differs from the
                // primary work area and proves the provider is authoritative.
                var secondMonitorWorkArea = LiveWorkArea(960, 600, 20);
                double initialWidth = Math.Min(900, secondMonitorWorkArea.Width);
                double initialHeight = Math.Min(560, secondMonitorWorkArea.Height);
                var initial = new Rect(
                    secondMonitorWorkArea.Left + ((secondMonitorWorkArea.Width - initialWidth) / 2),
                    secondMonitorWorkArea.Top + ((secondMonitorWorkArea.Height - initialHeight) / 2),
                    initialWidth,
                    initialHeight);
                window.Left = initial.Left;
                window.Top = initial.Top;
                window.Width = initial.Width;
                window.Height = initial.Height;
                initial = window.WindowBoundsForSmoke;
                window.SetCurrentMonitorWorkAreaForSmoke(secondMonitorWorkArea);
                window.ToggleMaximizeForSmoke();
                Rect maximized = window.WindowBoundsForSmoke;
                bool usedCurrentMonitor = window.FakeMaximizedForSmoke && SameRect(maximized, secondMonitorWorkArea);
                window.ToggleMaximizeForSmoke();
                Rect restored = window.WindowBoundsForSmoke;
                bool restoredExactly = !window.FakeMaximizedForSmoke && SameRect(restored, initial);

                // A disconnected monitor leaves the saved normal bounds far
                // outside the current desktop. Restore must keep the complete
                // window inside the new current work area.
                var changedWorkArea = LiveWorkArea(940, 580, 30);
                var disconnectedBounds = new Rect(2400, 140, 940, 570);
                window.SetCurrentMonitorWorkAreaForSmoke(changedWorkArea);
                Rect disconnectedRestore = window.RestoreFromFakeMaximizeForSmoke(disconnectedBounds);
                Rect disconnectedExpected = PhotoViewer.Wpf.MainWindow.NormalizeRestoreBoundsForSmoke(disconnectedBounds, changedWorkArea);
                bool disconnectedContained = SameRect(disconnectedRestore, disconnectedExpected)
                    && Contains(changedWorkArea, disconnectedRestore);

                // Resolution reductions must cap both dimensions and position,
                // rather than restoring a normal window larger than the screen.
                var oversizedBounds = new Rect(-500, -400, 2400, 1400);
                Rect oversizedRestore = window.RestoreFromFakeMaximizeForSmoke(oversizedBounds);
                bool oversizedContained = SameRect(oversizedRestore, changedWorkArea)
                    && Contains(changedWorkArea, oversizedRestore);

                // WPF bounds and monitor work areas are DIPs. A changed DIP work
                // area models a PerMonitorV2 DPI transition without mutating the
                // machine display configuration used by the verifier.
                var dpiChangedWorkArea = new Rect(-1100, 40, 1100, 640);
                var preDpiBounds = new Rect(-1520, 120, 1380, 780);
                Rect dpiEquivalentRestore = PhotoViewer.Wpf.MainWindow.NormalizeRestoreBoundsForSmoke(preDpiBounds, dpiChangedWorkArea);
                bool dpiEquivalentContained = Contains(dpiChangedWorkArea, dpiEquivalentRestore)
                    && dpiEquivalentRestore.Width == dpiChangedWorkArea.Width
                    && dpiEquivalentRestore.Height == dpiChangedWorkArea.Height;

                // Per-monitor DPI can reduce a physical work area below the
                // normal-window design minimum in DIPs. Fake maximize must
                // temporarily lower the effective minimums so no edge, footer,
                // or pinned navigation is coerced beyond that work area.
                var compactWorkArea = new Rect(80, 40, 760, 480);
                window.Left = initial.Left;
                window.Top = initial.Top;
                window.Width = initial.Width;
                window.Height = initial.Height;
                window.SetCurrentMonitorWorkAreaForSmoke(compactWorkArea);
                window.ToggleMaximizeForSmoke();
                await SettleLayoutAsync();
                Rect compactMaximized = window.WindowBoundsForSmoke;
                Size compactMinimum = window.EffectiveWindowMinimumForSmoke;
                bool compactContained = window.FakeMaximizedForSmoke
                    && SameRect(compactMaximized, compactWorkArea)
                    && SameRect(new Rect(0, 0, compactMinimum.Width, compactMinimum.Height), new Rect(0, 0, compactWorkArea.Width, compactWorkArea.Height))
                    && window.AdaptiveWorkbenchForSmoke
                    && window.SearchMinimumWidthForSmoke <= 140
                    && window.HeaderDragRegionWidthForSmoke >= 95
                    && window.WindowDragRegionsContractForSmoke
                    && window.VisibleWorkbenchChromeContainedForSmoke;
                window.ToggleMaximizeForSmoke();

                var shortWorkArea = new Rect(20, 20, 960, 500);
                window.Left = 40;
                window.Top = 40;
                window.Width = 940;
                window.Height = 570;
                window.SetCurrentMonitorWorkAreaForSmoke(shortWorkArea);
                window.ToggleMaximizeForSmoke();
                await SettleLayoutAsync();
                Rect shortMaximized = window.WindowBoundsForSmoke;
                Size shortMinimum = window.EffectiveWindowMinimumForSmoke;
                bool shortContained = window.FakeMaximizedForSmoke
                    && SameRect(shortMaximized, shortWorkArea)
                    && Math.Abs(shortMinimum.Width - 900) < 0.01
                    && Math.Abs(shortMinimum.Height - shortWorkArea.Height) < 0.01
                    && window.AdaptiveWorkbenchForSmoke
                    && window.VisibleWorkbenchChromeContainedForSmoke;
                window.ToggleMaximizeForSmoke();

                window.Left = initial.Left;
                window.Top = initial.Top;
                window.Width = initial.Width;
                window.Height = initial.Height;
                initial = window.WindowBoundsForSmoke;
                window.SetThrowingMonitorWorkAreaForSmoke();
                window.ToggleMaximizeForSmoke();
                Rect fallback = window.WindowBoundsForSmoke;
                bool safeFallback = window.FakeMaximizedForSmoke && SameRect(fallback, SystemParameters.WorkArea);
                window.ToggleMaximizeForSmoke();
                Rect fallbackExpected = PhotoViewer.Wpf.MainWindow.NormalizeRestoreBoundsForSmoke(initial, SystemParameters.WorkArea);
                bool fallbackRestored = !window.FakeMaximizedForSmoke
                    && SameRect(window.WindowBoundsForSmoke, fallbackExpected);
                var fallbackOffscreenBounds = new Rect(5000, 5000, 1600, 900);
                Rect fallbackNormalized = window.RestoreFromFakeMaximizeForSmoke(fallbackOffscreenBounds);
                bool fallbackOffscreenContained = Contains(SystemParameters.WorkArea, fallbackNormalized);
                ok = usedCurrentMonitor
                    && wideSidebarLayout
                    && compactStartupContained
                    && restoredExactly
                    && disconnectedContained
                    && oversizedContained
                    && dpiEquivalentContained
                    && compactContained
                    && shortContained
                    && safeFallback
                    && fallbackRestored
                    && fallbackOffscreenContained;
                result = new
                {
                    ok,
                    message = ok
                        ? "fake maximize and restore stayed current-monitor-safe across topology, resolution, and DPI-equivalent changes"
                        : $"window work-area contract failed: wide={wideSidebarLayout} startup={compactStartupContained} adaptiveOff={wideAdaptiveOff} pinned={wideSettingsPinned} scroll={wideScrollContained} text={wideButtonTextFits}[{string.Join(',', wideClippedButtons)}] chrome={wideChromeContained} drag={wideDragRegionWidth:0.##} compact={compactContained} short={shortContained}",
                    initial,
                    wideSidebarLayout,
                    wideAdaptiveOff,
                    wideSettingsPinned,
                    wideScrollContained,
                    wideButtonTextFits,
                    wideClippedButtons,
                    wideChromeContained,
                    wideDragRegionWidth,
                    compactStartupWorkArea,
                    compactStartupBounds,
                    compactStartupMinimum,
                    compactStartupContained,
                    secondMonitorWorkArea,
                    maximized,
                    restored,
                    fallback,
                    fallbackExpected,
                    usedCurrentMonitor,
                    restoredExactly,
                    changedWorkArea,
                    disconnectedBounds,
                    disconnectedRestore,
                    disconnectedContained,
                    oversizedBounds,
                    oversizedRestore,
                    oversizedContained,
                    dpiChangedWorkArea,
                    preDpiBounds,
                    dpiEquivalentRestore,
                    dpiEquivalentContained,
                    compactWorkArea,
                    compactMaximized,
                    compactMinimum,
                    compactContained,
                    shortWorkArea,
                    shortMaximized,
                    shortMinimum,
                    shortContained,
                    safeFallback,
                    fallbackRestored,
                    fallbackOffscreenBounds,
                    fallbackNormalized,
                    fallbackOffscreenContained,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.Message };
            }
            finally
            {
                try { wideProbe?.Close(); } catch { }
                try { window.ResetCurrentMonitorWorkAreaForSmoke(); } catch { }
                try { window.Close(); } catch { }
            }

            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static string? _styleStateForwardCompatSmokeStorageRoot;

    private static void ConfigureAutomationStorage(IReadOnlyList<string> args)
    {
        ValidateAutomationPathArguments(args);

        bool styleStateForwardCompatSmoke = args.Any(static arg =>
            string.Equals(
                arg,
                "--style-state-forward-compat-smoke",
                StringComparison.Ordinal));
        string root;
        if (styleStateForwardCompatSmoke)
        {
            if (!string.IsNullOrWhiteSpace(
                    ArgValue(
                        args.ToArray(),
                        "--automation-storage-slot")))
            {
                throw new ArgumentException(
                    "The Style state forward-compat smoke does not support a shared automation storage slot.");
            }

            root = Directory.CreateTempSubdirectory(
                    StyleStateSmokeTempDirectoryPrefix)
                .FullName;
            _styleStateForwardCompatSmokeStorageRoot = root;
        }
        else
        {
            root = ResolveAutomationStorageRoot(args);
        }
        ConfigureAutomationStorageRoot(root);
    }

    private static void ConfigureVideoV2ReaderSmokeStorage(string resultPath)
    {
        string fullResultPath = Path.GetFullPath(resultPath);
        string tempRoot = Path.GetFullPath(Path.GetTempPath())
            .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        string tempPrefix = tempRoot + Path.DirectorySeparatorChar;
        if (!fullResultPath.StartsWith(
                tempPrefix,
                StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException(
                "The video v2 reader smoke result must stay under TEMP.");
        }

        string? resultDirectory = Path.GetDirectoryName(fullResultPath);
        if (string.IsNullOrWhiteSpace(resultDirectory))
            throw new ArgumentException("The video v2 reader result path is invalid.");
        if (!Directory.Exists(resultDirectory))
        {
            throw new ArgumentException(
                "The video v2 reader result directory must already exist.");
        }
        ConfigureAutomationStorageRoot(resultDirectory);
    }

    private static void ConfigureAutomationStorageRoot(string root)
    {
        Directory.CreateDirectory(Path.Combine(root, "enhance"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", Path.Combine(root, "state.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", Path.Combine(root, "favorites.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", Path.Combine(root, "seen.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", Path.Combine(root, "recent-folders.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH", Path.Combine(root, "search-history.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", Path.Combine(root, "enhance", "jobs.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", Path.Combine(root, "settings.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", Path.Combine(root, "albums.json"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY", Path.Combine(root, "metadata-index"));
    }

    private static string ResolveAutomationStorageRoot(IReadOnlyList<string> args)
    {
        string? requestedSlot = ArgValue(args.ToArray(), "--automation-storage-slot");
        if (string.IsNullOrWhiteSpace(requestedSlot))
        {
            return Directory.CreateTempSubdirectory(
                    "photoviewer-wpf-automation-")
                .FullName;
        }

        if (!string.Equals(
                requestedSlot,
                "metadata-index-cross-process-v1",
                StringComparison.Ordinal))
        {
            throw new ArgumentException(
                "Automation storage slot is unsupported.");
        }

        // This fixed slot is safe to reuse because the verifier gives both
        // child processes the same unique TEMP root. No caller-provided path
        // reaches a filesystem operation.
        return Path.Combine(
            Path.GetTempPath(),
            "pv-mi-x1");
    }

    // Automation fixtures never inherit CLI, result-file, or shared-state
    // paths. Keep the app-owned GUID child directly under OS TEMP so a portable
    // build located inside a source checkout does not place fixtures inside the
    // product's protected project roots.
    private static string CreateManagedAutomationRoot()
        => Directory.CreateTempSubdirectory(
            "photoviewer-wpf-automation-").FullName;

    private static string ResolveLegacySharedDataRootForActivation()
    {
        foreach (string start in new[] { Environment.CurrentDirectory, AppContext.BaseDirectory })
        {
            string root = PhotoViewer.Wpf.MainWindow.ResolveSharedProjectRootForSmoke(start);
            if (File.Exists(Path.Combine(root, "project.toml")))
                return Path.Combine(root, ".cache");
        }

        return Path.Combine(Environment.CurrentDirectory, ".cache");
    }

    private static void ValidateAutomationPathArguments(IReadOnlyList<string> args)
    {
        string tempRoot = Path.GetFullPath(Path.GetTempPath());
        string[] commandLine = args.ToArray();
        string[] protectedOptions = [
            "--state-path",
            "--favorites-path",
            "--seen-path",
            "--recent-path",
            "--search-history-path",
            "--enhancement-jobs-path",
            "--key-root",
            "--target-path",
        ];

        foreach (string option in protectedOptions)
        {
            string? candidate = ArgValue(commandLine, option);
            if (string.IsNullOrWhiteSpace(candidate))
                continue;

            string fullPath;
            try
            {
                fullPath = Path.GetFullPath(candidate);
            }
            catch (Exception ex)
            {
                throw new ArgumentException($"Automation {option} path is invalid: {ex.Message}");
            }

            if (!fullPath.StartsWith(tempRoot, StringComparison.OrdinalIgnoreCase))
                throw new ArgumentException($"Automation {option} must be under the temp directory. Refusing to touch '{fullPath}'.");
        }
    }

    private void CaptureAutomationIsolationSmoke(string resultPath)
    {
        string syntheticPositionalFolder = Path.Combine(Path.GetTempPath(), "aibos-image-portrait-smoke");
        bool positionalFolderRemainsInteractive = !IsAutomationInvocation([
            "PhotoViewer.Wpf.exe",
            syntheticPositionalFolder,
        ]);
        bool knownSmokeIsIsolated = IsAutomationInvocation(["PhotoViewer.Wpf.exe", "--p1a-smoke", "result.json"]);
        bool screenshotIsIsolated = IsAutomationInvocation(["PhotoViewer.Wpf.exe", "--shot", "shot.png"]);
        bool ok = positionalFolderRemainsInteractive
            && knownSmokeIsIsolated
            && screenshotIsIsolated;
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(resultPath))!);
        File.WriteAllText(resultPath, JsonSerializer.Serialize(new
        {
            ok,
            positionalFolderRemainsInteractive,
            knownSmokeIsIsolated,
            screenshotIsIsolated,
        }));
        Shutdown(ok ? 0 : 1);
    }

    private void CaptureDiagnosticsSmoke(string resultPath)
    {
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var win = HiddenWindow();
        win.Show();
        win.Dispatcher.InvokeAsync(() =>
        {
            win.OpenAppSettingsForSmoke();
            win.Dispatcher.BeginInvoke(() =>
            {
            string existingRoot = Path.GetDirectoryName(Path.GetFullPath(win.StatePathForSmoke))
                ?? throw new InvalidOperationException("diagnostics automation root was unavailable");
            string missingRoot = Path.Combine(existingRoot, "shared-data-location-not-created");
            SharedDataLocationSmokeSnapshot shared = win.CaptureSharedDataLocationForSmoke(
                "shared",
                existingRoot,
                directoryExists: true,
                launcherBehavior: "success");
            SharedDataLocationSmokeSnapshot legacy = win.CaptureSharedDataLocationForSmoke(
                "legacy",
                existingRoot,
                directoryExists: true,
                launcherBehavior: "success");
            SharedDataLocationSmokeSnapshot uninitialized = win.CaptureSharedDataLocationForSmoke(
                "legacy-uninitialized",
                missingRoot,
                directoryExists: false,
                launcherBehavior: "success");
            SharedDataLocationSmokeSnapshot overrides = win.CaptureSharedDataLocationForSmoke(
                "overrides",
                existingRoot,
                directoryExists: false,
                launcherBehavior: "success");
            SharedDataLocationSmokeSnapshot shellFailure = win.CaptureSharedDataLocationForSmoke(
                "shared",
                existingRoot,
                directoryExists: true,
                launcherBehavior: "throw");
            win.FocusDiagnosticsForSmoke();
            DiagnosticsSmokeSnapshot success = win.CopyDiagnosticsForSmoke(injectClipboardFailure: false);
            DiagnosticsSmokeSnapshot failure = win.CopyDiagnosticsForSmoke(injectClipboardFailure: true);
            bool doneReachable = win.FocusAppSettingsDoneForSmoke();
            string payload = success.CopyText;
            bool privateDataAbsent = !payload.Contains(win.StatePathForSmoke, StringComparison.OrdinalIgnoreCase)
                && !payload.Contains(win.FavoritesPathForSmoke, StringComparison.OrdinalIgnoreCase)
                && !payload.Contains(win.SeenPathForSmoke, StringComparison.OrdinalIgnoreCase)
                && !payload.Contains("\\", StringComparison.Ordinal)
                && !payload.Contains("prompt", StringComparison.OrdinalIgnoreCase);
            bool sharedLocation = shared.Kind == "shared"
                && shared.ModeText.Contains("Aibos shared data", StringComparison.Ordinal)
                && string.Equals(shared.DisplayPath, existingRoot, StringComparison.OrdinalIgnoreCase)
                && shared.OpenEnabled
                && shared.Opened
                && shared.LauncherInvoked
                && string.Equals(shared.FileName, "explorer.exe", StringComparison.OrdinalIgnoreCase)
                && shared.Arguments.Count == 1
                && string.Equals(shared.Arguments[0], existingRoot, StringComparison.OrdinalIgnoreCase)
                && string.IsNullOrEmpty(shared.ArgumentsText)
                && shared.UseShellExecute
                && shared.Status.Contains("No shared data was changed", StringComparison.Ordinal)
                && shared.SurfaceContract
                && shared.SettingsFocused;
            bool legacyLocation = legacy.Kind == "legacy"
                && legacy.ModeText.Contains("Local Aibos data", StringComparison.Ordinal)
                && string.Equals(legacy.DisplayPath, existingRoot, StringComparison.OrdinalIgnoreCase)
                && legacy.Opened
                && legacy.UseShellExecute;
            bool uninitializedSafe = uninitialized.Kind == "legacy-uninitialized"
                && string.Equals(uninitialized.DisplayPath, missingRoot, StringComparison.OrdinalIgnoreCase)
                && !uninitialized.OpenEnabled
                && !uninitialized.Opened
                && !uninitialized.LauncherInvoked
                && uninitialized.Status.Contains("did not create", StringComparison.OrdinalIgnoreCase)
                && !Directory.Exists(missingRoot);
            bool overridesSafe = overrides.Kind == "overrides"
                && string.Equals(overrides.DisplayPath, "No single data folder", StringComparison.Ordinal)
                && !overrides.OpenEnabled
                && !overrides.Opened
                && !overrides.LauncherInvoked;
            bool shellFailureSafe = shellFailure.OpenEnabled
                && !shellFailure.Opened
                && shellFailure.LauncherInvoked
                && shellFailure.UseShellExecute
                && shellFailure.Status.Contains("could not be opened", StringComparison.OrdinalIgnoreCase);
            bool ok = success.Copied && !failure.Copied && failure.Status.Contains("could not be copied", StringComparison.OrdinalIgnoreCase) && doneReachable
                && success.SurfaceContract && success.SettingsFocused && privateDataAbsent
                && payload.Contains("PhotoViewer.Wpf", StringComparison.Ordinal) && payload.Contains("Build:", StringComparison.Ordinal)
                && payload.Contains("Process:", StringComparison.Ordinal) && payload.Contains("Catalog:", StringComparison.Ordinal)
                && sharedLocation && legacyLocation && uninitializedSafe && overridesSafe && shellFailureSafe;
            WriteCrossRuntimeSharedStateResult(resultPath, new
            {
                ok,
                success,
                failure,
                privateDataAbsent,
                doneReachable,
                sharedLocation,
                legacyLocation,
                uninitializedSafe,
                overridesSafe,
                shellFailureSafe,
                shared,
                legacy,
                uninitialized,
                overrides,
                shellFailure,
                payload,
            });
            win.Close();
            Shutdown(ok ? 0 : 1);
            }, DispatcherPriority.Input);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureThumbnailStatusBordersSmoke(string resultPath)
    {
        string settingsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH")
            ?? throw new InvalidOperationException("automation settings path was not configured");
        string smokeRoot = Path.GetDirectoryName(Path.GetFullPath(settingsPath))
            ?? throw new InvalidOperationException("automation settings root was unavailable");
        Directory.CreateDirectory(smokeRoot);
        const string seededSettingsJson = """
        {
          "confirmBeforeDelete": true,
          "keyBindings": { "nextImage": "ArrowRight", "futureChord": { "mode": "preserve" } },
          "futureRoot": { "owner": "browser" },
          "thumbnailStatusBorders": {
            "futureStatus": "preserve",
            "favorite": { "enabled": false, "color": "#112233", "futureFavorite": 17 },
            "enhanced": { "enabled": true, "color": "#445566", "futureEnhanced": { "mode": "keep" } }
          }
        }
        """;
        File.WriteAllText(settingsPath, seededSettingsJson);

        static bool UnknownFieldsArePreserved(string path, bool expectedConfirmBeforeDelete)
        {
            using JsonDocument document = JsonDocument.Parse(File.ReadAllText(path));
            JsonElement root = document.RootElement;
            JsonElement borders = root.GetProperty("thumbnailStatusBorders");
            return root.GetProperty("confirmBeforeDelete").GetBoolean() == expectedConfirmBeforeDelete
                && root.GetProperty("keyBindings").GetProperty("nextImage").GetString() == "ArrowRight"
                && root.GetProperty("keyBindings").GetProperty("futureChord").GetProperty("mode").GetString() == "preserve"
                && root.GetProperty("futureRoot").GetProperty("owner").GetString() == "browser"
                && borders.GetProperty("futureStatus").GetString() == "preserve"
                && borders.GetProperty("favorite").GetProperty("futureFavorite").GetInt32() == 17
                && borders.GetProperty("enhanced").GetProperty("futureEnhanced").GetProperty("mode").GetString() == "keep";
        }

        static bool PersistedContractMatches(
            string path,
            bool favoriteEnabled,
            string favoriteColor,
            bool enhancedEnabled,
            string enhancedColor)
        {
            using JsonDocument document = JsonDocument.Parse(File.ReadAllText(path));
            JsonElement borders = document.RootElement.GetProperty("thumbnailStatusBorders");
            JsonElement favorite = borders.GetProperty("favorite");
            JsonElement enhanced = borders.GetProperty("enhanced");
            return favorite.GetProperty("enabled").GetBoolean() == favoriteEnabled
                && string.Equals(favorite.GetProperty("color").GetString(), favoriteColor, StringComparison.Ordinal)
                && enhanced.GetProperty("enabled").GetBoolean() == enhancedEnabled
                && string.Equals(enhanced.GetProperty("color").GetString(), enhancedColor, StringComparison.Ordinal);
        }

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var windows = new List<MainWindow>();
        var first = HiddenWindow();
        windows.Add(first);
        first.Show();
        first.Dispatcher.InvokeAsync(async () =>
        {
            object result;
            bool ok = false;
            try
            {
                first.OpenAppSettingsForSmoke();
                bool surfaceContract = first.ThumbnailStatusBorderSurfaceContractForSmoke;
                bool seededSettingsLoaded = !first.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && first.FavoriteThumbnailStatusBorderColorForSmoke == "#112233"
                    && first.EnhancedThumbnailStatusBorderEnabledForSmoke
                    && first.EnhancedThumbnailStatusBorderColorForSmoke == "#445566"
                    && !first.FavoriteThumbnailStatusBorderCheckedForSmoke
                    && first.FavoriteThumbnailStatusBorderDraftColorForSmoke == "#112233"
                    && first.EnhancedThumbnailStatusBorderCheckedForSmoke
                    && first.EnhancedThumbnailStatusBorderDraftColorForSmoke == "#445566"
                    && first.ConfirmBeforeDeleteForSmoke;
                bool seededFavoriteResourceVisible =
                    first.FavoriteThumbnailStatusBorderResourceVisibleForSmoke;
                bool seededEnhancedResourceVisible =
                    first.EnhancedThumbnailStatusBorderResourceVisibleForSmoke;
                string seededEnhancedResourceColor =
                    first.EnhancedThumbnailStatusBorderResourceColorForSmoke;
                bool seededEnhancedResourceIsRainbow =
                    first.EnhancedThumbnailStatusBorderResourceIsRainbowForSmoke;
                bool seededEnhancedResourceIsFrozen =
                    first.EnhancedThumbnailStatusBorderResourceIsFrozenForSmoke;
                bool seededResourcesLoaded = !seededFavoriteResourceVisible
                    && seededEnhancedResourceVisible
                    && seededEnhancedResourceColor == "#445566"
                    && !seededEnhancedResourceIsRainbow
                    && seededEnhancedResourceIsFrozen;

                first.SetThumbnailStatusBorderDraftForSmoke(true, "#ABCDEF", true, "RAINBOW");
                bool firstSaveSucceeded = first.SaveThumbnailStatusBorderDraftForSmoke();
                bool normalizedAndApplied = first.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && first.FavoriteThumbnailStatusBorderColorForSmoke == "#abcdef"
                    && first.EnhancedThumbnailStatusBorderEnabledForSmoke
                    && first.EnhancedThumbnailStatusBorderColorForSmoke == ThumbnailStatusBorderSettings.DefaultEnhancedColor
                    && first.FavoriteThumbnailStatusBorderResourceVisibleForSmoke
                    && first.FavoriteThumbnailStatusBorderResourceColorForSmoke == "#abcdef"
                    && first.EnhancedThumbnailStatusBorderResourceVisibleForSmoke
                    && first.EnhancedThumbnailStatusBorderResourceUsesDefaultCyanForSmoke
                    && first.EnhancedThumbnailStatusBorderResourceIsSolidForSmoke
                    && first.EnhancedThumbnailStatusBorderResourceIsFrozenForSmoke;
                bool legacyRainbowMigratedToSolidCyan = !first.EnhancedThumbnailStatusBorderRainbowModeForSmoke
                    && first.EnhancedThumbnailStatusBorderSolidModeForSmoke
                    && first.EnhancedThumbnailStatusBorderSolidColorEnabledForSmoke
                    && !first.EnhancedThumbnailStatusBorderResourceIsRainbowForSmoke
                    && !first.EnhancedThumbnailStatusBorderRainbowStopsForSmoke;
                bool unknownFieldsPreserved = UnknownFieldsArePreserved(settingsPath, expectedConfirmBeforeDelete: true);
                bool firstPersisted = PersistedContractMatches(
                    settingsPath,
                    true,
                    "#abcdef",
                    true,
                    ThumbnailStatusBorderSettings.DefaultEnhancedColor);
                bool sharedConfirmBeforeDeleteSaved = first.PersistConfirmBeforeDeleteForSmoke(false)
                    && !first.ConfirmBeforeDeleteForSmoke
                    && !JsonDocument.Parse(File.ReadAllText(settingsPath)).RootElement
                        .GetProperty("confirmBeforeDelete").GetBoolean()
                    && UnknownFieldsArePreserved(settingsPath, expectedConfirmBeforeDelete: false);

                first.SetEnhancedThumbnailStatusBorderDraftForSmoke(false, "#334455");
                bool browserFavoriteMerged = ThumbnailStatusBorderSettingsStore.TryMerge(
                    File.ReadAllText(settingsPath),
                    new ThumbnailStatusBorderSettings(
                        new ThumbnailStatusBorderPreference(false, "#667788"),
                        ThumbnailStatusBorderSettings.Default.Enhanced),
                    ThumbnailStatusBorderDirtyPreferences.Favorite,
                    out string browserFavoriteJson,
                    out _);
                if (browserFavoriteMerged)
                    File.WriteAllText(settingsPath, browserFavoriteJson);
                bool crossRuntimePreferenceMerge = browserFavoriteMerged
                    && first.SaveThumbnailStatusBorderDraftForSmoke()
                    && PersistedContractMatches(settingsPath, false, "#667788", false, "#334455")
                    && !first.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && first.FavoriteThumbnailStatusBorderColorForSmoke == "#667788"
                    && !first.EnhancedThumbnailStatusBorderEnabledForSmoke
                    && first.EnhancedThumbnailStatusBorderColorForSmoke == "#334455"
                    && UnknownFieldsArePreserved(settingsPath, expectedConfirmBeforeDelete: false);
                first.SetThumbnailStatusBorderDraftForSmoke(true, "#abcdef", true, "rainbow");
                bool crossRuntimeStateRestored = first.SaveThumbnailStatusBorderDraftForSmoke()
                    && PersistedContractMatches(
                        settingsPath,
                        true,
                        "#abcdef",
                        true,
                        ThumbnailStatusBorderSettings.DefaultEnhancedColor);
                first.Close();

                var reload = HiddenWindow();
                windows.Add(reload);
                reload.Show();
                reload.OpenAppSettingsForSmoke();
                bool reloadPersisted = reload.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && reload.FavoriteThumbnailStatusBorderColorForSmoke == "#abcdef"
                    && reload.EnhancedThumbnailStatusBorderEnabledForSmoke
                    && reload.EnhancedThumbnailStatusBorderColorForSmoke == ThumbnailStatusBorderSettings.DefaultEnhancedColor
                    && reload.FavoriteThumbnailStatusBorderCheckedForSmoke
                    && reload.EnhancedThumbnailStatusBorderCheckedForSmoke
                    && !reload.EnhancedThumbnailStatusBorderRainbowModeForSmoke
                    && reload.EnhancedThumbnailStatusBorderSolidModeForSmoke
                    && reload.EnhancedThumbnailStatusBorderSolidColorEnabledForSmoke
                    && reload.EnhancedThumbnailStatusBorderResourceIsSolidForSmoke
                    && reload.EnhancedThumbnailStatusBorderResourceUsesDefaultCyanForSmoke
                    && reload.EnhancedThumbnailStatusBorderResourceIsFrozenForSmoke
                    && !reload.ConfirmBeforeDeleteForSmoke;

                reload.ResetThumbnailStatusBorderDraftForSmoke();
                bool resetIsDraftOnly = reload.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && reload.EnhancedThumbnailStatusBorderEnabledForSmoke
                    && reload.FavoriteThumbnailStatusBorderDraftColorForSmoke == ThumbnailStatusBorderSettings.DefaultFavoriteColor
                    && string.Equals(
                        reload.EnhancedThumbnailStatusBorderDraftColorForSmoke,
                        ThumbnailStatusBorderSettings.DefaultEnhancedColor,
                        StringComparison.OrdinalIgnoreCase)
                    && !reload.EnhancedThumbnailStatusBorderRainbowModeForSmoke
                    && reload.EnhancedThumbnailStatusBorderSolidModeForSmoke
                    && reload.ThumbnailStatusBorderSettingsStatusForSmoke.Contains("ready", StringComparison.OrdinalIgnoreCase);
                reload.SetThumbnailStatusBorderDraftForSmoke(true, "red", true, "#010203");
                string beforeInvalid = File.ReadAllText(settingsPath);
                bool invalidColorProtected = !reload.SaveThumbnailStatusBorderDraftForSmoke()
                    && reload.ThumbnailStatusBorderSaveShowsRetryForSmoke
                    && string.Equals(beforeInvalid, File.ReadAllText(settingsPath), StringComparison.Ordinal);

                reload.SetThumbnailStatusBorderDraftForSmoke(true, "#010203", true, "#040506");
                string beforeBusy = File.ReadAllText(settingsPath);
                string lockPath = settingsPath + ".lock";
                bool busyWriteProtected;
                using (var lockStream = new FileStream(lockPath, FileMode.CreateNew, FileAccess.ReadWrite, FileShare.Read))
                {
                    byte[] lockPayload = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new
                    {
                        pid = Environment.ProcessId,
                        createdAtUtc = DateTimeOffset.UtcNow.ToString("O"),
                    }));
                    lockStream.Write(lockPayload);
                    lockStream.Flush(flushToDisk: true);
                    busyWriteProtected = !reload.SaveThumbnailStatusBorderDraftForSmoke()
                        && reload.ThumbnailStatusBorderSaveShowsRetryForSmoke
                        && string.Equals(beforeBusy, File.ReadAllText(settingsPath), StringComparison.Ordinal);
                }
                File.Delete(lockPath);
                string beforeUnreadableSettings = File.ReadAllText(settingsPath);
                bool unreadableSettingsReadProtected;
                bool unreadableSettingsWritersRefused;
                using (var settingsStream = new FileStream(
                           settingsPath,
                           FileMode.Open,
                           FileAccess.Read,
                           FileShare.None))
                {
                    ThumbnailStatusBorderLoadResult unreadableLoad =
                        ThumbnailStatusBorderSettingsStore.Read(settingsPath);
                    unreadableSettingsReadProtected = unreadableLoad.IsProtected
                        && ThumbnailStatusBorderSettingsStore.ResolveEffectiveConfirmBeforeDelete(
                            false,
                            unreadableLoad);
                    unreadableSettingsWritersRefused =
                        !reload.SaveThumbnailStatusBorderDraftForSmoke()
                        && !reload.PersistConfirmBeforeDeleteForSmoke(true);
                }
                bool unreadableSettingsProtected = unreadableSettingsReadProtected
                    && unreadableSettingsWritersRefused
                    && string.Equals(
                        beforeUnreadableSettings,
                        File.ReadAllText(settingsPath),
                        StringComparison.Ordinal);
                bool retrySucceeded = reload.SaveThumbnailStatusBorderDraftForSmoke()
                    && PersistedContractMatches(settingsPath, true, "#010203", true, "#040506")
                    && UnknownFieldsArePreserved(settingsPath, expectedConfirmBeforeDelete: false);
                bool browserConfirmMerged = ThumbnailStatusBorderSettingsStore.TryMergeConfirmBeforeDelete(
                    File.ReadAllText(settingsPath),
                    true,
                    out string browserConfirmJson,
                    out _);
                if (browserConfirmMerged)
                    File.WriteAllText(settingsPath, browserConfirmJson);
                reload.Close();

                var retryReload = HiddenWindow();
                windows.Add(retryReload);
                retryReload.Show();
                bool retryReloaded = retryReload.FavoriteThumbnailStatusBorderEnabledForSmoke
                    && retryReload.FavoriteThumbnailStatusBorderColorForSmoke == "#010203"
                    && retryReload.EnhancedThumbnailStatusBorderEnabledForSmoke
