                malformed.SetThumbnailStatusBorderDraftForSmoke(true, "#111111", true, "#222222");
                bool malformedProtected = malformed.ThumbnailStatusBorderSettingsProtectedForSmoke
                    && !malformed.SaveThumbnailStatusBorderDraftForSmoke()
