                    && !exactLimitSettings.SaveThumbnailStatusBorderDraftForSmoke()
                    && !exactLimitSettings.PersistConfirmBeforeDeleteForSmoke(false)
                    && File.ReadAllBytes(settingsPath).AsSpan().SequenceEqual(
