                bool unknownLocalPreserved = finalDocument.RootElement.TryGetProperty("futureOwner", out JsonElement finalFuture)
                    && finalFuture.TryGetProperty("keep", out JsonElement finalKeep)
                    && finalKeep.GetBoolean();
                bool sharedSettingsUntouched = string.Equals(
                    sharedSettingsBefore,
                    FileFingerprint(settingsPath),
                    StringComparison.Ordinal);

                ok = englishLoaded
                    && englishFavoriteFilterSurface
                    && englishGalleryShellSurface
                    && japaneseSaved
                    && japaneseHotApplied
                    && japanesePersisted
                    && japaneseReloaded
                    && japaneseFavoriteFilterSurface
                    && japaneseGalleryShellSurface
                    && englishSaved
                    && englishReloaded
                    && unknownLocalPreserved
                    && sharedSettingsUntouched;
                result = new
                {
                    ok,
                    message = ok
                        ? "English/Japanese live resources, WPF-local persistence, and shared-settings isolation passed"
                        : "UI language contract did not match expectations",
                    englishLoaded,
                    englishFavoriteFilterSurface,
                    englishGalleryShellSurface,
                    japaneseSaved,
                    japaneseHotApplied,
                    japanesePersisted,
                    japaneseReloaded,
                    japaneseFavoriteFilterSurface,
                    japaneseGalleryShellSurface,
                    englishSaved,
                    englishReloaded,
                    unknownLocalPreserved,
                    sharedSettingsUntouched,
                    finalLanguage = finalWindow.UiLanguageForSmoke,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString() };
            }
            finally
            {
                foreach (MainWindow window in windows)
                {
                    try { window.Close(); } catch { }
                }
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", previousSettingsPath);
                try { if (Directory.Exists(root)) Directory.Delete(root, recursive: true); } catch { }
            }

            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(resultPath))!);
            File.WriteAllText(
                resultPath,
                JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureSettingsUnseenDotsSmoke(string resultPath)
    {
        string smokeRoot = Path.Combine(Path.GetTempPath(), "photoviewer-wpf-settings-unseen-dots-" + Guid.NewGuid().ToString("N"));
        string folder = Path.Combine(smokeRoot, "source fixture");
        string statePath = Path.Combine(smokeRoot, "state.json");
        string favoritesPath = Path.Combine(smokeRoot, "favorites.json");
        string seenPath = Path.Combine(smokeRoot, "seen.json");
        string recentPath = Path.Combine(smokeRoot, "recent-folders.json");
        string jobsPath = Path.Combine(smokeRoot, "enhance", "jobs.json");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousRecentPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH");
        string? previousJobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH");

        Directory.CreateDirectory(folder);
        Directory.CreateDirectory(Path.GetDirectoryName(jobsPath)!);
        DateTime fixtureTime = new(2026, 7, 18, 0, 0, 0, DateTimeKind.Utc);
        for (int index = 0; index < 3; index++)
        {
            string fixturePath = Path.Combine(folder, $"unseen-setting-{index}.png");
            WriteSmokePng(fixturePath, 96, 72, Color.FromRgb((byte)(70 + index * 35), 105, 165));
            // The viewer marks the first selected image Seen. Keep that selection deterministic
            // so this smoke can distinguish selection semantics from the display-only toggle.
            File.SetLastWriteTimeUtc(fixturePath, fixtureTime.AddMinutes(-index));
        }
        string seededSeenPath = Path.Combine(folder, "unseen-setting-0.png");
        string favoriteFixturePath = Path.Combine(folder, "unseen-setting-1.png");
        File.WriteAllText(
            favoritesPath,
            JsonSerializer.Serialize(new Dictionary<string, int> { [favoriteFixturePath] = 3 }));
        File.WriteAllText(seenPath, JsonSerializer.Serialize(new Dictionary<string, bool> { [seededSeenPath] = true }));
        File.WriteAllText(recentPath, "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"updatedAtUtc\":\"\"}");
        File.WriteAllText(jobsPath, "{\"version\":1,\"jobs\":[]}");
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", favoritesPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", seenPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", recentPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", jobsPath);

        string sourceBefore = FolderFingerprint(folder);
        string favoritesBefore = FileFingerprint(favoritesPath);
        string seenBefore = FileFingerprint(seenPath);
        string jobsBefore = FileFingerprint(jobsPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var windows = new List<MainWindow>();
        var first = HiddenWindow();
        windows.Add(first);
        first.Show();
        first.Dispatcher.InvokeAsync(async () =>
        {
            object result;
            bool ok = false;
            try
            {
                bool defaultOff = !first.ShowUnseenDotsForSmoke
                    && !first.SidebarUnseenDotsCheckedForSmoke
                    && !first.AppSettingsUnseenDotsCheckedForSmoke;
                bool gridInfoDefaultOn = first.ShowGridFileInfoOverlayForSmoke
                    && first.SidebarGridFileInfoOverlayCheckedForSmoke
                    && first.AppSettingsGridFileInfoOverlayCheckedForSmoke;
                bool favoriteNotificationsDefaultOn = first.ShowFavoriteChangeNotificationsForSmoke;
                bool calendarContrast = first.DatePickerCalendarContrastForSmoke;
                bool landingCaptionContract = first.LandingCaptionControlsContractForSmoke;
                bool landingHeaderBorderContract = first.LandingHeaderBorderContractForSmoke;
                bool landingDragRegionContract = first.LandingDragRegionContractForSmoke;
                bool landingCaptionButtonsContract = first.LandingCaptionButtonsContractForSmoke;
                bool landingMinimize = first.ActivateLandingMinimizeForSmoke();
                bool landingChrome = landingCaptionContract && landingMinimize;
                await first.LoadFolderAsync(folder);
                first.UpdateLayout();
                bool gridInfoVisualRealized = first.GridFileInfoOverlayVisualRealizedForSmoke;
                bool gridInfoVisibleByDefault = first.GridFileInfoOverlayVisibleForSmoke;
                bool gridStatusVisibleBeforeToggle = first.FirstGridStatusBadgeVisibleForSmoke;
                bool searchClear = first.ClearSearchButtonContractForSmoke;
                bool sidebarScroll = first.SidebarScrollContractForSmoke
                    && first.VisibleWorkbenchChromeContainedForSmoke;
                string recentAfterFolderOpen = FileFingerprint(recentPath);
                int unseenCount = first.UnseenCountForSmoke;
                bool sidebarFocused = first.FocusSidebarUnseenDotsForSmoke() && first.IsSidebarUnseenDotsFocusedForSmoke;

                first.OpenAppSettingsForSmoke();
                await first.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Input);
                bool settingsFocused = first.FocusAppSettingsUnseenDotsForSmoke() && first.IsAppSettingsUnseenDotsFocusedForSmoke;
                bool accessible = first.UnseenDotsSurfaceContractForSmoke
                    && first.GridFileInfoOverlaySurfaceContractForSmoke
                    && first.FavoriteChangeNotificationsSurfaceContractForSmoke
                    && first.SettingsFocusTrapConfiguredForSmoke
                    && first.IsSettingsDialogFocusedForSmoke;
                bool settingsSurface = first.AppSettingsScrollContractForSmoke
                    && first.ShortcutDiscoverabilityContractForSmoke
                    && first.SidebarSettingsPinnedForSmoke
                    && first.HoverAndTooltipContractForSmoke;
                bool defaultSyncedInSettings = !first.SidebarUnseenDotsCheckedForSmoke && !first.AppSettingsUnseenDotsCheckedForSmoke;
                bool gridInfoDefaultSyncedInSettings = first.SidebarGridFileInfoOverlayCheckedForSmoke
                    && first.AppSettingsGridFileInfoOverlayCheckedForSmoke;
                bool favoriteNotificationsDisabled = first.SetFavoriteChangeNotificationsForSmoke(false)
                    && !first.ShowFavoriteChangeNotificationsForSmoke
                    && !first.FavoriteChangeNotificationsCheckedForSmoke;

                first.SetAppSettingsGridFileInfoOverlayForSmoke(false);
                bool settingsHideGridInfo = !first.ShowGridFileInfoOverlayForSmoke
                    && !first.SidebarGridFileInfoOverlayCheckedForSmoke
                    && !first.AppSettingsGridFileInfoOverlayCheckedForSmoke
                    && first.GridFileInfoOverlayVisualRealizedForSmoke
                    && !first.GridFileInfoOverlayVisibleForSmoke
                    && first.FirstGridStatusBadgeVisibleForSmoke == gridStatusVisibleBeforeToggle;
                first.SetSidebarGridFileInfoOverlayForSmoke(true);
                bool sidebarRestoreGridInfo = first.ShowGridFileInfoOverlayForSmoke
                    && first.SidebarGridFileInfoOverlayCheckedForSmoke
                    && first.AppSettingsGridFileInfoOverlayCheckedForSmoke
                    && first.GridFileInfoOverlayVisibleForSmoke;
                first.SetSidebarGridFileInfoOverlayForSmoke(false);
                bool sidebarHideGridInfo = !first.ShowGridFileInfoOverlayForSmoke
                    && !first.SidebarGridFileInfoOverlayCheckedForSmoke
                    && !first.AppSettingsGridFileInfoOverlayCheckedForSmoke
                    && !first.GridFileInfoOverlayVisibleForSmoke;

                first.SetAppSettingsUnseenDotsForSmoke(true);
                bool settingsToSidebar = first.ShowUnseenDotsForSmoke
                    && first.AppSettingsUnseenDotsCheckedForSmoke
                    && first.SidebarUnseenDotsCheckedForSmoke
                    && first.VisibleUnseenDotCountForSmoke == unseenCount
                    && unseenCount == 2;
                bool settingsInsideClick = first.AppSettingsInsideClickStaysOpenForSmoke();
                bool settingsBackdropClose = first.AppSettingsBackdropClosesForSmoke();
                first.SetSidebarUnseenDotsForSmoke(false);
                bool sidebarToSettings = !first.ShowUnseenDotsForSmoke
                    && !first.SidebarUnseenDotsCheckedForSmoke
                    && !first.AppSettingsUnseenDotsCheckedForSmoke
                    && first.VisibleUnseenDotCountForSmoke == 0;
                first.OpenAppSettingsForSmoke();
                await first.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Input);
                bool settingsReopenedSynced = !first.AppSettingsUnseenDotsCheckedForSmoke;
                first.CloseTopmostOverlayForSmoke();
                bool shortcutEntryOpened = first.ActivateShortcutEntryForSmoke("viewer");
                first.SetAppSettingsUnseenDotsForSmoke(true);
                ViewerState? persistedOn = ReadPersistedState(statePath);
                bool persistedEnabled = persistedOn?.ShowUnseenDots == true;
                bool gridInfoPersistedOff = persistedOn?.ShowGridFileInfoOverlay == false;
                bool favoriteNotificationsPersistedOff = persistedOn?.ShowFavoriteChangeNotifications == false;
                first.Close();

                var reload = HiddenWindow();
                windows.Add(reload);
                reload.Show();
                reload.OpenAppSettingsForSmoke();
                await reload.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Input);
                bool reloadSynced = reload.ShowUnseenDotsForSmoke
                    && reload.SidebarUnseenDotsCheckedForSmoke
                    && reload.AppSettingsUnseenDotsCheckedForSmoke;
                bool gridInfoReloadedOff = !reload.ShowGridFileInfoOverlayForSmoke
                    && !reload.SidebarGridFileInfoOverlayCheckedForSmoke
                    && !reload.AppSettingsGridFileInfoOverlayCheckedForSmoke;
                bool favoriteNotificationsReloadedOff = !reload.ShowFavoriteChangeNotificationsForSmoke
                    && !reload.FavoriteChangeNotificationsCheckedForSmoke;
                bool reloadSettingsFocused = reload.FocusAppSettingsUnseenDotsForSmoke() && reload.IsAppSettingsUnseenDotsFocusedForSmoke;
                reload.Close();

                File.WriteAllText(statePath, "{\"Version\":1,\"futureDisplay\":{\"mode\":\"preserve\"}}");
                var migration = HiddenWindow();
                windows.Add(migration);
                migration.Show();
                migration.OpenAppSettingsForSmoke();
                await migration.Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Input);
                bool migrationDefaultOff = !migration.ShowUnseenDotsForSmoke
                    && !migration.SidebarUnseenDotsCheckedForSmoke
                    && !migration.AppSettingsUnseenDotsCheckedForSmoke;
                bool gridInfoMigrationDefaultOn = migration.ShowGridFileInfoOverlayForSmoke
                    && migration.SidebarGridFileInfoOverlayCheckedForSmoke
                    && migration.AppSettingsGridFileInfoOverlayCheckedForSmoke;
                bool favoriteNotificationsMigrationDefaultOn = migration.ShowFavoriteChangeNotificationsForSmoke
                    && migration.FavoriteChangeNotificationsCheckedForSmoke;
                migration.Close();
                bool migrationUnknownPreserved = File.ReadAllText(statePath).Contains("futureDisplay", StringComparison.Ordinal);

                bool seenByteIdentical = string.Equals(seenBefore, FileFingerprint(seenPath), StringComparison.Ordinal);
                bool cacheIsolation = string.Equals(favoritesBefore, FileFingerprint(favoritesPath), StringComparison.Ordinal)
                    && string.Equals(jobsBefore, FileFingerprint(jobsPath), StringComparison.Ordinal)
                    && string.Equals(recentAfterFolderOpen, FileFingerprint(recentPath), StringComparison.Ordinal);
                bool sourceUntouched = string.Equals(sourceBefore, FolderFingerprint(folder), StringComparison.Ordinal);
                string rootPrefix = Path.GetFullPath(smokeRoot).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
                bool isolated = new[] { statePath, favoritesPath, seenPath, recentPath, jobsPath }
                    .All(path => Path.GetFullPath(path).StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase));
                bool residueFree = NoPersistenceResidue(smokeRoot);
                ok = defaultOff && gridInfoDefaultOn && gridInfoVisualRealized
                    && gridInfoVisibleByDefault && gridStatusVisibleBeforeToggle
                    && favoriteNotificationsDefaultOn && calendarContrast && searchClear && sidebarScroll
                    && landingChrome && defaultSyncedInSettings && gridInfoDefaultSyncedInSettings
                    && sidebarFocused && settingsFocused && accessible
                    && settingsSurface && settingsInsideClick && settingsBackdropClose && shortcutEntryOpened
                    && settingsHideGridInfo && sidebarRestoreGridInfo && sidebarHideGridInfo
                    && settingsToSidebar && sidebarToSettings && settingsReopenedSynced && persistedEnabled
                    && gridInfoPersistedOff
                    && favoriteNotificationsDisabled && favoriteNotificationsPersistedOff
                    && reloadSynced && gridInfoReloadedOff
                    && favoriteNotificationsReloadedOff && reloadSettingsFocused
                    && migrationDefaultOff && gridInfoMigrationDefaultOn
                    && favoriteNotificationsMigrationDefaultOn && migrationUnknownPreserved
                    && seenByteIdentical && cacheIsolation && sourceUntouched && isolated && residueFree;
                result = new
                {
                    ok,
                    message = ok
                        ? "landing chrome, pinned Settings/shortcut entry, dark hover/tooltip, one-scroll backdrop-close Settings, and unseen-dot persistence passed without mutating Seen or unrelated cache"
                        : "unseen-dot Settings parity smoke did not meet its synchronization and isolation contract",
                    defaultOff,
                    gridInfoDefaultOn,
                    gridInfoVisualRealized,
                    gridInfoVisibleByDefault,
                    gridStatusVisibleBeforeToggle,
                    favoriteNotificationsDefaultOn,
                    calendarContrast,
                    searchClear,
                    sidebarScroll,
                    landingChrome,
                    landingCaptionContract,
                    landingHeaderBorderContract,
                    landingDragRegionContract,
                    landingCaptionButtonsContract,
                    landingMinimize,
                    defaultSyncedInSettings,
                    gridInfoDefaultSyncedInSettings,
                    sidebarFocused,
                    settingsFocused,
                    accessible,
                    settingsSurface,
                    settingsInsideClick,
                    settingsBackdropClose,
                    shortcutEntryOpened,
                    settingsHideGridInfo,
                    sidebarRestoreGridInfo,
                    sidebarHideGridInfo,
                    settingsToSidebar,
                    sidebarToSettings,
                    settingsReopenedSynced,
                    persistedEnabled,
                    gridInfoPersistedOff,
                    favoriteNotificationsDisabled,
                    favoriteNotificationsPersistedOff,
                    reloadSynced,
                    gridInfoReloadedOff,
                    favoriteNotificationsReloadedOff,
                    reloadSettingsFocused,
                    migrationDefaultOff,
                    gridInfoMigrationDefaultOn,
                    favoriteNotificationsMigrationDefaultOn,
                    migrationUnknownPreserved,
                    unseenCount,
                    seenByteIdentical,
                    cacheIsolation,
                    sourceUntouched,
                    isolated,
                    residueFree,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.Message, smokeRoot };
            }
            finally
            {
                foreach (MainWindow window in windows)
                {
                    try { if (window.IsLoaded) window.Close(); } catch { }
                }
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", previousRecentPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", previousJobsPath);
            }

            WriteCrossRuntimeSharedStateResult(resultPath, result);
            try { if (Directory.Exists(smokeRoot)) Directory.Delete(smokeRoot, recursive: true); } catch { }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureKeyBindingsSmoke(string resultPath, string[] args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string? rawRoot = ArgValue(args, "--key-root");
        string phase = (ArgValue(args, "--key-phase") ?? "write").Trim().ToLowerInvariant();
        if (string.IsNullOrWhiteSpace(rawRoot) || phase is not ("write" or "reload"))
        {
            WriteCrossRuntimeSharedStateResult(resultFullPath, new
            {
                ok = false,
                message = "key-binding smoke requires a temp --key-root and --key-phase write|reload",
                phase,
            });
            Shutdown(1);
            return;
        }

        string generatedAutomationState = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH") ?? "";
        string generatedAutomationRoot = Path.GetDirectoryName(generatedAutomationState) ?? "";
        string smokeRoot = Path.GetFullPath(rawRoot);
        string folder = Path.Combine(smokeRoot, "images");
        string statePath = Path.Combine(smokeRoot, "state.json");
        string favoritesPath = Path.Combine(smokeRoot, "favorites.json");
        string seenPath = Path.Combine(smokeRoot, "seen.json");
        string recentPath = Path.Combine(smokeRoot, "recent-folders.json");
        string jobsPath = Path.Combine(smokeRoot, "enhance", "jobs.json");
        string settingsPath = Path.Combine(smokeRoot, "settings.json");
        string metadataIndexDirectory = Path.Combine(smokeRoot, "metadata-index");
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", favoritesPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", seenPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", recentPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", jobsPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", settingsPath);
        Environment.SetEnvironmentVariable(
            "PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY",
            metadataIndexDirectory);
        if (!string.IsNullOrWhiteSpace(generatedAutomationRoot)
            && !string.Equals(generatedAutomationRoot, smokeRoot, StringComparison.OrdinalIgnoreCase))
        {
            try { if (Directory.Exists(generatedAutomationRoot)) Directory.Delete(generatedAutomationRoot, recursive: true); } catch { }
        }

        const string firstName = "a-first.png";
        const string secondName = "b-second.png";
        const string thirdName = "c-third.png";
        if (phase == "write")
        {
            Directory.CreateDirectory(folder);
            Directory.CreateDirectory(Path.GetDirectoryName(jobsPath)!);
            WriteSmokePng(Path.Combine(folder, firstName), 72, 54, Color.FromRgb(70, 125, 205));
            WriteSmokePng(Path.Combine(folder, secondName), 72, 54, Color.FromRgb(195, 95, 125));
            WriteSmokePng(Path.Combine(folder, thirdName), 72, 54, Color.FromRgb(95, 185, 115));
            File.WriteAllText(statePath, "{\"Version\":2,\"futureTop\":{\"mode\":\"preserve\"},\"KeyBindings\":{\"favoriteIncrease\":\"Win+Shift+T\",\"favoriteDecrease\":\"Alt+F4\",\"futureAction\":{\"mode\":\"preserve\"}}}");
            File.WriteAllText(favoritesPath, "{}");
            File.WriteAllText(seenPath, "{}");
            File.WriteAllText(recentPath, "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"updatedAtUtc\":\"\"}");
            File.WriteAllText(jobsPath, "{\"version\":1,\"jobs\":[]}");
            File.WriteAllText(
                settingsPath,
                "{\"version\":1,\"keyBindings\":{\"nextImage\":\"ArrowRight\",\"futureBrowserAction\":\"x\"},\"futureSetting\":{\"mode\":\"preserve\"}}");
        }

        if (!Directory.Exists(folder) || !File.Exists(statePath) || !File.Exists(jobsPath) || !File.Exists(settingsPath))
        {
            WriteCrossRuntimeSharedStateResult(resultFullPath, new
            {
                ok = false,
                message = "key-binding smoke fixture is incomplete; run write before reload",
                phase,
                smokeRoot,
            });
            Shutdown(1);
            return;
        }

        string sourceBefore = FolderFingerprint(folder);
        string jobsBefore = FileFingerprint(jobsPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var window = HiddenWindow();
        window.Show();
        window.Dispatcher.InvokeAsync(async () =>
        {
            bool ok = false;
            object result;
            try
            {
                await window.LoadFolderAsync(folder);
                window.SetSortByForSmoke("name");
                int shortcutApiReads = 0;
                int shortcutApiMutations = 0;
                window.ConfigureModalEnhancementForSmoke((request, _) =>
                {
                    if (request.Method == HttpMethod.Get)
                    {
                        Interlocked.Increment(ref shortcutApiReads);
                        bool jobsRead = request.RequestUri?.AbsolutePath.EndsWith(
                            "/api/enhance/jobs",
                            StringComparison.Ordinal) == true;
                        return Task.FromResult(new HttpResponseMessage(
                            jobsRead ? HttpStatusCode.OK : HttpStatusCode.ServiceUnavailable)
                        {
                            Content = jobsRead
                                ? new StringContent("{\"jobs\":[]}", Encoding.UTF8, "application/json")
                                : new StringContent("{\"error\":\"synthetic unavailable\"}", Encoding.UTF8, "application/json"),
                        });
                    }

                    Interlocked.Increment(ref shortcutApiMutations);
                    return Task.FromResult(new HttpResponseMessage(HttpStatusCode.MethodNotAllowed));
                });
                if (phase == "write")
                {
                    bool defaultsLoaded = window.KeyBindingTextForSmoke("favoriteIncrease", draft: false) == "F"
                        && window.KeyBindingTextForSmoke("nextImage", draft: false) == "Right"
                        && window.KeyBindingTextForSmoke("photorealizeCurrentImage", draft: false) == "R"
                        && window.KeyBindingTextForSmoke("openEnhancementJobs", draft: false) == "J"
                        && window.KeyBindingTextForSmoke("openI2iEdit", draft: false) == "I"
                        && window.KeyBindingTextForSmoke("openVideoGeneration", draft: false) == "V"
                        && window.KeyBindingTextForSmoke("reopenLastClosedPreviewTab", draft: false) == "Ctrl+Shift+T"
                        && window.KeyBindingTextForSmoke("movePreviewTabLeft", draft: false) == "Alt+Shift+Left";
                    bool persistedInvalidFallback = window.KeyBindingTextForSmoke("favoriteIncrease", draft: false) == "F"
                        && window.KeyBindingTextForSmoke("favoriteDecrease", draft: false) == "U";
                    string[] exhaustedCandidateTokens =
                    [
                        "T", "B", "G", "V", "Y", "J", "K", "L", "N", "M", "Q", "W", "X", "C", "Z",
                        "F6", "F7", "F8", "F9", "F10", "F11", "F12",
                    ];
                    var exhaustedFixture = exhaustedCandidateTokens
                        .Select((token, index) => new KeyValuePair<string, JsonElement>(
                            $"futureAction{index}",
                            JsonSerializer.SerializeToElement(token)))
                        .ToDictionary(static pair => pair.Key, static pair => pair.Value, StringComparer.Ordinal);
                    Dictionary<ViewerKeyAction, KeyChord> exhaustedBindings = KeyBindingSettings.NormalizePersisted(
                        exhaustedFixture,
                        out Dictionary<string, JsonElement>? exhaustedUnknown);
                    Dictionary<string, JsonElement> exhaustedPersisted = KeyBindingSettings.ToPersisted(
                        exhaustedBindings,
                        exhaustedUnknown);
                    bool exhaustedMigrationProtected = exhaustedBindings.TryGetValue(ViewerKeyAction.ToggleModalFilmstrip, out KeyChord exhaustedFilmstrip)
                        && !exhaustedFilmstrip.IsBound
                        && exhaustedBindings.TryGetValue(ViewerKeyAction.AddToAlbum, out KeyChord exhaustedAlbum)
                        && !exhaustedAlbum.IsBound
                        && KeyBindingSettings.FindConflicts(exhaustedBindings).Count == 0
                        && exhaustedUnknown?.Count == exhaustedCandidateTokens.Length
                        && exhaustedPersisted.TryGetValue("toggleModalFilmstrip", out JsonElement persistedFilmstrip)
                        && persistedFilmstrip.GetString() == KeyChord.UnboundStorageValue
                        && exhaustedPersisted.TryGetValue("addToAlbum", out JsonElement persistedAlbum)
                        && persistedAlbum.GetString() == KeyChord.UnboundStorageValue
                        && exhaustedCandidateTokens.Select((token, index) => (token, index)).All(item =>
                            exhaustedPersisted.TryGetValue($"futureAction{item.index}", out JsonElement preserved)
                            && preserved.GetString() == item.token);
                    exhaustedBindings[ViewerKeyAction.AddToAlbum] = new KeyChord(Key.P, ModifierKeys.None);
                    Dictionary<string, JsonElement> repairedPersisted = KeyBindingSettings.ToPersisted(exhaustedBindings, exhaustedUnknown);
                    Dictionary<ViewerKeyAction, KeyChord> repairedReloaded = KeyBindingSettings.NormalizePersisted(
                        repairedPersisted,
                        out Dictionary<string, JsonElement>? repairedUnknown);
                    bool exhaustedMigrationRepairable = repairedReloaded.TryGetValue(ViewerKeyAction.AddToAlbum, out KeyChord repairedAlbum)
                        && repairedAlbum == new KeyChord(Key.P, ModifierKeys.None)
                        && repairedReloaded.TryGetValue(ViewerKeyAction.ToggleModalFilmstrip, out KeyChord repairedFilmstrip)
                        && !repairedFilmstrip.IsBound
                        && repairedUnknown?.Count == exhaustedCandidateTokens.Length
                        && exhaustedCandidateTokens.Select((token, index) => (token, index)).All(item =>
                            repairedUnknown.TryGetValue($"futureAction{item.index}", out JsonElement preserved)
                            && preserved.GetString() == item.token);
                    bool sharedCollisionRepaired = KeyBindingSettings.TryApplyBrowserSharedBindings(
                            KeyBindingSettings.CreateDefaults(),
                            new Dictionary<string, string>(StringComparer.Ordinal)
                            {
                                ["toggleFavorite"] = "e",
                            },
                            out Dictionary<ViewerKeyAction, KeyChord> collisionRepaired,
                            out _)
                        && collisionRepaired[ViewerKeyAction.FavoriteIncrease] == new KeyChord(Key.E, ModifierKeys.None)
                        && collisionRepaired[ViewerKeyAction.ToggleEnhancedPreview] != new KeyChord(Key.E, ModifierKeys.None)
                        && KeyBindingSettings.FindConflicts(collisionRepaired).Count == 0;
