    private static async Task<SharedRecentSmokeResult> RunSharedRecentSmokeAsync(
        MainWindow first,
        string fullFolder,
        string smokeRoot)
    {
        first.SuppressStatePersistence();
        first.Close();

        string cacheRoot = Path.Combine(smokeRoot, ".cache");
        string sharedRecentPath = Path.Combine(cacheRoot, "recent-folders.json");
        string favoritesPath = Path.Combine(cacheRoot, "favorites.json");
        string seenPath = Path.Combine(cacheRoot, "seen.json");
        string statePath = Path.Combine(cacheRoot, "state.json");
        string writeFolder = Path.Combine(smokeRoot, "write-folder");
        string preservedFolder = Path.Combine(smokeRoot, "preserved-folder");
        string localFallbackFolder = Path.Combine(smokeRoot, "local-fallback-folder");
        string externalSharedFolder = Path.Combine(smokeRoot, "external-shared-folder");
        string malformedFolder = Path.Combine(smokeRoot, "malformed-folder");
        string futureFolder = Path.Combine(smokeRoot, "future-folder");
        Directory.CreateDirectory(writeFolder);
        Directory.CreateDirectory(preservedFolder);
        Directory.CreateDirectory(localFallbackFolder);
        Directory.CreateDirectory(externalSharedFolder);
        Directory.CreateDirectory(malformedFolder);
        Directory.CreateDirectory(futureFolder);

        static void WriteLocalFolderFallback(string path, string folder)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, JsonSerializer.Serialize(new
            {
                Version = 1,
                LastFolder = Path.GetFullPath(folder),
                LastFolderSet = new[] { Path.GetFullPath(folder) },
                ConfirmBeforeDelete = true,
            }));
        }

        string favoriteSeedPath = Path.Combine(fullFolder, "shared-recent-favorite-seed.png");
        string seenSeedPath = Path.Combine(fullFolder, "shared-recent-seen-seed.png");
        WriteFavoriteSeed(favoritesPath, favoriteSeedPath, 4);
        WriteSeenSeed(seenPath, seenSeedPath);
        string favoritesBefore = File.ReadAllText(favoritesPath);
        string seenBefore = File.ReadAllText(seenPath);

        WriteLocalFolderFallback(statePath, localFallbackFolder);
        WriteSharedRecentSeed(sharedRecentPath, fullFolder, preservedFolder);
        var importWindow = HiddenWindow();
        importWindow.Show();
        string? importedCurrentFolder = importWindow.CurrentFolderForSmoke;
        string resolvedRecentPath = importWindow.SharedRecentPathForSmoke;
        importWindow.Close();
        bool importedSharedLastFolder = string.Equals(
            NormalizeFavoritePath(fullFolder),
            NormalizeFavoritePath(importedCurrentFolder ?? ""),
            StringComparison.OrdinalIgnoreCase);

        WriteLocalFolderFallback(statePath, localFallbackFolder);
        WriteSharedRecentSetSeed(sharedRecentPath, [], []);
        string explicitEmptyBefore = File.ReadAllText(sharedRecentPath);
        var explicitEmptyWindow = HiddenWindow();
        explicitEmptyWindow.Show();
        string? explicitEmptyCurrentFolder = explicitEmptyWindow.CurrentFolderForSmoke;
        explicitEmptyWindow.Close();
        bool explicitEmptySharedWins = string.IsNullOrWhiteSpace(explicitEmptyCurrentFolder)
            && string.Equals(
                explicitEmptyBefore,
                File.ReadAllText(sharedRecentPath),
                StringComparison.Ordinal);

        File.Delete(sharedRecentPath);
        WriteLocalFolderFallback(statePath, localFallbackFolder);
        var missingWindow = HiddenWindow();
        missingWindow.Show();
        string? missingCurrentFolder = missingWindow.CurrentFolderForSmoke;
        missingWindow.Close();
        bool missingUsesLocalFallback = string.Equals(
                NormalizeFavoritePath(missingCurrentFolder ?? ""),
                NormalizeFavoritePath(localFallbackFolder),
                StringComparison.OrdinalIgnoreCase)
            && !File.Exists(sharedRecentPath);

        const string malformedJson = "[";
        File.WriteAllText(sharedRecentPath, malformedJson);
        WriteLocalFolderFallback(statePath, malformedFolder);
        var malformedWindow = HiddenWindow();
        malformedWindow.Show();
        string? malformedCurrentFolder = malformedWindow.CurrentFolderForSmoke;
        await malformedWindow.LoadFolderAsync(malformedFolder);
        malformedWindow.Close();
        bool malformedUsesLocalFallback = string.Equals(
            NormalizeFavoritePath(malformedCurrentFolder ?? ""),
            NormalizeFavoritePath(malformedFolder),
            StringComparison.OrdinalIgnoreCase);
        bool malformedPreserved = string.Equals(
            malformedJson,
            File.ReadAllText(sharedRecentPath),
            StringComparison.Ordinal);

        const string futureJson = "{\"version\":2,\"lastFolderSet\":[],\"futureRoot\":true}";
        File.WriteAllText(sharedRecentPath, futureJson);
        WriteLocalFolderFallback(statePath, futureFolder);
        var futureWindow = HiddenWindow();
        futureWindow.Show();
        string? futureCurrentFolder = futureWindow.CurrentFolderForSmoke;
        await futureWindow.LoadFolderAsync(futureFolder);
        futureWindow.Close();
        bool futureUsesLocalFallback = string.Equals(
            NormalizeFavoritePath(futureCurrentFolder ?? ""),
            NormalizeFavoritePath(futureFolder),
            StringComparison.OrdinalIgnoreCase);
        bool futurePreserved = string.Equals(
            futureJson,
            File.ReadAllText(sharedRecentPath),
            StringComparison.Ordinal);

        string unreadableFolder = Path.Combine(smokeRoot, "unreadable-folder");
        Directory.CreateDirectory(unreadableFolder);
        WriteSharedRecentSeed(sharedRecentPath, fullFolder, preservedFolder);
        string beforeUnreadableRecent = File.ReadAllText(sharedRecentPath);
        SharedRecentReadResult unreadableRecentRead;
        bool unreadableRecentWriteRefused;
        using (var recentStream = new FileStream(
                   sharedRecentPath,
                   FileMode.Open,
                   FileAccess.Read,
                   FileShare.None))
        {
            unreadableRecentRead =
                PhotoViewer.Wpf.MainWindow.ReadSharedRecentFoldersForSmoke(
                    sharedRecentPath);
            unreadableRecentWriteRefused =
                !PhotoViewer.Wpf.MainWindow.TryMergeSharedRecentForSmoke(
                    sharedRecentPath,
                    unreadableFolder);
        }
        bool unreadableExistingProtected = !unreadableRecentRead.Ok
            && unreadableRecentRead.Exists
            && unreadableRecentWriteRefused
            && string.Equals(
                beforeUnreadableRecent,
                File.ReadAllText(sharedRecentPath),
                StringComparison.Ordinal);

        byte[] invalidUtf8RecentBytes = Convert.FromBase64String(
            "eyJ2ZXJzaW9uIjoxLCJsYXN0Rm9sZGVyU2V0IjpbXSwicmVjZW50Rm9sZGVyU2V0cyI6W10sImZ1dHVyZVJvb3QiOiLDKCJ9");
        File.WriteAllBytes(sharedRecentPath, invalidUtf8RecentBytes);
        SharedRecentReadResult invalidUtf8RecentRead =
            PhotoViewer.Wpf.MainWindow.ReadSharedRecentFoldersForSmoke(
                sharedRecentPath);
        IReadOnlyList<string> invalidUtf8Selection =
            PhotoViewer.Wpf.MainWindow.ResolveStartupFolderSetForSmoke(
                sharedRecentPath,
                [localFallbackFolder],
                null);
        bool invalidUtf8RecentProtected = !invalidUtf8RecentRead.Ok
            && invalidUtf8RecentRead.Exists
            && invalidUtf8Selection.Count == 1
            && string.Equals(
                NormalizeFavoritePath(invalidUtf8Selection[0]),
                NormalizeFavoritePath(localFallbackFolder),
                StringComparison.OrdinalIgnoreCase)
            && !PhotoViewer.Wpf.MainWindow.TryMergeSharedRecentForSmoke(
                sharedRecentPath,
                unreadableFolder)
            && File.ReadAllBytes(sharedRecentPath).AsSpan().SequenceEqual(
                invalidUtf8RecentBytes);

        byte[] utf32RecentBytes = Convert.FromBase64String(
            "");
        File.WriteAllBytes(sharedRecentPath, utf32RecentBytes);
        SharedRecentReadResult utf32RecentRead =
            PhotoViewer.Wpf.MainWindow.ReadSharedRecentFoldersForSmoke(
                sharedRecentPath);
        IReadOnlyList<string> utf32Selection =
            PhotoViewer.Wpf.MainWindow.ResolveStartupFolderSetForSmoke(
                sharedRecentPath,
                [localFallbackFolder],
                null);
        bool utf32RecentProtected = !utf32RecentRead.Ok
            && utf32RecentRead.Exists
            && utf32Selection.Count == 1
            && string.Equals(
                NormalizeFavoritePath(utf32Selection[0]),
                NormalizeFavoritePath(localFallbackFolder),
                StringComparison.OrdinalIgnoreCase)
            && !PhotoViewer.Wpf.MainWindow.TryMergeSharedRecentForSmoke(
                sharedRecentPath,
                unreadableFolder)
            && File.ReadAllBytes(sharedRecentPath).AsSpan().SequenceEqual(
                utf32RecentBytes);

        byte[] exactLimitRecentBytes = BuildPaddedSharedJsonFixture(
            "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"padding\":\"",
            "\"}",
            SharedJsonDocumentReader.MaxDocumentBytes);
        File.WriteAllBytes(sharedRecentPath, exactLimitRecentBytes);
        SharedRecentReadResult exactLimitRecentRead =
            PhotoViewer.Wpf.MainWindow.ReadSharedRecentFoldersForSmoke(
                sharedRecentPath);
        bool exactLimitRecentWriterRefused = exactLimitRecentRead.Ok
            && exactLimitRecentRead.Exists
            && exactLimitRecentRead.Recent.LastFolderSet.Count == 0
            && !PhotoViewer.Wpf.MainWindow.TryMergeSharedRecentForSmoke(
                sharedRecentPath,
                unreadableFolder)
            && File.ReadAllBytes(sharedRecentPath).AsSpan().SequenceEqual(
                exactLimitRecentBytes);

        byte[] oversizedRecentBytes = BuildPaddedSharedJsonFixture(
            "{\"version\":1,\"lastFolderSet\":[],\"recentFolderSets\":[],\"padding\":\"",
            "\"}",
            SharedJsonDocumentReader.MaxDocumentBytes + 1);
        File.WriteAllBytes(sharedRecentPath, oversizedRecentBytes);
        SharedRecentReadResult oversizedRecentRead =
            PhotoViewer.Wpf.MainWindow.ReadSharedRecentFoldersForSmoke(
                sharedRecentPath);
        IReadOnlyList<string> oversizedSelection =
            PhotoViewer.Wpf.MainWindow.ResolveStartupFolderSetForSmoke(
                sharedRecentPath,
                [localFallbackFolder],
                null);
        bool oversizedRecentProtected = !oversizedRecentRead.Ok
            && oversizedRecentRead.Exists
            && oversizedSelection.Count == 1
            && string.Equals(
                NormalizeFavoritePath(oversizedSelection[0]),
                NormalizeFavoritePath(localFallbackFolder),
                StringComparison.OrdinalIgnoreCase)
            && !PhotoViewer.Wpf.MainWindow.TryMergeSharedRecentForSmoke(
                sharedRecentPath,
                unreadableFolder)
            && File.ReadAllBytes(sharedRecentPath).AsSpan().SequenceEqual(
                oversizedRecentBytes);

        WriteLocalFolderFallback(statePath, localFallbackFolder);
        WriteSharedRecentSeed(sharedRecentPath, fullFolder, preservedFolder);
        var writeWindow = HiddenWindow();
        writeWindow.Show();
        await writeWindow.LoadFolderAsync(writeFolder);
        string? writeCurrentFolder = writeWindow.CurrentFolderForSmoke;
        writeWindow.Close();

        SharedRecentSmokeSnapshot afterWrite = ReadSharedRecentSnapshot(sharedRecentPath);
        ViewerState? stateAfterWrite = ReadPersistedState(statePath);
        bool wroteLastFolder = afterWrite.Ok
            && afterWrite.LastFolderSet.Count == 1
            && string.Equals(afterWrite.LastFolderSet[0], NormalizeFavoritePath(writeFolder), StringComparison.OrdinalIgnoreCase);
        bool additivePreserved = afterWrite.Ok && afterWrite.ContainsFolderSet(preservedFolder);
        bool writeFolderInRecent = afterWrite.Ok && afterWrite.ContainsFolderSet(writeFolder);
        bool statePreserved = stateAfterWrite is not null
            && string.Equals(
                NormalizeFavoritePath(stateAfterWrite.LastFolder ?? ""),
                NormalizeFavoritePath(writeFolder),
                StringComparison.OrdinalIgnoreCase);
        WriteSharedRecentSeed(sharedRecentPath, externalSharedFolder, preservedFolder);
        var reloadWindow = HiddenWindow();
        reloadWindow.Show();
        string? reloadedCurrentFolder = reloadWindow.CurrentFolderForSmoke;
        reloadWindow.Close();
        bool reloadedSharedStateWins = string.Equals(
            NormalizeFavoritePath(reloadedCurrentFolder ?? ""),
            NormalizeFavoritePath(externalSharedFolder),
            StringComparison.OrdinalIgnoreCase);

        ViewerState? stateAfterSharedReload = ReadPersistedState(statePath);
        bool localFallbackTracksSharedAuthority = stateAfterSharedReload is not null
            && string.Equals(
                NormalizeFavoritePath(stateAfterSharedReload.LastFolder ?? ""),
                NormalizeFavoritePath(externalSharedFolder),
                StringComparison.OrdinalIgnoreCase);
        bool favoritesUnchanged = string.Equals(favoritesBefore, File.ReadAllText(favoritesPath), StringComparison.Ordinal);
        bool seenUnchanged = string.Equals(seenBefore, File.ReadAllText(seenPath), StringComparison.Ordinal);

        bool ok = string.Equals(Path.GetFullPath(resolvedRecentPath), Path.GetFullPath(sharedRecentPath), StringComparison.OrdinalIgnoreCase)
            && importedSharedLastFolder
            && explicitEmptySharedWins
            && missingUsesLocalFallback
            && malformedUsesLocalFallback
            && futureUsesLocalFallback
            && string.Equals(NormalizeFavoritePath(writeCurrentFolder ?? ""), NormalizeFavoritePath(writeFolder), StringComparison.OrdinalIgnoreCase)
            && wroteLastFolder
            && writeFolderInRecent
            && additivePreserved
            && statePreserved
            && reloadedSharedStateWins
            && malformedPreserved
            && futurePreserved
            && unreadableExistingProtected
            && invalidUtf8RecentProtected
            && utf32RecentProtected
            && exactLimitRecentWriterRefused
            && oversizedRecentProtected
            && localFallbackTracksSharedAuthority
            && favoritesUnchanged
            && seenUnchanged;

        return new SharedRecentSmokeResult
        {
            Ok = ok,
            Message = ok ? "shared recent authority, fallback, write-through, and byte protection passed" : "shared recent smoke did not meet expected policy",
            Folder = fullFolder,
            ProjectRoot = smokeRoot,
            SharedRecentPath = sharedRecentPath,
            ResolvedRecentPath = resolvedRecentPath,
            ImportedCurrentFolder = importedCurrentFolder,
            WriteFolder = writeFolder,
            PreservedFolder = preservedFolder,
            MalformedFolder = malformedFolder,
            WriteCurrentFolder = writeCurrentFolder,
            LastFolderAfterWrite = afterWrite.LastFolderSet,
            RecentFolderSetCountAfterWrite = afterWrite.RecentFolderSets.Count,
            ImportedSharedLastFolder = importedSharedLastFolder,
            ExplicitEmptySharedWins = explicitEmptySharedWins,
            MissingUsesLocalFallback = missingUsesLocalFallback,
            MalformedUsesLocalFallback = malformedUsesLocalFallback,
            FutureUsesLocalFallback = futureUsesLocalFallback,
            WroteLastFolder = wroteLastFolder,
            WriteFolderInRecent = writeFolderInRecent,
            AdditivePreserved = additivePreserved,
            StatePreserved = statePreserved,
            ReloadedCurrentFolder = reloadedCurrentFolder,
            ReloadedSharedStateWins = reloadedSharedStateWins,
            MalformedPreserved = malformedPreserved,
            FuturePreserved = futurePreserved,
            UnreadableExistingProtected = unreadableExistingProtected,
            InvalidUtf8RecentProtected = invalidUtf8RecentProtected,
            Utf32RecentProtected = utf32RecentProtected,
            ExactLimitRecentWriterRefused = exactLimitRecentWriterRefused,
            OversizedRecentProtected = oversizedRecentProtected,
            LocalFallbackTracksSharedAuthority = localFallbackTracksSharedAuthority,
            FavoritesUnchanged = favoritesUnchanged,
            SeenUnchanged = seenUnchanged,
        };
    }

    private void CaptureFolderSetSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteFolderSetSmokeResult(resultPath, new FolderSetSmokeResult { Ok = false, Message = "missing required --folder", Folder = folder });
            Shutdown(1);
            return;
        }

        string fullFolder = Path.GetFullPath(folder);
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousRecentPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        Environment.SetEnvironmentVariable(
            "PHOTOVIEWER_WPF_RECENT_PATH",
            Path.Combine(smokeRoot, ".cache", "recent-folders.json"));
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        win.Show();

        win.Dispatcher.InvokeAsync(async () =>
        {
            FolderSetSmokeResult result;
            try
            {
                result = await RunFolderSetSmokeAsync(win, fullFolder, smokeRoot);
            }
            catch (Exception ex)
            {
                win.Close();
                result = new FolderSetSmokeResult { Ok = false, Message = ex.Message, Folder = folder, ProjectRoot = smokeRoot };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", previousRecentPath);
            }

            WriteFolderSetSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static async Task<FolderSetSmokeResult> RunFolderSetSmokeAsync(MainWindow win, string fullFolder, string smokeRoot)
    {
        string cacheRoot = Path.Combine(smokeRoot, ".cache");
        string sharedRecentPath = Path.Combine(cacheRoot, "recent-folders.json");
        string favoritesPath = Path.Combine(cacheRoot, "favorites.json");
        string seenPath = Path.Combine(cacheRoot, "seen.json");
        string statePath = Path.Combine(cacheRoot, "state.json");
        string secondFolder = PrepareSecondFolderFixture(fullFolder, smokeRoot);
        string preservedFolder = Path.Combine(smokeRoot, "preserved-folder");
        string missingFolder = Path.Combine(smokeRoot, "missing-folder");
        Directory.CreateDirectory(preservedFolder);

        WriteFavoriteSeed(favoritesPath, Path.Combine(fullFolder, "folder-set-favorite-seed.png"), 4);
        WriteSeenSeed(seenPath, Path.Combine(fullFolder, "folder-set-seen-seed.png"));
        string favoritesBefore = File.ReadAllText(favoritesPath);
        var seenBeforeMap = ReadSeenMap(seenPath);
        WriteSharedRecentSetSeed(sharedRecentPath, [fullFolder, secondFolder], [preservedFolder]);

        var importWindow = HiddenWindow();
        importWindow.Show();
        string resolvedRecentPath = importWindow.SharedRecentPathForSmoke;
        var importedLanding = importWindow.LandingFolderSetForSmoke;
        int recentCountOnStartup = importWindow.RecentFolderSetCountForSmoke;
        importWindow.Close();

        string folderSetFavoritesPath = Path.Combine(
            cacheRoot,
            "folder-set-favorites.json");
        win.SetLandingFolderSetForSmoke([fullFolder]);
        bool favoriteSaved = win.SaveCurrentFolderSetFavoriteForSmoke();
        bool favoriteDuplicateDeduplicated = win.SaveCurrentFolderSetFavoriteForSmoke()
            && win.FavoriteFolderSetCountForSmoke == 1;
        string folderSetFavoriteJson = File.ReadAllText(folderSetFavoritesPath);
        File.WriteAllText(
            folderSetFavoritesPath,
            folderSetFavoriteJson.Replace(
                "\"version\": 1,",
                "\"version\": 1,\n  \"smokeMarker\": \"keep\",",
                StringComparison.Ordinal));
        win.SetLandingFolderSetForSmoke([secondFolder]);
        bool secondFavoriteSaved = win.SaveCurrentFolderSetFavoriteForSmoke();
        bool favoriteSelectionRestored = win.SelectFavoriteFolderSetForSmoke(1)
            && SameFolderSet(win.LandingFolderSetForSmoke, [fullFolder]);
        bool favoriteRemoved = win.RemoveFavoriteFolderSetForSmoke(0)
            && win.FavoriteFolderSetCountForSmoke == 1
            && SameFolderSet(win.FavoriteFolderSetsForSmoke[0], [fullFolder]);
        bool favoriteUnknownPreserved = File.ReadAllText(folderSetFavoritesPath)
            .Contains("\"smokeMarker\": \"keep\"", StringComparison.Ordinal);
        bool favoriteStoreIsolated = string.Equals(
                win.FolderSetFavoritesPathForSmoke,
                folderSetFavoritesPath,
                StringComparison.OrdinalIgnoreCase)
            && Path.GetFullPath(folderSetFavoritesPath)
            .StartsWith(Path.GetFullPath(smokeRoot) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase);

        win.SetLandingFolderSetForSmoke([fullFolder, secondFolder]);
        win.SetLandingFolderSetForSmoke([secondFolder]);
        bool replaceDiscardedOldDraft = SameFolderSet(win.LandingFolderSetForSmoke, [secondFolder]);

        var scrollFolders = new List<string>();
        for (int index = 0; index < 10; index++)
        {
            string scrollFolder = Path.Combine(smokeRoot, $"scroll-folder-{index:00}");
            Directory.CreateDirectory(scrollFolder);
            scrollFolders.Add(scrollFolder);
        }
        win.SetLandingFolderSetForSmoke(scrollFolders);
        win.UpdateLandingFolderNavigationLayoutForSmoke();
        bool selectedFoldersScrollable = win.LandingFolderSetOverflowForSmoke;
        bool navigationSurface = win.LandingFolderNavigationSurfaceContractForSmoke;

        win.SetLandingFolderSetForSmoke([fullFolder]);
        int pastedAdded = win.AppendPastedFoldersForSmoke(string.Join(Environment.NewLine, [secondFolder, missingFolder, fullFolder]));
        var landingAfterPaste = win.LandingFolderSetForSmoke;
        win.ConfigureScanPhaseDelaysForSmoke(enumerationMilliseconds: 200, metadataMilliseconds: 0);
        Task<bool> openTask = win.StartLandingFolderSetOpenForSmokeAsync();
        bool immediateBusyFeedback = win.LandingFolderOpenBusyForSmoke;
        bool duplicateOpenBlocked = !await win.StartLandingFolderSetOpenForSmokeAsync();
        bool openedFromLanding = await openTask;
        win.ConfigureScanPhaseDelaysForSmoke(enumerationMilliseconds: 0, metadataMilliseconds: 0);
        var currentFolderSet = win.CurrentFolderSetForSmoke;
        int filteredAfterLoad = win.FilteredCountForSmoke;
        string? currentFolder = win.CurrentFolderForSmoke;
        win.Close();

        SharedRecentSmokeSnapshot afterWrite = ReadSharedRecentSnapshot(sharedRecentPath);
        ViewerState? stateAfterWrite = ReadPersistedState(statePath);
        int expectedMinImages = CountDirectSmokeImages(fullFolder) + CountDirectSmokeImages(secondFolder);
        bool importedSharedLastFolderSet = SameFolderSet(importedLanding, [fullFolder, secondFolder]);
        bool pastedSecondFolder = pastedAdded == 1 && SameFolderSet(landingAfterPaste, [fullFolder, secondFolder]);
        bool loadedCurrentFolderSet = SameFolderSet(currentFolderSet, [fullFolder, secondFolder]);
        bool stateSavedFolderSet = stateAfterWrite?.LastFolderSet is not null && SameFolderSet(stateAfterWrite.LastFolderSet, [fullFolder, secondFolder]);
        bool wroteSharedLastFolderSet = afterWrite.Ok && SameFolderSet(afterWrite.LastFolderSet, [fullFolder, secondFolder]);
        bool writeFolderSetInRecent = afterWrite.Ok && SnapshotContainsFolderSet(afterWrite, [fullFolder, secondFolder]);
        bool additivePreserved = afterWrite.Ok && SnapshotContainsFolderSet(afterWrite, [preservedFolder]);
        bool favoritesUnchanged = string.Equals(favoritesBefore, File.ReadAllText(favoritesPath), StringComparison.Ordinal);
        var seenAfterMap = ReadSeenMap(seenPath);
        bool seenPreserved = seenBeforeMap.Keys.All(path => seenAfterMap.ContainsKey(path));

        bool ok = string.Equals(Path.GetFullPath(resolvedRecentPath), Path.GetFullPath(sharedRecentPath), StringComparison.OrdinalIgnoreCase)
            && importedSharedLastFolderSet
            && recentCountOnStartup > 0
            && favoriteSaved
            && favoriteDuplicateDeduplicated
            && secondFavoriteSaved
            && favoriteSelectionRestored
            && favoriteRemoved
            && favoriteUnknownPreserved
            && favoriteStoreIsolated
            && replaceDiscardedOldDraft
            && selectedFoldersScrollable
            && navigationSurface
            && immediateBusyFeedback
            && duplicateOpenBlocked
            && openedFromLanding
            && pastedSecondFolder
            && loadedCurrentFolderSet
            && string.Equals(NormalizeFavoritePath(currentFolder ?? ""), NormalizeFavoritePath(fullFolder), StringComparison.OrdinalIgnoreCase)
            && filteredAfterLoad >= expectedMinImages
            && stateSavedFolderSet
            && wroteSharedLastFolderSet
            && writeFolderSetInRecent
            && additivePreserved
            && favoritesUnchanged
            && seenPreserved;

        return new FolderSetSmokeResult
        {
            Ok = ok,
            Message = ok ? "folder-set replace, scrolling, favorites, immediate load feedback, multi-folder load, shared recent write-through, and state persistence passed" : "folder-set smoke did not meet expected policy",
            Folder = fullFolder,
            ProjectRoot = smokeRoot,
            SharedRecentPath = sharedRecentPath,
            ResolvedRecentPath = resolvedRecentPath,
            SecondFolder = secondFolder,
            MissingFolder = missingFolder,
            ImportedLandingFolderSet = importedLanding,
            LandingAfterPaste = landingAfterPaste,
            CurrentFolderSet = currentFolderSet,
            CurrentFolder = currentFolder,
            PastedAdded = pastedAdded,
            RecentCountOnStartup = recentCountOnStartup,
            FilteredAfterLoad = filteredAfterLoad,
            ExpectedMinImages = expectedMinImages,
            StateLastFolderSet = stateAfterWrite?.LastFolderSet ?? [],
            SharedLastFolderSet = afterWrite.LastFolderSet,
            RecentFolderSetCountAfterWrite = afterWrite.RecentFolderSets.Count,
            FolderSetFavoritesPath = folderSetFavoritesPath,
            ImportedSharedLastFolderSet = importedSharedLastFolderSet,
            FavoriteSaved = favoriteSaved,
            FavoriteDuplicateDeduplicated = favoriteDuplicateDeduplicated,
            SecondFavoriteSaved = secondFavoriteSaved,
            FavoriteSelectionRestored = favoriteSelectionRestored,
            FavoriteRemoved = favoriteRemoved,
            FavoriteUnknownPreserved = favoriteUnknownPreserved,
            FavoriteStoreIsolated = favoriteStoreIsolated,
            ReplaceDiscardedOldDraft = replaceDiscardedOldDraft,
            SelectedFoldersScrollable = selectedFoldersScrollable,
            NavigationSurface = navigationSurface,
            ImmediateBusyFeedback = immediateBusyFeedback,
            DuplicateOpenBlocked = duplicateOpenBlocked,
            OpenedFromLanding = openedFromLanding,
            PastedSecondFolder = pastedSecondFolder,
            LoadedCurrentFolderSet = loadedCurrentFolderSet,
            StateSavedFolderSet = stateSavedFolderSet,
            WroteSharedLastFolderSet = wroteSharedLastFolderSet,
            WriteFolderSetInRecent = writeFolderSetInRecent,
            AdditivePreserved = additivePreserved,
            FavoritesUnchanged = favoritesUnchanged,
            SeenPreserved = seenPreserved,
        };
    }

    private void CaptureFolderBucketSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        FolderBucketSmokeFixture fixture = PrepareFolderBucketSmokeFixture(smokeRoot);
        string seededStatePath = Path.Combine(smokeRoot, ".cache", "state.json");
        File.WriteAllText(seededStatePath, "{\"Version\":1,\"futureFolderBucketFlag\":{\"preserve\":true}}");

        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var first = HiddenWindow();
        first.Show();

        first.Dispatcher.InvokeAsync(async () =>
        {
            FolderBucketSmokeResult result;
            try
            {
                await first.LoadFolderSetAsync([fixture.FolderA, fixture.FolderB]);
                string statePath = first.StatePathForSmoke;
                int allCount = first.FilteredCountForSmoke;
                int bucketCount = first.FolderBucketCountForSmoke;
                List<string> bucketKeys = first.FolderBucketKeysForSmoke;
                bool defaultExpanded = first.FoldersSectionExpandedForSmoke;
                bool folderAccessibility = first.FolderBucketSelectionAccessibleForSmoke && first.FocusFolderBucketListForSmoke();
                System.Windows.Automation.Peers.AutomationPeer? foldersTogglePeer =
                    System.Windows.Automation.Peers.UIElementAutomationPeer.CreatePeerForElement(first.FoldersSectionToggle);
                var foldersExpandCollapseProvider = foldersTogglePeer?
                    .GetPattern(System.Windows.Automation.Peers.PatternInterface.ExpandCollapse)
                    as System.Windows.Automation.Provider.IExpandCollapseProvider;
                string folderAutomationInitialState = foldersExpandCollapseProvider?.ExpandCollapseState.ToString() ?? "Unavailable";
                foldersExpandCollapseProvider?.Collapse();
                string folderAutomationCollapsedState = foldersExpandCollapseProvider?.ExpandCollapseState.ToString() ?? "Unavailable";
                bool folderAutomationCollapsedVisual = !first.FoldersSectionExpandedForSmoke;
                foldersExpandCollapseProvider?.Expand();
                string folderAutomationExpandedState = foldersExpandCollapseProvider?.ExpandCollapseState.ToString() ?? "Unavailable";
                bool folderAutomationExpandedVisual = first.FoldersSectionExpandedForSmoke;
                bool folderAutomationRoundTrip = foldersExpandCollapseProvider is not null
                    && string.Equals(folderAutomationInitialState, "Expanded", StringComparison.Ordinal)
                    && string.Equals(folderAutomationCollapsedState, "Collapsed", StringComparison.Ordinal)
                    && folderAutomationCollapsedVisual
                    && string.Equals(folderAutomationExpandedState, "Expanded", StringComparison.Ordinal)
                    && folderAutomationExpandedVisual;
                int favoritesBeforeBucketSelection = first.FavoriteStoreCountForSmoke;
                int seenBeforeBucketSelection = first.SeenStoreCountForSmoke;
                bool selectedRange = first.SelectFolderBucketRangeForSmoke(0, 1);
                bool toggledFirstBucket = first.ToggleFolderBucketSelectionForSmoke(0);
                List<string> selectedAfterToggle = first.SelectedFolderBucketKeysForSmoke;
                string? primaryAfterToggle = first.PrimarySelectedFolderBucketKeyForSmoke;
                bool hideSelected = first.HideSelectedFolderBucketsForSmoke();
                int afterHideSelected = first.FilteredCountForSmoke;
                bool showSelected = first.ShowSelectedFolderBucketsForSmoke();
                int afterShowSelected = first.FilteredCountForSmoke;
                bool selectedActionsOk = selectedRange && toggledFirstBucket
                    && selectedAfterToggle.SequenceEqual([fixture.FolderB], StringComparer.OrdinalIgnoreCase)
                    && string.Equals(primaryAfterToggle, fixture.FolderB, StringComparison.OrdinalIgnoreCase)
                    && hideSelected && afterHideSelected == fixture.FolderACount
                    && showSelected && afterShowSelected == fixture.TotalCount
                    && first.FavoriteStoreCountForSmoke == favoritesBeforeBucketSelection
                    && first.SeenStoreCountForSmoke == seenBeforeBucketSelection;

                bool selectedFolderA = first.SelectFileNameForSmoke(fixture.FolderASelectedName);
                bool hideFolderA = first.SetFolderBucketHiddenForSmoke(fixture.FolderA, true);
                int afterHideFolderA = first.FilteredCountForSmoke;
                List<string> afterHideFolderAOrder = first.FilteredFileNamesForSmoke(10);
                string? selectedAfterHideFolderA = first.SelectedFileNameForSmoke;

                bool showFolderA = first.SetFolderBucketHiddenForSmoke(fixture.FolderA, false);
                int afterShowFolderA = first.FilteredCountForSmoke;

                bool selectedFolderAAgain = first.SelectFileNameForSmoke(fixture.FolderASelectedName);
                bool hideFolderB = first.SetFolderBucketHiddenForSmoke(fixture.FolderB, true);
                int afterHideFolderB = first.FilteredCountForSmoke;
                string? selectedAfterHideFolderB = first.SelectedFileNameForSmoke;

                first.InvertFolderBucketsForSmoke();
                int afterInvert = first.FilteredCountForSmoke;
                List<string> afterInvertOrder = first.FilteredFileNamesForSmoke(10);

                first.ShowAllFolderBucketsForSmoke();
                int afterShowAll = first.FilteredCountForSmoke;

                first.HideAllFolderBucketsForSmoke();
                int afterHideAll = first.FilteredCountForSmoke;

                first.ShowAllFolderBucketsForSmoke();
                bool selectedFolderBBeforePersistence = first.SelectFolderBucketRangeForSmoke(1, 1);
                List<string> selectedBeforePersistence = first.SelectedFolderBucketKeysForSmoke;
                bool persistedHideFolderB = first.SetFolderBucketHiddenForSmoke(fixture.FolderB, true);
                first.ToggleFoldersSectionForSmoke();
                ViewerState? persisted = ReadPersistedState(statePath);
                string favoritesPath = first.FavoritesPathForSmoke;
                string seenPath = first.SeenPathForSmoke;
                string favoritesBefore = File.Exists(favoritesPath) ? File.ReadAllText(favoritesPath) : "";
                int seenBefore = first.SeenStoreCountForSmoke;
                first.Close();

                var second = HiddenWindow();
                second.Show();
                await second.LoadFolderSetAsync([fixture.FolderA, fixture.FolderB]);
                int restoredCount = second.FilteredCountForSmoke;
                int restoredHiddenCount = second.HiddenFolderBucketCountForSmoke;
                List<string> restoredHiddenKeys = second.HiddenFolderBucketKeysForSmoke;
                List<string> restoredOrder = second.FilteredFileNamesForSmoke(10);
                int favoriteCountAfterReload = second.FavoriteStoreCountForSmoke;
                int seenAfterReload = second.SeenStoreCountForSmoke;
                bool collapsedAfterReload = !second.FoldersSectionExpandedForSmoke;
                List<string> selectedBucketsAfterReload = second.SelectedFolderBucketKeysForSmoke;
                string? primaryBucketAfterReload = second.PrimarySelectedFolderBucketKeyForSmoke;
                bool sortSelectionPreserved = second.SetSortByForSmoke("name")
                    && second.SelectedFolderBucketKeysForSmoke.SequenceEqual([fixture.FolderB], StringComparer.OrdinalIgnoreCase)
                    && string.Equals(second.PrimarySelectedFolderBucketKeyForSmoke, fixture.FolderB, StringComparison.OrdinalIgnoreCase);
                bool rootsPreserved = second.CurrentFolderSetForSmoke.SequenceEqual([fixture.FolderA, fixture.FolderB], StringComparer.OrdinalIgnoreCase);
                second.Close();

                string invalidStatePath = Path.Combine(smokeRoot, ".cache", "invalid-legacy-state.json");
                File.WriteAllText(invalidStatePath, "{\"Version\":99,\"FoldersSectionExpanded\":false}");
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", invalidStatePath);
                var invalidLegacy = HiddenWindow();
                invalidLegacy.Show();
                bool invalidLegacyFallback = invalidLegacy.FoldersSectionExpandedForSmoke;
                invalidLegacy.Close();
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);

                bool bucketKeysOk = bucketCount == 2
                    && bucketKeys.Contains(fixture.FolderA, StringComparer.OrdinalIgnoreCase)
                    && bucketKeys.Contains(fixture.FolderB, StringComparer.OrdinalIgnoreCase);
                bool hideFolderAOk = selectedFolderA
                    && hideFolderA
                    && afterHideFolderA == fixture.FolderBCount
                    && afterHideFolderAOrder.All(name => name.EndsWith("-b.png", StringComparison.OrdinalIgnoreCase))
                    && !string.Equals(selectedAfterHideFolderA, fixture.FolderASelectedName, StringComparison.OrdinalIgnoreCase);
                bool showFolderAOk = showFolderA && afterShowFolderA == fixture.TotalCount;
                bool hideFolderBOk = selectedFolderAAgain
                    && hideFolderB
                    && afterHideFolderB == fixture.FolderACount
                    && string.Equals(selectedAfterHideFolderB, fixture.FolderASelectedName, StringComparison.OrdinalIgnoreCase);
                bool invertOk = afterInvert == fixture.FolderBCount
                    && afterInvertOrder.All(name => name.EndsWith("-b.png", StringComparison.OrdinalIgnoreCase));
                bool bulkOk = afterShowAll == fixture.TotalCount && afterHideAll == 0;
                bool persistenceOk = persistedHideFolderB
                    && persisted?.HiddenFolderBuckets is not null
                    && persisted.HiddenFolderBuckets.Count == 1
                    && persisted.HiddenFolderBuckets.Contains(fixture.FolderB, StringComparer.OrdinalIgnoreCase)
                    && restoredCount == fixture.FolderACount
                    && restoredHiddenCount == 1
                    && restoredHiddenKeys.Contains(fixture.FolderB, StringComparer.OrdinalIgnoreCase)
                    && restoredOrder.All(name => name.EndsWith("-a.png", StringComparison.OrdinalIgnoreCase));
                bool stateIsolated = favoriteCountAfterReload == 0
                    && string.IsNullOrWhiteSpace(favoritesBefore)
                    && Path.GetFullPath(favoritesPath).StartsWith(Path.GetFullPath(smokeRoot), StringComparison.OrdinalIgnoreCase)
                    && Path.GetFullPath(seenPath).StartsWith(Path.GetFullPath(smokeRoot), StringComparison.OrdinalIgnoreCase)
                    && seenAfterReload >= seenBefore;

                bool ok = allCount == fixture.TotalCount
                    && bucketKeysOk
                    && hideFolderAOk
                    && showFolderAOk
                    && hideFolderBOk
                    && invertOk
                    && bulkOk
                    && defaultExpanded
                    && folderAccessibility
                    && folderAutomationRoundTrip
                    && selectedActionsOk
                    && persistenceOk
                    && selectedFolderBBeforePersistence
                    && persisted?.Version == 2
                    && persisted?.FoldersSectionExpanded == false
                    && persisted?.SelectedFolderBucketKeys?.SequenceEqual([fixture.FolderB], StringComparer.OrdinalIgnoreCase) == true
                    && string.Equals(persisted?.PrimarySelectedFolderBucketKey, fixture.FolderB, StringComparison.OrdinalIgnoreCase)
                    && File.ReadAllText(statePath).Contains("futureFolderBucketFlag", StringComparison.OrdinalIgnoreCase)
                    && collapsedAfterReload
                    && selectedBucketsAfterReload.SequenceEqual([fixture.FolderB], StringComparer.OrdinalIgnoreCase)
                    && string.Equals(primaryBucketAfterReload, fixture.FolderB, StringComparison.OrdinalIgnoreCase)
                    && sortSelectionPreserved
                    && rootsPreserved
                    && invalidLegacyFallback
                    && stateIsolated;

                result = new FolderBucketSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "folder bucket sidebar UI Automation expansion, multi-select actions, migration, persistence, and state isolation checks passed"
                        : "folder bucket smoke did not meet UI Automation/show/hide/selection/persistence expectations",
                    ProjectRoot = smokeRoot,
                    FolderA = fixture.FolderA,
                    FolderB = fixture.FolderB,
                    StatePath = statePath,
                    AllCount = allCount,
                    BucketCount = bucketCount,
                    BucketKeys = bucketKeys,
                    DefaultExpanded = defaultExpanded,
                    FolderAccessibility = folderAccessibility,
                    FolderAutomationInitialState = folderAutomationInitialState,
                    FolderAutomationCollapsedState = folderAutomationCollapsedState,
                    FolderAutomationExpandedState = folderAutomationExpandedState,
                    FolderAutomationRoundTrip = folderAutomationRoundTrip,
                    SelectedActionsOk = selectedActionsOk,
                    SelectedFolderA = selectedFolderA,
                    AfterHideFolderA = afterHideFolderA,
                    AfterHideFolderAOrder = afterHideFolderAOrder,
                    SelectedAfterHideFolderA = selectedAfterHideFolderA,
                    AfterShowFolderA = afterShowFolderA,
                    SelectedFolderAAgain = selectedFolderAAgain,
                    AfterHideFolderB = afterHideFolderB,
                    SelectedAfterHideFolderB = selectedAfterHideFolderB,
                    AfterInvert = afterInvert,
                    AfterInvertOrder = afterInvertOrder,
                    AfterShowAll = afterShowAll,
                    AfterHideAll = afterHideAll,
                    PersistedHiddenBuckets = persisted?.HiddenFolderBuckets ?? [],
                    SelectedBeforePersistence = selectedBeforePersistence,
                    PersistedSelectedBuckets = persisted?.SelectedFolderBucketKeys ?? [],
                    CollapsedAfterReload = collapsedAfterReload,
                    SelectedBucketsAfterReload = selectedBucketsAfterReload,
                    SortSelectionPreserved = sortSelectionPreserved,
                    InvalidLegacyFallback = invalidLegacyFallback,
                    RestoredCount = restoredCount,
                    RestoredHiddenCount = restoredHiddenCount,
                    RestoredHiddenKeys = restoredHiddenKeys,
                    RestoredOrder = restoredOrder,
                    FavoriteCountAfterReload = favoriteCountAfterReload,
                    SeenBefore = seenBefore,
                    SeenAfterReload = seenAfterReload,
                    FavoritesPath = favoritesPath,
                    SeenPath = seenPath,
                    StateIsolated = stateIsolated,
                };
            }
            catch (Exception ex)
            {
                first.Close();
                result = new FolderBucketSmokeResult { Ok = false, Message = ex.Message, ProjectRoot = smokeRoot, FolderA = fixture.FolderA, FolderB = fixture.FolderB };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteFolderBucketSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureGridZoomSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteGridZoomSmokeResult(resultPath, new GridZoomSmokeResult { Message = "missing required --folder", Folder = folder });
            Shutdown(1);
            return;
        }

        string resultFullPath = Path.GetFullPath(resultPath);
        int expectedInitialWidth = ArgInt(args, "--expected-initial-width", 20);
        string resultDir = Path.GetDirectoryName(resultFullPath) ?? Path.GetTempPath();
        string statePath = Path.Combine(resultDir, Path.GetFileNameWithoutExtension(resultFullPath) + "-state.json");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        double migratedStateCardWidth = double.NaN;
        bool migrationUnknownStatePreserved = false;
        try
        {
            using JsonDocument migratedState = JsonDocument.Parse(File.ReadAllText(statePath));
            if (migratedState.RootElement.TryGetProperty("CardWidth", out JsonElement cardWidthElement))
                migratedStateCardWidth = cardWidthElement.GetDouble();
            migrationUnknownStatePreserved = migratedState.RootElement.TryGetProperty("LegacyZoomMigrationSentinel", out JsonElement sentinel)
                && sentinel.ValueKind == JsonValueKind.Object
                && sentinel.TryGetProperty("keep", out JsonElement keep)
                && !string.IsNullOrWhiteSpace(keep.GetString());
        }
        catch
        {
        }
        win.Show();
        win.SuppressStatePersistence();

        win.Dispatcher.InvokeAsync(async () =>
        {
            GridZoomSmokeResult result;
            try
            {
                await win.LoadFolderAsync(folder);
                double initial = win.CardWidthForSmoke;
                bool buttonIn = win.ZoomInForSmoke();
                double afterButtonIn = win.CardWidthForSmoke;
                bool buttonOut = win.ZoomOutForSmoke();
                double afterButtonOut = win.CardWidthForSmoke;
                bool shortcutIn = win.ZoomShortcutForSmoke("plus");
                double afterShortcutIn = win.CardWidthForSmoke;
                bool shortcutReset = win.ZoomShortcutForSmoke("0");
                double afterShortcutReset = win.CardWidthForSmoke;
                bool wheelIn = win.ZoomWheelForSmoke(120);
                double afterWheelIn = win.CardWidthForSmoke;
                bool wheelOut = win.ZoomWheelForSmoke(-120);
                double afterWheelOut = win.CardWidthForSmoke;
                double gallerySurfaceWidthBefore = win.CardWidthForSmoke;
                bool gallerySurfaceWheelIn = win.InvokeGallerySurfaceMouseWheelForSmoke(120, ModifierKeys.Control)
                    && win.CardWidthForSmoke > gallerySurfaceWidthBefore;
                bool gallerySurfaceWheelOut = win.InvokeGallerySurfaceMouseWheelForSmoke(-120, ModifierKeys.Control)
                    && Math.Abs(win.CardWidthForSmoke - gallerySurfaceWidthBefore) < 0.01;
                double galleryScrollbarWidthBefore = win.CardWidthForSmoke;
                bool galleryScrollbarWheelIn = win.InvokeGalleryScrollbarMouseWheelForSmoke(120, ModifierKeys.Control)
                    && win.CardWidthForSmoke > galleryScrollbarWidthBefore;
                bool galleryScrollbarWheelOut = win.InvokeGalleryScrollbarMouseWheelForSmoke(-120, ModifierKeys.Control)
                    && Math.Abs(win.CardWidthForSmoke - galleryScrollbarWidthBefore) < 0.01;
                double nonGalleryWidthBefore = win.CardWidthForSmoke;
                bool nonGalleryWheelIsolation = !win.InvokeRightPanelMouseWheelForSmoke(120, ModifierKeys.Control)
                    && !win.InvokeLandingMouseWheelForSmoke(120, ModifierKeys.Control)
                    && Math.Abs(win.CardWidthForSmoke - nonGalleryWidthBefore) < 0.01;
                bool allWidthsMatch = win.AllCardWidthsMatchForSmoke(afterWheelOut);
                int filtered = win.FilteredCountForSmoke;

                bool minimumChanged = win.SetGridZoomForSmoke(20);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                double minimumWidth = win.CardWidthForSmoke;
                bool maximumChanged = win.SetGridZoomForSmoke(600);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                double maximumWidth = win.CardWidthForSmoke;
                int maximumColumns = win.GridColumnCountForSmoke;
                bool maximumForcedSingleColumn = win.GridForcesSingleColumnForSmoke;
                int maximumRealized = win.GridRealizedCountForSmoke;
                int maximumRealizedBound = win.GridMaxRealizationCountForSmoke;

                _ = win.SetGridZoomForSmoke(200);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool middle = await win.ScrollGridToMiddleForSmokeAsync();
                double autoScrollOffsetBefore = win.GalleryVerticalOffsetForSmoke;
                double autoScrollPointer = autoScrollOffsetBefore > 0 ? -180 : 420;
                bool autoScrollStarted = win.BeginGalleryAutoScrollForSmoke(120, autoScrollPointer);
                bool autoScrollTicked = win.TickGalleryAutoScrollForSmoke();
                double autoScrollOffsetAfter = win.GalleryVerticalOffsetForSmoke;
                win.StopGalleryAutoScrollForSmoke();
                bool middleAutoScroll = autoScrollStarted
                    && autoScrollTicked
                    && Math.Abs(autoScrollOffsetAfter - autoScrollOffsetBefore) > 0.1
                    && !win.GalleryAutoScrollActiveForSmoke;
                string duplicateSiblingPath = Path.GetFullPath(Path.Combine(folder, "duplicate-a", "duplicate.png"));
                string selectedCandidatePath = Path.GetFullPath(Path.Combine(folder, "duplicate-b", "duplicate.png"));
                bool duplicateBasenameFixture = win.GridContainsPathForSmoke(duplicateSiblingPath)
                    && win.GridContainsPathForSmoke(selectedCandidatePath)
                    && string.Equals(Path.GetFileName(duplicateSiblingPath), Path.GetFileName(selectedCandidatePath), StringComparison.OrdinalIgnoreCase);
                bool selected = win.SelectPathForSmoke(selectedCandidatePath);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                string? selectedAnchorPath = win.CaptureGridViewportAnchorPathForSmoke();
                string? selectedAnchor = Path.GetFileName(selectedAnchorPath);
                bool selectedAnchorUsesSelection = selected
                    && string.Equals(selectedAnchorPath, selectedCandidatePath, StringComparison.OrdinalIgnoreCase);
                bool duplicateBasenameCanonicalAnchor = duplicateBasenameFixture
                    && selectedAnchorUsesSelection
                    && !string.Equals(selectedAnchorPath, duplicateSiblingPath, StringComparison.OrdinalIgnoreCase);

                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool sidebarCollapsed = !win.SidebarVisibleForSmoke;
                bool sidebarCollapseAnchorKept = string.Equals(win.LastGridZoomAnchorPathForSmoke, selectedAnchorPath, StringComparison.OrdinalIgnoreCase);
                double sidebarCollapseDrift = win.LastGridZoomAnchorDriftForSmoke;
                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool sidebarExpanded = win.SidebarVisibleForSmoke;
                bool sidebarExpandAnchorKept = string.Equals(win.LastGridZoomAnchorPathForSmoke, selectedAnchorPath, StringComparison.OrdinalIgnoreCase);
                double sidebarExpandDrift = win.LastGridZoomAnchorDriftForSmoke;

                double rightPanelWidth = win.RightPanelWidthForSmoke;
                win.ResizeRightPanelForSmoke(Math.Clamp(rightPanelWidth + 80, 240, 900));
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool rightPanelResizeAnchorKept = string.Equals(win.LastGridZoomAnchorPathForSmoke, selectedAnchorPath, StringComparison.OrdinalIgnoreCase);
                double rightPanelResizeDrift = win.LastGridZoomAnchorDriftForSmoke;

                win.ResizeWindowForSmoke(980, 680);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool resizeAnchorKept = string.Equals(win.LastGridZoomAnchorPathForSmoke, selectedAnchorPath, StringComparison.OrdinalIgnoreCase);
                double resizeDrift = win.LastGridZoomAnchorDriftForSmoke;
                win.SimulateDpiGeometryChangeForSmoke(1280, 820);
                await win.WaitForGridZoomAnchorForSmokeAsync();
                string? dpiAnchorPath = win.LastGridZoomAnchorPathForSmoke;
                string? dpiStableAnchorPath = win.LastStableGridViewportAnchorPathForSmoke;
                string? dpiRequestedAnchorPath = win.LastRequestedGridGeometryAnchorPathForSmoke;
                bool dpiAnchorKept = string.Equals(dpiAnchorPath, selectedAnchorPath, StringComparison.OrdinalIgnoreCase);
                double dpiDrift = win.LastGridZoomAnchorDriftForSmoke;

                win.ClearSelectionForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                string? noSelectionAnchorPath = win.CaptureGridViewportAnchorPathForSmoke();
                string? noSelectionAnchor = Path.GetFileName(noSelectionAnchorPath);
                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool noSelectionCollapseKept = !string.IsNullOrWhiteSpace(noSelectionAnchor)
                    && string.Equals(win.LastGridZoomAnchorPathForSmoke, noSelectionAnchorPath, StringComparison.OrdinalIgnoreCase);
                double noSelectionCollapseDrift = win.LastGridZoomAnchorDriftForSmoke;
                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool noSelectionExpandKept = string.Equals(win.LastGridZoomAnchorPathForSmoke, noSelectionAnchorPath, StringComparison.OrdinalIgnoreCase);
                double noSelectionExpandDrift = win.LastGridZoomAnchorDriftForSmoke;

                double gridWidthBeforeList = win.CardWidthForSmoke;
                ListVirtualizationProbe listProbe = await win.ProbeListVirtualizationForSmokeAsync();
                bool listWheelNative = !win.InvokeListSurfaceMouseWheelForSmoke(120, ModifierKeys.Control)
                    && Math.Abs(win.CardWidthForSmoke - gridWidthBeforeList) < 0.01;
                bool listZoomRejected = !win.SetGridZoomForSmoke(600)
                    && Math.Abs(win.CardWidthForSmoke - gridWidthBeforeList) < 0.01;
                bool gridRestored = win.SetGridModeForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();

                bool ok = filtered > 0
                    && Math.Abs(initial - expectedInitialWidth) < 0.01
                    && buttonIn
                    && afterButtonIn > initial
                    && buttonOut
                    && Math.Abs(afterButtonOut - initial) < 0.01
                    && shortcutIn
                    && afterShortcutIn > afterButtonOut
                    && shortcutReset
                    && Math.Abs(afterShortcutReset - 200) < 0.01
                    && wheelIn
                    && afterWheelIn > afterShortcutReset
                    && wheelOut
                    && Math.Abs(afterWheelOut - afterShortcutReset) < 0.01
                    && gallerySurfaceWheelIn
                    && gallerySurfaceWheelOut
                    && galleryScrollbarWheelIn
                    && galleryScrollbarWheelOut
                    && nonGalleryWheelIsolation
                    && allWidthsMatch
                    && minimumChanged
                    && Math.Abs(minimumWidth - 20) < 0.01
                    && maximumChanged
                    && Math.Abs(maximumWidth - 600) < 0.01
                    && maximumColumns == 1
                    && maximumForcedSingleColumn
                    && maximumRealized is > 0
                    && maximumRealized <= maximumRealizedBound
                    && middle
                    && middleAutoScroll
                    && selectedAnchorUsesSelection
                    && duplicateBasenameCanonicalAnchor
                    && sidebarCollapsed
                    && sidebarExpanded
                    && sidebarCollapseAnchorKept
                    && sidebarExpandAnchorKept
                    && sidebarCollapseDrift <= 8
                    && sidebarExpandDrift <= 8
                    && rightPanelResizeAnchorKept
                    && rightPanelResizeDrift <= 8
                    && resizeAnchorKept
                    && resizeDrift <= 8
                    && dpiAnchorKept
                    && dpiDrift <= 8
                    && noSelectionCollapseKept
                    && noSelectionExpandKept
                    && noSelectionCollapseDrift <= 8
                    && noSelectionExpandDrift <= 8
                    && listProbe.ListMode
                    && listProbe.Recycling
                    && listProbe.Bounded
                    && listWheelNative
                    && listZoomRejected
                    && gridRestored;

                result = new GridZoomSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "20px-to-one-column zoom, gallery-surface/scrollbar Ctrl+wheel, middle auto-scroll, canonical anchors, and Grid/List virtualization passed"
                        : "grid zoom/geometry anchor smoke did not match the Browser-parity contract",
                    Folder = folder,
                    StatePath = statePath,
                    FilteredCount = filtered,
                    InitialWidth = initial,
                    MigratedStateCardWidth = migratedStateCardWidth,
                    MigrationUnknownStatePreserved = migrationUnknownStatePreserved,
                    AfterButtonIn = afterButtonIn,
                    AfterButtonOut = afterButtonOut,
                    AfterShortcutIn = afterShortcutIn,
                    AfterShortcutReset = afterShortcutReset,
                    AfterWheelIn = afterWheelIn,
                    ButtonIn = buttonIn,
                    ButtonOut = buttonOut,
                    ShortcutIn = shortcutIn,
                    ShortcutReset = shortcutReset,
                    WheelIn = wheelIn,
                    WheelOutAndTileSync = wheelOut && allWidthsMatch,
                    GallerySurfaceWheelIn = gallerySurfaceWheelIn,
                    GallerySurfaceWheelOut = gallerySurfaceWheelOut,
                    GalleryScrollbarWheelIn = galleryScrollbarWheelIn,
                    GalleryScrollbarWheelOut = galleryScrollbarWheelOut,
                    NonGalleryWheelIsolation = nonGalleryWheelIsolation,
                    MiddleAutoScroll = middleAutoScroll,
                    AutoScrollOffsetBefore = autoScrollOffsetBefore,
                    AutoScrollOffsetAfter = autoScrollOffsetAfter,
                    MinimumWidth = minimumWidth,
                    MaximumWidth = maximumWidth,
                    MaximumColumns = maximumColumns,
                    MaximumForcedSingleColumn = maximumForcedSingleColumn,
                    MaximumRealized = maximumRealized,
                    MaximumRealizedBound = maximumRealizedBound,
                    SelectedAnchor = selectedAnchor,
                    SelectedAnchorPath = selectedAnchorPath,
                    SelectedAnchorUsesSelection = selectedAnchorUsesSelection,
                    DuplicateBasenameCanonicalAnchor = duplicateBasenameCanonicalAnchor,
                    SidebarCollapseAnchorKept = sidebarCollapseAnchorKept,
                    SidebarExpandAnchorKept = sidebarExpandAnchorKept,
                    SidebarCollapseDrift = sidebarCollapseDrift,
                    SidebarExpandDrift = sidebarExpandDrift,
                    RightPanelResizeAnchorKept = rightPanelResizeAnchorKept,
                    RightPanelResizeDrift = rightPanelResizeDrift,
                    ResizeAnchorKept = resizeAnchorKept,
                    ResizeDrift = resizeDrift,
                    DpiAnchorKept = dpiAnchorKept,
                    DpiAnchorPath = dpiAnchorPath,
                    DpiStableAnchorPath = dpiStableAnchorPath,
                    DpiRequestedAnchorPath = dpiRequestedAnchorPath,
                    DpiDrift = dpiDrift,
                    NoSelectionAnchor = noSelectionAnchor,
                    NoSelectionAnchorPath = noSelectionAnchorPath,
                    NoSelectionCollapseKept = noSelectionCollapseKept,
                    NoSelectionExpandKept = noSelectionExpandKept,
                    NoSelectionCollapseDrift = noSelectionCollapseDrift,
                    NoSelectionExpandDrift = noSelectionExpandDrift,
                    ListMode = listProbe.ListMode,
                    ListUsesRecyclingVirtualization = listProbe.Recycling,
                    ListBounded = listProbe.Bounded,
                    ListRealizedFirst = listProbe.FirstRealized,
                    ListRealizedMiddle = listProbe.MiddleRealized,
                    ListRealizedLast = listProbe.LastRealized,
                    ListWheelNative = listWheelNative,
                    ListZoomRejected = listZoomRejected,
                };
            }
            catch (Exception ex)
            {
                result = new GridZoomSmokeResult { Message = ex.Message, Folder = folder, StatePath = statePath };
            }
            finally
            {
                win.Close();
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteGridZoomSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureDisplayStyleSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteDisplayStyleSmokeResult(resultPath, new DisplayStyleSmokeResult(false, "missing required --folder", folder, null, null, 0, null, null, null, null, false, false, false, false));
            Shutdown(1);
            return;
        }

        string fullFolder = Path.GetFullPath(folder);
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var first = HiddenWindow();
        first.Show();

        first.Dispatcher.InvokeAsync(async () =>
        {
            DisplayStyleSmokeResult result;
            try
            {
                await first.LoadFolderAsync(fullFolder);
                DisplayStyleMetrics standard = first.DisplayStyleMetricsForSmoke();
                bool compactChanged = first.SetDisplayStyleForSmoke("compact");
                DisplayStyleMetrics compact = first.DisplayStyleMetricsForSmoke();
                bool posterChanged = first.SetDisplayStyleForSmoke("poster");
                DisplayStyleMetrics poster = first.DisplayStyleMetricsForSmoke();
                bool zoomed = first.ZoomInForSmoke();
                DisplayStyleMetrics posterZoomed = first.DisplayStyleMetricsForSmoke();
                string statePath = first.StatePathForSmoke;
                int filtered = first.FilteredCountForSmoke;
                first.Close();

                var second = HiddenWindow();
                second.Show();
                await second.LoadFolderAsync(fullFolder);
                DisplayStyleMetrics restored = second.DisplayStyleMetricsForSmoke();
                second.Close();

                ViewerState? persisted = ReadPersistedState(statePath);
                bool compactDense = compact.CardWidth < standard.CardWidth
                    && compact.CardHeight < standard.CardHeight
                    && compact.ListThumbnailSize < standard.ListThumbnailSize
                    && Area(compact) < Area(standard);
                bool posterExpanded = poster.CardWidth > standard.CardWidth
                    && poster.CardHeight > standard.CardHeight
                    && poster.ListThumbnailSize > standard.ListThumbnailSize
                    && Area(poster) > Area(standard);
                bool zoomComposes = zoomed
                    && posterZoomed.CardWidth > poster.CardWidth
                    && posterZoomed.CardHeight > poster.CardHeight;
                bool persistedPoster = string.Equals(persisted?.DisplayStyle, "poster", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(restored.Style, "poster", StringComparison.OrdinalIgnoreCase);

                bool ok = filtered > 0
                    && string.Equals(standard.Style, "standard", StringComparison.OrdinalIgnoreCase)
                    && compactChanged
                    && posterChanged
                    && compactDense
                    && posterExpanded
                    && zoomComposes
                    && persistedPoster;

                result = new DisplayStyleSmokeResult(
                    ok,
                    ok ? "display styles changed grid density/size, composed with zoom, and restored from WPF state" : "display style smoke did not meet density/size/persistence expectations",
                    fullFolder,
                    smokeRoot,
                    statePath,
                    filtered,
                    standard,
                    compact,
                    poster,
                    posterZoomed,
                    compactChanged,
                    posterChanged,
                    zoomed,
                    persistedPoster);
            }
            catch (Exception ex)
            {
                first.Close();
                result = new DisplayStyleSmokeResult(false, ex.Message, fullFolder, smokeRoot, null, 0, null, null, null, null, false, false, false, false);
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteDisplayStyleSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static double Area(DisplayStyleMetrics metrics)
        => metrics.CardWidth * metrics.CardHeight;

    private void CaptureAspectSmoke(string resultPath, string[] args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        string aspectFolder = PrepareAspectSmokeFolder(smokeRoot);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var first = HiddenWindow();
        first.Show();

        first.Dispatcher.InvokeAsync(async () =>
        {
            AspectSmokeResult result;
            try
            {
                await first.LoadFolderAsync(aspectFolder);
                bool metadataReady = await first.WaitForCatalogImageDimensionsForSmokeAsync();
                int metadataLayoutPublishCount = first.MetadataOriginalAspectLayoutPublishCountForSmoke;
                int metadataFallbackBefore = first.MetadataOriginalAspectLayoutFallbackCountForSmoke;
                int discardedBefore = first.CatalogProjectionDiscardedCountForSmoke;
                using var projectionEntered = new ManualResetEventSlim(false);
                using var projectionRelease = new ManualResetEventSlim(false);
                first.ConfigureCatalogProjectionComputeGateForSmoke(projectionEntered, projectionRelease);
                Task<MainWindow.SearchFilterCompletion> metadataRaceTask = first.PublishCompletedMetadataLayoutForSmokeAsync();
                var projectionWait = Stopwatch.StartNew();
                while (!projectionEntered.IsSet
                    && !metadataRaceTask.IsCompleted
                    && projectionWait.ElapsedMilliseconds < 5_000)
                {
                    await Task.Delay(5);
                }
                bool metadataRaceComputeEntered = projectionEntered.IsSet;
                bool metadataRaceSelectionChanged = metadataRaceComputeEntered
                    && first.SelectFileNameForSmoke("charlie-portrait.png");
                projectionRelease.Set();
                MainWindow.SearchFilterCompletion metadataRaceCompletion = await metadataRaceTask;
                first.ConfigureCatalogProjectionComputeGateForSmoke(null, null);
                await Task.Delay(20);
                DisplayStyleMetrics metadataRacePortrait = first.DisplayStyleMetricsForSmoke("charlie-portrait.png");
                bool metadataSelectionRaceRecovered = metadataRaceComputeEntered
                    && metadataRaceSelectionChanged
                    && metadataRaceCompletion.Discarded
                    && first.CatalogProjectionDiscardedCountForSmoke == discardedBefore + 1
                    && first.MetadataOriginalAspectLayoutFallbackCountForSmoke == metadataFallbackBefore + 1
                    && !first.MetadataOriginalAspectLayoutPendingForSmoke
                    && string.Equals(first.SelectedFileNameForSmoke, "charlie-portrait.png", StringComparison.OrdinalIgnoreCase)
                    && Math.Abs((metadataRacePortrait.CardHeight / metadataRacePortrait.CardWidth) - 1.5) < 0.03;
                int filtered = first.FilteredCountForSmoke;
                List<string> initialOrder = first.FilteredFileNamesForSmoke(3);
                bool selectedBravo = first.SelectFileNameForSmoke("bravo-square.png");
                string? selectedBefore = first.SelectedFileNameForSmoke;

                DisplayStyleMetrics originalLandscape = first.DisplayStyleMetricsForSmoke("alpha-landscape.png");
                DisplayStyleMetrics originalSquare = first.DisplayStyleMetricsForSmoke("bravo-square.png");
                DisplayStyleMetrics originalPortrait = first.DisplayStyleMetricsForSmoke("charlie-portrait.png");
                DisplayStyleMetrics original = originalLandscape;
                bool squareChanged = first.SetAspectModeForSmoke("square");
                DisplayStyleMetrics square = first.DisplayStyleMetricsForSmoke();
                List<string> squareOrder = first.FilteredFileNamesForSmoke(3);
                string? selectedAfterSquare = first.SelectedFileNameForSmoke;

                bool portraitChanged = first.SetAspectModeForSmoke("portrait");
                DisplayStyleMetrics portrait = first.DisplayStyleMetricsForSmoke();
                List<string> portraitOrder = first.FilteredFileNamesForSmoke(3);
                string? selectedAfterPortrait = first.SelectedFileNameForSmoke;

                bool zoomed = first.ZoomInForSmoke();
                DisplayStyleMetrics portraitZoomed = first.DisplayStyleMetricsForSmoke();
                bool originalChanged = first.SetAspectModeForSmoke("original");
                DisplayStyleMetrics restoredOriginalRuntime = first.DisplayStyleMetricsForSmoke();

                MainWindow.SearchFilterCompletion narrowOriginalSearch =
                    await first.SetSearchInputForSmokeAsync("alpha-landscape");
                first.UpdateLayout();
                await first.Dispatcher.InvokeAsync(
                    first.UpdateLayout,
                    DispatcherPriority.Render);
                int narrowOriginalDistinctRowHeights =
                    first.GridDistinctItemRowHeightCountForSmoke;
                bool narrowOriginalLayoutExact = narrowOriginalSearch.Applied
                    && first.FilteredCountForSmoke == 1
                    && first.GridUsesVariableItemHeightForSmoke
                    && narrowOriginalDistinctRowHeights == 1;
                MainWindow.SearchFilterCompletion clearOriginalSearch =
                    await first.SetSearchInputForSmokeAsync("");
                first.UpdateLayout();
                await first.Dispatcher.InvokeAsync(
                    first.UpdateLayout,
                    DispatcherPriority.Render);
                bool searchClearVariableLayoutRestored = narrowOriginalLayoutExact
                    && clearOriginalSearch.Applied
                    && first.FilteredCountForSmoke == filtered
                    && first.GridUsesVariableItemHeightForSmoke
                    && first.GridDistinctItemRowHeightCountForSmoke >= 2;
                int searchClearDistinctRowHeights =
                    first.GridDistinctItemRowHeightCountForSmoke;

                string statePath = first.StatePathForSmoke;
                bool persistedTargetSet = first.SetAspectModeForSmoke("portrait");
                first.Close();

                var second = HiddenWindow();
                second.Show();
                await second.LoadFolderAsync(aspectFolder);
                DisplayStyleMetrics restored = second.DisplayStyleMetricsForSmoke();
                List<string> restoredOrder = second.FilteredFileNamesForSmoke(3);
                second.Close();

                const int searchClearCatalogCount = 174_325;
                var searchClearWindow = HiddenWindow();
                searchClearWindow.SuppressStatePersistence();
                searchClearWindow.Show();
                searchClearWindow.SeedLargeInteractionCatalogForSmoke(
                    searchClearCatalogCount);
                searchClearWindow.UpdateLayout();
                bool searchClearInitialRealizationSettled =
                    await searchClearWindow.WaitForGridRealizationIdleForSmokeAsync(
                        timeoutMilliseconds: 10_000);
                MainWindow.SearchFilterCompletion largeNarrowSearch =
                    await searchClearWindow.SetSearchInputForSmokeAsync("needle");
                bool searchClearNarrowRealizationSettled =
                    await searchClearWindow.WaitForGridRealizationIdleForSmokeAsync(
                        timeoutMilliseconds: 10_000);
                MainWindow.SearchFilterCompletion largeClearSearch =
                    await searchClearWindow.SetSearchInputForSmokeAsync("");
                bool searchClearFullRealizationSettled =
                    await searchClearWindow.WaitForGridRealizationIdleForSmokeAsync(
                        timeoutMilliseconds: 10_000);
                int searchClearVisibleUnrealized =
                    searchClearWindow.GridVisibleUnrealizedCountForSmoke;
                int searchClearVisiblePlaceholders =
                    searchClearWindow.GridVisiblePlaceholderCountForSmoke;
                bool largeSearchClearRealizationRecovered =
                    searchClearInitialRealizationSettled
                    && largeNarrowSearch.Applied
                    && searchClearNarrowRealizationSettled
                    && largeClearSearch.Applied
                    && searchClearFullRealizationSettled
                    && searchClearWindow.FilteredCountForSmoke
                        == searchClearCatalogCount
                    && searchClearVisibleUnrealized == 0
                    && searchClearVisiblePlaceholders == 0
                    && !searchClearWindow
                        .GridRealizationContinuationPendingForSmoke;
                searchClearWindow.Close();

                ViewerState? persisted = ReadPersistedState(statePath);
                bool squareShape = Math.Abs(square.CardWidth - square.CardHeight) < 0.5
                    && Math.Abs(square.ListThumbnailWidth - square.ListThumbnailHeight) < 0.5
                    && string.Equals(square.CardThumbnailStretch, "UniformToFill", StringComparison.Ordinal);
                bool portraitShape = portrait.CardHeight > square.CardHeight
                    && portrait.ListThumbnailHeight > square.ListThumbnailHeight
                    && Math.Abs((portrait.CardHeight / portrait.CardWidth) - 1.5) < 0.03
                    && string.Equals(portrait.CardThumbnailStretch, "UniformToFill", StringComparison.Ordinal);
                bool originalShape = metadataReady
                    && Math.Abs((originalLandscape.CardHeight / originalLandscape.CardWidth) - (2d / 3d)) < 0.03
                    && Math.Abs((originalSquare.CardHeight / originalSquare.CardWidth) - 1d) < 0.03
                    && Math.Abs((originalPortrait.CardHeight / originalPortrait.CardWidth) - 1.5d) < 0.03
                    && originalLandscape.ListThumbnailHeight < originalSquare.ListThumbnailHeight
                    && originalSquare.ListThumbnailHeight < originalPortrait.ListThumbnailHeight
                    && string.Equals(originalLandscape.AspectMode, "original", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(originalLandscape.CardThumbnailStretch, "Uniform", StringComparison.Ordinal)
                    && string.Equals(originalSquare.CardThumbnailStretch, "Uniform", StringComparison.Ordinal)
                    && string.Equals(originalPortrait.CardThumbnailStretch, "Uniform", StringComparison.Ordinal);
                bool orderStable = SameNameOrder(squareOrder, initialOrder)
                    && SameNameOrder(portraitOrder, initialOrder)
                    && SameNameOrder(restoredOrder, initialOrder);
                bool selectionStable = selectedBravo
                    && string.Equals(selectedBefore, "bravo-square.png", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(selectedAfterSquare, selectedBefore, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(selectedAfterPortrait, selectedBefore, StringComparison.OrdinalIgnoreCase);
                bool zoomComposes = zoomed
                    && portraitZoomed.CardWidth > portrait.CardWidth
                    && portraitZoomed.CardHeight > portrait.CardHeight
                    && Math.Abs((portraitZoomed.CardHeight / portraitZoomed.CardWidth) - (portrait.CardHeight / portrait.CardWidth)) < 0.03;
                bool persistence = persistedTargetSet
                    && string.Equals(persisted?.AspectMode, "portrait", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(restored.AspectMode, "portrait", StringComparison.OrdinalIgnoreCase)
                    && restored.CardHeight > restored.CardWidth;
                bool runtimeRestore = originalChanged
                    && string.Equals(restoredOriginalRuntime.AspectMode, "original", StringComparison.OrdinalIgnoreCase)
                    && Math.Abs((restoredOriginalRuntime.CardHeight / restoredOriginalRuntime.CardWidth) - (2d / 3d)) < 0.03
                    && string.Equals(restoredOriginalRuntime.CardThumbnailStretch, "Uniform", StringComparison.Ordinal);
                bool metadataLayoutCoalesced = metadataLayoutPublishCount == 1;

                bool ok = filtered == 131
                    && initialOrder.SequenceEqual(new[] { "alpha-landscape.png", "bravo-square.png", "charlie-portrait.png" })
                    && squareChanged
                    && portraitChanged
                    && squareShape
                    && portraitShape
                    && originalShape
                    && orderStable
                    && selectionStable
                    && zoomComposes
                    && runtimeRestore
                    && persistence
                    && metadataLayoutCoalesced
                    && metadataSelectionRaceRecovered
                    && searchClearVariableLayoutRestored
                    && largeSearchClearRealizationRecovered;

                result = new AspectSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "late metadata published Original card geometry once after multiple decode batches; selection-discard fallback completed exactly once; aspect controls preserved order/selection, composed with zoom, and restored from WPF state"
                        : "aspect smoke did not meet dimension/order/selection/persistence expectations",
                    Folder = aspectFolder,
                    ProjectRoot = smokeRoot,
                    StatePath = statePath,
                    FilteredCount = filtered,
                    InitialOrder = initialOrder,
                    SquareOrder = squareOrder,
                    PortraitOrder = portraitOrder,
                    RestoredOrder = restoredOrder,
                    Original = original,
                    OriginalLandscape = originalLandscape,
                    OriginalSquare = originalSquare,
                    OriginalPortrait = originalPortrait,
                    Square = square,
                    Portrait = portrait,
                    PortraitZoomed = portraitZoomed,
                    RestoredOriginalRuntime = restoredOriginalRuntime,
                    Restored = restored,
                    SelectedBefore = selectedBefore,
                    SelectedAfterSquare = selectedAfterSquare,
                    SelectedAfterPortrait = selectedAfterPortrait,
                    PersistedAspect = persisted?.AspectMode,
                    SquareChanged = squareChanged,
                    PortraitChanged = portraitChanged,
                    OriginalChanged = originalChanged,
                    Zoomed = zoomed,
                    PersistedTargetSet = persistedTargetSet,
                    MetadataReady = metadataReady,
                    MetadataLayoutPublishCount = metadataLayoutPublishCount,
                    MetadataLayoutCoalesced = metadataLayoutCoalesced,
                    MetadataRaceComputeEntered = metadataRaceComputeEntered,
                    MetadataRaceSelectionChanged = metadataRaceSelectionChanged,
                    MetadataRaceDiscarded = metadataRaceCompletion.Discarded,
                    MetadataRaceFallbackCount = first.MetadataOriginalAspectLayoutFallbackCountForSmoke - metadataFallbackBefore,
                    MetadataRacePendingAtEnd = first.MetadataOriginalAspectLayoutPendingForSmoke,
                    MetadataSelectionRaceRecovered = metadataSelectionRaceRecovered,
                    SquareShape = squareShape,
                    PortraitShape = portraitShape,
                    OriginalShape = originalShape,
                    OrderStable = orderStable,
                    SelectionStable = selectionStable,
                    ZoomComposes = zoomComposes,
                    Persistence = persistence,
                    SearchClearVariableLayoutRestored = searchClearVariableLayoutRestored,
                    SearchNarrowDistinctRowHeights = narrowOriginalDistinctRowHeights,
                    SearchClearDistinctRowHeights = searchClearDistinctRowHeights,
                    LargeSearchClearRealizationRecovered =
                        largeSearchClearRealizationRecovered,
                    SearchClearInitialRealizationSettled =
                        searchClearInitialRealizationSettled,
                    SearchClearNarrowRealizationSettled =
                        searchClearNarrowRealizationSettled,
                    SearchClearFullRealizationSettled =
                        searchClearFullRealizationSettled,
                    SearchClearVisibleUnrealized = searchClearVisibleUnrealized,
                    SearchClearVisiblePlaceholders = searchClearVisiblePlaceholders,
                };
            }
            catch (Exception ex)
            {
                first.Close();
                result = new AspectSmokeResult { Ok = false, Message = ex.Message, Folder = aspectFolder, ProjectRoot = smokeRoot };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteAspectSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureSortSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteSortSmokeResult(resultPath, new SortSmokeResult { Ok = false, Message = "missing required --folder", Folder = folder });
            Shutdown(1);
            return;
        }

        string fullFolder = Path.GetFullPath(folder);
        string[] fixtureNames = GetSmokeImageFileNames(fullFolder);
        if (fixtureNames.Length < 3)
        {
            WriteSortSmokeResult(resultPath, new SortSmokeResult { Ok = false, Message = "sort smoke requires at least 3 fixture images", Folder = fullFolder });
            Shutdown(1);
            return;
        }

        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        string sortFolder = PrepareSortSmokeFolder(fullFolder, fixtureNames, smokeRoot);
        string alphaName = "alpha-sort" + Path.GetExtension(fixtureNames[0]).ToLowerInvariant();
        string bravoName = "bravo-sort" + Path.GetExtension(fixtureNames[1]).ToLowerInvariant();
        string charlieName = "charlie-sort" + Path.GetExtension(fixtureNames[2]).ToLowerInvariant();

        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var first = HiddenWindow();
        first.Show();

        first.Dispatcher.InvokeAsync(async () =>
        {
            SortSmokeResult result;
            try
            {
                await first.LoadFolderAsync(sortFolder);
                string statePath = first.StatePathForSmoke;
                List<string> newestOrder = first.FilteredFileNamesForSmoke(3);
                bool newestFlat = first.FlatGridActiveForSmoke;
                bool selectedAlpha = first.SelectFileNameForSmoke(alphaName);
                bool changedOldest = first.SetSortByForSmoke("modified-oldest");
                List<string> oldestOrder = first.FilteredFileNamesForSmoke(3);
                bool oldestFlat = first.FlatGridActiveForSmoke;
                bool selectionKeptAfterOldest = string.Equals(first.SelectedFileNameForSmoke, alphaName, StringComparison.OrdinalIgnoreCase);
                bool changedName = first.SetSortByForSmoke("name");
                List<string> nameOrder = first.FilteredFileNamesForSmoke(3);
                bool nameFlat = first.FlatGridActiveForSmoke;
                bool selectionKeptAfterName = string.Equals(first.SelectedFileNameForSmoke, alphaName, StringComparison.OrdinalIgnoreCase);

                first.SetSearchQuery("alpha", persist: false);
                List<string> filteredAlphaOrder = first.FilteredFileNamesForSmoke(3);
                bool filterPreserved = first.FilteredCountForSmoke == 1
                    && filteredAlphaOrder.Count == 1
                    && string.Equals(filteredAlphaOrder[0], alphaName, StringComparison.OrdinalIgnoreCase);

                first.SetSearchQuery("", persist: false);
                bool modalOpened = first.OpenModalForSmoke();
                bool modalMovedNext = first.NavigateModalForSmoke(1);
                string? modalNextName = first.SelectedFileNameForSmoke;
                bool modalUsesSortedNameOrder = modalOpened
                    && modalMovedNext
                    && string.Equals(modalNextName, bravoName, StringComparison.OrdinalIgnoreCase);

                bool changedCreatedNewest = first.SetSortByForSmoke("created-newest");
                List<string> createdNewestOrder = first.FilteredFileNamesForSmoke(3);
                bool createdNewestGrouped = first.DateGroupingActiveForSmoke;
                bool changedCreatedOldest = first.SetSortByForSmoke("created-oldest");
                List<string> createdOldestOrder = first.FilteredFileNamesForSmoke(3);
                bool createdOldestGrouped = first.DateGroupingActiveForSmoke;
                DateTimeOffset activityBase = new(
                    2026,
                    1,
                    1,
                    12,
                    0,
                    0,
                    TimeSpan.Zero);
                bool activityFixtures =
                    first.SetSortActivityForSmoke(alphaName, "upscale", activityBase.AddDays(3))
                    && first.SetSortActivityForSmoke(bravoName, "upscale", activityBase.AddDays(2))
                    && first.SetSortActivityForSmoke(bravoName, "photoreal", activityBase.AddDays(4))
                    && first.SetSortActivityForSmoke(charlieName, "photoreal", activityBase.AddDays(1))
                    && first.SetSortActivityForSmoke(charlieName, "video", activityBase.AddDays(5))
                    && first.SetSortActivityForSmoke(alphaName, "video", activityBase.AddDays(4))
                    && first.SetSortActivityForSmoke(bravoName, "favorite", activityBase.AddDays(6))
                    && first.SetSortActivityForSmoke(alphaName, "favorite", activityBase.AddDays(2));
                bool changedUpscaleNewest = first.SetSortByForSmoke("upscale-completed-newest");
                List<string> upscaleNewestOrder = first.FilteredFileNamesForSmoke(3);
                bool changedPhotorealNewest = first.SetSortByForSmoke("photoreal-completed-newest");
                List<string> photorealNewestOrder = first.FilteredFileNamesForSmoke(3);
                bool changedVideoNewest = first.SetSortByForSmoke("video-completed-newest");
                List<string> videoNewestOrder = first.FilteredFileNamesForSmoke(3);
                bool changedFavoriteNewest = first.SetSortByForSmoke("favorite-changed-newest");
                List<string> favoriteNewestOrder = first.FilteredFileNamesForSmoke(3);
                bool activitySortsFlat = first.FlatGridActiveForSmoke;
                bool changedRandom = first.SetSortByForSmoke("random");
                bool randomFlat = first.FlatGridActiveForSmoke;
                string randomSeedBefore = first.RandomSortSeedForSmoke;
                List<string> randomOrderBefore = first.FilteredFileNamesForSmoke(3);
                bool reshuffled = first.ReshuffleRandomSortForSmoke();
                string randomSeedAfter = first.RandomSortSeedForSmoke;
                List<string> randomOrderAfter = first.FilteredFileNamesForSmoke(3);
                ViewerState? persisted = ReadPersistedState(statePath);
                first.Close();

                var second = HiddenWindow();
                second.Show();
                await second.LoadFolderAsync(sortFolder);
                string restoredSort = second.SortByForSmoke;
                List<string> restoredOrder = second.FilteredFileNamesForSmoke(3);
                string restoredRandomSeed = second.RandomSortSeedForSmoke;
                bool restoredRandomFlat = second.FlatGridActiveForSmoke;
                bool restoredFavoriteSortChanged = second.SetSortByForSmoke(
                    "favorite-changed-newest");
                List<string> restoredFavoriteOrder =
                    second.FilteredFileNamesForSmoke(3);
                second.Close();

                List<string> expectedNewest = [bravoName, alphaName, charlieName];
                List<string> expectedOldest = [charlieName, alphaName, bravoName];
                List<string> expectedName = [alphaName, bravoName, charlieName];
                List<string> expectedCreatedNewest = [bravoName, alphaName, charlieName];
                List<string> expectedCreatedOldest = [charlieName, alphaName, bravoName];
                List<string> expectedUpscaleNewest = [alphaName, bravoName, charlieName];
                List<string> expectedPhotorealNewest = [bravoName, charlieName, alphaName];
                List<string> expectedVideoNewest = [charlieName, alphaName, bravoName];
                List<string> expectedFavoriteNewest = [bravoName, alphaName, charlieName];
                bool newestOk = SameNameOrder(newestOrder, expectedNewest);
                bool oldestOk = SameNameOrder(oldestOrder, expectedOldest);
                bool nameOk = SameNameOrder(nameOrder, expectedName);
                bool createdNewestOk = SameNameOrder(createdNewestOrder, expectedCreatedNewest);
                bool createdOldestOk = SameNameOrder(createdOldestOrder, expectedCreatedOldest);
                bool activitySortsOk = activityFixtures
                    && changedUpscaleNewest
                    && changedPhotorealNewest
                    && changedVideoNewest
                    && changedFavoriteNewest
                    && SameNameOrder(upscaleNewestOrder, expectedUpscaleNewest)
                    && SameNameOrder(photorealNewestOrder, expectedPhotorealNewest)
                    && SameNameOrder(videoNewestOrder, expectedVideoNewest)
                    && SameNameOrder(favoriteNewestOrder, expectedFavoriteNewest)
                    && restoredFavoriteSortChanged
                    && SameNameOrder(restoredFavoriteOrder, expectedFavoriteNewest)
                    && activitySortsFlat;
                bool randomPersistence = changedRandom
                    && reshuffled
                    && !string.Equals(randomSeedBefore, randomSeedAfter, StringComparison.Ordinal)
                    && persisted?.SortBy == "random"
                    && string.Equals(persisted.RandomSortSeed, randomSeedAfter, StringComparison.Ordinal)
                    && string.Equals(restoredSort, "random", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(restoredRandomSeed, randomSeedAfter, StringComparison.Ordinal)
                    && SameNameOrder(restoredOrder, randomOrderAfter);
                bool ok = newestOk
                    && changedOldest
                    && oldestOk
                    && selectionKeptAfterOldest
                    && changedName
                    && nameOk
                    && selectionKeptAfterName
                    && filterPreserved
                    && modalUsesSortedNameOrder
                    && changedCreatedNewest
                    && createdNewestOk
                    && changedCreatedOldest
                    && createdOldestOk
                    && newestFlat && oldestFlat && nameFlat && randomFlat && restoredRandomFlat
                    && createdNewestGrouped && createdOldestGrouped
                    && activitySortsOk
                    && randomPersistence;

                result = new SortSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "modified, created, operation activity, favorite activity, name, random/reshuffle sort, filter, selection, modal navigation, and persistence checks passed"
                        : "sort smoke did not meet order/filter/selection/modal/persistence expectations",
                    Folder = sortFolder,
                    ProjectRoot = smokeRoot,
                    StatePath = statePath,
                    ExpectedNewest = expectedNewest,
                    ExpectedOldest = expectedOldest,
                    ExpectedName = expectedName,
                    ExpectedCreatedNewest = expectedCreatedNewest,
                    ExpectedCreatedOldest = expectedCreatedOldest,
                    ExpectedUpscaleNewest = expectedUpscaleNewest,
                    ExpectedPhotorealNewest = expectedPhotorealNewest,
                    ExpectedVideoNewest = expectedVideoNewest,
                    ExpectedFavoriteNewest = expectedFavoriteNewest,
                    NewestOrder = newestOrder,
                    OldestOrder = oldestOrder,
                    NameOrder = nameOrder,
                    CreatedNewestOrder = createdNewestOrder,
                    CreatedOldestOrder = createdOldestOrder,
                    UpscaleNewestOrder = upscaleNewestOrder,
                    PhotorealNewestOrder = photorealNewestOrder,
                    VideoNewestOrder = videoNewestOrder,
                    FavoriteNewestOrder = favoriteNewestOrder,
                    RestoredFavoriteOrder = restoredFavoriteOrder,
                    RandomOrderBefore = randomOrderBefore,
                    RandomOrderAfter = randomOrderAfter,
                    RestoredOrder = restoredOrder,
                    SelectedAlpha = selectedAlpha,
                    SelectionKeptAfterOldest = selectionKeptAfterOldest,
                    SelectionKeptAfterName = selectionKeptAfterName,
                    FilterPreserved = filterPreserved,
                    ModalOpened = modalOpened,
                    ModalMovedNext = modalMovedNext,
                    ModalNextName = modalNextName,
                    RandomSeedBefore = randomSeedBefore,
                    RandomSeedAfter = randomSeedAfter,
                    PersistedSort = persisted?.SortBy,
                    RestoredSort = restoredSort,
                    RestoredRandomSeed = restoredRandomSeed,
                    RandomPersistence = randomPersistence,
                    NewestFlat = newestFlat,
                    OldestFlat = oldestFlat,
                    NameFlat = nameFlat,
                    CreatedNewestGrouped = createdNewestGrouped,
                    CreatedOldestGrouped = createdOldestGrouped,
                    ActivitySortsOk = activitySortsOk,
                    ActivitySortsFlat = activitySortsFlat,
                    RandomFlat = randomFlat,
                    RestoredRandomFlat = restoredRandomFlat,
                };
            }
            catch (Exception ex)
            {
                first.Close();
                result = new SortSmokeResult { Ok = false, Message = ex.Message, Folder = sortFolder, ProjectRoot = smokeRoot };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteSortSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureDateFilterSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        DateFilterSmokeFixture fixture = PrepareDateFilterSmokeFolder(smokeRoot);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var first = HiddenWindow();
        first.Show();

        first.Dispatcher.InvokeAsync(async () =>
        {
            DateFilterSmokeResult result;
            try
            {
                await first.LoadFolderAsync(fixture.Folder);
                string statePath = first.StatePathForSmoke;
                int allCount = first.FilteredCountForSmoke;
                List<string> allOrder = first.FilteredFileNamesForSmoke(10);
                bool selectedManualExcluded = first.SelectFileNameForSmoke(fixture.TodayName);
                bool manualRangeChanged = first.SetManualDateRangeForSmoke(fixture.ManualFromText, fixture.ManualToText);
                List<string> manualRangeOrder = first.FilteredFileNamesForSmoke(10);
                string? selectedAfterManualRange = first.SelectedFileNameForSmoke;

                bool manualFromOnlyChanged = first.SetManualDateRangeForSmoke(fixture.ManualFromText, null);
                List<string> manualFromOnlyOrder = first.FilteredFileNamesForSmoke(10);
                string? selectedAfterManualFromOnly = first.SelectedFileNameForSmoke;

                bool manualToOnlyChanged = first.SetManualDateRangeForSmoke(null, fixture.ManualToText);
                List<string> manualToOnlyOrder = first.FilteredFileNamesForSmoke(10);
                string? selectedAfterManualToOnly = first.SelectedFileNameForSmoke;

                bool manualClearChanged = first.ClearManualDateRangeForSmoke();
                List<string> manualClearOrder = first.FilteredFileNamesForSmoke(10);
                string clearPreset = first.DatePresetForSmoke;

                bool manualPersistChanged = first.SetManualDateRangeForSmoke(fixture.ManualFromText, fixture.ManualToText);
                bool selectedManualPersisted = first.SelectFileNameForSmoke(fixture.SevenDayName);
                ViewerState? persistedManual = ReadPersistedState(statePath);
                first.Close();

                WriteLegacyDateFilterState(statePath, "30d", fixture.ManualFromText, fixture.ManualToText);
                var legacyWithRange = HiddenWindow();
                legacyWithRange.Show();
                await legacyWithRange.LoadFolderAsync(fixture.Folder);
                string legacyRangePreset = legacyWithRange.DatePresetForSmoke;
                string? legacyRangeFrom = legacyWithRange.DateFromForSmoke;
                string? legacyRangeTo = legacyWithRange.DateToForSmoke;
                string legacyRangeSummary = legacyWithRange.DateFilterSummaryForSmoke;
                List<string> legacyRangeOrder = legacyWithRange.FilteredFileNamesForSmoke(10);
                ViewerState? migratedLegacyWithRange = ReadPersistedState(statePath);
                bool legacyUnknownFieldPreserved = PersistedStateHasStringProperty(statePath, "futureDateMarker", "preserve-me");
                legacyWithRange.Close();

                WriteLegacyDateFilterState(statePath, "7d", fixture.ManualFromText, null);
                var legacyWithPartialRange = HiddenWindow();
                legacyWithPartialRange.Show();
                await legacyWithPartialRange.LoadFolderAsync(fixture.Folder);
                string legacyPartialPreset = legacyWithPartialRange.DatePresetForSmoke;
                string? legacyPartialFrom = legacyWithPartialRange.DateFromForSmoke;
                string? legacyPartialTo = legacyWithPartialRange.DateToForSmoke;
                List<string> legacyPartialOrder = legacyWithPartialRange.FilteredFileNamesForSmoke(10);
                ViewerState? migratedLegacyWithPartialRange = ReadPersistedState(statePath);
                legacyWithPartialRange.Close();

                WriteLegacyDateFilterState(statePath, "today", null, null);
                var legacyWithoutRange = HiddenWindow();
                legacyWithoutRange.Show();
                await legacyWithoutRange.LoadFolderAsync(fixture.Folder);
                string legacyFallbackPreset = legacyWithoutRange.DatePresetForSmoke;
                string? legacyFallbackFrom = legacyWithoutRange.DateFromForSmoke;
                string? legacyFallbackTo = legacyWithoutRange.DateToForSmoke;
                List<string> legacyFallbackOrder = legacyWithoutRange.FilteredFileNamesForSmoke(10);
                ViewerState? migratedLegacyWithoutRange = ReadPersistedState(statePath);
                legacyWithoutRange.Close();

                string? persistedManualDatePreset = persistedManual?.DatePreset;
                string? persistedManualDateFrom = persistedManual?.DateFrom;
                string? persistedManualDateTo = persistedManual?.DateTo;

                bool allOk = allCount == fixture.AllExpected.Count && SameNameOrder(allOrder, fixture.AllExpected);
                bool manualRangeOk = selectedManualExcluded
                    && manualRangeChanged
                    && string.Equals(first.DatePresetForSmoke, "manual", StringComparison.OrdinalIgnoreCase)
                    && SameNameOrder(manualRangeOrder, fixture.ManualRangeExpected)
                    && string.Equals(selectedAfterManualRange, fixture.ManualRangeExpected.FirstOrDefault(), StringComparison.OrdinalIgnoreCase);
                bool manualFromOnlyOk = manualFromOnlyChanged
                    && SameNameOrder(manualFromOnlyOrder, fixture.ManualFromOnlyExpected)
                    && string.Equals(selectedAfterManualFromOnly, selectedAfterManualRange, StringComparison.OrdinalIgnoreCase);
                bool manualToOnlyOk = manualToOnlyChanged
                    && SameNameOrder(manualToOnlyOrder, fixture.ManualToOnlyExpected)
                    && string.Equals(selectedAfterManualToOnly, selectedAfterManualRange, StringComparison.OrdinalIgnoreCase);
                bool manualClearOk = manualClearChanged
                    && string.Equals(clearPreset, "none", StringComparison.OrdinalIgnoreCase)
                    && SameNameOrder(manualClearOrder, fixture.AllExpected);
                bool manualPersistenceOk = manualPersistChanged
                    && selectedManualPersisted
                    && string.Equals(persistedManualDatePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(persistedManualDateFrom, fixture.ManualFromText, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(persistedManualDateTo, fixture.ManualToText, StringComparison.OrdinalIgnoreCase);
                bool legacyRangeMigrationOk = string.Equals(legacyRangePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(legacyRangeFrom, fixture.ManualFromText, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(legacyRangeTo, fixture.ManualToText, StringComparison.OrdinalIgnoreCase)
                    && legacyRangeSummary.StartsWith("Manual:", StringComparison.Ordinal)
                    && SameNameOrder(legacyRangeOrder, fixture.ManualRangeExpected)
                    && string.Equals(migratedLegacyWithRange?.DatePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(migratedLegacyWithRange?.DateFrom, fixture.ManualFromText, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(migratedLegacyWithRange?.DateTo, fixture.ManualToText, StringComparison.OrdinalIgnoreCase)
                    && legacyUnknownFieldPreserved;
                bool legacyPartialMigrationOk = string.Equals(legacyPartialPreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(legacyPartialFrom, fixture.ManualFromText, StringComparison.OrdinalIgnoreCase)
                    && legacyPartialTo is null
                    && SameNameOrder(legacyPartialOrder, fixture.ManualFromOnlyExpected)
                    && string.Equals(migratedLegacyWithPartialRange?.DatePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(migratedLegacyWithPartialRange?.DateFrom, fixture.ManualFromText, StringComparison.OrdinalIgnoreCase)
                    && migratedLegacyWithPartialRange?.DateTo is null;
                string today = DateTime.Today.ToString("yyyy-MM-dd");
                bool legacyFallbackMigrationOk = string.Equals(legacyFallbackPreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(legacyFallbackFrom, today, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(legacyFallbackTo, today, StringComparison.OrdinalIgnoreCase)
                    && SameNameOrder(legacyFallbackOrder, fixture.TodayExpected)
                    && string.Equals(migratedLegacyWithoutRange?.DatePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(migratedLegacyWithoutRange?.DateFrom, today, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(migratedLegacyWithoutRange?.DateTo, today, StringComparison.OrdinalIgnoreCase);

                bool ok = allOk
                    && manualRangeOk
                    && manualFromOnlyOk
                    && manualToOnlyOk
                    && manualClearOk
                    && manualPersistenceOk
                    && legacyRangeMigrationOk
                    && legacyPartialMigrationOk
                    && legacyFallbackMigrationOk;

                result = new DateFilterSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "manual Created/Birth date filtering, fixed legacy migration, clear action, selection fallback/preservation, and persistence checks passed"
                        : "date filter smoke did not meet manual/migration/selection/persistence expectations",
                    Folder = fixture.Folder,
                    ProjectRoot = smokeRoot,
                    StatePath = statePath,
                    TodayName = fixture.TodayName,
                    SevenDayName = fixture.SevenDayName,
                    ThirtyDayName = fixture.ThirtyDayName,
                    ThisYearName = fixture.ThisYearName,
                    PreviousYearName = fixture.PreviousYearName,
                    AllExpected = fixture.AllExpected,
                    ManualFrom = fixture.ManualFromText,
                    ManualTo = fixture.ManualToText,
                    ManualRangeExpected = fixture.ManualRangeExpected,
                    ManualFromOnlyExpected = fixture.ManualFromOnlyExpected,
                    ManualToOnlyExpected = fixture.ManualToOnlyExpected,
                    AllOrder = allOrder,
                    ClearOrder = manualClearOrder,
                    ManualRangeOrder = manualRangeOrder,
                    ManualFromOnlyOrder = manualFromOnlyOrder,
                    ManualToOnlyOrder = manualToOnlyOrder,
                    ManualClearOrder = manualClearOrder,
                    SelectedAfterManualRange = selectedAfterManualRange,
                    SelectedAfterManualFromOnly = selectedAfterManualFromOnly,
                    SelectedAfterManualToOnly = selectedAfterManualToOnly,
                    PersistedManualDatePreset = persistedManualDatePreset,
                    PersistedManualDateFrom = persistedManualDateFrom,
                    PersistedManualDateTo = persistedManualDateTo,
                    LegacyRangePreset = legacyRangePreset,
                    LegacyRangeFrom = legacyRangeFrom,
                    LegacyRangeTo = legacyRangeTo,
                    LegacyRangeSummary = legacyRangeSummary,
                    LegacyRangeOrder = legacyRangeOrder,
                    LegacyPartialPreset = legacyPartialPreset,
                    LegacyPartialFrom = legacyPartialFrom,
                    LegacyPartialTo = legacyPartialTo,
                    LegacyPartialOrder = legacyPartialOrder,
                    LegacyFallbackPreset = legacyFallbackPreset,
                    LegacyFallbackFrom = legacyFallbackFrom,
                    LegacyFallbackTo = legacyFallbackTo,
                    LegacyFallbackOrder = legacyFallbackOrder,
                    LegacyUnknownFieldPreserved = legacyUnknownFieldPreserved,
                };
            }
            catch (Exception ex)
            {
                first.Close();
                result = new DateFilterSmokeResult { Ok = false, Message = ex.Message, Folder = fixture.Folder, ProjectRoot = smokeRoot };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            WriteDateFilterSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureP1ASmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        string folderA = Path.Combine(smokeRoot, "folder-a");
        string folderB = Path.Combine(smokeRoot, "folder-b");
        Directory.CreateDirectory(folderA);
        Directory.CreateDirectory(folderB);

        string filenameCatPath = Path.Combine(folderA, "filename-cat.png");
        string promptPath = Path.Combine(folderA, "prompt-only.png");
        string reversedPath = Path.Combine(folderA, "reversed-words.png");
        string addedPath = Path.Combine(folderB, "added-folder.png");
        WriteSmokePng(filenameCatPath, 64, 48, Color.FromRgb(52, 152, 219));
        WritePngTextFixture(
            promptPath,
            "parameters",
            "night cat portrait\nNegative prompt: forbidden wolf\nSteps: 20, Sampler: Euler",
            Color.FromRgb(46, 204, 113));
        WritePngTextFixture(
            reversedPath,
            "parameters",
            "cat beneath a bright night sky\nNegative prompt: artifact\nSteps: 24, Sampler: DPM++ 2M",
            Color.FromRgb(155, 89, 182));
        WriteSmokePng(addedPath, 64, 48, Color.FromRgb(241, 196, 15));

        File.SetCreationTime(filenameCatPath, new DateTime(2026, 1, 10, 10, 0, 0));
        File.SetLastWriteTime(filenameCatPath, new DateTime(2026, 7, 15, 10, 0, 0));
        File.SetCreationTime(promptPath, new DateTime(2026, 7, 15, 12, 0, 0));
        File.SetLastWriteTime(promptPath, new DateTime(2026, 1, 10, 12, 0, 0));
        File.SetCreationTime(reversedPath, new DateTime(2026, 7, 17, 12, 0, 0));
        File.SetLastWriteTime(reversedPath, new DateTime(2026, 7, 17, 12, 0, 0));

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var win = HiddenWindow();
        win.Show();
        win.Dispatcher.InvokeAsync(async () =>
        {
            P1ASmokeResult result;
            try
            {
                await win.LoadFolderAsync(folderA);
                string? indexedPrompt = win.PromptForFileNameForSmoke("prompt-only.png");

                win.SetSearchQuery("filename-cat", persist: false);
                List<string> filenameMatches = win.FilteredFileNamesForSmoke(10);
                win.SetSearchQuery("night cat", persist: false);
                List<string> phraseMatches = win.FilteredFileNamesForSmoke(10);
                win.SetSearchQuery("cat, night", persist: false);
                List<string> andMatches = win.FilteredFileNamesForSmoke(10);
                win.SetSearchQuery("cat,, night,", persist: false);
                List<string> emptyTokenMatches = win.FilteredFileNamesForSmoke(10);
                win.SetSearchQuery("forbidden wolf", persist: false);
                List<string> negativeMatches = win.FilteredFileNamesForSmoke(10);
                win.SetSearchQuery(Path.GetFileName(smokeRoot), persist: false);
                List<string> pathMatches = win.FilteredFileNamesForSmoke(10);

                win.SetSearchQuery("", persist: false);
                bool dateChanged = win.SetManualDateRangeForSmoke("2026-07-14", "2026-07-16");
                List<string> createdDateMatches = win.FilteredFileNamesForSmoke(10);
                string datePreset = win.DatePresetForSmoke;
                string dateSummary = win.DateFilterSummaryForSmoke;
                bool dateCleared = win.ClearManualDateRangeForSmoke();
                string clearedDatePreset = win.DatePresetForSmoke;

                bool folderAdded = await win.AddFoldersToCurrentSetForSmokeAsync([folderB]);
                List<string> currentFolderSet = win.CurrentFolderSetForSmoke;
                int catalogAfterAdd = win.CatalogCountForSmoke;
                win.ReturnToFolderSetEditorForSmoke();
                List<string> landingFolderSet = win.LandingFolderSetForSmoke;

                bool searchOk = string.Equals(indexedPrompt, "night cat portrait", StringComparison.Ordinal)
                    && SameNameOrder(filenameMatches, ["filename-cat.png"])
                    && SameNameOrder(phraseMatches, ["prompt-only.png"])
                    && SameNameOrder(andMatches, ["reversed-words.png", "prompt-only.png"])
                    && SameNameOrder(emptyTokenMatches, andMatches)
                    && negativeMatches.Count == 0
                    && pathMatches.Count == 0;
                bool dateOk = dateChanged
                    && SameNameOrder(createdDateMatches, ["prompt-only.png"])
                    && string.Equals(datePreset, "manual", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(dateSummary, "Manual: 2026-07-14 – 2026-07-16", StringComparison.Ordinal)
                    && dateCleared
                    && string.Equals(clearedDatePreset, "none", StringComparison.OrdinalIgnoreCase);
                bool folderOk = folderAdded
                    && currentFolderSet.Count == 2
                    && currentFolderSet.Contains(folderA, StringComparer.OrdinalIgnoreCase)
                    && currentFolderSet.Contains(folderB, StringComparer.OrdinalIgnoreCase)
                    && catalogAfterAdd == 4
                    && win.LandingVisibleForSmoke
                    && SameNameOrder(landingFolderSet, currentFolderSet);
                bool ok = searchOk && dateOk && folderOk;

                result = new P1ASmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "comma-AND filename/prompt search, Created/Birth manual date filtering, and Add/Change folder semantics passed"
                        : "P1A search/date/folder expectations did not match",
                    SearchOk = searchOk,
                    DateOk = dateOk,
                    FolderOk = folderOk,
                    IndexedPrompt = indexedPrompt,
                    FilenameMatches = filenameMatches,
                    PhraseMatches = phraseMatches,
                    AndMatches = andMatches,
                    EmptyTokenMatches = emptyTokenMatches,
                    NegativeMatches = negativeMatches,
                    PathMatches = pathMatches,
                    CreatedDateMatches = createdDateMatches,
                    CurrentFolderSet = currentFolderSet,
                    LandingFolderSet = landingFolderSet,
                    CatalogAfterAdd = catalogAfterAdd,
                    LandingVisible = win.LandingVisibleForSmoke,
                };
            }
            catch (Exception ex)
            {
                result = new P1ASmokeResult { Message = ex.Message };
            }
            finally
            {
                win.Close();
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            try { if (Directory.Exists(smokeRoot)) Directory.Delete(smokeRoot, recursive: true); } catch { }
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureCatalogInteractionSmoke(string resultPath, string[] args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        int count = ArgInt(args, "--count", 100_000);
        if (count < 10_000 || count > 250_000)
        {
            WriteCatalogInteractionSmokeResult(resultFullPath, new CatalogInteractionSmokeResult
            {
                RequestedCount = count,
                Message = "--count must be between 10,000 and 250,000",
            });
            Shutdown(1);
            return;
        }

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        string progressPath = resultFullPath + ".progress";
        try { File.WriteAllText(progressPath, "construct-window"); } catch { }
        var window = HiddenWindow();
        try { File.WriteAllText(progressPath, "show-window"); } catch { }
        window.Show();
        try { File.WriteAllText(progressPath, "queue-dispatcher"); } catch { }
        window.SuppressStatePersistence();

        window.Dispatcher.InvokeAsync(async () =>
        {
            CatalogInteractionSmokeResult result;
            var heartbeat = new DispatcherTimer(DispatcherPriority.Input)
            {
                Interval = TimeSpan.FromMilliseconds(15),
            };
            var heartbeatWatch = Stopwatch.StartNew();
            long lastHeartbeatMs = 0;
            long lastHeartbeatTimestamp = 0;
            long lastHeartbeatUiThreadCpuTicks = -1;
            long maxHeartbeatGapMs = 0;
            double maxHeartbeatGapGcPauseMs = 0;
            long maxHeartbeatGapProjectionGeneration = 0;
            int heartbeatCount = 0;
            string activeOperation = "startup";
            string maxHeartbeatGapSample = "";
            TimeSpan lastHeartbeatGcPause = GC.GetTotalPauseDuration();
            bool lastHeartbeatGcBoundaryAmbiguous = false;
            void SetActiveOperation(string operation)
            {
                activeOperation = operation;
                window.SetCatalogInteractionDiagnosticOperationForSmoke(operation);
            }
            void ReportProgress(string operation)
            {
                SetActiveOperation(operation);
                try { File.WriteAllText(progressPath, operation); } catch { }
            }
            ReportProgress(activeOperation);
            var heartbeatGapSamples = new List<string>();
            var heartbeatDiagnosticSamples = new List<DispatcherHeartbeatDiagnosticSample>();
            using var dispatcherDiagnostics =
                new CatalogDispatcherDiagnosticRecorder(
                    window.Dispatcher,
                    () => activeOperation);
            bool uiThreadPriorityNormal =
                Thread.CurrentThread.Priority == ThreadPriority.Normal;
            using var schedulerControlProbes = new SchedulerControlProbePair();
            bool schedulerControlProbesStarted =
                schedulerControlProbes.StartAndWaitForInitialSamples(
                    TimeSpan.FromSeconds(2));
            long schedulerMeasurementStartTimestamp = 0;
            var layoutSamples = new List<string>();
            var accessibilityWarmupSubstepSamples = new List<CatalogInteractionSubstepSample>();
            var stalePeerSubstepSamples = new List<CatalogInteractionSubstepSample>();
            var keyboardFocusSubstepSamples = new List<CatalogInteractionGcSubstepSample>();
            T MeasureAccessibilityWarmupSubstep<T>(string operation, Func<T> action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    return action();
                }
                finally
                {
                    watch.Stop();
                    accessibilityWarmupSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            async Task<T> MeasureAccessibilityWarmupSubstepAsync<T>(
                string operation,
                Func<Task<T>> action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    return await action();
                }
                finally
                {
                    watch.Stop();
                    accessibilityWarmupSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            async Task MeasureAccessibilityWarmupActionAsync(
                string operation,
                Func<Task> action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    await action();
                }
                finally
                {
                    watch.Stop();
                    accessibilityWarmupSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            T MeasureStalePeerSubstep<T>(string operation, Func<T> action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    return action();
                }
                finally
                {
                    watch.Stop();
                    stalePeerSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            void MeasureStalePeerAction(string operation, Action action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    action();
                }
                finally
                {
                    watch.Stop();
                    stalePeerSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            async Task<T> MeasureStalePeerSubstepAsync<T>(
                string operation,
                Func<Task<T>> action)
            {
                SetActiveOperation(operation);
                var watch = Stopwatch.StartNew();
                try
                {
                    return await action();
                }
                finally
                {
                    watch.Stop();
                    stalePeerSubstepSamples.Add(new(operation, watch.Elapsed.TotalMilliseconds));
                }
            }
            async Task<T> MeasureKeyboardFocusSubstepAsync<T>(
                string operation,
                Func<Task<T>> action)
            {
                SetActiveOperation(operation);
                long allocatedBefore = GC.GetTotalAllocatedBytes(precise: false);
                TimeSpan gcPauseBefore = GC.GetTotalPauseDuration();
                int gen0Before = GC.CollectionCount(0);
                int gen1Before = GC.CollectionCount(1);
                int gen2Before = GC.CollectionCount(2);
                var watch = Stopwatch.StartNew();
                try
                {
                    return await action();
                }
                finally
                {
                    watch.Stop();
                    keyboardFocusSubstepSamples.Add(new(
                        operation,
                        watch.Elapsed.TotalMilliseconds,
                        Math.Max(0, GC.GetTotalAllocatedBytes(precise: false) - allocatedBefore),
                        Math.Max(0, (GC.GetTotalPauseDuration() - gcPauseBefore).TotalMilliseconds),
                        GC.CollectionCount(0) - gen0Before,
                        GC.CollectionCount(1) - gen1Before,
                        GC.CollectionCount(2) - gen2Before,
                        window.CatalogProjectionGenerationForSmoke));
                }
            }
            async Task FlushLayoutAsync()
            {
                string operation = activeOperation;
                SetActiveOperation(operation + "-layout");
                var watch = Stopwatch.StartNew();
                await window.Dispatcher.InvokeAsync(window.UpdateLayout, DispatcherPriority.Render);
                watch.Stop();
                layoutSamples.Add($"{operation}:{watch.ElapsedMilliseconds}ms");
                SetActiveOperation(operation);
            }
            heartbeat.Tick += (_, _) =>
            {
                CatalogHeartbeatMarker marker =
                    dispatcherDiagnostics.MarkHeartbeatStarted();
                try
                {
                    TimeSpan gcPauseBeforeTimestamp = GC.GetTotalPauseDuration();
                    long nowTimestamp = Stopwatch.GetTimestamp();
                    TimeSpan gcPauseAfterTimestamp = GC.GetTotalPauseDuration();
                    long now = heartbeatWatch.ElapsedMilliseconds;
                    long gap = now - lastHeartbeatMs;
                    double preciseGapMs =
                        (nowTimestamp - lastHeartbeatTimestamp)
                            * 1000d / Stopwatch.Frequency;
                    double uiThreadCpuMs =
                        lastHeartbeatUiThreadCpuTicks >= 0
                            && marker.UiThreadCpuTicks >= lastHeartbeatUiThreadCpuTicks
                            ? TimeSpan.FromTicks(
                                marker.UiThreadCpuTicks
                                    - lastHeartbeatUiThreadCpuTicks)
                                .TotalMilliseconds
                            : -1;
                    double containedGcPauseMs = Math.Max(
                        0,
                        (gcPauseBeforeTimestamp - lastHeartbeatGcPause)
                            .TotalMilliseconds);
                    double boundaryGcPauseMs = Math.Max(
                        0,
                        (gcPauseAfterTimestamp - gcPauseBeforeTimestamp)
                            .TotalMilliseconds);
                    double gcPauseDeltaMs = containedGcPauseMs + boundaryGcPauseMs;
                    bool gcTimingAmbiguous =
                        lastHeartbeatGcBoundaryAmbiguous || boundaryGcPauseMs > 0;
                    lastHeartbeatGcBoundaryAmbiguous = boundaryGcPauseMs > 0;
                    lastHeartbeatGcPause = gcPauseAfterTimestamp;
                    long projectionGeneration = window.CatalogProjectionGenerationForSmoke;
                    if (gap >= 30)
                    {
                        heartbeatDiagnosticSamples.Add(new(
                            activeOperation,
                            now,
                            gap,
                            gcPauseDeltaMs,
                            projectionGeneration,
                            lastHeartbeatTimestamp,
                            nowTimestamp,
                            gcTimingAmbiguous,
                            marker.Tag,
                            uiThreadCpuMs));
                    }
                    if (gap > maxHeartbeatGapMs)
                    {
                        maxHeartbeatGapMs = gap;
                        maxHeartbeatGapGcPauseMs = gcPauseDeltaMs;
                        maxHeartbeatGapProjectionGeneration = projectionGeneration;
                        maxHeartbeatGapSample =
                            $"{activeOperation}@{now}ms:{gap}ms"
                            + $":gc={gcPauseDeltaMs:F3}ms"
                            + $":ui-cpu={uiThreadCpuMs:F3}ms"
                            + $":generation={projectionGeneration}";
                    }
                    // Keep the raw over-budget receipt on the same
                    // high-resolution timestamps used by the dispatcher
                    // attribution recorder. ElapsedMilliseconds truncation can
                    // otherwise report 50 ms for a 50.x ms interval and make
                    // the two diagnostics disagree at the exact boundary.
                    if (preciseGapMs > CatalogInteractionDispatcherHeartbeatBudgetMs)
                    {
                        heartbeatGapSamples.Add(
                            $"{activeOperation}@{now}ms:{preciseGapMs:F3}ms");
                    }
                    lastHeartbeatMs = now;
                    lastHeartbeatTimestamp = nowTimestamp;
                    lastHeartbeatUiThreadCpuTicks = marker.UiThreadCpuTicks;
                    heartbeatCount++;
                }
                finally
                {
                    dispatcherDiagnostics.MarkHeartbeatCompleted(marker.Tag);
                }
            };

            try
            {
                ReportProgress("seed");
                var seedWatch = Stopwatch.StartNew();
                window.SeedLargeInteractionCatalogForSmoke(count);
                window.UpdateLayout();
                seedWatch.Stop();

                string selectedName = $"interaction-smoke-{50_000:D6}-needle.png";
                bool selected = count > 50_000 && window.SelectFileNameForSmoke(selectedName);
                await window.Dispatcher.InvokeAsync(window.UpdateLayout, DispatcherPriority.Render);

                // Prime each measured interaction path before taking the memory
                // baseline. This keeps the gate focused on repeated catalog
                // churn instead of one-time WPF generator/JIT page commitment.
                ReportProgress("warmup");
                MainWindow.SearchFilterCompletion warmSearch =
                    await window.SetSearchInputForSmokeAsync("needle");
                await FlushLayoutAsync();
                MainWindow.SearchFilterCompletion warmClear =
                    await window.SetSearchInputForSmokeAsync("");
                await FlushLayoutAsync();
                MainWindow.SearchFilterCompletion warmFavorite =
                    await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                await FlushLayoutAsync();
                bool warmFavoriteCountExact = window.FilteredCountForSmoke == count / 10;
                MainWindow.SearchFilterCompletion warmFavoriteClear =
                    await window.ClearFavoriteFiltersForSmokeAsync();
                await FlushLayoutAsync();
                bool warmSortOldest =
                    await window.SetSortByInteractiveForSmokeAsync("modified-oldest");
                await FlushLayoutAsync();
                bool warmSortName =
                    await window.SetSortByInteractiveForSmokeAsync("name");
                await FlushLayoutAsync();
                bool warmSortRestored =
                    await window.SetSortByInteractiveForSmokeAsync("modified-newest");
                await FlushLayoutAsync();
                selected &= window.SelectFileNameForSmoke(selectedName);
                await FlushLayoutAsync();
                ReportProgress("mixed-latest-wins");
                bool mixedAnchorPrepared = window.MarkSelectedTileRealForSmoke()
                    && await window.WaitForGridRealizationIdleForSmokeAsync();
                string? mixedAnchorBefore = window.CaptureGridViewportAnchorPathForSmoke();
                int discardCountBeforeMixed = window.CatalogProjectionDiscardedCountForSmoke;
                Task<MainWindow.SearchFilterCompletion> staleMixedSearch =
                    window.SetSearchInputForSmokeAsync("needle");
                Task<MainWindow.SearchFilterCompletion> staleMixedFilter =
                    window.SetFavoriteOnlyFilterForSmokeAsync(true);
                Task<bool> latestMixedSort =
                    window.SetSortByInteractiveForSmokeAsync("name");
                MainWindow.SearchFilterCompletion staleMixedSearchResult =
                    await staleMixedSearch;
                MainWindow.SearchFilterCompletion staleMixedFilterResult =
                    await staleMixedFilter;
                bool latestMixedSortApplied = await latestMixedSort;
                await FlushLayoutAsync();
                await window.WaitForGridZoomAnchorForSmokeAsync();
                bool mixedRealizationSettled =
                    await window.WaitForGridRealizationIdleForSmokeAsync();
                string? mixedAnchorAfter = window.CaptureGridViewportAnchorPathForSmoke();
                int mixedDiscardedCount =
                    window.CatalogProjectionDiscardedCountForSmoke - discardCountBeforeMixed;
                int mixedFilteredCount = window.FilteredCountForSmoke;
                bool mixedViewportAnchorPreserved = mixedAnchorPrepared
                    && mixedRealizationSettled
                    && !string.IsNullOrWhiteSpace(mixedAnchorBefore)
                    && string.Equals(mixedAnchorBefore, mixedAnchorAfter, StringComparison.OrdinalIgnoreCase);
                bool mixedLatestWins = staleMixedSearchResult.Discarded
                    && !staleMixedSearchResult.Applied
                    && staleMixedFilterResult.Discarded
                    && !staleMixedFilterResult.Applied
                    && latestMixedSortApplied
                    && mixedFilteredCount == count / 100
                    && string.Equals(
                        window.SelectedFileNameForSmoke,
                        selectedName,
                        StringComparison.OrdinalIgnoreCase);
                Task<MainWindow.SearchFilterCompletion> staleMixedClear =
                    window.SetSearchInputForSmokeAsync("");
                Task<MainWindow.SearchFilterCompletion> latestMixedFilterClear =
                    window.ClearFavoriteFiltersForSmokeAsync();
                MainWindow.SearchFilterCompletion staleMixedClearResult =
                    await staleMixedClear;
                MainWindow.SearchFilterCompletion latestMixedFilterClearResult =
                    await latestMixedFilterClear;
                bool mixedSortRestored =
                    await window.SetSortByInteractiveForSmokeAsync("modified-newest");
                window.SetSelectedTileRealForSmoke(false);
                selected &= window.SelectFileNameForSmoke(selectedName);
                bool mixedCleanupComplete = staleMixedClearResult.Discarded
                    && latestMixedFilterClearResult.Applied
                    && !latestMixedFilterClearResult.Discarded
                    && mixedSortRestored
                    && window.FilteredCountForSmoke == count
                    && selected;

                // A favorite-only exclusion may reuse the current projection
                // only when that projection is stable. Reproduce the race where
                // clearing a narrow search has been scheduled but not applied
                // before the selected favorite is removed. The exclusion must
                // restart from the full catalog, not the stale narrow subset.
                ReportProgress("favorite-pending-broaden-race");
                window.ForceSharedStoreWritersForSmoke();
                bool favoritePendingBroadenRaceExact =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.MarkSelectedTileRealForSmoke()
                    && window.SetSelectedFavoriteLevelForSmoke(1);
                SharedWriteStatus[] racePreparedWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                MainWindow.SearchFilterCompletion raceFavoriteFilter =
                    await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                MainWindow.SearchFilterCompletion raceNarrowSearch =
                    await window.SetSearchInputForSmokeAsync("needle");
                favoritePendingBroadenRaceExact &=
                    racePreparedWrites.All(static status => status == SharedWriteStatus.Succeeded)
                    && raceFavoriteFilter.Applied
                    && !raceFavoriteFilter.Discarded
                    && raceNarrowSearch.Applied
                    && !raceNarrowSearch.Discarded
                    && window.FilteredCountForSmoke == count / 100
                    && window.SelectFileNameForSmoke(selectedName);
                int resetNotificationsBeforePendingBroaden =
                    window.ProjectionResetNotificationCountForSmoke;
                int removeNotificationsBeforePendingBroaden =
                    window.ProjectionRemoveNotificationCountForSmoke;
                Task<MainWindow.SearchFilterCompletion> pendingRaceBroaden =
                    window.SetSearchInputForSmokeAsync("");
                (bool raceFavoriteEvicted, MainWindow.SearchFilterCompletion raceFavoriteProjection) =
                    await window.AdjustGalleryFavoriteImmediateForSmokeAsync(selectedName, -1);
                MainWindow.SearchFilterCompletion raceBroadenResult =
                    await pendingRaceBroaden;
                bool raceRealizationSettled =
                    await window.WaitForGridRealizationIdleForSmokeAsync();
                favoritePendingBroadenRaceExact &=
                    raceFavoriteEvicted
                    && raceBroadenResult.Discarded
                    && !raceBroadenResult.Applied
                    && raceFavoriteProjection.Applied
                    && !raceFavoriteProjection.Discarded
                    && window.ProjectionResetNotificationCountForSmoke
                        > resetNotificationsBeforePendingBroaden
                    && window.ProjectionRemoveNotificationCountForSmoke
                        == removeNotificationsBeforePendingBroaden
                    && raceRealizationSettled
                    && window.FilteredCountForSmoke == (count / 10) - 1
                    && !string.Equals(
                        window.SelectedFileNameForSmoke,
                        selectedName,
                        StringComparison.OrdinalIgnoreCase);
                MainWindow.SearchFilterCompletion raceFavoriteClear =
                    await window.ClearFavoriteFiltersForSmokeAsync();
                bool raceFavoriteRestored =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.SetSelectedFavoriteLevelForSmoke(5);
                SharedWriteStatus[] raceRestoredWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                selected &= window.SelectFileNameForSmoke(selectedName);
                favoritePendingBroadenRaceExact &=
                    raceFavoriteClear.Applied
                    && !raceFavoriteClear.Discarded
                    && raceFavoriteRestored
                    && raceRestoredWrites.All(static status => status == SharedWriteStatus.Succeeded)
                    && window.FilteredCountForSmoke == count
                    && selected;

                // A rapid re-favorite must cancel the in-flight exclusion
                // snapshot. Otherwise the stale Fav=0 projection can remove a
                // tile after its model and durable intent are Fav=1 again.
                ReportProgress("favorite-rapid-reinclude-race");
                bool favoriteRapidReincludeRaceExact =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.MarkSelectedTileRealForSmoke()
                    && window.SetSelectedFavoriteLevelForSmoke(1);
                SharedWriteStatus[] rapidPreparedWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                MainWindow.SearchFilterCompletion rapidFavoriteFilter =
                    await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                favoriteRapidReincludeRaceExact &=
                    rapidPreparedWrites.All(static status => status == SharedWriteStatus.Succeeded)
                    && rapidFavoriteFilter.Applied
                    && !rapidFavoriteFilter.Discarded
                    && window.SelectFileNameForSmoke(selectedName);
                bool rapidExcluded =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, -1);
                Task<MainWindow.SearchFilterCompletion> staleRapidExclusion =
                    window.PendingCatalogProjectionForSmoke();
                bool rapidReincluded =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, 1);
                Task<MainWindow.SearchFilterCompletion> latestRapidInclusion =
                    window.PendingCatalogProjectionForSmoke();
                MainWindow.SearchFilterCompletion staleRapidResult =
                    await staleRapidExclusion;
                MainWindow.SearchFilterCompletion latestRapidResult =
                    await latestRapidInclusion;
                bool rapidRealizationSettled =
                    await window.WaitForGridRealizationIdleForSmokeAsync();
                favoriteRapidReincludeRaceExact &=
                    rapidExcluded
                    && rapidReincluded
                    && staleRapidResult.Discarded
                    && !staleRapidResult.Applied
                    && latestRapidResult.Applied
                    && !latestRapidResult.Discarded
                    && rapidRealizationSettled
                    && window.FilteredCountForSmoke == count / 10
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 1
                    && string.Equals(
                        window.SelectedFileNameForSmoke,
                        selectedName,
                        StringComparison.OrdinalIgnoreCase);

                // A favorite mutation that supersedes a running interactive
                // sort must inherit its reorder intent. Otherwise the new
                // sort label can be published over the old catalog order.
                ReportProgress("favorite-sort-race");
                Task<bool> pendingFavoriteSort =
                    window.SetSortByInteractiveForSmokeAsync("name");
                Task<MainWindow.SearchFilterCompletion> staleFavoriteSortProjection =
                    window.PendingCatalogProjectionForSmoke();
                bool favoriteChangedDuringSort =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, 1);
                Task<MainWindow.SearchFilterCompletion> latestFavoriteSortProjection =
                    window.PendingCatalogProjectionForSmoke();
                MainWindow.SearchFilterCompletion staleFavoriteSortResult =
                    await staleFavoriteSortProjection;
                bool staleFavoriteSortApplied = await pendingFavoriteSort;
                MainWindow.SearchFilterCompletion latestFavoriteSortResult =
                    await latestFavoriteSortProjection;
                bool favoriteSortRaceExact =
                    favoriteChangedDuringSort
                    && !staleFavoriteSortApplied
                    && staleFavoriteSortResult.Discarded
                    && !staleFavoriteSortResult.Applied
                    && latestFavoriteSortResult.Applied
                    && !latestFavoriteSortResult.Discarded
                    && string.Equals(
                        window.SortByForSmoke,
                        "name",
                        StringComparison.Ordinal)
                    && window.CatalogOrderMatchesCurrentSortForSmoke()
                    && window.FilteredCountForSmoke == count / 10
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 2;
                bool favoriteSortRestored =
                    await window.SetSortByInteractiveForSmokeAsync("modified-newest");
                bool favoriteLevelRestored =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.AdjustGalleryFavoriteForSmoke(selectedName, -1);
                SharedWriteStatus[] favoriteSortWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                favoriteSortRaceExact &=
                    favoriteSortRestored
                    && favoriteLevelRestored
                    && favoriteSortWrites.All(static status =>
                        status == SharedWriteStatus.Succeeded)
                    && window.CatalogOrderMatchesCurrentSortForSmoke()
                    && window.FilteredCountForSmoke == count / 10
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 1
                    && window.SelectFileNameForSmoke(selectedName);

                // Two identical fast decreases create two projection
                // generations. The discarded first generation must not flush
                // the second generation's deferred binding notifications.
                bool duplicateFirstDecrease =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, -1);
                Task<MainWindow.SearchFilterCompletion> duplicateFirstProjection =
                    window.PendingCatalogProjectionForSmoke();
                bool duplicateSecondDecrease =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, -1);
                Task<MainWindow.SearchFilterCompletion> duplicateSecondProjection =
                    window.PendingCatalogProjectionForSmoke();
                Task duplicateSecondPresentation =
                    window.PendingDeferredFavoritePresentationForSmoke();
                long duplicateLatestGeneration =
                    window.FavoriteMutationGenerationForSmoke;
                MainWindow.SearchFilterCompletion duplicateFirstResult =
                    await duplicateFirstProjection;
                bool duplicateNotificationPendingAfterFirst =
                    window.FavoriteNotificationsPendingForFileForSmoke(selectedName);
                bool duplicateLatestProjectionCompletedAtFirstObservation =
                    duplicateSecondProjection.IsCompleted;
                long duplicateLastFlushGenerationAtFirstObservation =
                    window.LastDeferredFavoriteNotificationFlushGenerationForSmoke;
                bool duplicateFirstReleaseOwnershipExact =
                    duplicateNotificationPendingAfterFirst
                    || (duplicateLatestProjectionCompletedAtFirstObservation
                        && duplicateLastFlushGenerationAtFirstObservation
                            == duplicateLatestGeneration);
                MainWindow.SearchFilterCompletion duplicateSecondResult =
                    await duplicateSecondProjection;
                await duplicateSecondPresentation;
                bool favoriteDuplicateEvictionRaceExact =
                    duplicateFirstDecrease
                    && duplicateSecondDecrease
                    && duplicateFirstResult.Discarded
                    && !duplicateFirstResult.Applied
                    && duplicateFirstReleaseOwnershipExact
                    && duplicateSecondResult.Applied
                    && !duplicateSecondResult.Discarded
                    && !window.FavoriteNotificationsPendingForFileForSmoke(selectedName)
                    && window.LastDeferredFavoriteNotificationFlushGenerationForSmoke
                        == duplicateLatestGeneration
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 0
                    && window.FilteredCountForSmoke == (count / 10) - 1;
                MainWindow.SearchFilterCompletion duplicateFavoriteClear =
                    await window.ClearFavoriteFiltersForSmokeAsync();
                bool duplicateFavoriteRestored =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.SetSelectedFavoriteLevelForSmoke(1);
                SharedWriteStatus[] duplicateRestoredWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                MainWindow.SearchFilterCompletion duplicateFavoriteFilter =
                    await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                favoriteDuplicateEvictionRaceExact &=
                    duplicateFavoriteClear.Applied
                    && !duplicateFavoriteClear.Discarded
                    && duplicateFavoriteRestored
                    && duplicateRestoredWrites.All(static status =>
                        status == SharedWriteStatus.Succeeded)
                    && duplicateFavoriteFilter.Applied
                    && !duplicateFavoriteFilter.Discarded
                    && window.FilteredCountForSmoke == count / 10
                    && window.SelectFileNameForSmoke(selectedName);

                // A failed durable write rolls the model back to Fav=1 and
                // schedules a recovery projection. The deferred presentation
                // must not overwrite that final Retry status with stale
                // "Saving..." feedback.
                window.FailNextFavoriteWriterForSmoke();
                bool filteredFailureAccepted =
                    window.AdjustGalleryFavoriteForSmoke(selectedName, -1);
                Task<MainWindow.SearchFilterCompletion> failedExclusion =
                    window.PendingCatalogProjectionForSmoke();
                SharedWriteStatus[] filteredFailureStatuses =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                Task<MainWindow.SearchFilterCompletion> rollbackProjection =
                    window.PendingCatalogProjectionForSmoke();
                MainWindow.SearchFilterCompletion failedExclusionResult =
                    await failedExclusion;
                MainWindow.SearchFilterCompletion rollbackProjectionResult =
                    await rollbackProjection;
                await window.Dispatcher.InvokeAsync(
                    () => { },
                    DispatcherPriority.ContextIdle);
                string favoriteFilteredFailureStatus =
                    window.DeleteStatusForSmoke;
                bool favoriteFilteredRollbackProjectionExact =
                    rollbackProjectionResult.Applied
                    || rollbackProjectionResult.Discarded;
                bool favoriteFilteredRollbackStateExact =
                    window.FailedFavoriteRetryPendingForSmoke
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 1
                    && window.FilteredCountForSmoke == count / 10;
                bool favoriteFilteredFailureToastExact =
                    favoriteFilteredFailureStatus.Contains(
                        "Retry",
                        StringComparison.OrdinalIgnoreCase)
                    && !favoriteFilteredFailureStatus.Contains(
                        "Saving",
                        StringComparison.OrdinalIgnoreCase);
                bool favoriteFilteredFailureStatusExact =
                    filteredFailureAccepted
                    && filteredFailureStatuses.Contains(SharedWriteStatus.Failed)
                    && (failedExclusionResult.Applied
                        || failedExclusionResult.Discarded)
                    && favoriteFilteredRollbackStateExact
                    && favoriteFilteredFailureToastExact;
                window.RetryFailedFavoriteForSmoke();
                Task<MainWindow.SearchFilterCompletion> retryProjection =
                    window.PendingCatalogProjectionForSmoke();
                SharedWriteStatus[] filteredRetryStatuses =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                MainWindow.SearchFilterCompletion retryProjectionResult =
                    await retryProjection;
                bool favoriteFilteredRetryExact =
                    filteredRetryStatuses.All(static status =>
                        status == SharedWriteStatus.Succeeded)
                    && retryProjectionResult.Applied
                    && !retryProjectionResult.Discarded
                    && !window.FailedFavoriteRetryPendingForSmoke
                    && window.FavoriteLevelForFileForSmoke(selectedName) == 0
                    && window.FilteredCountForSmoke == (count / 10) - 1;
                favoriteFilteredFailureStatusExact &=
                    favoriteFilteredRetryExact;
                MainWindow.SearchFilterCompletion rapidFavoriteClear =
                    await window.ClearFavoriteFiltersForSmokeAsync();
                bool rapidFavoriteRestored =
                    window.SelectFileNameForSmoke(selectedName)
                    && window.SetSelectedFavoriteLevelForSmoke(5);
                SharedWriteStatus[] rapidRestoredWrites =
                    await window.DrainSharedStoreWritersForSmokeAsync();
                selected &= window.SelectFileNameForSmoke(selectedName);
                favoriteRapidReincludeRaceExact &=
                    rapidFavoriteClear.Applied
                    && !rapidFavoriteClear.Discarded
                    && rapidFavoriteRestored
                    && rapidRestoredWrites.All(static status => status == SharedWriteStatus.Succeeded)
                    && window.FilteredCountForSmoke == count
                    && selected;

                // Prime the accessibility paths before the memory and heartbeat
                // baselines just like the search/filter/sort paths above. The
                // first UI Automation client connection commits native UIA/WPF
                // pages, while the first focused projection reset initializes
                // focus restoration and container realization. Counting those
                // one-time subsystem costs as repeated catalog churn made the
                // normalized working-set and dispatcher gates runner-dependent.
                ReportProgress("accessibility-warmup");
                bool warmAccessibilitySelected =
                    MeasureAccessibilityWarmupSubstep(
                        "accessibility-warmup-select",
                        () => window.SelectFileNameForSmoke(selectedName));
                await MeasureAccessibilityWarmupActionAsync(
                    "accessibility-warmup-select-layout",
                    FlushLayoutAsync);
                bool warmAccessibilityFocused =
                    MeasureAccessibilityWarmupSubstep(
                        "accessibility-warmup-focus",
                        window.FocusSelectedGalleryItemForSmoke);
                string? warmAccessibilityPath = window.SelectedPathForSmoke;
                MainWindow.SearchFilterCompletion warmAccessibilityFilter =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-filter",
                        () => window.SetSearchInputForSmokeAsync("needle"));
                bool warmAccessibilityFilterSettled =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-filter-idle",
                        async () =>
                            await window.WaitForGridRealizationIdleForSmokeAsync()
                            && await window.WaitForPrimaryGalleryFocusForSmokeAsync()
                            && string.Equals(
                                window.FocusedGalleryPathForSmoke,
                                warmAccessibilityPath,
                                StringComparison.OrdinalIgnoreCase));
                MainWindow.SearchFilterCompletion warmAccessibilityClear =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-clear",
                        () => window.SetSearchInputForSmokeAsync(""));
                bool warmAccessibilityClearSettled =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-clear-idle",
                        async () =>
                            await window.WaitForGridRealizationIdleForSmokeAsync()
                            && await window.WaitForPrimaryGalleryFocusForSmokeAsync()
                            && string.Equals(
                                window.FocusedGalleryPathForSmoke,
                                warmAccessibilityPath,
                                StringComparison.OrdinalIgnoreCase));
                int warmAutomationIndex = count - 1;
                string warmAutomationSuffix =
                    warmAutomationIndex % 100 == 0 ? "-needle" : "";
                string warmAutomationName =
                    $"interaction-smoke-{warmAutomationIndex:D6}{warmAutomationSuffix}.png";
                ExternalGalleryAutomationSmokeSnapshot warmAutomation =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-automation",
                        () => RunExternalGalleryAutomationLookupAsync(
                            window,
                            warmAutomationName));
                bool warmAutomationSettled =
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-automation-idle",
                        () => window.WaitForGridRealizationIdleForSmokeAsync());
                bool accessibilityWarmupComplete =
                    warmAccessibilitySelected
                    && warmAccessibilityFocused
                    && warmAccessibilityFilter.Applied
                    && !warmAccessibilityFilter.Discarded
                    && warmAccessibilityFilterSettled
                    && warmAccessibilityClear.Applied
                    && !warmAccessibilityClear.Discarded
                    && warmAccessibilityClearSettled
                    && warmAutomation.Found
                    && warmAutomation.NameExact
                    && warmAutomation.VirtualizedItemPatternAvailable
                    && warmAutomation.SelectionItemPatternAvailable
                    && warmAutomation.RealizeInvoked
                    && warmAutomationSettled
                    && window.SelectFileNameForSmoke(selectedName);
                await MeasureAccessibilityWarmupActionAsync(
                    "accessibility-warmup-final-layout",
                    FlushLayoutAsync);
                accessibilityWarmupComplete &=
                    await MeasureAccessibilityWarmupSubstepAsync(
                        "accessibility-warmup-final-focus",
                        async () =>
                            window.FocusSelectedGalleryItemForSmoke()
                            && await window.WaitForPrimaryGalleryFocusForSmokeAsync()
                            && await window.WaitForGridRealizationIdleForSmokeAsync());
                window.ResetGridAutomationLookupMetricsForSmoke();
                heartbeatWatch.Restart();
                lastHeartbeatMs = 0;
                lastHeartbeatTimestamp = Stopwatch.GetTimestamp();
                lastHeartbeatUiThreadCpuTicks =
                    dispatcherDiagnostics.ReadUiThreadCpuTicks();
                schedulerMeasurementStartTimestamp = lastHeartbeatTimestamp;
                lastHeartbeatGcPause = GC.GetTotalPauseDuration();
                lastHeartbeatGcBoundaryAmbiguous = false;
                heartbeat.Start();

                bool warmupComplete = warmSearch.Applied
                    && !warmSearch.Discarded
                    && warmClear.Applied
                    && !warmClear.Discarded
                    && warmFavorite.Applied
                    && !warmFavorite.Discarded
                    && warmFavoriteClear.Applied
                    && !warmFavoriteClear.Discarded
                    && warmFavoriteCountExact
                    && window.FilteredCountForSmoke == count
                    && warmSortOldest
                    && warmSortName
                    && warmSortRestored
                    && mixedLatestWins
                    && mixedViewportAnchorPreserved
                    && mixedCleanupComplete
                    && favoritePendingBroadenRaceExact
                    && favoriteRapidReincludeRaceExact
                    && favoriteSortRaceExact
                    && favoriteDuplicateEvictionRaceExact
                    && favoriteFilteredFailureStatusExact
                    && accessibilityWarmupComplete
                    && selected;

                dispatcherDiagnostics.PrepareCapacityForMeasurement();
                dispatcherDiagnostics.Start();

                var process = Process.GetCurrentProcess();
                // The forced collection below defines the memory baseline; it
                // is harness work, not an app interaction. Preserve every
                // heartbeat sample already captured during the cold
                // accessibility warmup, but do not attribute the deliberate
                // stop-the-world collection to the next product operation.
                heartbeat.Stop();
                long managedMemoryBefore = GC.GetTotalMemory(forceFullCollection: true);
                process.Refresh();
                long workingSetBefore = process.WorkingSet64;
                int gen2Before = GC.CollectionCount(2);
                lastHeartbeatMs = heartbeatWatch.ElapsedMilliseconds;
                lastHeartbeatTimestamp = Stopwatch.GetTimestamp();
                lastHeartbeatUiThreadCpuTicks =
                    dispatcherDiagnostics.ReadUiThreadCpuTicks();
                lastHeartbeatGcPause = GC.GetTotalPauseDuration();
                lastHeartbeatGcBoundaryAmbiguous = false;
                heartbeat.Start();
                var searchSamples = new List<long>();
                var searchPhaseSamples = new List<MainWindow.SearchFilterCompletion>();
                var filterSamples = new List<long>();
                var filterPhaseSamples = new List<MainWindow.SearchFilterCompletion>();
                var sortSamples = new List<long>();
                bool countsExact = true;
                bool completionsApplied = true;
                bool favoriteEvictionExact = false;
                bool favoriteEvictionAutomationExact = false;
                bool favoriteEvictionSingleRemovalExact = false;
                ExternalGalleryAutomationSmokeSnapshot? favoriteEvictionAutomation = null;
                long favoriteEvictionElapsedMs = 0;
                long favoriteEvictionApplySliceMs = 0;
                string? favoriteEvictionSelected = null;
                int favoriteEvictionNeighborIndex = count > 50_010 ? 50_010 : 49_990;
                string favoriteEvictionNeighborSuffix =
                    favoriteEvictionNeighborIndex % 100 == 0 ? "-needle" : "";
                string favoriteEvictionExpectedNeighbor =
                    $"interaction-smoke-{favoriteEvictionNeighborIndex:D6}{favoriteEvictionNeighborSuffix}.png";
                int favoriteEvictionAutomationProbeIndex = Math.Max(0, count - 10);
                string favoriteEvictionAutomationProbeSuffix =
                    favoriteEvictionAutomationProbeIndex % 100 == 0 ? "-needle" : "";
                string favoriteEvictionAutomationProbe =
                    $"interaction-smoke-{favoriteEvictionAutomationProbeIndex:D6}{favoriteEvictionAutomationProbeSuffix}.png";
                ReportProgress("search-churn");

                for (int iteration = 0; iteration < 6; iteration++)
                {
                    SetActiveOperation($"search-match-{iteration + 1}");
                    var watch = Stopwatch.StartNew();
                    MainWindow.SearchFilterCompletion match = await window.SetSearchInputForSmokeAsync("needle");
                    await FlushLayoutAsync();
                    watch.Stop();
                    searchSamples.Add(watch.ElapsedMilliseconds);
                    searchPhaseSamples.Add(match);
                    completionsApplied &= match.Applied && !match.Discarded;
                    countsExact &= window.FilteredCountForSmoke == count / 100;

                    SetActiveOperation($"search-clear-{iteration + 1}");
                    watch.Restart();
                    MainWindow.SearchFilterCompletion clear = await window.SetSearchInputForSmokeAsync("");
                    await FlushLayoutAsync();
                    watch.Stop();
                    searchSamples.Add(watch.ElapsedMilliseconds);
                    searchPhaseSamples.Add(clear);
                    completionsApplied &= clear.Applied && !clear.Discarded;
                    countsExact &= window.FilteredCountForSmoke == count;
                }

                ReportProgress("filter-churn");
                for (int iteration = 0; iteration < 6; iteration++)
                {
                    SetActiveOperation($"filter-on-{iteration + 1}");
                    var watch = Stopwatch.StartNew();
                    MainWindow.SearchFilterCompletion favorite =
                        await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                    await FlushLayoutAsync();
                    watch.Stop();
                    filterSamples.Add(watch.ElapsedMilliseconds);
                    filterPhaseSamples.Add(favorite);
                    completionsApplied &= favorite.Applied && !favorite.Discarded;
                    countsExact &= window.FilteredCountForSmoke == count / 10;

                    SetActiveOperation($"filter-clear-{iteration + 1}");
                    watch.Restart();
                    MainWindow.SearchFilterCompletion favoriteClear =
                        await window.ClearFavoriteFiltersForSmokeAsync();
                    await FlushLayoutAsync();
                    watch.Stop();
                    filterSamples.Add(watch.ElapsedMilliseconds);
                    filterPhaseSamples.Add(favoriteClear);
                    completionsApplied &= favoriteClear.Applied && !favoriteClear.Discarded;
                    countsExact &= window.FilteredCountForSmoke == count;
                }

                ReportProgress("favorite-eviction-prepare");
                SetActiveOperation("favorite-eviction-select");
                bool favoriteEvictionPrepared = window.SelectFileNameForSmoke(selectedName)
                    && window.MarkSelectedTileRealForSmoke();
                SetActiveOperation("favorite-eviction-write");
                window.ForceSharedStoreWritersForSmoke();
                favoriteEvictionPrepared &= window.SetSelectedFavoriteLevelForSmoke(1);
                SetActiveOperation("favorite-eviction-drain");
                SharedWriteStatus[] preparedWrites = await window.DrainSharedStoreWritersForSmokeAsync();
                favoriteEvictionPrepared &= preparedWrites.All(static status => status == SharedWriteStatus.Succeeded);
                SetActiveOperation("favorite-eviction-filter");
                MainWindow.SearchFilterCompletion favoriteEvictionFilter =
                    await window.SetFavoriteOnlyFilterForSmokeAsync(true);
                favoriteEvictionPrepared &= window.FilteredCountForSmoke == count / 10
                    && favoriteEvictionFilter.Applied
                    && !favoriteEvictionFilter.Discarded
                    && string.Equals(window.SelectedFileNameForSmoke, selectedName, StringComparison.OrdinalIgnoreCase);

                ReportProgress("favorite-eviction");
                int resetNotificationsBeforeFavoriteEviction =
                    window.ProjectionResetNotificationCountForSmoke;
                int removeNotificationsBeforeFavoriteEviction =
                    window.ProjectionRemoveNotificationCountForSmoke;
                var favoriteEvictionWatch = Stopwatch.StartNew();
                bool favoriteEvicted = await window.AdjustGalleryFavoritePointerForSmokeAsync(selectedName, -1);
                favoriteEvictionApplySliceMs = window.LastCatalogProjectionApplySliceMsForSmoke;
                await FlushLayoutAsync();
                favoriteEvictionWatch.Stop();
                favoriteEvictionElapsedMs = favoriteEvictionWatch.ElapsedMilliseconds;
                favoriteEvictionSingleRemovalExact =
                    window.ProjectionResetNotificationCountForSmoke
                        == resetNotificationsBeforeFavoriteEviction
                    && window.ProjectionRemoveNotificationCountForSmoke
                        == removeNotificationsBeforeFavoriteEviction + 1;
                int selectionBeforeFavoriteAutomation = window.SelectedIndexForSmoke;
                SetActiveOperation("favorite-eviction-automation");
                favoriteEvictionAutomation =
                    await RunExternalGalleryAutomationLookupAsync(
                        window,
                        favoriteEvictionAutomationProbe);
                SetActiveOperation("favorite-eviction-realization-idle");
                await window.WaitForGridRealizationIdleForSmokeAsync();
                favoriteEvictionAutomationExact = favoriteEvictionAutomation.Found
                    && favoriteEvictionAutomation.NameExact
                    && favoriteEvictionAutomation.VirtualizedItemPatternAvailable
                    && favoriteEvictionAutomation.SelectionItemPatternAvailable
                    && favoriteEvictionAutomation.RealizeInvoked
                    && window.SelectedIndexForSmoke == selectionBeforeFavoriteAutomation
                    && window.GridAutomationLookupMaxMsForSmoke <= 4;
                favoriteEvictionSelected = window.SelectedFileNameForSmoke;
                favoriteEvictionExact = favoriteEvictionPrepared
                    && favoriteEvicted
                    && favoriteEvictionSingleRemovalExact
                    && favoriteEvictionAutomationExact
                    && window.FilteredCountForSmoke == (count / 10) - 1
                    && string.Equals(
                        favoriteEvictionSelected,
                        favoriteEvictionExpectedNeighbor,
                        StringComparison.OrdinalIgnoreCase);
                countsExact &= favoriteEvictionExact;

                ReportProgress("favorite-eviction-restore");
                SetActiveOperation("favorite-eviction-restore-filter");
                MainWindow.SearchFilterCompletion favoriteEvictionClear =
                    await window.ClearFavoriteFiltersForSmokeAsync();
                SetActiveOperation("favorite-eviction-restore-select");
                bool favoriteEvictionRestored = window.SelectFileNameForSmoke(selectedName)
                    && window.SetSelectedFavoriteLevelForSmoke(5);
                SetActiveOperation("favorite-eviction-restore-drain");
                SharedWriteStatus[] restoredWrites = await window.DrainSharedStoreWritersForSmokeAsync();
                countsExact &= favoriteEvictionRestored
                    && favoriteEvictionClear.Applied
                    && !favoriteEvictionClear.Discarded
                    && restoredWrites.All(static status => status == SharedWriteStatus.Succeeded)
                    && window.FilteredCountForSmoke == count;

                ReportProgress("sort-churn");
                string[] sortModes =
                [
                    "name",
                    "created-oldest",
                    "modified-oldest",
                    "created-newest",
                    "modified-newest",
                    "name",
                ];
                foreach (string sortMode in sortModes)
                {
                    SetActiveOperation($"sort-{sortMode}");
                    var watch = Stopwatch.StartNew();
                    bool changed = await window.SetSortByInteractiveForSmokeAsync(sortMode);
                    await FlushLayoutAsync();
                    watch.Stop();
                    sortSamples.Add(watch.ElapsedMilliseconds);
                    countsExact &= changed && window.FilteredCountForSmoke == count;
                }

                ReportProgress("keyboard-accessibility");
                int keyboardStartIndex = Math.Min(count - 2, 50_000);
                int tailIndex = count - 1;
                string tailName = $"interaction-smoke-{tailIndex:D6}{(tailIndex % 100 == 0 ? "-needle" : "")}.png";
                string headName = "interaction-smoke-000000-needle.png";
                SetActiveOperation("keyboard-seed-layout");
                bool keyboardSeeded = window.SelectIndexForSmoke(keyboardStartIndex);
                await FlushLayoutAsync();
                SetActiveOperation("keyboard-initial-focus");
                bool keyboardInitialFocus = window.FocusSelectedGalleryItemForSmoke();
                int keyboardMaxRealized = window.GridRealizedCountForSmoke;
                long keyboardSelectionSyncMaxMs = window.LastCardsSelectionSyncMsForSmoke;

                // Verify projection focus restoration while the mid-catalog
                // item is already realized. Re-jumping to index 50,000 after
                // the Home/arrow sequence forced an unrelated second full
                // layout into the heartbeat window on slower hosted runners.
                bool projectionFocusPrepared = keyboardInitialFocus;
                string? projectionFocusPath = window.SelectedPathForSmoke;
                SetActiveOperation("keyboard-focus-filter");
                MainWindow.SearchFilterCompletion keyboardFocusFilter =
                    await window.SetSearchInputForSmokeAsync("needle");
                bool keyboardFocusFilterRealized = await MeasureKeyboardFocusSubstepAsync(
                    "keyboard-focus-filter-realize",
                    () => window.WaitForGridRealizationIdleForSmokeAsync());
                bool projectionFilterFocusRestored = await MeasureKeyboardFocusSubstepAsync(
                    "keyboard-focus-filter-focus",
                    () => window.WaitForPrimaryGalleryFocusForSmokeAsync())
                    && string.Equals(window.FocusedGalleryPathForSmoke, projectionFocusPath, StringComparison.OrdinalIgnoreCase);
                SetActiveOperation("keyboard-focus-clear");
                MainWindow.SearchFilterCompletion keyboardFocusClear =
                    await window.SetSearchInputForSmokeAsync("");
                bool keyboardFocusClearRealized = await MeasureKeyboardFocusSubstepAsync(
                    "keyboard-focus-clear-realize",
                    () => window.WaitForGridRealizationIdleForSmokeAsync());
                bool projectionClearFocusRestored = await MeasureKeyboardFocusSubstepAsync(
                    "keyboard-focus-clear-focus",
                    () => window.WaitForPrimaryGalleryFocusForSmokeAsync())
                    && string.Equals(window.FocusedGalleryPathForSmoke, projectionFocusPath, StringComparison.OrdinalIgnoreCase);
                bool projectionFocusRestored = projectionFocusPrepared
                    && keyboardFocusFilter.Applied
                    && !keyboardFocusFilter.Discarded
                    && keyboardFocusClear.Applied
                    && !keyboardFocusClear.Discarded
                    && keyboardFocusFilterRealized
                    && keyboardFocusClearRealized
                    && projectionFilterFocusRestored
                    && projectionClearFocusRestored;
                keyboardMaxRealized = Math.Max(keyboardMaxRealized, window.GridRealizedCountForSmoke);

                SetActiveOperation("keyboard-end");
                bool keyboardEndHandled = window.InvokeGalleryNavigationKeyForSmoke(Key.End);
                keyboardSelectionSyncMaxMs = Math.Max(
                    keyboardSelectionSyncMaxMs,
                    window.LastCardsSelectionSyncMsForSmoke);
                bool keyboardEndFocused = await window.WaitForPrimaryGalleryFocusForSmokeAsync();
                await window.WaitForGridRealizationIdleForSmokeAsync();
                bool keyboardEndExact = window.SelectedIndexForSmoke == tailIndex
                    && string.Equals(window.SelectedFileNameForSmoke, tailName, StringComparison.Ordinal)
                    && keyboardEndFocused;
                bool keyboardBoundaryEndHandled = window.InvokeGalleryNavigationKeyForSmoke(Key.End);
                bool keyboardBoundaryEndExact = keyboardBoundaryEndHandled
                    && window.SelectedIndexForSmoke == tailIndex;
                bool keyboardLetterIgnored = !window.InvokeGalleryNavigationKeyForSmoke(Key.A)
                    && window.SelectedIndexForSmoke == tailIndex;
