                await FlushLayoutAsync();
                const int minimumLargeProjectionCount = 24_000;
                int secondaryEvictionFilteredCount = window.FilteredCountForSmoke;
                int secondaryEvictionSelectedCount = window.SelectedCountForSmoke;
