                    && !secondaryEvictionReleaseCompletion.Discarded
                    && secondaryEvictionClear.Applied
                    && !secondaryEvictionClear.Discarded
                    && boundarySelectionReleaseCompletion.Applied
                    && !boundarySelectionReleaseCompletion.Discarded
                    && boundarySelectionClear.Applied
                    && !boundarySelectionClear.Discarded;

                double searchP95 = SmokePercentile(searchSamples, 0.95);
                double filterP95 = SmokePercentile(filterSamples, 0.95);
                double sortP95 = SmokePercentile(sortSamples, 0.95);
                double coldGalleryFocusWarmupMs =
                    accessibilityWarmupSubstepSamples
                        .FirstOrDefault(static sample =>
                            sample.Operation == "accessibility-warmup-focus")
                        ?.WallMs ?? double.PositiveInfinity;
                bool selectionStable = selected
                    && string.Equals(window.SelectedFileNameForSmoke, selectedName, StringComparison.OrdinalIgnoreCase);
                bool bounded = window.GridItemsSourceCountForSmoke == count
                    && window.GridUsesFullExtentVirtualizationForSmoke
                    && window.GridRealizedCountForSmoke <= window.GridMaxRealizationCountForSmoke;
                bool detachedContainerReuseActive =
                    window.GridDetachedContainerReuseCountForSmoke > 0;
                long catalogProjectionMaxApplySliceMs = Math.Max(
                    searchPhaseSamples.Count == 0
                        ? 0
                        : searchPhaseSamples.Max(static sample => sample.MaxApplySliceMs),
                    filterPhaseSamples.Count == 0
                        ? 0
                        : filterPhaseSamples.Max(static sample => sample.MaxApplySliceMs));
                long catalogProjectionMaxSingleContainerDetachMs = Math.Max(
                    searchPhaseSamples.Count == 0
                        ? 0
                        : searchPhaseSamples.Max(static sample => sample.PreResetMs),
                    filterPhaseSamples.Count == 0
                        ? 0
                        : filterPhaseSamples.Max(static sample => sample.PreResetMs));
                List<MainWindow.SearchFilterCompletion> catalogProjectionDetachSamples =
                    searchPhaseSamples.Concat(filterPhaseSamples).ToList();
                MainWindow.SearchFilterCompletion catalogProjectionMaxBudgetSample =
                    catalogProjectionDetachSamples.Count == 0
                        ? default
                        : catalogProjectionDetachSamples
                            .OrderByDescending(static sample => sample.ResetPanelBudgetMs)
                            .First();
                double catalogProjectionMaxResetPanelBudgetMs =
                    catalogProjectionMaxBudgetSample.ResetPanelBudgetMs;
                double catalogProjectionMaxResetPanelThreadCpuMs =
                    catalogProjectionDetachSamples
                        .Where(static sample => sample.ResetPanelThreadCpuMs >= 0)
                        .Select(static sample => sample.ResetPanelThreadCpuMs)
                        .DefaultIfEmpty(-1)
                        .Max();
                string catalogProjectionDetachBudgetBasis =
                    catalogProjectionMaxBudgetSample.ResetPanelBudgetUsedWallFallback
                        ? "wall-fallback"
                        : "thread-cpu-clamped-to-wall";
                bool catalogProjectionDetachWithinBudget =
                    catalogProjectionMaxResetPanelBudgetMs
                        <= CatalogProjectionSingleContainerDetachBudgetMs;
                bool catalogProjectionDetachWithinHostedAcceptance =
                    catalogProjectionMaxResetPanelBudgetMs
                        <= CatalogProjectionSingleContainerDetachHostedAcceptanceMs;
                double dispatcherHeartbeatHostedAcceptanceLimitMs =
                    CatalogInteractionDispatcherHeartbeatBudgetMs
                    + CatalogInteractionDispatcherHeartbeatMeasurementToleranceMs;
                List<CatalogDispatcherHeartbeatDiagnostic>
                    dispatcherHeartbeatHostedOutliers =
                        dispatcherDiagnostic.OverBudgetHeartbeats
                            .Where(sample =>
                                sample.ProductGapMs
                                    > dispatcherHeartbeatHostedAcceptanceLimitMs)
                            .ToList();
                const string synchronizationContextAwaitCallbackPrefix =
                    "System.Threading.Tasks.SynchronizationContextAwaitTaskContinuation+";
                Dictionary<long, SchedulerControlConsensusSample>
                    schedulerControlByHeartbeatTag =
                        schedulerHostAttribution.HeartbeatSamples
                            .GroupBy(static sample => sample.HeartbeatTag)
                            .Where(static group => group.Count() == 1)
                            .ToDictionary(
                                static group => group.Key,
                                static group => group.Single());
                var dispatcherHeartbeatHostedEvidence =
                    new List<HostedDispatcherPreemptionEvidence>(
                        dispatcherHeartbeatHostedOutliers.Count);
                foreach (CatalogDispatcherHeartbeatDiagnostic sample
                    in dispatcherHeartbeatHostedOutliers)
                {
                    bool matchedControl = schedulerControlByHeartbeatTag.TryGetValue(
                        sample.HeartbeatTag,
                        out SchedulerControlConsensusSample? control);
                    List<CatalogDispatcherOperationDiagnostic> longOperations =
                        sample.ActiveOperations
                            .Where(operation =>
                                operation.ExecutionWallMs
                                    > dispatcherHeartbeatHostedAcceptanceLimitMs)
                            .ToList();
                    bool positiveControlConsensus = matchedControl
                        && schedulerHostAttribution.SensorValid
                        && string.Equals(
                            control!.Classification,
                            "CONTROL_CONSENSUS_OVERLAP",
                            StringComparison.Ordinal)
                        && Math.Abs(control.RawGapMs - sample.RawGapMs)
                            <= CatalogInteractionDispatcherHeartbeatAttributionToleranceMs;
                    dispatcherHeartbeatHostedEvidence.Add(new(
                        RawGapMs: sample.RawGapMs,
                        ProductGapMs: sample.ProductGapMs,
                        DispatcherClassificationExact: string.Equals(
                            sample.Classification,
                            "ACTIVE_OPERATION_DIAGNOSTIC",
                            StringComparison.Ordinal),
                        QueueDiagnosticExact:
                            sample.HeartbeatQueueUiCpuMs == 0
                            && sample.ExcessQueueUiCpuMs <= 0
                            && sample.HeartbeatQueueWallMs
                                > dispatcherHeartbeatHostedAcceptanceLimitMs,
                        UiCpuExact:
                            sample.UiThreadCpuMs == 0
                            && sample.ActiveOperations.Count > 0
                            && sample.ActiveOperations.All(
                                static operation =>
                                    operation.ExecutionUiCpuMs == 0),
                        PanelCpuExact:
                            sample.PanelPhaseOverlapMs <= 1
                            && sample.PanelPhases.All(
                                static phase => phase.UiCpuMs == 0),
                        LongAwaitContinuationExact:
                            longOperations.Count > 0
                            && longOperations.All(operation =>
                                operation.ExecutionUiCpuMs == 0
                                && operation.CallbackName.StartsWith(
                                    synchronizationContextAwaitCallbackPrefix,
                                    StringComparison.Ordinal)),
                        PositiveControlConsensus: positiveControlConsensus,
                        ControlConsensusOverlapMs: matchedControl
                            ? control!.ControlConsensusOverlapMs
                            : double.PositiveInfinity,
                        UnexplainedGapMs: matchedControl
                            ? control!.UnexplainedGapMs
                            : double.PositiveInfinity,
                        GcTimingAmbiguous: !matchedControl
                            || control!.GcTimingAmbiguous));
                }
                HostedDispatcherPreemptionPolicySelfTest
                    dispatcherHeartbeatHostedPreemptionPolicySelfTest =
                        VerifyHostedDispatcherPreemptionPolicy(
                            dispatcherHeartbeatHostedAcceptanceLimitMs,
                            CatalogInteractionDispatcherHeartbeatHostedAbsoluteCeilingMs);
                bool dispatcherHeartbeatHostedPreemptionAccepted =
                    dispatcherHeartbeatHostedOutliers.Count > 0
                    && dispatcherHeartbeatHostedPreemptionPolicySelfTest.Exact
                    && dispatcherHeartbeatHostedEvidence.All(evidence =>
                        IsHostedDispatcherPreemptionAcceptable(
                            evidence,
                            dispatcherHeartbeatHostedAcceptanceLimitMs,
                            CatalogInteractionDispatcherHeartbeatHostedAbsoluteCeilingMs));
                bool dispatcherHeartbeatWithinHostedAcceptance =
                    dispatcherDiagnostic.MaxProductGapMs
                        <= dispatcherHeartbeatHostedAcceptanceLimitMs
                    || dispatcherHeartbeatHostedPreemptionAccepted;
                List<MainWindow.SearchFilterCompletion> appliedProjectionSamples =
                    catalogProjectionDetachSamples
                        .Where(static sample => sample.Applied && !sample.Discarded)
                        .ToList();
                long catalogSnapshotResetMaxWallMs =
                    appliedProjectionSamples
                        .Select(static sample => sample.ResetMs)
                        .DefaultIfEmpty(0)
                        .Max();
                double catalogSnapshotResetMaxThreadCpuMs =
                    appliedProjectionSamples
                        .Where(static sample =>
                            sample.CatalogSnapshotResetCount > 0)
                        .Select(static sample =>
                            sample.CatalogSnapshotResetThreadCpuMs)
                        .DefaultIfEmpty(-1)
                        .Max();
                bool catalogSnapshotResetCountExact =
                    appliedProjectionSamples.Count > 0
                    && appliedProjectionSamples.All(static sample =>
                        sample.CatalogSnapshotResetNestedCount == 0
                        && sample.CatalogSnapshotResetCount
                            == (sample.PublishedSingleRemoval ? 0 : 1));
                bool catalogSnapshotResetCpuMeasuredExact =
                    appliedProjectionSamples
                        .Where(static sample =>
                            sample.CatalogSnapshotResetCount > 0)
                        .All(static sample =>
                            sample.CatalogSnapshotResetThreadCpuMs >= 0);
                long catalogProjectionMaxPreResetSelectionReleaseMs =
                    appliedProjectionSamples
                        .Where(static sample =>
                            sample.CatalogSnapshotResetCount > 0)
                        .Select(static sample =>
                            sample.PreResetSelectionReleaseMs)
                        .DefaultIfEmpty(0)
                        .Max();
                bool catalogProjectionPreResetSelectionClearedExact =
                    appliedProjectionSamples
                        .Where(static sample =>
                            sample.CatalogSnapshotResetCount > 0)
                        .All(static sample =>
                            sample.PreResetSelectionCleared);
                int catalogProjectionPreResetSelectionReleasedCount =
                    appliedProjectionSamples
                        .Where(static sample =>
                            sample.CatalogSnapshotResetCount > 0)
                        .Sum(static sample =>
                            sample.PreResetSelectionReleasedCount);
                int catalogProjectionMaxDetachedContainersPerSlice =
                    appliedProjectionSamples
                        .Select(static sample => sample.MaxResetDetachedContainersPerSlice)
                        .DefaultIfEmpty(0)
                        .Max();
                bool catalogProjectionInputBoundaryBeforePublicationExact =
                    appliedProjectionSamples.Count > 0
                    && appliedProjectionSamples.All(
                        static sample => sample.InputBoundaryBeforePublication);
                bool catalogProjectionInputBoundaryAfterPublicationExact =
                    appliedProjectionSamples.Count > 0
                    && appliedProjectionSamples.All(
                        static sample => sample.InputBoundaryAfterPublication);
                MainWindow.SearchFilterCompletion catalogProjectionMaxDetachSample =
                    catalogProjectionDetachSamples.Count == 0
                        ? default
                        : catalogProjectionDetachSamples
                            .OrderByDescending(static sample => sample.PreResetMs)
                            .First();
                double catalogProjectionMaxGeneratorRemoveMs =
                    catalogProjectionMaxDetachSample.ResetGeneratorRemoveMs;
                double catalogProjectionMaxForgetDeferredMeasureMs =
                    catalogProjectionMaxDetachSample.ResetForgetDeferredMeasureMs;
                double catalogProjectionMaxRemoveInternalChildRangeMs =
                    catalogProjectionMaxDetachSample.ResetRemoveInternalChildRangeMs;
                double catalogProjectionMaxRemoveInternalChildRangeThreadCpuMs =
                    catalogProjectionMaxDetachSample.ResetRemoveInternalChildRangeThreadCpuMs;
                double catalogProjectionMaxResetPanelTotalMs =
                    catalogProjectionMaxDetachSample.ResetPanelTotalMs;
                string catalogProjectionDominantResetSubstep =
                    catalogProjectionMaxGeneratorRemoveMs <= 0
                    && catalogProjectionMaxForgetDeferredMeasureMs <= 0
                    && catalogProjectionMaxRemoveInternalChildRangeMs <= 0
                        ? "none"
                        : catalogProjectionMaxGeneratorRemoveMs
                            >= catalogProjectionMaxForgetDeferredMeasureMs
                        && catalogProjectionMaxGeneratorRemoveMs
                            >= catalogProjectionMaxRemoveInternalChildRangeMs
                            ? "ItemContainerGenerator.Remove"
                            : catalogProjectionMaxForgetDeferredMeasureMs
                                >= catalogProjectionMaxRemoveInternalChildRangeMs
                                ? "ForgetDeferredMeasureRange"
                                : "RemoveInternalChildRange";
                string catalogProjectionMaxApplySliceOperation =
                    catalogProjectionMaxApplySliceMs <= CatalogProjectionDiagnosticSliceTargetMs
                        ? "within-diagnostic-target"
                        : "app-owned-cooperative-phase";
                bool ok = window.CatalogCountForSmoke == count
                    && warmupComplete
                    && coldGalleryFocusWarmupMs
                        <= CatalogColdGalleryFocusWarmupBudgetMs
                    && countsExact
                    && completionsApplied
                    && farTailSelectionReleaseExact
                    && secondaryEvictionReleaseExact
                    && boundarySelectionReleaseExact
                    && selectedAfterExtendedSelectionCases
                    && selectionStable
                    && bounded
                    && detachedContainerReuseActive
                    && keyboardNavigationExact
                    && projectionFocusRestored
                    && externalAutomationExact
                    && externalAutomationPreservedSelection
                    && repeatedRealizeCoalesced
                    && automationVirtualizedItemExact
                    && stalePeerLifetimeExact
                    && recycledContainerStateReset
                    && keyboardAccessibilityBounded
                    && searchP95 <= CatalogInteractionSearchHostedAcceptanceMs
                        + CatalogInteractionHostedMeasurementToleranceMs
                    && filterP95 <= CatalogInteractionFilterHostedAcceptanceMs
                        + CatalogInteractionHostedMeasurementToleranceMs
                    && sortP95 <= CatalogInteractionSortHostedAcceptanceMs
                        + CatalogInteractionHostedMeasurementToleranceMs
                    && favoriteEvictionExact
                    && favoriteEvictionAutomationExact
                    && favoriteEvictionSingleRemovalExact
                    && favoriteEvictionElapsedMs
                        <= CatalogFavoriteEvictionBudgetMs
                            + CatalogInteractionHostedMeasurementToleranceMs
                    && catalogProjectionMaxDetachedContainersPerSlice <= 1
                    && catalogProjectionInputBoundaryBeforePublicationExact
                    && catalogProjectionInputBoundaryAfterPublicationExact
                    && catalogSnapshotResetMaxWallMs
                        <= CatalogSnapshotResetBudgetMs
                    && catalogSnapshotResetCountExact
                    && catalogSnapshotResetCpuMeasuredExact
                    && catalogProjectionPreResetSelectionClearedExact
                    && catalogProjectionPreResetSelectionReleasedCount > 0
                    && catalogProjectionDetachWithinHostedAcceptance
                    && dispatcherDiagnostic.SensorValid
                    // Hosted preemption requires the exact zero-CPU await
                    // signature plus positive independent-control consensus
                    // for the same heartbeat. GC ambiguity and more than
                    // 75 ms of unexplained time are never accepted.
                    && dispatcherHeartbeatHostedPreemptionPolicySelfTest.Exact
                    && dispatcherHeartbeatWithinHostedAcceptance
                    && dispatcherDiagnostic.InconclusiveCount == 0
                    // Rapid churn leaves dead WPF generator/layout objects in
                    // young generations and committed pages in the process
                    // working set. Gate the collectible live graph tightly and
                    // keep a separate normalized native/committed-page ceiling.
                    && liveManagedMemoryRegressionPercent <= 15
                    && normalizedWorkingSetRegressionPercent <= 35;
                result = new CatalogInteractionSmokeResult
                {
                    Ok = ok,
                    RequestedCount = count,
                    CatalogCount = window.CatalogCountForSmoke,
                    FilteredCount = window.FilteredCountForSmoke,
                    SeedElapsedMs = seedWatch.ElapsedMilliseconds,
                    WarmupComplete = warmupComplete,
                    AccessibilityWarmupFilterCompletion = warmAccessibilityFilter,
                    AccessibilityWarmupClearCompletion = warmAccessibilityClear,
                    AccessibilityWarmupSubstepSamples = accessibilityWarmupSubstepSamples,
                    SearchP95Ms = searchP95,
                    FilterP95Ms = filterP95,
                    SortP95Ms = sortP95,
                    SearchProductTargetMs = CatalogInteractionSearchProductTargetMs,
                    FilterProductTargetMs = CatalogInteractionFilterProductTargetMs,
                    SortProductTargetMs = CatalogInteractionSortProductTargetMs,
                    SearchHostedAcceptanceMs = CatalogInteractionSearchHostedAcceptanceMs,
                    FilterHostedAcceptanceMs = CatalogInteractionFilterHostedAcceptanceMs,
                    SortHostedAcceptanceMs = CatalogInteractionSortHostedAcceptanceMs,
                    HostedMeasurementToleranceMs =
                        CatalogInteractionHostedMeasurementToleranceMs,
                    SearchProductTargetMet = searchP95 <= CatalogInteractionSearchProductTargetMs,
                    FilterProductTargetMet = filterP95 <= CatalogInteractionFilterProductTargetMs,
                    SortProductTargetMet = sortP95 <= CatalogInteractionSortProductTargetMs,
                    FavoriteEvictionElapsedMs = favoriteEvictionElapsedMs,
                    FavoriteEvictionApplySliceMs = favoriteEvictionApplySliceMs,
                    FavoriteEvictionExact = favoriteEvictionExact,
                    FavoriteEvictionAutomationExact = favoriteEvictionAutomationExact,
                    FavoriteEvictionSingleRemovalExact = favoriteEvictionSingleRemovalExact,
                    FavoriteEvictionAutomation = favoriteEvictionAutomation,
                    FavoriteEvictionSelectedFileName = favoriteEvictionSelected,
                    FavoriteEvictionExpectedNeighbor = favoriteEvictionExpectedNeighbor,
                    FarTailSelectionReleaseExact = farTailSelectionReleaseExact,
                    FarTailSelectionReleaseCompletion = farTailSelectionReleaseCompletion,
                    SecondaryEvictionReleaseExact = secondaryEvictionReleaseExact,
                    SecondaryEvictionReleaseCompletion = secondaryEvictionReleaseCompletion,
                    SecondaryEvictionPrepared = secondaryEvictionPrepared,
                    SecondaryEvictionMinimumFilteredCount = minimumLargeProjectionCount,
                    SecondaryEvictionFilteredCount = secondaryEvictionFilteredCount,
                    SecondaryEvictionSelectedCount = secondaryEvictionSelectedCount,
                    SecondaryEvictionSelectedFileName = secondaryEvictionSelectedFileName,
                    BoundarySelectionReleaseExact = boundarySelectionReleaseExact,
                    BoundarySelectionReleaseCompletion = boundarySelectionReleaseCompletion,
                    SearchSamplesMs = searchSamples,
                    SearchPhaseSamples = searchPhaseSamples,
                    FilterSamplesMs = filterSamples,
                    FilterPhaseSamples = filterPhaseSamples,
                    SortSamplesMs = sortSamples,
                    CountsExact = countsExact,
                    SearchCompletionsApplied = completionsApplied,
                    SelectionStable = selectionStable,
                    SelectedFileName = window.SelectedFileNameForSmoke,
                    KeyboardNavigationExact = keyboardNavigationExact,
                    KeyboardEndExact = keyboardEndExact,
                    KeyboardBoundaryEndExact = keyboardBoundaryEndExact,
                    KeyboardLetterIgnored = keyboardLetterIgnored,
                    KeyboardHomeExact = keyboardHomeExact,
                    KeyboardRightExact = keyboardRightExact,
                    KeyboardDownExact = keyboardDownExact,
                    KeyboardPageDownExact = keyboardPageDownExact,
                    ProjectionFocusRestored = projectionFocusRestored,
                    ExternalAutomationExact = externalAutomationExact,
                    ExternalAutomationPreservedSelection = externalAutomationPreservedSelection,
                    ExternalAutomation = externalAutomation,
                    RepeatedAutomationRealizeCoalesced = repeatedRealizeCoalesced,
                    AutomationRealizeDispatchCount = window.GridAutomationRealizeDispatchCountForSmoke,
                    AutomationRealizeCoalescedCount = window.GridAutomationRealizeCoalescedCountForSmoke,
                    AutomationRealizeMaxDispatchMs = window.GridAutomationRealizeMaxDispatchMsForSmoke,
                    AutomationLookupMaxMs = window.GridAutomationLookupMaxMsForSmoke,
                    StaleAutomationPeerLifetimeExact = stalePeerLifetimeExact,
                    StaleAutomationRealizeUnavailable = staleRealizeUnavailable,
                    StaleAutomationSelectUnavailable = staleSelectUnavailable,
                    StaleAutomationFilterCompletion = stalePeerFilter,
                    StaleAutomationClearCompletion = stalePeerClear,
                    StaleAutomationSubstepSamples = stalePeerSubstepSamples,
                    AutomationVirtualizedItemExact = automationVirtualizedItemExact,
                    AutomationRealizePreservedSelection = automationRealizePreservedSelection,
                    AutomationSelectionExact = automationSelectionExact,
                    RecycledContainerStateReset = recycledContainerStateReset,
                    KeyboardAccessibilityMaxRealized = keyboardMaxRealized,
                    KeyboardSelectionSyncMaxMs = keyboardSelectionSyncMaxMs,
                    KeyboardAccessibilityBounded = keyboardAccessibilityBounded,
                    KeyboardFocusFilterCompletion = keyboardFocusFilter,
                    KeyboardFocusClearCompletion = keyboardFocusClear,
                    KeyboardFocusSubstepSamples = keyboardFocusSubstepSamples,
                    AutomationTailPeer = automationTailPeer,
                    AutomationTailContainer = automationTailContainer,
                    RecycledHeadContainer = recycledHeadContainer,
                    GridItemsSourceCount = window.GridItemsSourceCountForSmoke,
                    GridRealizedCount = window.GridRealizedCountForSmoke,
                    GridRealizationLimit = window.GridMaxRealizationCountForSmoke,
                    GridUsesFullExtentVirtualization = window.GridUsesFullExtentVirtualizationForSmoke,
                    GridDetachedContainerCreatedCount =
                        window.GridDetachedContainerCreatedCountForSmoke,
                    GridDetachedContainerReuseCount =
                        window.GridDetachedContainerReuseCountForSmoke,
                    HeartbeatCount = heartbeatCount,
                    DispatcherHeartbeatMaxGapMs = maxHeartbeatGapMs,
                    DispatcherHeartbeatMaxGapSample = maxHeartbeatGapSample,
                    DispatcherHeartbeatMaxGapGcPauseMs = maxHeartbeatGapGcPauseMs,
                    DispatcherHeartbeatMaxGapProjectionGeneration =
                        maxHeartbeatGapProjectionGeneration,
                    SchedulerControlConsensus = schedulerHostAttribution,
                    DispatcherDiagnostic = dispatcherDiagnostic,
                    CatalogProjectionMaxApplySliceMs = catalogProjectionMaxApplySliceMs,
                    CatalogProjectionMaxApplySliceOperation = catalogProjectionMaxApplySliceOperation,
                    CatalogProjectionDiagnosticSliceTargetMs = CatalogProjectionDiagnosticSliceTargetMs,
                    CatalogSnapshotResetBudgetMs =
                        CatalogSnapshotResetBudgetMs,
                    CatalogSnapshotResetMaxWallMs =
                        catalogSnapshotResetMaxWallMs,
                    CatalogSnapshotResetMaxThreadCpuMs =
                        catalogSnapshotResetMaxThreadCpuMs,
                    CatalogSnapshotResetCountExact =
                        catalogSnapshotResetCountExact,
                    CatalogSnapshotResetCpuMeasuredExact =
                        catalogSnapshotResetCpuMeasuredExact,
                    CatalogProjectionMaxPreResetSelectionReleaseMs =
                        catalogProjectionMaxPreResetSelectionReleaseMs,
                    CatalogProjectionPreResetSelectionClearedExact =
                        catalogProjectionPreResetSelectionClearedExact,
                    CatalogProjectionPreResetSelectionReleasedCount =
                        catalogProjectionPreResetSelectionReleasedCount,
                    ColdGalleryFocusWarmupMs =
                        coldGalleryFocusWarmupMs,
                    ColdGalleryFocusWarmupBudgetMs =
                        CatalogColdGalleryFocusWarmupBudgetMs,
                    CatalogProjectionSingleContainerDetachBudgetMs =
                        CatalogProjectionSingleContainerDetachBudgetMs,
                    CatalogProjectionSingleContainerDetachHostedAcceptanceMs =
                        CatalogProjectionSingleContainerDetachHostedAcceptanceMs,
                    CatalogProjectionMaxSingleContainerDetachMs =
                        catalogProjectionMaxSingleContainerDetachMs,
                    CatalogProjectionMaxResetPanelThreadCpuMs =
                        catalogProjectionMaxResetPanelThreadCpuMs,
                    CatalogProjectionMaxResetPanelBudgetMs =
                        catalogProjectionMaxResetPanelBudgetMs,
                    CatalogProjectionDetachBudgetBasis =
                        catalogProjectionDetachBudgetBasis,
                    CatalogProjectionDetachWithinDiagnosticBudget =
                        catalogProjectionDetachWithinBudget,
                    CatalogProjectionDetachWithinHostedAcceptance =
                        catalogProjectionDetachWithinHostedAcceptance,
                    CatalogProjectionMaxDetachedContainersPerSlice =
                        catalogProjectionMaxDetachedContainersPerSlice,
                    CatalogProjectionInputBoundaryBeforePublicationExact =
                        catalogProjectionInputBoundaryBeforePublicationExact,
                    CatalogProjectionInputBoundaryAfterPublicationExact =
                        catalogProjectionInputBoundaryAfterPublicationExact,
                    CatalogProjectionMaxGeneratorRemoveMs =
                        catalogProjectionMaxGeneratorRemoveMs,
                    CatalogProjectionMaxForgetDeferredMeasureMs =
                        catalogProjectionMaxForgetDeferredMeasureMs,
                    CatalogProjectionMaxRemoveInternalChildRangeMs =
                        catalogProjectionMaxRemoveInternalChildRangeMs,
                    CatalogProjectionMaxRemoveInternalChildRangeThreadCpuMs =
                        catalogProjectionMaxRemoveInternalChildRangeThreadCpuMs,
                    CatalogProjectionMaxResetPanelTotalMs =
                        catalogProjectionMaxResetPanelTotalMs,
                    CatalogProjectionDominantResetSubstep =
                        catalogProjectionDominantResetSubstep,
                    DispatcherHeartbeatBudgetMs = CatalogInteractionDispatcherHeartbeatBudgetMs,
                    DispatcherHeartbeatProductTargetMet =
                        dispatcherDiagnostic.MaxProductGapMs
                            <= CatalogInteractionDispatcherHeartbeatBudgetMs,
                    DispatcherHeartbeatMeasurementToleranceMs =
                        CatalogInteractionDispatcherHeartbeatMeasurementToleranceMs,
                    DispatcherHeartbeatHostedPreemptionAbsoluteCeilingMs =
                        CatalogInteractionDispatcherHeartbeatHostedAbsoluteCeilingMs,
                    DispatcherHeartbeatHostedPreemptionPolicySelfTest =
                        dispatcherHeartbeatHostedPreemptionPolicySelfTest,
                    DispatcherHeartbeatHostedEvidence =
                        dispatcherHeartbeatHostedEvidence,
                    DispatcherHeartbeatHostedPreemptionAccepted =
                        dispatcherHeartbeatHostedPreemptionAccepted,
                    DispatcherHeartbeatWithinHostedAcceptance =
                        dispatcherHeartbeatWithinHostedAcceptance,
                    FavoriteEvictionBudgetMs = CatalogFavoriteEvictionBudgetMs,
                    CatalogProjectionDiscardedCount = window.CatalogProjectionDiscardedCountForSmoke,
                    PreparedCatalogLayoutAppliedCount = window.PreparedCatalogLayoutAppliedCountForSmoke,
                    PreparedCatalogLayoutRejectedCount = window.PreparedCatalogLayoutRejectedCountForSmoke,
                    CatalogLayoutMaxMeasureMs = window.CatalogLayoutMaxMeasureMsForSmoke,
                    CatalogLayoutMaxMeasureWallMs = window.CatalogLayoutMaxMeasureWallMsForSmoke,
                    CatalogLayoutMaxMeasureOperation = window.CatalogLayoutMaxMeasureOperationForSmoke,
                    CatalogLayoutMaxMeasureGeneration = window.CatalogLayoutMaxMeasureGenerationForSmoke,
                    CatalogLayoutMaxMeasureThreadCpuMs =
                        window.CatalogLayoutMaxMeasureThreadCpuMsForSmoke,
                    MixedLatestWins = mixedLatestWins,
                    FavoritePendingBroadenRaceExact = favoritePendingBroadenRaceExact,
                    FavoriteRapidReincludeRaceExact = favoriteRapidReincludeRaceExact,
                    FavoriteSortRaceExact = favoriteSortRaceExact,
                    FavoriteDuplicateEvictionRaceExact =
                        favoriteDuplicateEvictionRaceExact,
                    FavoriteDuplicateNotificationPendingAfterFirst =
                        duplicateNotificationPendingAfterFirst,
                    FavoriteDuplicateLatestProjectionCompletedAtFirstObservation =
                        duplicateLatestProjectionCompletedAtFirstObservation,
                    FavoriteDuplicateLatestGeneration =
                        duplicateLatestGeneration,
                    FavoriteDuplicateLastFlushGenerationAtFirstObservation =
                        duplicateLastFlushGenerationAtFirstObservation,
                    FavoriteDuplicateLastFlushGeneration =
                        window.LastDeferredFavoriteNotificationFlushGenerationForSmoke,
                    FavoriteFilteredFailureStatusExact =
                        favoriteFilteredFailureStatusExact,
                    FavoriteFilteredFailureStatus =
                        favoriteFilteredFailureStatus,
                    FavoriteFilteredRollbackProjectionExact =
                        favoriteFilteredRollbackProjectionExact,
                    FavoriteFilteredRollbackStateExact =
                        favoriteFilteredRollbackStateExact,
                    FavoriteFilteredFailureToastExact =
                        favoriteFilteredFailureToastExact,
                    FavoriteFilteredRetryExact =
                        favoriteFilteredRetryExact,
                    MixedViewportAnchorPreserved = mixedViewportAnchorPreserved,
                    MixedDiscardedCount = mixedDiscardedCount,
                    MixedStaleSearchDiscarded = staleMixedSearchResult.Discarded,
                    MixedStaleFilterDiscarded = staleMixedFilterResult.Discarded,
                    MixedLatestSortApplied = latestMixedSortApplied,
                    MixedFilteredCount = mixedFilteredCount,
                    HeartbeatGapSamples = heartbeatGapSamples,
                    HeartbeatDiagnosticSamples = heartbeatDiagnosticSamples,
                    LayoutSamples = layoutSamples,
                    WorkingSetBeforeBytes = workingSetBefore,
                    WorkingSetAfterBytes = workingSetAfter,
                    WorkingSetRegressionPercent = workingSetRegressionPercent,
                    NormalizedWorkingSetRegressionPercent = normalizedWorkingSetRegressionPercent,
                    ManagedMemoryBeforeBytes = managedMemoryBefore,
                    ManagedMemoryAfterBytes = managedMemoryAfter,
                    ManagedMemoryAfterFullGcBytes = managedMemoryAfterFullGc,
                    WorkingSetAfterFullGcBytes = workingSetAfterFullGc,
                    LiveManagedMemoryRegressionPercent = liveManagedMemoryRegressionPercent,
                    Gen2Collections = GC.CollectionCount(2) - gen2Before,
                    Message = ok
                        ? $"{count:N0}-item logical catalog search/filter/sort stayed exact, bounded, and responsive"
                        : "logical catalog interaction gate did not meet the expected result",
                };
            }
            catch (Exception ex)
            {
                heartbeat.Stop();
                result = new CatalogInteractionSmokeResult
                {
                    RequestedCount = count,
                    Message = ex.Message,
                };
            }
            finally
            {
                heartbeat.Stop();
                window.Close();
            }

            WriteCatalogInteractionSmokeResult(resultFullPath, result);
            try { if (File.Exists(progressPath)) File.Delete(progressPath); } catch { }
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static void WriteCatalogInteractionSmokeResult(
        string resultFullPath,
        CatalogInteractionSmokeResult result)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
        File.WriteAllText(
            resultFullPath,
            JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
    }

    private static Task<ExternalGalleryAutomationSmokeSnapshot>
        RunExternalGalleryAutomationLookupAsync(
            MainWindow window,
            string expectedName)
    {
        nint windowHandle = new WindowInteropHelper(window).Handle;
        var completion =
            new TaskCompletionSource<ExternalGalleryAutomationSmokeSnapshot>(
                TaskCreationOptions.RunContinuationsAsynchronously);
        var thread = new Thread(() =>
        {
            try
            {
                AutomationElement root = AutomationElement.FromHandle(windowHandle);
                AutomationElement? gallery = root.FindFirst(
                    TreeScope.Descendants,
                    new PropertyCondition(
                        AutomationElement.AutomationIdProperty,
                        "AibosGalleryGrid"));
                if (gallery is null
                    || !gallery.TryGetCurrentPattern(
                        ItemContainerPattern.Pattern,
                        out object itemContainerObject)
                    || itemContainerObject is not ItemContainerPattern itemContainer)
                {
                    completion.TrySetResult(new ExternalGalleryAutomationSmokeSnapshot
                    {
                        Message = "Gallery ItemContainer pattern was not available.",
                    });
                    return;
                }

                var lookupWatch = Stopwatch.StartNew();
                AutomationElement? item = itemContainer.FindItemByProperty(
                    null,
                    AutomationElement.NameProperty,
                    expectedName);
                lookupWatch.Stop();
                if (item is null)
                {
                    completion.TrySetResult(new ExternalGalleryAutomationSmokeSnapshot
                    {
                        LookupMs = lookupWatch.ElapsedMilliseconds,
                        Message = "External ItemContainer lookup returned no item.",
                    });
                    return;
                }

                bool virtualized = item.TryGetCurrentPattern(
                    VirtualizedItemPattern.Pattern,
                    out object virtualizedObject)
                    && virtualizedObject is VirtualizedItemPattern;
                bool selection = item.TryGetCurrentPattern(
                    SelectionItemPattern.Pattern,
                    out object selectionObject)
                    && selectionObject is SelectionItemPattern;
                bool realizeInvoked = false;
                if (virtualizedObject is VirtualizedItemPattern virtualizedPattern)
                {
                    virtualizedPattern.Realize();
                    realizeInvoked = true;
                }

                completion.TrySetResult(new ExternalGalleryAutomationSmokeSnapshot
                {
                    Found = true,
                    NameExact = string.Equals(
                        item.Current.Name,
                        expectedName,
                        StringComparison.Ordinal),
                    VirtualizedItemPatternAvailable = virtualized,
                    SelectionItemPatternAvailable = selection,
                    RealizeInvoked = realizeInvoked,
                    LookupMs = lookupWatch.ElapsedMilliseconds,
                    Message = "External AutomationElement ItemContainer lookup completed.",
                });
            }
            catch (Exception ex)
            {
                completion.TrySetResult(new ExternalGalleryAutomationSmokeSnapshot
                {
                    Message = ex.GetType().Name + ": " + ex.Message,
                });
            }
        })
        {
            IsBackground = true,
            Name = "Aibos catalog UI Automation smoke",
        };
        thread.SetApartmentState(ApartmentState.MTA);
        thread.Start();
        return completion.Task;
    }

    private void CaptureCatalogStressSmoke(string resultPath, string[] args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        int count = ArgInt(args, "--count", 20_000);
        int folderCount = ArgInt(args, "--folder-count", 1);
        int viewportChurnSeconds = ArgInt(args, "--viewport-churn-seconds", 0);
        if (count < 2 || folderCount < 1 || folderCount > count || viewportChurnSeconds < 0 || viewportChurnSeconds > 120)
        {
            WriteCatalogStressSmokeResult(resultFullPath, new CatalogStressSmokeResult
            {
                RequestedCount = count,
                RequestedFolderCount = folderCount,
                Message = "--count must be at least 2, --folder-count must be 1..count, and --viewport-churn-seconds must be 0..120",
            });
            Shutdown(1);
            return;
        }

        string tempRootPrefix = Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
        string smokeRoot = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "photoviewer-wpf-catalog-stress-" + Guid.NewGuid().ToString("N")));
        string smokeRootPrefix = smokeRoot.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
        if (!smokeRootPrefix.StartsWith(tempRootPrefix, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("catalog stress root escaped the temp directory");
        string seedPath = Path.Combine(smokeRoot, "seed.png");
        var folders = Enumerable.Range(0, folderCount)
            .Select(index => Path.Combine(smokeRoot, $"images-{index:D4}"))
            .ToList();
        string statePath = Path.Combine(smokeRoot, "state.json");
        string favoritesPath = Path.Combine(smokeRoot, "favorites.json");
        string seenPath = Path.Combine(smokeRoot, "seen.json");
        string recentPath = Path.Combine(smokeRoot, "recent.json");
        string jobsPath = Path.Combine(smokeRoot, "jobs.json");
        string metadataIndexDirectory = Path.Combine(smokeRoot, "metadata-index-v1");
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousRecentPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH");
        string? previousJobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH");
        string? previousMetadataIndexDirectory = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY");
        var fixtureWatch = Stopwatch.StartNew();
        Directory.CreateDirectory(smokeRoot);
        File.WriteAllText(Path.Combine(smokeRoot, "project.toml"), "# isolated catalog stress project root");
        Directory.CreateDirectory(Path.Combine(smokeRoot, "local-native"));
        foreach (string folder in folders)
            Directory.CreateDirectory(folder);
        WriteSmokePng(seedPath, 4, 3, Color.FromRgb(70, 130, 210));
        for (int index = 0; index < count; index++)
            File.Copy(seedPath, Path.Combine(folders[index % folders.Count], $"stress-{index:D6}.png"));
        fixtureWatch.Stop();

        Environment.CurrentDirectory = smokeRoot;
        string browserCacheSourcePath = Path.Combine(folders[0], "stress-000000.png");
        DateTime browserCacheModifiedUtc = DateTime.UtcNow.AddMinutes(5);
        browserCacheModifiedUtc = new DateTime(browserCacheModifiedUtc.Ticks - (browserCacheModifiedUtc.Ticks % TimeSpan.TicksPerMillisecond) + 4321, DateTimeKind.Utc);
        File.SetLastWriteTimeUtc(browserCacheSourcePath, browserCacheModifiedUtc);
        browserCacheModifiedUtc = File.GetLastWriteTimeUtc(browserCacheSourcePath);
        IReadOnlyList<string> browserCacheCandidatePaths = PhotoViewer.Wpf.MainWindow.BrowserThumbnailCachePathsForSmoke(browserCacheSourcePath, browserCacheModifiedUtc);
        Directory.CreateDirectory(Path.GetDirectoryName(browserCacheCandidatePaths[0])!);
        File.Copy(seedPath, browserCacheCandidatePaths[0], overwrite: true);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", favoritesPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", seenPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", recentPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", jobsPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY", metadataIndexDirectory);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var win = HiddenWindow();
        win.Show();
        win.SuppressStatePersistence();

        win.Dispatcher.InvokeAsync(async () =>
        {
            CatalogStressSmokeResult result;
            var process = Process.GetCurrentProcess();
            process.Refresh();
            long workingSetBefore = process.WorkingSet64;
            long managedBefore = GC.GetTotalMemory(forceFullCollection: false);
            int generation0Before = GC.CollectionCount(0);
            int generation1Before = GC.CollectionCount(1);
            int generation2Before = GC.CollectionCount(2);
            var loadWatch = Stopwatch.StartNew();
            var heartbeat = new DispatcherTimer(DispatcherPriority.Input) { Interval = TimeSpan.FromMilliseconds(15) };
            int heartbeatCount = 0;
            var heartbeatWatch = Stopwatch.StartNew();
            long lastHeartbeatMs = 0;
            long maxHeartbeatGapMs = 0;
            string heartbeatStage = "load";
            string lastHeartbeatStage = heartbeatStage;
            string lastHeartbeatLoadPhase = win.LoadPhaseForSmoke;
            var dispatcherGapSegments = new List<DispatcherGapSmokeSegment>();
            heartbeat.Tick += (_, _) =>
            {
                long nowMs = heartbeatWatch.ElapsedMilliseconds;
                long gapMs = nowMs - lastHeartbeatMs;
                string currentLoadPhase = win.LoadPhaseForSmoke;
                if (gapMs >= 100)
                {
                    dispatcherGapSegments.Add(new DispatcherGapSmokeSegment
                    {
                        StartMs = lastHeartbeatMs,
                        EndMs = nowMs,
                        DurationMs = gapMs,
                        StageBefore = lastHeartbeatStage,
                        StageAfter = heartbeatStage,
                        LoadPhaseBefore = lastHeartbeatLoadPhase,
                        LoadPhaseAfter = currentLoadPhase,
                    });
                }
                maxHeartbeatGapMs = Math.Max(maxHeartbeatGapMs, gapMs);
                lastHeartbeatMs = nowMs;
                lastHeartbeatStage = heartbeatStage;
                lastHeartbeatLoadPhase = currentLoadPhase;
                heartbeatCount++;
            };
            try
            {
                heartbeat.Start();
                await win.LoadFolderSetAsync(folders, commitRecent: false);
                loadWatch.Stop();
                heartbeatStage = "post-load-layout";
                var initialGridLayoutWatch = Stopwatch.StartNew();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                initialGridLayoutWatch.Stop();
                heartbeatStage = "source-count-before";
                int sourceCountBefore = await Task.Run(
                    () => folders.Sum(folder => Directory.EnumerateFiles(folder, "*.png", SearchOption.TopDirectoryOnly).Count()));
                int catalogCount = win.CatalogCountForSmoke;
                int filteredCount = win.FilteredCountForSmoke;
                int gridRealized = win.GridRealizedCountForSmoke;
                int gridMaximum = win.GridMaxRealizationCountForSmoke;
                int gridDeferred = win.GridDeferredCountForSmoke;
                int gridItemsSourceCount = win.GridItemsSourceCountForSmoke;
                bool gridUsesFullExtentVirtualization = win.GridUsesFullExtentVirtualizationForSmoke;
                double gridExtentHeight = win.GridExtentHeightForSmoke;
                double gridViewportHeight = win.GridViewportHeightForSmoke;
                int gridInitialFirstVisible = win.GridFirstVisibleIndexForSmoke;
                int gridInitialLastVisible = win.GridLastVisibleIndexForSmoke;
                var viewportChurn = new ViewportChurnSmokeResult
                {
                    RequestedSeconds = viewportChurnSeconds,
                    Ok = viewportChurnSeconds == 0,
                };
                if (viewportChurnSeconds > 0)
                {
                    heartbeatStage = "viewport-churn";
                    int gapStart = dispatcherGapSegments.Count;
                    process.Refresh();
                    long churnWorkingSetBefore = process.WorkingSet64;
                    var selectionLatencies = new List<long>();
                    var previewLatencies = new List<long>();
                    int selectionLosses = 0;
                    int stalePreviewCount = 0;
                    int thumbnailTimeouts = 0;
                    int iteration = 0;
                    var churnWatch = Stopwatch.StartNew();
                    while (churnWatch.Elapsed < TimeSpan.FromSeconds(viewportChurnSeconds))
                    {
                        int index = (int)(((long)iteration * 7_919) % count);
                        string fileName = $"stress-{index:D6}.png";
                        var selectionWatch = Stopwatch.StartNew();
                        bool selected = win.SelectFileNameForSmoke(fileName);
                        GridSelectionVisualSmokeSnapshot visual = await win.WaitForGridSelectionVisualForSmokeAsync(fileName);
                        selectionWatch.Stop();
                        selectionLatencies.Add(selectionWatch.ElapsedMilliseconds);
                        if (!selected || !visual.CanonicalSelected || !visual.ContainerRealized || !visual.ContainerSelected)
                            selectionLosses++;

                        var previewWatch = Stopwatch.StartNew();
                        PreviewDecodeSmokeSnapshot preview = await win.WaitForCurrentPreviewDecodeForSmokeAsync(fileName);
                        previewWatch.Stop();
                        previewLatencies.Add(previewWatch.ElapsedMilliseconds);
                        if (!preview.StableLatestSelection)
                            stalePreviewCount++;
                        if (!await win.WaitForThumbnailForSmokeAsync(fileName, timeoutMilliseconds: 750))
                            thumbnailTimeouts++;
                        iteration++;
                    }
                    churnWatch.Stop();
                    heartbeatStage = "viewport-churn-settle";
                    await Task.Delay(250);
                    process.Refresh();
                    long churnWorkingSetAfter = process.WorkingSet64;
                    int stallsOver250 = dispatcherGapSegments
                        .Skip(gapStart)
                        .Count(static gap => gap.DurationMs > 250);
                    viewportChurn = new ViewportChurnSmokeResult
                    {
                        RequestedSeconds = viewportChurnSeconds,
                        ElapsedMs = churnWatch.ElapsedMilliseconds,
                        Iterations = iteration,
                        SelectionLossCount = selectionLosses,
                        StalePreviewCount = stalePreviewCount,
                        ThumbnailTimeoutCount = thumbnailTimeouts,
                        SelectionP95Ms = SmokePercentile(selectionLatencies, 0.95),
                        CachedPreviewP95Ms = SmokePercentile(previewLatencies, 0.95),
                        UiStallsOver250Ms = stallsOver250,
                        WorkingSetBeforeBytes = churnWorkingSetBefore,
                        WorkingSetAfterBytes = churnWorkingSetAfter,
                        WorkingSetRegressionPercent = churnWorkingSetBefore <= 0
                            ? 0
                            : ((churnWorkingSetAfter / (double)churnWorkingSetBefore) - 1) * 100,
                        ResidentThumbnailCount = win.ResidentThumbnailCountForSmoke,
                        MaxResidentThumbnailCount = win.MaxResidentThumbnailCountForSmoke,
                        ResidentThumbnailLimit = win.ResidentThumbnailLimitForSmoke,
                        ResidentThumbnailBytes = win.ResidentThumbnailBytesForSmoke,
                        MaxResidentThumbnailBytes = win.MaxResidentThumbnailBytesForSmoke,
                        ResidentThumbnailBudgetBytes = win.ResidentThumbnailBudgetBytesForSmoke,
                        MaxEffectiveResidentThumbnailBudgetBytes = win.MaxEffectiveResidentThumbnailBudgetBytesForSmoke,
                        MaxProtectedResidentThumbnailBytes = win.MaxProtectedResidentThumbnailBytesForSmoke,
                        VisibleThumbnailEvictionCount = win.VisibleThumbnailEvictionCountForSmoke,
                        MaxActiveThumbnailWorkers = win.MaxActiveThumbnailDecodeWorkersForSmoke,
                        ThumbnailWorkerLimit = win.ThumbnailDecodeWorkerLimitForSmoke,
                        ViewportScheduleCount = win.ThumbnailViewportScheduleCountForSmoke,
                        ViewportCancelCount = win.ThumbnailViewportCancelCountForSmoke,
                        DuplicateScheduleSuppressedCount = win.ThumbnailViewportDuplicateSuppressedCountForSmoke,
                    };
                    viewportChurn.Ok = viewportChurn.Iterations >= 10
                        && viewportChurn.SelectionLossCount == 0
                        && viewportChurn.StalePreviewCount == 0
                        && viewportChurn.ThumbnailTimeoutCount == 0
                        && viewportChurn.SelectionP95Ms <= 100
                        && viewportChurn.CachedPreviewP95Ms <= 150
                        && viewportChurn.UiStallsOver250Ms == 0
                        && viewportChurn.WorkingSetRegressionPercent <= 10
                        && viewportChurn.ResidentThumbnailBytes <= viewportChurn.MaxEffectiveResidentThumbnailBudgetBytes
                        && viewportChurn.MaxResidentThumbnailBytes <= viewportChurn.MaxEffectiveResidentThumbnailBudgetBytes
                        && viewportChurn.VisibleThumbnailEvictionCount == 0
                        && viewportChurn.MaxActiveThumbnailWorkers <= viewportChurn.ThumbnailWorkerLimit;
                }
                heartbeatStage = "list-switch";
                var listSwitchWatch = Stopwatch.StartNew();
                bool listMode = win.SetListModeForSmoke();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                listSwitchWatch.Stop();
                int listRealized = win.ListRealizedContainerCountForSmoke;
                bool listBounded = win.ListUsesRecyclingVirtualizationForSmoke && listRealized <= Math.Min(count, 512);
                var listThumbnailProbeWatch = Stopwatch.StartNew();
                int listThumbnailProbeIndex = count - 1;
                bool listThumbnailProbeRequested = win.ScrollListThumbnailProbeForSmoke(listThumbnailProbeIndex);
                bool listViewportThumbnailLoaded = listThumbnailProbeRequested
                    && await win.WaitForListThumbnailProbeForSmokeAsync(listThumbnailProbeIndex);
                listThumbnailProbeWatch.Stop();
                bool gridModeAfterListProbe = win.SetGridModeForSmoke();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);

                string tailName = $"stress-{count - 1:D6}.png";
                heartbeatStage = "tail-select";
                var tailSelectWatch = Stopwatch.StartNew();
                bool selectedTail = win.SelectFileNameForSmoke(tailName);
                tailSelectWatch.Stop();
                var tailGridVisualWatch = Stopwatch.StartNew();
                GridSelectionVisualSmokeSnapshot tailGridVisual = await win.WaitForGridSelectionVisualForSmokeAsync(tailName);
                int tailGridFirstVisible = win.GridFirstVisibleIndexForSmoke;
                int tailGridLastVisible = win.GridLastVisibleIndexForSmoke;
                tailGridVisualWatch.Stop();
                var tailModeRoundTripWatch = Stopwatch.StartNew();
                bool tailListModeRoundTrip = win.SetListModeForSmoke();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                ListSelectionVisualSmokeSnapshot tailListVisual = await win.WaitForListSelectionVisualForSmokeAsync(tailName);
                bool tailGridModeRoundTrip = win.SetGridModeForSmoke();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                GridSelectionVisualSmokeSnapshot tailGridRoundTripVisual = await win.WaitForGridSelectionVisualForSmokeAsync(tailName);
                tailModeRoundTripWatch.Stop();
                long tailCardsSelectionSyncMs = win.LastCardsSelectionSyncMsForSmoke;
                long tailRowsSelectionSyncMs = win.LastRowsSelectionSyncMsForSmoke;
                long tailEnsureGridSelectionMs = win.LastEnsureGridSelectionMsForSmoke;
                long tailCardsScrollSelectionMs = win.LastCardsScrollSelectionMsForSmoke;
                long tailRowsScrollSelectionMs = win.LastRowsScrollSelectionMsForSmoke;
                long tailPreviewSelectionMs = win.LastPreviewSelectionMsForSmoke;
                long tailSeenSelectionMs = win.LastSeenSelectionMsForSmoke;
                heartbeatStage = "tail-modal";
                var modalTailWatch = Stopwatch.StartNew();
                bool modalTail = selectedTail && win.OpenModalForSmoke() && win.ModalVisibleForSmoke;
                win.CloseModalForSmoke();
                modalTailWatch.Stop();

                heartbeatStage = "flat-zoom-roundtrip";
                bool flatZoomMiddle = await win.ScrollGridToMiddleForSmokeAsync();
                string? flatZoomAnchor = win.CaptureGridViewportAnchorForSmoke();
                double flatZoomInitialWidth = win.CardWidthForSmoke;
                var flatZoomInWatch = Stopwatch.StartNew();
                bool flatZoomIn = win.ZoomInForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                flatZoomInWatch.Stop();
                double flatZoomInDrift = win.LastGridZoomAnchorDriftForSmoke;
                bool flatZoomInAnchorKept = !string.IsNullOrWhiteSpace(flatZoomAnchor)
                    && string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), flatZoomAnchor, StringComparison.OrdinalIgnoreCase);
                var flatZoomOutWatch = Stopwatch.StartNew();
                bool flatZoomOut = win.ZoomOutForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                flatZoomOutWatch.Stop();
                double flatZoomOutDrift = win.LastGridZoomAnchorDriftForSmoke;
                bool flatZoomOutAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), flatZoomAnchor, StringComparison.OrdinalIgnoreCase);
                bool flatZoomRoundTrip = flatZoomMiddle && flatZoomIn && flatZoomOut
                    && Math.Abs(win.CardWidthForSmoke - flatZoomInitialWidth) < 0.01
                    && flatZoomInAnchorKept
                    && flatZoomOutAnchorKept
                    && flatZoomInDrift <= 8
                    && flatZoomOutDrift <= 8;

                heartbeatStage = "flat-endpoints-sidebar-anchor";
                string? endpointAnchor = win.CaptureGridViewportAnchorForSmoke();
                var endpointSidebarWatch = Stopwatch.StartNew();
                heartbeatStage = "endpoint-minimum-set";
                var endpointMinimumSetWatch = Stopwatch.StartNew();
                bool endpointMinimumChanged = win.SetGridZoomForSmoke(20);
                endpointMinimumSetWatch.Stop();
                heartbeatStage = "endpoint-minimum-settle";
                var endpointMinimumSettleWatch = Stopwatch.StartNew();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                endpointMinimumSettleWatch.Stop();
                double endpointMinimumWidth = win.CardWidthForSmoke;
                int endpointMinimumRealized = win.GridRealizedCountForSmoke;
                bool endpointMinimumAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), endpointAnchor, StringComparison.OrdinalIgnoreCase);
                double endpointMinimumDrift = win.LastGridZoomAnchorDriftForSmoke;
                heartbeatStage = "endpoint-maximum-set";
                bool endpointMaximumChanged = win.SetGridZoomForSmoke(600);
                heartbeatStage = "endpoint-maximum-settle";
                await win.WaitForGridZoomAnchorForSmokeAsync();
                double endpointMaximumWidth = win.CardWidthForSmoke;
                bool endpointMaximumAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), endpointAnchor, StringComparison.OrdinalIgnoreCase);
                double endpointMaximumDrift = win.LastGridZoomAnchorDriftForSmoke;
                int endpointMaximumColumns = win.GridColumnCountForSmoke;
                int endpointMaximumRealized = win.GridRealizedCountForSmoke;
                bool endpointMaximumForcedSingleColumn = win.GridForcesSingleColumnForSmoke;
                heartbeatStage = "endpoint-restore-set";
                bool endpointRestored = win.SetGridZoomForSmoke(flatZoomInitialWidth);
                heartbeatStage = "endpoint-restore-settle";
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool endpointRestoreAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), endpointAnchor, StringComparison.OrdinalIgnoreCase);
                double endpointRestoreDrift = win.LastGridZoomAnchorDriftForSmoke;
                heartbeatStage = "endpoint-sidebar-collapse";
                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool endpointSidebarCollapseAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), endpointAnchor, StringComparison.OrdinalIgnoreCase);
                double endpointSidebarCollapseDrift = win.LastGridZoomAnchorDriftForSmoke;
                heartbeatStage = "endpoint-sidebar-expand";
                win.ToggleSidebarForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                bool endpointSidebarExpandAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), endpointAnchor, StringComparison.OrdinalIgnoreCase);
                double endpointSidebarExpandDrift = win.LastGridZoomAnchorDriftForSmoke;
                endpointSidebarWatch.Stop();
                bool endpointSidebarRoundTrip = !string.IsNullOrWhiteSpace(endpointAnchor)
                    && endpointMinimumChanged
                    && Math.Abs(endpointMinimumWidth - 20) < 0.01
                    && endpointMinimumAnchorKept
                    && endpointMinimumDrift <= 8
                    && endpointMaximumChanged
                    && Math.Abs(endpointMaximumWidth - 600) < 0.01
                    && endpointMaximumAnchorKept
                    && endpointMaximumDrift <= 8
                    && endpointMaximumColumns == 1
                    && endpointMaximumForcedSingleColumn
                    && endpointMaximumRealized is > 0
                    && endpointMaximumRealized <= gridMaximum
                    && endpointRestored
                    && endpointRestoreAnchorKept
                    && endpointRestoreDrift <= 8
                    && endpointSidebarCollapseAnchorKept
                    && endpointSidebarCollapseDrift <= 8
                    && endpointSidebarExpandAnchorKept
                    && endpointSidebarExpandDrift <= 8;

                heartbeatStage = "created-group-tail";
                var createdTailWatch = Stopwatch.StartNew();
                var createdSortCallWatch = Stopwatch.StartNew();
                bool changedCreatedSort = win.SetSortByForSmoke("created-newest");
                createdSortCallWatch.Stop();
                var createdLayoutWatch = Stopwatch.StartNew();
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                await win.Dispatcher.InvokeAsync(win.UpdateLayout, DispatcherPriority.Render);
                createdLayoutWatch.Stop();
                bool createdGroupingActive = win.DateGroupingActiveForSmoke;
                int createdItemsSourceCount = win.GridItemsSourceCountForSmoke;
                bool createdUsesFullExtentVirtualization = win.GridUsesFullExtentVirtualizationForSmoke;
                int createdRealized = win.GridRealizedCountForSmoke;
                double createdExtentHeight = win.GridExtentHeightForSmoke;
                double createdViewportHeight = win.GridViewportHeightForSmoke;
                var createdTailSelectWatch = Stopwatch.StartNew();
                bool createdTailSelected = win.SelectIndexForSmoke(count - 1);
                createdTailSelectWatch.Stop();
                string? createdTailName = win.SelectedFileNameForSmoke;
                var createdTailVisualWatch = Stopwatch.StartNew();
                GridSelectionVisualSmokeSnapshot createdTailVisual = string.IsNullOrWhiteSpace(createdTailName)
                    ? new GridSelectionVisualSmokeSnapshot(null, false, false, false, false, false, false)
                    : await win.WaitForGridSelectionVisualForSmokeAsync(createdTailName);
                createdTailVisualWatch.Stop();
                int createdTailFirstVisible = win.GridFirstVisibleIndexForSmoke;
                int createdTailLastVisible = win.GridLastVisibleIndexForSmoke;
                createdTailWatch.Stop();

                heartbeatStage = "created-zoom-roundtrip";
                bool createdZoomMiddle = await win.ScrollGridToMiddleForSmokeAsync();
                string? createdZoomAnchor = win.CaptureGridViewportAnchorForSmoke();
                double createdZoomInitialWidth = win.CardWidthForSmoke;
                var createdZoomInWatch = Stopwatch.StartNew();
                bool createdZoomIn = win.ZoomInForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                createdZoomInWatch.Stop();
                double createdZoomInDrift = win.LastGridZoomAnchorDriftForSmoke;
                bool createdZoomInAnchorKept = !string.IsNullOrWhiteSpace(createdZoomAnchor)
                    && string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), createdZoomAnchor, StringComparison.OrdinalIgnoreCase);
                var createdZoomOutWatch = Stopwatch.StartNew();
                bool createdZoomOut = win.ZoomOutForSmoke();
                await win.WaitForGridZoomAnchorForSmokeAsync();
                createdZoomOutWatch.Stop();
                double createdZoomOutDrift = win.LastGridZoomAnchorDriftForSmoke;
                bool createdZoomOutAnchorKept = string.Equals(Path.GetFileName(win.LastGridZoomAnchorPathForSmoke), createdZoomAnchor, StringComparison.OrdinalIgnoreCase);
                bool createdZoomRoundTrip = createdZoomMiddle && createdZoomIn && createdZoomOut
                    && Math.Abs(win.CardWidthForSmoke - createdZoomInitialWidth) < 0.01
                    && createdZoomInAnchorKept
                    && createdZoomOutAnchorKept
                    && createdZoomInDrift <= 8
                    && createdZoomOutDrift <= 8;

                heartbeatStage = "rapid-search";
                var inputWatch = Stopwatch.StartNew();
                var searchWatch = Stopwatch.StartNew();
                string[] rapidQueries = ["s", "st", "str", "stress", "stress-0", "stress-01", "stress-019", "stress-0199", $"stress-{count - 1:D6}"];
                var completions = new List<Task<MainWindow.SearchFilterCompletion>>();
                foreach (string query in rapidQueries)
                    completions.Add(win.SetSearchInputForSmokeAsync(query));
                inputWatch.Stop();
                Task<MainWindow.SearchFilterCompletion> finalTask = completions[^1];
                Task completed = await Task.WhenAny(finalTask, Task.Delay(TimeSpan.FromSeconds(12)));
                MainWindow.SearchFilterCompletion finalCompletion = completed == finalTask
                    ? await finalTask
                    : new MainWindow.SearchFilterCompletion(false, false, "timed out waiting for the final stress search");
                MainWindow.SearchFilterCompletion[] earlierCompletions = await Task.WhenAll(completions.Take(completions.Count - 1));
                await Task.Delay(120);

                List<string> finalMatches = win.FilteredFileNamesForSmoke(4);
                bool finalSearchExact = finalCompletion.Applied
                    && string.Equals(win.SearchQueryForSmoke, $"stress-{count - 1:D6}", StringComparison.Ordinal)
                    && finalMatches.SequenceEqual([tailName], StringComparer.OrdinalIgnoreCase)
                    && string.Equals(win.SelectedFileNameForSmoke, tailName, StringComparison.OrdinalIgnoreCase);
                bool staleCancelled = earlierCompletions.All(static completion => completion.Discarded);
                bool heartbeatAdvanced = heartbeatCount >= 4;
                heartbeatStage = "source-count-after-cold";
                int sourceCountAfterCold = await Task.Run(
                    () => folders.Sum(folder => Directory.EnumerateFiles(folder, "*.png", SearchOption.TopDirectoryOnly).Count()));

                heartbeatStage = "warm-index-probe";
                string? coldIndexPath = win.MetadataIndexPathForSmoke;
                if (string.IsNullOrWhiteSpace(coldIndexPath) || !File.Exists(coldIndexPath))
                    throw new InvalidOperationException("cold catalog load did not publish a metadata index");
                string indexSha256BeforeWarm = FileSha256ForSmoke(coldIndexPath);
                long indexLastWriteUtcTicksBeforeWarm = File.GetLastWriteTimeUtc(coldIndexPath).Ticks;

                var warm = new WarmCatalogStressSmokeResult();
                var warmWin = HiddenWindow();
                var warmHeartbeat = new DispatcherTimer(DispatcherPriority.Input) { Interval = TimeSpan.FromMilliseconds(15) };
                var warmHeartbeatWatch = Stopwatch.StartNew();
                int warmHeartbeatCount = 0;
                long warmLastHeartbeatMs = 0;
                long warmMaxHeartbeatGapMs = 0;
                warmHeartbeat.Tick += (_, _) =>
                {
                    long nowMs = warmHeartbeatWatch.ElapsedMilliseconds;
                    warmMaxHeartbeatGapMs = Math.Max(warmMaxHeartbeatGapMs, nowMs - warmLastHeartbeatMs);
                    warmLastHeartbeatMs = nowMs;
                    warmHeartbeatCount++;
                };
                try
                {
                    warmWin.Show();
                    warmWin.SuppressStatePersistence();
                    warmHeartbeat.Start();
                    heartbeatStage = "warm-load";
                    var warmLoadWatch = Stopwatch.StartNew();
                    await warmWin.LoadFolderSetAsync(folders, commitRecent: false);
                    warmLoadWatch.Stop();

                    heartbeatStage = "warm-grid-layout";
                    await warmWin.Dispatcher.InvokeAsync(warmWin.UpdateLayout, DispatcherPriority.Render);
                    int warmCatalogCount = warmWin.CatalogCountForSmoke;
                    int warmFilteredCount = warmWin.FilteredCountForSmoke;
                    int warmGridRealized = warmWin.GridRealizedCountForSmoke;
                    int warmGridMaximum = warmWin.GridMaxRealizationCountForSmoke;
                    int warmGridDeferred = warmWin.GridDeferredCountForSmoke;
                    int warmGridItemsSourceCount = warmWin.GridItemsSourceCountForSmoke;
                    bool warmGridUsesFullExtentVirtualization = warmWin.GridUsesFullExtentVirtualizationForSmoke;
                    double warmGridExtentHeight = warmWin.GridExtentHeightForSmoke;
                    double warmGridViewportHeight = warmWin.GridViewportHeightForSmoke;
                    int warmGridInitialFirstVisible = warmWin.GridFirstVisibleIndexForSmoke;

                    heartbeatStage = "warm-list-switch";
                    bool warmListMode = warmWin.SetListModeForSmoke();
                    await warmWin.Dispatcher.InvokeAsync(warmWin.UpdateLayout, DispatcherPriority.Render);
                    int warmListRealized = warmWin.ListRealizedContainerCountForSmoke;
                    bool warmListUsesRecyclingVirtualization = warmWin.ListUsesRecyclingVirtualizationForSmoke;
                    bool warmListBounded = warmListMode
                        && warmListUsesRecyclingVirtualization
                        && warmListRealized is > 0
                        && warmListRealized <= Math.Min(count, 512);
                    bool warmGridMode = warmWin.SetGridModeForSmoke();
                    await warmWin.Dispatcher.InvokeAsync(warmWin.UpdateLayout, DispatcherPriority.Render);

                    heartbeatStage = "warm-tail-select";
                    bool warmSelectedTail = warmWin.SelectFileNameForSmoke(tailName);
                    GridSelectionVisualSmokeSnapshot warmTailVisual = await warmWin.WaitForGridSelectionVisualForSmokeAsync(tailName);
                    int warmTailFirstVisible = warmWin.GridFirstVisibleIndexForSmoke;
                    int warmTailLastVisible = warmWin.GridLastVisibleIndexForSmoke;

                    heartbeatStage = "warm-grid-zoom";
                    bool warmZoomMiddle = await warmWin.ScrollGridToMiddleForSmokeAsync();
                    string? warmZoomAnchor = warmWin.CaptureGridViewportAnchorForSmoke();
                    double warmZoomInitialWidth = warmWin.CardWidthForSmoke;
                    bool warmZoomIn = warmWin.ZoomInForSmoke();
                    await warmWin.WaitForGridZoomAnchorForSmokeAsync();
                    double warmZoomInDrift = warmWin.LastGridZoomAnchorDriftForSmoke;
                    bool warmZoomInAnchorKept = !string.IsNullOrWhiteSpace(warmZoomAnchor)
                        && string.Equals(Path.GetFileName(warmWin.LastGridZoomAnchorPathForSmoke), warmZoomAnchor, StringComparison.OrdinalIgnoreCase);
                    bool warmZoomOut = warmWin.ZoomOutForSmoke();
                    await warmWin.WaitForGridZoomAnchorForSmokeAsync();
                    double warmZoomOutDrift = warmWin.LastGridZoomAnchorDriftForSmoke;
                    bool warmZoomOutAnchorKept = string.Equals(Path.GetFileName(warmWin.LastGridZoomAnchorPathForSmoke), warmZoomAnchor, StringComparison.OrdinalIgnoreCase);
                    bool warmZoomRoundTrip = warmZoomMiddle
                        && warmZoomIn
                        && warmZoomOut
                        && Math.Abs(warmWin.CardWidthForSmoke - warmZoomInitialWidth) < 0.01
                        && warmZoomInAnchorKept
                        && warmZoomOutAnchorKept
                        && warmZoomInDrift <= 8
                        && warmZoomOutDrift <= 8;

                    heartbeatStage = "warm-heartbeat-settle";
                    await Task.Delay(90);
                    warmHeartbeat.Stop();
                    long warmHeartbeatEndMs = warmHeartbeatWatch.ElapsedMilliseconds;
                    warmMaxHeartbeatGapMs = Math.Max(warmMaxHeartbeatGapMs, warmHeartbeatEndMs - warmLastHeartbeatMs);

                    LoadMetrics? warmLoadMetrics = warmWin.LastLoadMetrics;
                    string? warmIndexPath = warmWin.MetadataIndexPathForSmoke;
                    string indexSha256AfterWarm = FileSha256ForSmoke(coldIndexPath);
                    long indexLastWriteUtcTicksAfterWarm = File.GetLastWriteTimeUtc(coldIndexPath).Ticks;
                    int warmSourceCountAfter = await Task.Run(
                        () => folders.Sum(folder => Directory.EnumerateFiles(folder, "*.png", SearchOption.TopDirectoryOnly).Count()));

                    warm = new WarmCatalogStressSmokeResult
                    {
                        LoadedFolderCount = warmWin.CurrentFolderSetForSmoke.Count,
                        CatalogCount = warmCatalogCount,
                        FilteredCount = warmFilteredCount,
                        SourceCountAfter = warmSourceCountAfter,
                        LoadElapsedMs = warmLoadWatch.ElapsedMilliseconds,
                        LoadMetricsTotalElapsedMs = warmLoadMetrics?.TotalMs,
                        ScanElapsedMs = warmLoadMetrics?.ScanMs,
                        MaterializeElapsedMs = warmLoadMetrics?.MaterializeMs,
                        CatalogPreparationParallelized = warmLoadMetrics?.CatalogPreparationParallelized ?? false,
                        CatalogPreparationWorkers = warmLoadMetrics?.CatalogPreparationWorkers ?? 0,
                        CatalogReadyElapsedMs = warmLoadMetrics?.CatalogReadyMs,
                        FirstUsableViewportElapsedMs = warmLoadMetrics?.FirstUsableViewportMs,
                        MetadataElapsedMs = warmLoadMetrics?.MetadataMs,
                        MetadataIndexReadMs = warmLoadMetrics?.MetadataIndexReadMs,
                        MetadataIndexWriteMs = warmLoadMetrics?.MetadataIndexWriteMs,
                        MetadataIndexLoadState = warmLoadMetrics?.MetadataIndexLoadState ?? "",
                        MetadataCacheHits = warmLoadMetrics?.MetadataCacheHits ?? -1,
                        MetadataCacheMisses = warmLoadMetrics?.MetadataCacheMisses ?? -1,
                        MetadataIndexSaveSucceeded = warmLoadMetrics?.MetadataIndexSaveSucceeded ?? false,
                        MetadataIndexWritten = warmLoadMetrics?.MetadataIndexWritten ?? true,
                        MetadataIndexSaveError = warmLoadMetrics?.MetadataIndexSaveError,
                        ColdIndexPath = coldIndexPath,
                        WarmIndexPath = warmIndexPath,
                        IndexPathUnchanged = string.Equals(coldIndexPath, warmIndexPath, StringComparison.OrdinalIgnoreCase),
                        IndexSha256Before = indexSha256BeforeWarm,
                        IndexSha256After = indexSha256AfterWarm,
                        IndexSha256Unchanged = string.Equals(indexSha256BeforeWarm, indexSha256AfterWarm, StringComparison.Ordinal),
                        IndexLastWriteUtcTicksBefore = indexLastWriteUtcTicksBeforeWarm,
                        IndexLastWriteUtcTicksAfter = indexLastWriteUtcTicksAfterWarm,
                        IndexLastWriteUtcUnchanged = indexLastWriteUtcTicksBeforeWarm == indexLastWriteUtcTicksAfterWarm,
                        GridRealized = warmGridRealized,
                        GridMaximum = warmGridMaximum,
                        GridDeferred = warmGridDeferred,
                        GridItemsSourceCount = warmGridItemsSourceCount,
                        GridUsesFullExtentVirtualization = warmGridUsesFullExtentVirtualization,
                        GridExtentHeight = warmGridExtentHeight,
                        GridViewportHeight = warmGridViewportHeight,
                        GridInitialFirstVisible = warmGridInitialFirstVisible,
                        ListMode = warmListMode,
