                    VideoStyleReloaded = videoStyleReloaded,
                    VideoStyleDeleted = videoStyleDeleted,
                    ReloadFilteredCount = reloadFilteredCount,
                    ReloadPhotorealVisible = reloadPhotorealVisible,
                    ReloadVideoFilteredCount = reloadVideoFilteredCount,
                    ReloadVideoVisible = reloadVideoVisible,
                    ReloadVideoSettings = reloadVideoSettings,
                    OutputRootSettingsSurface = outputRootSettingsSurface,
                    OutputRootChanged = outputRootChanged,
                    OutputRootRestored = outputRootRestored,
                    EnhancementStateUnchanged = enhancementStateUnchanged,
                    ReadOk = win.EnhancementReadOkForSmoke,
                    ReadError = win.EnhancementReadErrorForSmoke,
                };
            }
            catch (Exception ex)
            {
                win.Close();
                result = new EnhancedFilterSmokeResult { Ok = false, Message = ex.Message, Folder = fullFolder, ProjectRoot = smokeRoot, JobsPath = jobsPath };
            }
            finally
            {
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", previousJobsPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_OUTPUT_ROOT", previousOutputRoot);
                Environment.SetEnvironmentVariable("PVU_ENHANCE_OUTPUT_ROOT", previousSharedOutputRoot);
            }

            WriteEnhancedFilterSmokeResult(resultFullPath, result);
            try
            {
                if (Directory.Exists(smokeRoot))
                    Directory.Delete(smokeRoot, recursive: true);
            }
            catch
            {
            }
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureModalEnhancedSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteModalEnhancedSmokeResult(resultPath, new ModalEnhancedSmokeResult { Ok = false, Message = "missing required --folder", Folder = folder });
            Shutdown(1);
            return;
        }

        string fullFolder = Path.GetFullPath(folder);
        string[] fixtureNames = GetSmokeImageFileNames(fullFolder);
        if (fixtureNames.Length < 3)
        {
            WriteModalEnhancedSmokeResult(resultPath, new ModalEnhancedSmokeResult { Ok = false, Message = "modal enhanced smoke requires at least 3 fixture images", Folder = fullFolder });
            Shutdown(1);
            return;
        }

        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string previousCurrentDirectory = Environment.CurrentDirectory;
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousJobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH");

        PrepareSharedSeenSmokeEnvironment(smokeRoot);
        bool sqliteJobs = args.Contains("--sqlite-jobs", StringComparer.Ordinal);
        string jobsPath = Path.Combine(
            smokeRoot,
            ".cache",
            "enhance",
            sqliteJobs ? "jobs.sqlite3" : "jobs.json");
        string jobsSeedPath = sqliteJobs
            ? Path.Combine(Path.GetDirectoryName(jobsPath)!, "jobs.seed.json")
            : jobsPath;
        string outputRoot = Path.Combine(Path.GetDirectoryName(jobsPath)!, "outputs");
        Directory.CreateDirectory(outputRoot);

        string validSource = Path.Combine(fullFolder, fixtureNames[0]);
        string staleSource = Path.Combine(fullFolder, fixtureNames[1]);
        string failedSource = Path.Combine(fullFolder, fixtureNames[2]);
        string validOutput = Path.Combine(outputRoot, "enhanced-" + Path.GetFileName(validSource));
        string missingOutput = Path.Combine(outputRoot, "missing-output.png");
        string missingSource = Path.Combine(smokeRoot, "missing-source.png");
        File.Copy(validSource, validOutput, overwrite: true);
        WriteEnhancedJobsFixture(jobsSeedPath, validSource, validOutput, staleSource, missingOutput, failedSource, missingSource);
        if (sqliteJobs)
        {
            WriteEnhancementJobsSqliteFixture(jobsPath, jobsSeedPath);
            File.Delete(jobsSeedPath);
        }
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", jobsPath);
        byte[] beforeJobsBytes = File.ReadAllBytes(jobsPath);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        var win = HiddenWindow();
        win.Show();

        win.Dispatcher.InvokeAsync(async () =>
        {
            ModalEnhancedSmokeResult result;
            try
            {
                bool jobsWorkspaceReadOk = true;
                int jobsWorkspaceJobCount = 0;
                bool jobsDetailsLazyLoaded = true;
                bool jobsFullPayloadPreserved = true;
                bool largeJobsWorkspaceReadOk = true;
                int largeJobsWorkspaceJobCount = 0;
                bool largeJobsDetailsLazyLoaded = true;
                bool largeJobsOversizedDetailRejected = true;
                bool largeJobsStateUnchanged = true;
                long largeJobsFullPayloadBytes = 0;
                if (sqliteJobs)
                {
                    (jobsWorkspaceReadOk, jobsWorkspaceJobCount,
                        jobsDetailsLazyLoaded, jobsFullPayloadPreserved) =
                        await win.ReadEnhancementJobsWorkspaceSqliteForSmokeAsync(
                            jobsPath);
                    string largeJobsPath = Path.Combine(
                        Path.GetDirectoryName(jobsPath)!,
                        "jobs-over-32mib.sqlite3");
                    const string largeTargetId = "large-job-000";
                    const string largeDetailMarker = "large lazy detail marker";
                    const string oversizedDetailTargetId = "large-job-039";
                    largeJobsFullPayloadBytes = WriteLargeEnhancementJobsSqliteFixture(
                        largeJobsPath,
                        largeTargetId,
                        largeDetailMarker);
                    byte[] largeBefore = File.ReadAllBytes(largeJobsPath);
                    (largeJobsWorkspaceReadOk, largeJobsWorkspaceJobCount,
                        largeJobsDetailsLazyLoaded,
                        largeJobsOversizedDetailRejected) =
                        await win.ReadLargeEnhancementJobsWorkspaceSqliteForSmokeAsync(
                            largeJobsPath,
                            largeTargetId,
                            largeDetailMarker,
                            oversizedDetailTargetId);
                    byte[] largeAfter = File.ReadAllBytes(largeJobsPath);
                    largeJobsStateUnchanged = largeBefore.AsSpan().SequenceEqual(
                        largeAfter);
                }
                await win.LoadFolderAsync(fullFolder);
                bool selectedValid = win.SelectFileNameForSmoke(Path.GetFileName(validSource));
                win.ShowModalForShot();
                bool validToggleAvailable = win.ModalEnhancedToggleAvailableForSmoke;
                string? originalDisplayPath = win.ModalDisplayPathForSmoke;
                bool toggledEnhanced = win.ToggleModalEnhancedForSmoke();
                bool showingEnhanced = win.ModalShowingEnhancedForSmoke;
                string? enhancedDisplayPath = win.ModalDisplayPathForSmoke;
                bool toggledOriginal = win.ToggleModalEnhancedForSmoke();
                bool showingOriginal = !win.ModalShowingEnhancedForSmoke;
                string? restoredOriginalPath = win.ModalDisplayPathForSmoke;

                bool selectedStale = win.SelectFileNameForSmoke(Path.GetFileName(staleSource));
                win.ShowModalForShot();
                bool staleToggleAvailable = win.ModalEnhancedToggleAvailableForSmoke;
                bool staleToggleAttempt = win.ToggleModalEnhancedForSmoke();
                string? staleDisplayPath = win.ModalDisplayPathForSmoke;

                bool selectedAgain = win.SelectFileNameForSmoke(Path.GetFileName(validSource));
                win.ShowModalForShot();
                bool toggledBeforeNavigation = win.ToggleModalEnhancedForSmoke();
                string? validPathBeforeNavigation = win.ModalDisplayPathForSmoke;
                bool movedNext = win.NavigateModalForSmoke(1);
                if (!movedNext)
                    movedNext = win.NavigateModalForSmoke(-1);
                string? nextPath = win.SelectedPathForSmoke;
                bool navigationResetToOriginal = !win.ModalShowingEnhancedForSmoke
                    && string.Equals(win.ModalDisplayPathForSmoke, nextPath, StringComparison.OrdinalIgnoreCase);
                win.Close();

                byte[] afterJobsBytes = File.ReadAllBytes(jobsPath);
                bool enhancementStateUnchanged = beforeJobsBytes.AsSpan().SequenceEqual(afterJobsBytes);
                bool malformedSqliteCasesRejected = true;
                int malformedSqliteCaseCount = 0;
                if (sqliteJobs)
                {
                    malformedSqliteCasesRejected =
                        VerifyMalformedEnhancementSqliteFixtures(
                            smokeRoot,
                            out malformedSqliteCaseCount);
                }
                bool ok = win.EnhancementReadOkForSmoke
                    && selectedValid
                    && validToggleAvailable
                    && string.Equals(originalDisplayPath, validSource, StringComparison.OrdinalIgnoreCase)
                    && toggledEnhanced
                    && showingEnhanced
                    && string.Equals(enhancedDisplayPath, validOutput, StringComparison.OrdinalIgnoreCase)
                    && toggledOriginal
                    && showingOriginal
                    && string.Equals(restoredOriginalPath, validSource, StringComparison.OrdinalIgnoreCase)
                    && selectedStale
                    && !staleToggleAvailable
                    && !staleToggleAttempt
                    && string.Equals(staleDisplayPath, staleSource, StringComparison.OrdinalIgnoreCase)
                    && selectedAgain
                    && toggledBeforeNavigation
                    && string.Equals(validPathBeforeNavigation, validOutput, StringComparison.OrdinalIgnoreCase)
                    && movedNext
                    && !string.Equals(nextPath, validSource, StringComparison.OrdinalIgnoreCase)
                    && navigationResetToOriginal
                    && enhancementStateUnchanged
                    && malformedSqliteCasesRejected
                    && jobsWorkspaceReadOk
                    && jobsWorkspaceJobCount == 5
                    && jobsDetailsLazyLoaded
                    && jobsFullPayloadPreserved
                    && largeJobsWorkspaceReadOk
                    && largeJobsWorkspaceJobCount == 40
                    && largeJobsDetailsLazyLoaded
                    && largeJobsOversizedDetailRejected
                    && largeJobsStateUnchanged
                    && largeJobsFullPayloadBytes > 32L * 1024 * 1024;

                result = new ModalEnhancedSmokeResult
                {
                    Ok = ok,
                    Message = ok
                        ? "read-only modal original/enhanced toggle, stale fallback, navigation reset, and jobs-state isolation passed"
                        : "modal enhanced smoke did not meet expected read-only behavior",
                    Folder = fullFolder,
                    ProjectRoot = smokeRoot,
                    JobsPath = jobsPath,
                    ValidSourcePath = validSource,
                    ValidOutputPath = validOutput,
                    StaleSourcePath = staleSource,
                    OriginalDisplayPath = originalDisplayPath,
                    EnhancedDisplayPath = enhancedDisplayPath,
                    RestoredOriginalPath = restoredOriginalPath,
                    StaleDisplayPath = staleDisplayPath,
                    NextPath = nextPath,
                    ValidToggleAvailable = validToggleAvailable,
                    ToggledEnhanced = toggledEnhanced,
                    ToggledOriginal = toggledOriginal,
                    StaleToggleAvailable = staleToggleAvailable,
                    StaleToggleAttempt = staleToggleAttempt,
                    ToggledBeforeNavigation = toggledBeforeNavigation,
                    MovedNext = movedNext,
                    NavigationResetToOriginal = navigationResetToOriginal,
                    EnhancementStateUnchanged = enhancementStateUnchanged,
                    ReadOk = win.EnhancementReadOkForSmoke,
                    ReadError = win.EnhancementReadErrorForSmoke,
                    MalformedSqliteCasesRejected = malformedSqliteCasesRejected,
                    MalformedSqliteCaseCount = malformedSqliteCaseCount,
                    JobsWorkspaceReadOk = jobsWorkspaceReadOk,
                    JobsWorkspaceJobCount = jobsWorkspaceJobCount,
                    JobsDetailsLazyLoaded = jobsDetailsLazyLoaded,
                    JobsFullPayloadPreserved = jobsFullPayloadPreserved,
                    LargeJobsWorkspaceReadOk = largeJobsWorkspaceReadOk,
                    LargeJobsWorkspaceJobCount = largeJobsWorkspaceJobCount,
                    LargeJobsDetailsLazyLoaded = largeJobsDetailsLazyLoaded,
                    LargeJobsOversizedDetailRejected =
                        largeJobsOversizedDetailRejected,
                    LargeJobsStateUnchanged = largeJobsStateUnchanged,
                    LargeJobsFullPayloadBytes = largeJobsFullPayloadBytes,
                };
            }
            catch (Exception ex)
            {
                result = new ModalEnhancedSmokeResult { Ok = false, Message = ex.Message, Folder = fullFolder, ProjectRoot = smokeRoot, JobsPath = jobsPath };
            }
            finally
            {
                win.Close();
                Environment.CurrentDirectory = previousCurrentDirectory;
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", previousJobsPath);
            }

            WriteModalEnhancedSmokeResult(resultFullPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureEnhancementJobsScrollPerformanceSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = Directory.CreateTempSubdirectory(
            "aibos-enhancement-jobs-scroll-performance-").FullName;
        string storeRoot = Path.Combine(smokeRoot, "stores");
        var environmentOverrides = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["PHOTOVIEWER_WPF_STATE_PATH"] = Path.Combine(storeRoot, "state.json"),
            ["PHOTOVIEWER_WPF_SETTINGS_PATH"] = Path.Combine(storeRoot, "settings.json"),
            ["PHOTOVIEWER_WPF_FAVORITES_PATH"] = Path.Combine(storeRoot, "favorites.json"),
            ["PHOTOVIEWER_WPF_SEEN_PATH"] = Path.Combine(storeRoot, "seen.json"),
            ["PHOTOVIEWER_WPF_RECENT_PATH"] = Path.Combine(storeRoot, "recent.json"),
            ["PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH"] = Path.Combine(storeRoot, "search-history.json"),
            ["PHOTOVIEWER_WPF_ALBUMS_PATH"] = Path.Combine(storeRoot, "albums.json"),
            ["PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY"] = Path.Combine(storeRoot, "metadata-index"),
            ["PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH"] = Path.Combine(storeRoot, "enhance", "jobs.sqlite3"),
            ["PHOTOVIEWER_WPF_ENHANCEMENT_OUTPUT_ROOT"] = Path.Combine(storeRoot, "enhance", "outputs"),
        };
        Dictionary<string, string?> previousEnvironment = environmentOverrides.Keys.ToDictionary(
            static key => key,
            static key => Environment.GetEnvironmentVariable(key),
            StringComparer.Ordinal);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        _ = Dispatcher.InvokeAsync(async () =>
        {
            PhotoViewer.Wpf.MainWindow? window = null;
            object result;
            bool ok = false;
            try
            {
                Directory.CreateDirectory(storeRoot);
                foreach ((string key, string value) in environmentOverrides)
                    Environment.SetEnvironmentVariable(key, value);

                window = new PhotoViewer.Wpf.MainWindow
                {
                    Width = 1_200,
                    Height = 800,
                    WindowStartupLocation = WindowStartupLocation.Manual,
                    Left = -10_000,
                    Top = -10_000,
                };
                window.Show();
                await Dispatcher.Yield(DispatcherPriority.Loaded);
                EnhancementJobsScrollPerformanceSmokeSnapshot snapshot =
                    await window.RunEnhancementJobsScrollPerformanceSmokeAsync(
                        jobCount: 10_000,
                        scrollStepCount: 48);
                ok = snapshot.JobCount == 10_000
                    && snapshot.FilteredCount == 10_000
                    && snapshot.VisibleCount == 100
                    && snapshot.PageSize == 100
                    && snapshot.PageCount == 100
                    && snapshot.ScrollableHeight > 0
                    && snapshot.ScrollChangedCount >= 40
                    && snapshot.ThumbnailTimerRestartCount == 1
                    && snapshot.ThumbnailScrollCancellationCount == 1
                    && !snapshot.ThumbnailDebouncePending
                    && snapshot.ActionPresentationContract
                    && snapshot.RealizedContainerPeak > 0
                    // Compact rows may realize one extra card at the viewport
                    // edge; keep the bound small and independent of job count.
                    && snapshot.RealizedContainerPeak <= 10
                    // Seven action/source buttons plus the passive Details
                    // toggle and its collapsed Copy button per realized row.
                    && snapshot.RealizedButtonPeak <= snapshot.RealizedContainerPeak * 9
                    && snapshot.ThumbnailBatchSize == 0;
                result = new
                {
                    ok,
                    snapshot.JobCount,
                    snapshot.FilteredCount,
                    snapshot.VisibleCount,
                    snapshot.PageSize,
                    snapshot.PageCount,
                    snapshot.FilterMilliseconds,
                    snapshot.InitialLayoutMilliseconds,
                    snapshot.TotalScrollMilliseconds,
                    snapshot.MaximumScrollStepMilliseconds,
                    snapshot.P95ScrollStepMilliseconds,
                    snapshot.ScrollChangedCount,
                    snapshot.ThumbnailTimerRestartCount,
                    snapshot.ThumbnailScrollCancellationCount,
                    snapshot.ThumbnailDebouncePending,
                    snapshot.ActionPresentationContract,
                    snapshot.RealizedContainerPeak,
                    snapshot.RealizedButtonPeak,
                    snapshot.ThumbnailBatchSize,
                    snapshot.ScrollableHeight,
                };
            }
            catch (Exception ex)
            {
                result = new { ok = false, message = ex.ToString() };
            }
            finally
            {
                window?.Close();
                foreach ((string key, string? value) in previousEnvironment)
                    Environment.SetEnvironmentVariable(key, value);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(
                resultFullPath,
                JsonSerializer.Serialize(
                    result,
                    new JsonSerializerOptions { WriteIndented = true }));
            try
            {
                Directory.Delete(smokeRoot, recursive: true);
            }
            catch
            {
            }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

