                object[] CurrentQueuedJobs()
                {
                    return CurrentJobs()
                        .Select(job =>
                        {
                            using JsonDocument document = JsonDocument.Parse(
                                JsonSerializer.Serialize(job));
                            JsonElement root = document.RootElement;
                            return new
                            {
                                Job = job,
                                Status = root.GetProperty("status").GetString(),
                                QueueOrder = root.TryGetProperty(
                                        "queueOrder",
                                        out JsonElement queueOrder)
                                    && queueOrder.ValueKind == JsonValueKind.Number
                                    && queueOrder.TryGetInt32(out int parsed)
                                        ? parsed
                                        : int.MaxValue,
                            };
                        })
                        .Where(static item => item.Status == "queued")
                        .OrderBy(static item => item.QueueOrder)
                        .Select(static item => item.Job)
                        .ToArray();
                }

                object CurrentHealth()
                {
                    var counts = new Dictionary<string, int>(StringComparer.Ordinal)
                    {
                        ["queued"] = 0,
                        ["running"] = 0,
                        ["succeeded"] = 0,
                        ["failed"] = 0,
                        ["canceled"] = 0,
                        ["deleted"] = 0,
                    };
                    foreach (object job in CurrentJobs())
                    {
                        using JsonDocument jobDocument =
                            JsonDocument.Parse(JsonSerializer.Serialize(job));
                        string status =
                            jobDocument.RootElement.GetProperty("status").GetString() ?? "";
                        if (counts.ContainsKey(status))
                            counts[status]++;
                    }

                    var worker = new Dictionary<string, object?>(StringComparer.Ordinal)
                    {
                        ["pumpRunning"] = counts["running"] + counts["queued"] > 0,
                        ["processWorkerInstanceId"] = "smoke-worker",
                        ["consecutiveWorkerFailures"] = 0,
                        ["lastWorkerError"] = null,
                        ["lastWorkerErrorAt"] = null,
                        ["lastLeaseContentionAt"] = null,
                    };
                    if (healthMode != "legacy-pause")
                        worker["paused"] = queuePaused;
                    var capabilities = new Dictionary<string, object?>(
                        StringComparer.Ordinal);
                    if (healthMode != "legacy-prompt-update")
                    {
                        capabilities["queuedPhotorealPromptUpdate"] = true;
                        capabilities["queuedPhotorealSettingsUpdateV1"] = true;
                    }
                    capabilities["photorealPromptControlsV2"] = true;
                    capabilities["kreaAnimeToRealV1"] = true;
                    capabilities["kreaAnythingToReal1536V1"] = true;
                    capabilities["atomicImageEnqueueNext"] = true;
                    capabilities["terminalHistoryBatchDismissV1"] = true;
                    capabilities["queuedJobsBatchCancelV1"] = true;
                    capabilities["queuedJobsBatchReorderV1"] = true;
                    capabilities["terminalHistoryTargetsV1"] = true;
                    capabilities["terminalHistoryBatchRetryV1"] = true;
                    capabilities["durableEnqueueInboxV1"] = new
                    {
                        ready = true,
                        protocolVersion = 1,
                        backendGeneration = "json-v1",
                    };
                    if (photorealSeedCapabilityAvailable)
                        capabilities["photorealSeedControlV1"] = true;
                    if (healthMode == "h3-seal-missing")
                    {
                        using JsonDocument h3Health = JsonDocument.Parse(
                            CreateVideoV2HealthJson(
                                writerEnabled: true,
                                ready: false,
                                state: "unverified",
                                reasonCode: "MINIMAX_H3_RUNTIME_SEAL_INVALID",
                                runtimeSealVerified: false));
                        capabilities["videoV2"] = h3Health.RootElement
                            .GetProperty("capabilities")
                            .GetProperty("videoV2")
                            .Clone();
                        worker["pumpRunning"] = false;
                    }

                    return new
                    {
                        version = 1,
                        generatedAt = "2026-07-30T13:30:00.000Z",
                        status = healthMode switch
                        {
                            "unknown-status" => "future-health-state",
                            "unknown-issue" => "needs-attention",
                            "h3-seal-missing" => "needs-attention",
                            _ => counts["running"] + counts["queued"] > 0
                                ? "working"
                                : "healthy",
                        },
                        issues = healthMode switch
                        {
                            "unknown-issue" => ["future-health-issue"],
                            "h3-seal-missing" => ["queued-without-pump"],
                            _ => Array.Empty<string>(),
                        },
                        runtime = new
                        {
                            sourceRevision = "696849546ad61383def4d6d050e6fcb66a5fb3cd",
                            sourceDirty = false,
                            buildId = healthBuildId,
                            serverHost = "127.0.0.1",
                            serverPort = 3000,
                            serverStartedAtUtc = healthServerStartedAtUtc,
                            processId = healthProcessId,
                        },
                        store = new
                        {
                            version = 1,
                            inventoryRevision = healthInventoryRevision,
                            catalogRevision,
                            queueOrderRevision,
                        },
                        jobs = new
                        {
                            counts = new
                            {
                                queued = counts["queued"],
                                running = counts["running"],
                                succeeded = counts["succeeded"],
                                failed = counts["failed"],
                                canceled = counts["canceled"],
                                deleted = counts["deleted"],
                            },
                            current = (object?)null,
                            lastClaimAt = healthLastClaimAt,
                            lastProgressAt = (string?)null,
                            lastTerminalAt = healthLastTerminalAt,
                        },
                        worker,
                        capabilities,
                        comfyUi = new
                        {
                            endpoint = "http://127.0.0.1:8190",
                            loopback = true,
                            promptId = (string?)null,
                            submissionState = "not-active",
                        },
                    };
                }

                static HttpResponseMessage JsonResponse(HttpStatusCode status, object payload)
                    => new(status) { Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json") };
                static object DurableReceipt(HttpRequestMessage request, string jobId)
                {
                    string requestId = request.Headers.TryGetValues(
                            "Idempotency-Key",
                            out IEnumerable<string>? requestIds)
                        ? requestIds.Single()
                        : "missing-request-id";
                    return new { idempotencyKey = requestId, jobId };
                }

                HttpResponseMessage CurrentQueueMoveResponse()
                    => JsonResponse(HttpStatusCode.OK, new
                    {
                        moved = queueLaterFirst,
                        job = VideoJob(
                            "queue-later-job",
                            "queued",
                            0,
                            queueOrder: 0),
                        queue = CurrentQueuedJobs(),
                    });

                async Task<HttpResponseMessage> WaitForQueueMoveResponseAsync(
                    TaskCompletionSource<bool> gate)
                {
                    await gate.Task;
                    return CurrentQueueMoveResponse();
                }

                static async Task<HttpResponseMessage> WaitForResponseAsync(
                    TaskCompletionSource<bool> gate,
                    HttpResponseMessage response)
                {
                    await gate.Task;
                    return response;
                }

                async Task<HttpResponseMessage> CurrentJobsResponseAsync()
                {
                    object[] currentJobs = CurrentJobs();
                    object jobsPayload = jobsResponseMode switch
                    {
                        "duplicate-id" => new
                        {
                            jobs = currentJobs.Append(currentJobs[0]).ToArray(),
                        },
                        "non-object-row" => new
                        {
                            jobs = currentJobs.Append((object)42).ToArray(),
                        },
                        "missing-id" => new
                        {
                            jobs = currentJobs.Append((object)new
                            {
                                status = "queued",
                                progress = 0,
                            }).ToArray(),
                        },
                        "missing-status" => new
                        {
                            jobs = currentJobs.Append((object)new
                            {
                                id = "malformed-missing-status",
                                progress = 0,
                            }).ToArray(),
                        },
                        "unknown-status" => new
                        {
                            jobs = currentJobs.Append(Job(
                                "malformed-unknown-status",
                                "future-running-v2",
                                0)).ToArray(),
                        },
                        _ => new { jobs = currentJobs },
                    };
                    HttpResponseMessage response = JsonResponse(
                        HttpStatusCode.OK,
                        jobsPayload);
                    TaskCompletionSource<bool>? gate = jobsGetGate;
                    if (gate is not null)
                    {
                        jobsGetEntered?.TrySetResult(true);
                        await gate.Task;
                    }
                    return response;
                }

                async Task<HttpResponseMessage> CurrentHealthResponseAsync()
                {
                    HttpResponseMessage response = healthMode != "missing"
                        ? JsonResponse(HttpStatusCode.OK, CurrentHealth())
                        : JsonResponse(
                            HttpStatusCode.NotFound,
                            new { error = "health route unavailable" });
                    int currentHealthGetCount = Interlocked.Increment(
                        ref healthGetCount);
                    TaskCompletionSource<bool>? gate = healthGetGate;
                    if (gate is not null
                        && currentHealthGetCount > healthGetGateAfterCount)
                    {
                        healthGetEntered?.TrySetResult(true);
                        await gate.Task;
                    }
                    return response;
                }

                window = HiddenWindow();
                window.SuppressStatePersistence();
                bool mutationRefreshDebtContract =
                    window.EnhancementWorkspaceMutationDebtContractForSmoke();
                window.ConfigureEnhancementJobsBulkConfirmationForSmoke(
                    (title, message) =>
                    {
                        jobsBulkConfirmations.Add((title, message));
                        return acceptJobsBulkConfirmation;
                    });
                window.ConfigureModalEnhancementForSmoke((request, _) =>
                {
                    string route = request.RequestUri?.AbsolutePath ?? "";
                    requests.Add($"{request.Method.Method} {route}");
