                rapidNavigationDecodeApplies = win.ModalDecodeApplyCountForSmoke
                    - decodeAppliesBeforeBurst;
                rapidNavigationMetadataStarts = win.ModalMetadataReadStartCountForSmoke
                    - metadataStartsBeforeBurst;
                rapidNavigationMetadataApplies = win.ModalMetadataApplyCountForSmoke
                    - metadataAppliesBeforeBurst;
                rapidNavigationGetCoalesced = rapidNavigationGetStarts == 1;
                rapidNavigationDecodeCoalesced = rapidNavigationBaselineDecodeCompleted
                    && rapidNavigationFinalDecodeCompleted
                    && rapidNavigationDecodeStarts == 1
                    && rapidNavigationDecodeApplies == 1;
                rapidNavigationMetadataCoalesced = rapidNavigationMetadataStarts is 0 or 1
                    && rapidNavigationMetadataApplies == rapidNavigationMetadataStarts;
                rapidNavigationFinalSelection = rapidNavigationAccepted
                    && string.Equals(
                        win.SelectedPathForSmoke,
                        rapidNavigationStartPath,
                        StringComparison.OrdinalIgnoreCase);
                string? rapidFinalPath = win.SelectedPathForSmoke;
                string? rapidExpectedSource = string.IsNullOrWhiteSpace(rapidFinalPath)
                    ? null
                    : ResolveSmokeIdentity(rapidFinalPath);
                string[] rapidPolledSources = polledSourceIds
                    .Skip(polledSourcesBeforeBurst)
                    .ToArray();
                rapidNavigationGetFinalSource = rapidPolledSources.Length == 1
                    && string.Equals(
                        rapidPolledSources[0],
                        rapidExpectedSource,
                        StringComparison.OrdinalIgnoreCase);

                EnhancementCompanionAuthAclSmokeSnapshot authAcl =
                    PhotoViewer.Wpf.MainWindow
                        .EnhancementCompanionAuthAclContractForSmoke(smokeRoot);
                companionAuthAclProvenanceContract =
                    authAcl.CanonicalCurrentUserAclAccepted
                    && authAcl.ForeignOwnerRejected
                    && authAcl.ForeignAllowRejected
                    && authAcl.FixedCapabilityShape
                    && authAcl.RelativeFixtureRootRejected
                    && authAcl.OutsideTempFixtureRootRejected
                    && authAcl.UnavailableProductRootRejected;
                companionAuthStorage =
                    PhotoViewer.Wpf.MainWindow
                        .EnhancementCompanionAuthStorageContractForSmoke(
                            smokeRoot,
                            companionAuthJunctionFixtureRoot);
                companionAuthStorageContract =
                    companionAuthStorage.CreateAndStableReread
                    && companionAuthStorage.MalformedPreservedAndRejected
                    && companionAuthStorage.ForeignFileAclPreservedAndRejected
                    && companionAuthStorage.OversizedPreservedAndRejected
                    && companionAuthStorage.ForeignDirectoryAclPreservedAndRejected
                    && companionAuthStorage.FailedCreateExactHandleRemoved
                    && companionAuthStorage.ApplicationDirectoryJunctionRejectedOutsidePreserved
                    && companionAuthStorage.AuthDirectoryJunctionRejectedOutsidePreserved
                    && companionAuthStorage.DirectoryRenameContained;
                functionalOk = selected && opened && refreshedEmpty && started && queuedUi && canceled && canceledUi
                    && refreshedSucceeded && outputAvailable && toggledEnhanced && deletedOutput
                    && originalPreserved && outputRemoved && createContract && routesOk
                    && sourceIdentityCaseInsensitive && alternateLexicalIdentity && pollIdentityCanonical
                    && restartRecovery && legacyPhotorealRestartRecovery
                    && legacyPhotorealModalRecovery && missingLegacyPhotorealRejected
                    && lexicalOutputRejected && canonicalOutputRejected
                    && navigatedDuringResponse && staleResponseDiscarded
                    && rapidNavigationGetCoalesced && rapidNavigationGetFinalSource
                    && rapidNavigationDecodeCoalesced
                    && rapidNavigationMetadataCoalesced
                    && rapidNavigationFinalSelection
                    && passiveCompanionStartSuppressed
                    && startupCompanionAutoStart
                    && serverErrorCompanionStartSuppressed
                    && untrustedDurableReservationSuppressed
                    && companionIdentityBusySeparated
                    && companionIdentityBusyReconnected
                    && idempotentMutationReconnected
                    && idempotentMutationExactReplay
                    && idempotentMutationNoDuplicate
                    && idempotentMutationRecoverySuppressed
                    && explicitCompanionAutoStart
                    && companionAuthenticatedRequestHeaders
                    && companionListenerHandoffEncrypted
                    && companionListenerHandoffResponseRejected
                    && companionPassiveReadReconnected
                    && durableListenerHandoffSavedForDelivery
                    && durableBatchDefinitiveFailurePerItem
                    && durableLegacyWakeFallback
                    && durableRecoveryRequestsCoalesced
                    && companionAuthAclProvenanceContract
                    && companionAuthStorageContract
                    && companionIdentityFieldTamperRejected
                    && companionPrimaryRootSettingPrecedence
                    && companionCompatibilityRootSettingFallback
                    && companionConfiguredRootExact && companionAppBaseAncestor
                    && companionConfiguredAncestorRejected && companionIdentityRejected
                    && companionDedicatedLauncherSelected
                    && companionLegacyRollbackLauncherSelected
                    && nodeExecutableResolved && nodeProgramFilesCandidateAccepted
                    && nodeOutsideCandidateRejected;
            }
            catch (Exception ex)
            {
                failure = ex.Message;
            }
            finally
            {
                staleCreateRelease.TrySetResult(true);
                if (recoveryWin is not null)
                {
                    try { recoveryWin.Close(); } catch { }
                    recoveryWin = null;
                }
                if (!string.IsNullOrEmpty(jobsSeed))
                {
                    try { File.WriteAllText(jobsPath, jobsSeed); } catch { }
                }
                if (win is not null)
                {
                    try
                    {
                        await win.WaitForModalEnhancementRequestCompletionForSmokeAsync();
                        if (win.IsLoaded)
                            await win.CloseAndWaitForSmokeAsync();
                        else
                            win.Close();
                        closeCompleted = true;
                    }
                    catch (Exception closeException)
                    {
                        if (string.IsNullOrWhiteSpace(failure))
                            failure = $"window close/drain failed: {closeException.Message}";
                    }
                }

                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", previousStatePath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", previousFavoritesPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", previousSeenPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH", previousRecentPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH", previousSettingsPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH", previousAlbumsPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH", previousSearchHistoryPath);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY", previousMetadataIndexDirectory);
                Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", previousJobsPath);
            }

            foreach ((string key, string path) in storePaths)
                storeFingerprintsAfter[key] = FileFingerprint(path);
            bool environmentRestored = string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH"), previousStatePath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH"), previousFavoritesPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH"), previousSeenPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_RECENT_PATH"), previousRecentPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SETTINGS_PATH"), previousSettingsPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ALBUMS_PATH"), previousAlbumsPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH"), previousSearchHistoryPath, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY"), previousMetadataIndexDirectory, StringComparison.Ordinal)
                && string.Equals(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH"), previousJobsPath, StringComparison.Ordinal);
            string normalizedSmokeRoot = Path.GetFullPath(smokeRoot).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            bool pathsIsolated = storePaths.Values.All(path => Path.GetFullPath(path).StartsWith(normalizedSmokeRoot, StringComparison.OrdinalIgnoreCase));
            bool fingerprintsCaptured = storeFingerprintsBefore.Count == storePaths.Count
                && storeFingerprintsAfter.Count == storePaths.Count
                && storeFingerprintsBefore.Values.All(static fingerprint => fingerprint != "missing")
                && storeFingerprintsAfter.Values.All(static fingerprint => fingerprint != "missing");
            bool sharedStoresByteIdentical = new[] { "favorites", "seen", "recent", "settings", "albums", "searchHistory", "jobs" }
                .All(key => storeFingerprintsBefore.TryGetValue(key, out string? before)
                    && storeFingerprintsAfter.TryGetValue(key, out string? after)
                    && string.Equals(before, after, StringComparison.Ordinal));
            bool stateJsonValid = false;
            try
            {
                using JsonDocument stateDocument = JsonDocument.Parse(File.ReadAllText(statePath));
                stateJsonValid = stateDocument.RootElement.ValueKind == JsonValueKind.Object;
            }
            catch (Exception ex) when (ex is IOException or JsonException)
            {
            }
            bool sourceUntouched = string.Equals(sourceBefore, FolderFingerprint(folder), StringComparison.Ordinal);
            canonicalSourceUntouched = string.Equals(canonicalSourceBefore, FolderFingerprint(canonicalSourceRoot), StringComparison.Ordinal);
            bool residueFree = NoPersistenceResidue(smokeRoot);
            bool isolationOk = closeCompleted && environmentRestored && pathsIsolated && fingerprintsCaptured
                && sharedStoresByteIdentical && stateJsonValid && sourceUntouched && canonicalSourceUntouched && residueFree;
            bool ok = functionalOk && isolationOk && string.IsNullOrWhiteSpace(failure);
            object result = new
            {
                ok,
                message = ok
                    ? "explicit modal enhancement bridge and stale-response guard passed with TEMP-only store isolation"
                    : string.IsNullOrWhiteSpace(failure) ? "modal enhancement action/isolation contract failed" : failure,
                selected,
                opened,
                refreshedEmpty,
                started,
                queuedUi,
                canceled,
                canceledUi,
                refreshedSucceeded,
                outputAvailable,
                toggledEnhanced,
                deletedOutput,
                originalPreserved,
                outputRemoved,
                createContract,
                routesOk,
                sourceIdentityCaseInsensitive,
                alternateLexicalIdentity,
                pollIdentityCanonical,
                restartRecovery,
                legacyPhotorealRestartRecovery,
                legacyPhotorealModalRecovery,
                missingLegacyPhotorealRejected,
                lexicalOutputRejected,
                canonicalOutputRejected,
                navigatedDuringResponse,
                staleResponseDiscarded,
                rapidNavigationGetCoalesced,
                rapidNavigationGetFinalSource,
                rapidNavigationDecodeCoalesced,
                rapidNavigationMetadataCoalesced,
                rapidNavigationFinalSelection,
                rapidNavigationBaselineDecodeCompleted,
                rapidNavigationFinalDecodeCompleted,
                rapidNavigationGetStarts,
                rapidNavigationDecodeStarts,
                rapidNavigationDecodeApplies,
                rapidNavigationMetadataStarts,
                rapidNavigationMetadataApplies,
                passiveCompanionStartSuppressed,
                startupCompanionAutoStart,
                serverErrorCompanionStartSuppressed,
                companionIdentityBusySeparated,
                companionIdentityBusyReconnected,
                idempotentMutationReconnected,
                idempotentMutationExactReplay,
                idempotentMutationNoDuplicate,
                idempotentMutationRecoverySuppressed,
                explicitCompanionAutoStart,
                companionAuthenticatedRequestHeaders,
                companionQueueRecoveryAuthenticated,
                companionListenerHandoffEncrypted,
                companionListenerHandoffResponseRejected,
                companionPassiveReadReconnected,
                durableListenerHandoffSavedForDelivery,
                durableRecoveryBeforePublish,
                durableRecoveryAfterPublish,
                durableRecoveryCarriedRequestId,
                durableBatchDefinitiveFailurePerItem,
                durableLegacyWakeFallback,
                durableRecoveryRequestsCoalesced,
                companionAuthAclProvenanceContract,
                companionAuthStorageContract,
                companionAuthStorage,
                companionIdentityFieldTamperRejected,
                companionPrimaryRootSettingPrecedence,
                companionCompatibilityRootSettingFallback,
                companionConfiguredRootExact,
                companionAppBaseAncestor,
                companionConfiguredAncestorRejected,
                companionIdentityRejected,
                companionDedicatedLauncherSelected,
                companionLegacyRollbackLauncherSelected,
                nodeExecutableResolved,
                nodeProgramFilesCandidateAccepted,
                nodeOutsideCandidateRejected,
                closeCompleted,
                environmentRestored,
                pathsIsolated,
                fingerprintsCaptured,
                sharedStoresByteIdentical,
                stateJsonValid,
                sourceUntouched,
                canonicalSourceUntouched,
                residueFree,
                storePaths,
                storeFingerprintsBefore,
                storeFingerprintsAfter,
                requests,
                polledSourceIds,
            };
            Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
            File.WriteAllText(resultFullPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }));
            try { if (Directory.Exists(smokeRoot)) Directory.Delete(smokeRoot, recursive: true); } catch { }
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static bool IsPathInsideForSmoke(string candidate, string root)
    {
        string normalizedCandidate = Path.GetFullPath(candidate);
        string normalizedRoot = Path.TrimEndingDirectorySeparator(Path.GetFullPath(root));
        string rootPrefix = normalizedRoot + Path.DirectorySeparatorChar;
        return string.Equals(normalizedCandidate, normalizedRoot, StringComparison.OrdinalIgnoreCase)
            || normalizedCandidate.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase);
    }

    private static string ResolveFinalPathForSmoke(string path)
    {
        string fullPath = Path.GetFullPath(path);
        string root = Path.GetPathRoot(fullPath) ?? throw new IOException("path root is unavailable");
        string current = root;
        string[] parts = fullPath[root.Length..].Split(
            [Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar],
            StringSplitOptions.RemoveEmptyEntries);

        for (int index = 0; index < parts.Length; index++)
        {
            string candidate = Path.Combine(current, parts[index]);
            // This helper is the path sanitizer: it must inspect each existing component so
            // junctions/symlinks can be resolved before any smoke-test write is permitted.
            // codeql[cs/path-injection]
            if (!File.Exists(candidate) && !Directory.Exists(candidate))
            {
                for (int remainder = index; remainder < parts.Length; remainder++)
                    current = Path.Combine(current, parts[remainder]);
                return Path.GetFullPath(current);
            }

            // See the sanitizer invariant above; candidate is inspected, never written here.
            // codeql[cs/path-injection]
            FileSystemInfo info = Directory.Exists(candidate) ? new DirectoryInfo(candidate) : new FileInfo(candidate);
            if (info.LinkTarget is null)
            {
                current = candidate;
                continue;
            }

            FileSystemInfo? resolved = info.ResolveLinkTarget(returnFinalTarget: true);
            if (resolved is null)
                throw new IOException($"cannot resolve link target: {candidate}");
            current = Path.GetFullPath(resolved.FullName);
        }

        return Path.GetFullPath(current);
    }

    private static bool IsFinalPathInsideForSmoke(string candidate, string finalRoot)
        => IsPathInsideForSmoke(ResolveFinalPathForSmoke(candidate), finalRoot);

    private void CaptureH25EnhancementCompanionSmoke(string resultPath, string[] args)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string fixtureRoot = Path.GetFullPath(ArgValue(args, "--fixture-root")
            ?? throw new ArgumentException("--fixture-root is required"));
        string tempRoot = Path.GetFullPath(Path.GetTempPath());
        string tempPrefix = tempRoot
            .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
            + Path.DirectorySeparatorChar;
        string fixturePrefix = fixtureRoot.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
            + Path.DirectorySeparatorChar;
        string phase = ArgValue(args, "--phase") ?? "full";
        string sourceName = Path.GetFileName(ArgValue(args, "--source-name") ?? $"{phase}-source.png");
        if (!fixturePrefix.StartsWith(tempPrefix, StringComparison.OrdinalIgnoreCase)
            || !resultFullPath.StartsWith(fixturePrefix, StringComparison.OrdinalIgnoreCase)
            || sourceName.Length == 0
            || phase is not ("full" or "start-detached" or "start-interrupted" or "recover"))
        {
            throw new ArgumentException("H25 companion smoke paths and phase must be bounded under TEMP");
        }

        string finalTempRoot = ResolveFinalPathForSmoke(tempRoot);
        string finalFixtureRoot = ResolveFinalPathForSmoke(fixtureRoot);
        if (!IsPathInsideForSmoke(finalFixtureRoot, finalTempRoot))
            throw new ArgumentException("H25 companion smoke fixture escaped TEMP through a reparse point");

        string sharedRoot = Path.Combine(fixtureRoot, "s");
        string wpfLocalRoot = Path.Combine(fixtureRoot, "w");
        string imagesRoot = Path.Combine(fixtureRoot, "images");
        string sourcePath = Path.Combine(imagesRoot, sourceName);
        string jobsPath = Path.Combine(sharedRoot, "enhance", "jobs.json");
        string metadataIndexDirectory = Path.Combine(wpfLocalRoot, "metadata-index");
        string configuredMetadataIndexDirectory = Path.GetFullPath(Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY")
            ?? throw new InvalidOperationException("PHOTOVIEWER_WPF_METADATA_INDEX_DIRECTORY is required"));
        string[] fileEnvironmentNames =
        [
            "PHOTOVIEWER_WPF_STATE_PATH",
            "PHOTOVIEWER_WPF_FAVORITES_PATH",
            "PHOTOVIEWER_WPF_SEEN_PATH",
            "PHOTOVIEWER_WPF_RECENT_PATH",
            "PHOTOVIEWER_WPF_SETTINGS_PATH",
            "PHOTOVIEWER_WPF_ALBUMS_PATH",
            "PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH",
            "PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH",
        ];
        var expectedStorePaths = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["PHOTOVIEWER_WPF_STATE_PATH"] = Path.Combine(wpfLocalRoot, "state.json"),
            ["PHOTOVIEWER_WPF_FAVORITES_PATH"] = Path.Combine(sharedRoot, "favorites.json"),
            ["PHOTOVIEWER_WPF_SEEN_PATH"] = Path.Combine(sharedRoot, "seen.json"),
            ["PHOTOVIEWER_WPF_RECENT_PATH"] = Path.Combine(sharedRoot, "recent-folders.json"),
            ["PHOTOVIEWER_WPF_SETTINGS_PATH"] = Path.Combine(sharedRoot, "settings.json"),
            ["PHOTOVIEWER_WPF_ALBUMS_PATH"] = Path.Combine(sharedRoot, "albums.json"),
            ["PHOTOVIEWER_WPF_SEARCH_HISTORY_PATH"] = Path.Combine(sharedRoot, "search-history.json"),
            ["PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH"] = jobsPath,
        };
        var storePaths = fileEnvironmentNames.ToDictionary(
            static name => name,
            name => Path.GetFullPath(Environment.GetEnvironmentVariable(name)
                ?? throw new InvalidOperationException($"{name} is required")),
            StringComparer.Ordinal);
        var storePathIsolation = storePaths.ToDictionary(
            static pair => pair.Key,
            pair => string.Equals(pair.Value, expectedStorePaths[pair.Key], StringComparison.OrdinalIgnoreCase)
                && IsFinalPathInsideForSmoke(expectedStorePaths[pair.Key], finalFixtureRoot),
            StringComparer.Ordinal);
        bool metadataIndexIsolated = string.Equals(
                configuredMetadataIndexDirectory,
                metadataIndexDirectory,
                StringComparison.OrdinalIgnoreCase)
            && IsFinalPathInsideForSmoke(metadataIndexDirectory, finalFixtureRoot);
        bool sourcePathIsolated = IsFinalPathInsideForSmoke(sourcePath, finalFixtureRoot);
        bool resultPathIsolated = IsFinalPathInsideForSmoke(resultFullPath, finalFixtureRoot);
        bool pathsIsolated = storePathIsolation.Values.All(static isolated => isolated)
            && metadataIndexIsolated
            && sourcePathIsolated
            && resultPathIsolated;
        string configuredBaseUrl = Environment.GetEnvironmentVariable("PHOTOVIEWER_BROWSER_BASE_URL") ?? "";
        bool loopbackOnly = Uri.TryCreate(configuredBaseUrl, UriKind.Absolute, out Uri? companionUri)
            && companionUri.IsLoopback
            && companionUri.Scheme == Uri.UriSchemeHttp
            && string.Equals(companionUri.Host, "127.0.0.1", StringComparison.Ordinal);

        ShutdownMode = ShutdownMode.OnExplicitShutdown;
        Dispatcher.InvokeAsync(async () =>
        {
            MainWindow? win = null;
            bool selected = false;
            bool opened = false;
            bool passiveRefresh = false;
            bool started = false;
            bool canceled = false;
            bool retried = false;
            bool succeeded = false;
            bool outputAccepted = false;
            bool deletedOutput = false;
            bool restartJobObserved = false;
            bool interruptedJobFailed = false;
            bool sourceUnchanged = false;
            string? jobId = null;
            string? status = null;
            string? outputPath = null;
            string failure = "";
            string sourceSha256Before = "missing";
            var checkpoints = new List<string>();

            async Task<bool> WaitForStatusAsync(string expected, TimeSpan timeout)
            {
                var wait = Stopwatch.StartNew();
                while (wait.Elapsed < timeout)
                {
                    await win!.RefreshModalEnhancementForSmokeAsync();
                    if (string.Equals(win.ModalEnhancementStatusForSmoke, expected, StringComparison.Ordinal))
                        return true;
                    await Task.Delay(75);
                }
                return false;
            }

            Dictionary<string, object?> Snapshot(bool ok, string message)
                => new(StringComparer.Ordinal)
                {
                    ["ok"] = ok,
                    ["message"] = message,
                    ["phase"] = phase,
                    ["selected"] = selected,
                    ["opened"] = opened,
                    ["passiveRefresh"] = passiveRefresh,
                    ["started"] = started,
                    ["canceled"] = canceled,
                    ["retried"] = retried,
                    ["succeeded"] = succeeded,
                    ["outputAccepted"] = outputAccepted,
                    ["deletedOutput"] = deletedOutput,
                    ["restartJobObserved"] = restartJobObserved,
                    ["interruptedJobFailed"] = interruptedJobFailed,
                    ["sourceUnchanged"] = sourceUnchanged,
                    ["pathsIsolated"] = pathsIsolated,
                    ["pathIsolationFailures"] = storePathIsolation
                        .Where(static pair => !pair.Value)
                        .Select(static pair => pair.Key)
                        .OrderBy(static name => name, StringComparer.Ordinal)
                        .ToArray(),
                    ["metadataIndexIsolated"] = metadataIndexIsolated,
                    ["sourcePathIsolated"] = sourcePathIsolated,
                    ["resultPathIsolated"] = resultPathIsolated,
                    ["loopbackOnly"] = loopbackOnly,
                    ["checkpoints"] = checkpoints.ToArray(),
                    ["jobId"] = jobId,
                    ["status"] = status,
                    ["outputPath"] = outputPath,
                    ["sourceSha256Before"] = sourceSha256Before,
                    ["sourceSha256After"] = File.Exists(sourcePath)
                        ? Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(sourcePath)))
                        : "missing",
                };

            void WriteSnapshot(Dictionary<string, object?> snapshot)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(resultFullPath)!);
                File.WriteAllText(resultFullPath, JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true }));
            }

            void RecordCheckpoint(string checkpoint)
            {
                checkpoints.Add(checkpoint);
                WriteSnapshot(Snapshot(false, $"checkpoint: {checkpoint}"));
            }

            try
            {
                if (!pathsIsolated || !loopbackOnly)
                    throw new InvalidOperationException("companion smoke did not receive TEMP-only stores and an explicit 127.0.0.1 endpoint");
                RecordCheckpoint("isolation-accepted");
                Directory.CreateDirectory(imagesRoot);
                // The configured value was matched to this fixed path and its
                // final target was proven to remain inside finalFixtureRoot.
                // codeql[cs/path-injection]
                Directory.CreateDirectory(metadataIndexDirectory);
                if (!File.Exists(sourcePath))
                    WriteSmokePng(sourcePath, 320, 240, Color.FromRgb(76, 132, 196));
                sourceSha256Before = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(sourcePath)));

                win = HiddenWindow();
                win.SuppressStatePersistence();
                // This gate runs against a production Next server. Test-only
                // adapters are intentionally rejected there, so exercise the
                // same local ncnn backend used by an explicit WPF action.
                win.ConfigureModalEnhancementRequestProfileForSmoke("anime-sharp-x2", "realesrgan-ncnn", 2);
                win.ConfigureModalEnhancementConfirmationsForSmoke();
                win.Show();
                await win.LoadFolderSetAsync([imagesRoot], commitRecent: false);
                selected = win.SelectFileNameForSmoke(sourceName);
                opened = win.OpenModalForSmoke();
                string jobsBeforeRefresh = FileFingerprint(jobsPath);
                await win.RefreshModalEnhancementForSmokeAsync();
                passiveRefresh = string.Equals(jobsBeforeRefresh, FileFingerprint(jobsPath), StringComparison.Ordinal);
                RecordCheckpoint("modal-opened-passive-refresh-complete");

                if (phase == "full")
                {
                    started = await win.StartModalEnhancementForSmokeAsync(45_000);
                    jobId = win.ModalEnhancementJobIdForSmoke;
                    RecordCheckpoint("full-start-complete");
                    canceled = await win.CancelModalEnhancementForSmokeAsync()
                        || await WaitForStatusAsync("canceled", TimeSpan.FromSeconds(30));
                    RecordCheckpoint("full-cancel-complete");
                    retried = canceled && await win.StartModalEnhancementForSmokeAsync(45_000);
                    if (retried)
                        jobId = win.ModalEnhancementJobIdForSmoke;
                    RecordCheckpoint("full-retry-complete");
                    succeeded = retried && await WaitForStatusAsync("succeeded", TimeSpan.FromSeconds(180));
                    RecordCheckpoint("full-success-wait-complete");
                    outputAccepted = succeeded && win.ModalEnhancedToggleAvailableForSmoke;
                    outputPath = win.ModalDisplayPathForSmoke;
                    deletedOutput = outputAccepted && await win.DeleteModalEnhancedOutputForSmokeAsync();
                    RecordCheckpoint("full-delete-complete");
                }
                else if (phase is "start-interrupted" or "start-detached")
                {
                    started = await win.StartModalEnhancementForSmokeAsync(45_000);
                    jobId = win.ModalEnhancementJobIdForSmoke;
                    status = win.ModalEnhancementStatusForSmoke;
                    bool readyForInterruption = started
                        && !string.IsNullOrWhiteSpace(jobId)
                        && status is "queued" or "running";
                    sourceUnchanged = string.Equals(
                        sourceSha256Before,
                        Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(sourcePath))),
                        StringComparison.Ordinal);
                    WriteSnapshot(Snapshot(
                        readyForInterruption && selected && opened && passiveRefresh && sourceUnchanged,
                        readyForInterruption
                            ? "real H25 job is active and ready for the verifier to interrupt the companion"
                            : "real H25 job did not reach an interruptible state"));
                    if (phase == "start-interrupted")
                        await Task.Delay(TimeSpan.FromSeconds(10));
                }
                else
                {
                    interruptedJobFailed = await WaitForStatusAsync(
                        "failed",
                        TimeSpan.FromSeconds(45));
                    status = win.ModalEnhancementStatusForSmoke;
                    restartJobObserved = interruptedJobFailed
                        && !string.IsNullOrWhiteSpace(win.ModalEnhancementJobIdForSmoke);
                    jobId = win.ModalEnhancementJobIdForSmoke;
                    RecordCheckpoint("recovery-failed-job-observed");
                    retried = restartJobObserved && await win.StartModalEnhancementForSmokeAsync(45_000);
                    if (retried)
                        jobId = win.ModalEnhancementJobIdForSmoke;
                    RecordCheckpoint("recovery-retry-complete");
                    succeeded = retried && await WaitForStatusAsync("succeeded", TimeSpan.FromSeconds(180));
                    RecordCheckpoint("recovery-success-wait-complete");
                    outputAccepted = succeeded && win.ModalEnhancedToggleAvailableForSmoke;
                    outputPath = win.ModalDisplayPathForSmoke;
                    deletedOutput = outputAccepted && await win.DeleteModalEnhancedOutputForSmokeAsync();
                    RecordCheckpoint("recovery-delete-complete");
                }

                status = win.ModalEnhancementStatusForSmoke;
                sourceUnchanged = string.Equals(
                    sourceSha256Before,
                    Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(sourcePath))),
                    StringComparison.Ordinal);
            }
            catch (Exception ex)
            {
                failure = ex.Message;
            }
            finally
            {
                if (win is not null)
                {
                    try
                    {
                        RecordCheckpoint("window-close-start");
                        await win.WaitForModalEnhancementRequestCompletionForSmokeAsync(45_000);
                        RecordCheckpoint("window-request-drain-complete");
                        if (win.IsLoaded)
                            await win.CloseAndWaitForSmokeAsync();
                        else
                            win.Close();
                        RecordCheckpoint("window-close-complete");
                    }
                    catch (Exception closeError)
                    {
                        if (string.IsNullOrWhiteSpace(failure))
                            failure = closeError.Message;
                    }
                }
            }

            bool ok = string.IsNullOrWhiteSpace(failure)
                && selected
                && opened
                && passiveRefresh
                && sourceUnchanged
                && pathsIsolated
                && loopbackOnly
                && (phase is "start-interrupted" or "start-detached"
                    ? started && !string.IsNullOrWhiteSpace(jobId) && status is "queued" or "running"
                    : phase == "full"
                        ? started && canceled && retried && succeeded && outputAccepted && deletedOutput
                        : restartJobObserved && interruptedJobFailed && retried && succeeded && outputAccepted && deletedOutput);
            WriteSnapshot(Snapshot(ok, ok
                ? $"real H25 companion phase '{phase}' passed"
                : string.IsNullOrWhiteSpace(failure) ? $"real H25 companion phase '{phase}' failed" : failure));
            Shutdown(ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private static async Task<SharedSeenSmokeResult> RunSharedSeenSmokeAsync(
        MainWindow first,
        string fullFolder,
        string smokeRoot,
        string[] fixtureNames)
    {
        string sharedSeenPath = Path.Combine(smokeRoot, ".cache", "seen.json");
        string legacySeenPath = Path.Combine(smokeRoot, ".cache", "wpf-seen.json");
        string sharedSeedName = fixtureNames[0];
        string legacySeedName = fixtureNames[1];
        string targetName = fixtureNames[2];
        string sharedSeedPath = Path.Combine(fullFolder, sharedSeedName);
        string legacySeedPath = Path.Combine(fullFolder, legacySeedName);
        string targetPath = Path.Combine(fullFolder, targetName);

        WriteSeenSeed(sharedSeenPath, sharedSeedPath);
        WriteSeenSeed(legacySeenPath, legacySeedPath);
        string legacyBefore = File.ReadAllText(legacySeenPath);

        await first.LoadFolderAsync(fullFolder);
        first.SetSearchQuery("", persist: false);
        string resolvedSeenPath = first.SeenPathForSmoke;
        int initialSeenStoreCount = first.SeenStoreCountForSmoke;
        bool selectedTarget = first.SelectFileNameForSmoke(targetName);
        int seenStoreAfterSelection = first.SeenStoreCountForSmoke;
        bool targetSelectedSeen = first.IsFileUnseenForSmoke(targetName) == false;
        first.SetUnseenOnlyFilterForSmoke(true);
        int filteredAfterSelection = first.FilteredCountForSmoke;
        first.Close();

        var sharedMap = ReadSeenMap(sharedSeenPath);
        var legacyMap = ReadSeenMap(legacySeenPath);
        string legacyAfter = File.ReadAllText(legacySeenPath);
        bool sharedHasSharedSeed = sharedMap.ContainsKey(NormalizeFavoritePath(sharedSeedPath));
        bool sharedHasLegacySeed = sharedMap.ContainsKey(NormalizeFavoritePath(legacySeedPath));
        bool sharedHasTarget = sharedMap.ContainsKey(NormalizeFavoritePath(targetPath));
        bool legacyPreserved = string.Equals(legacyBefore, legacyAfter, StringComparison.Ordinal)
            && legacyMap.Count == 1
            && legacyMap.ContainsKey(NormalizeFavoritePath(legacySeedPath))
            && !legacyMap.ContainsKey(NormalizeFavoritePath(sharedSeedPath))
            && !legacyMap.ContainsKey(NormalizeFavoritePath(targetPath));

        var second = HiddenWindow();
        second.Show();
        second.SuppressStatePersistence();
        await second.LoadFolderAsync(fullFolder);
        second.SetSearchQuery("", persist: false);
        bool reloadSharedSeedSeen = second.IsFileUnseenForSmoke(sharedSeedName) == false;
        bool reloadLegacySeedSeen = second.IsFileUnseenForSmoke(legacySeedName) == false;
        bool reloadTargetSeen = second.IsFileUnseenForSmoke(targetName) == false;
        int reloadSeenStoreCount = second.SeenStoreCountForSmoke;
        second.Close();

        MalformedSeenSmokeCaseResult malformedLegacy = await RunMalformedSeenSmokeCaseAsync(
            fullFolder,
            smokeRoot,
            "malformed-legacy",
            fixtureNames,
            malformedShared: false);
        MalformedSeenSmokeCaseResult malformedShared = await RunMalformedSeenSmokeCaseAsync(
            fullFolder,
            smokeRoot,
            "malformed-shared",
            fixtureNames,
            malformedShared: true);

        bool ok = string.Equals(Path.GetFullPath(resolvedSeenPath), Path.GetFullPath(sharedSeenPath), StringComparison.OrdinalIgnoreCase)
            && selectedTarget
            && targetSelectedSeen
            && initialSeenStoreCount >= 2
            && seenStoreAfterSelection >= initialSeenStoreCount
            && filteredAfterSelection >= 0
            && sharedHasSharedSeed
            && sharedHasLegacySeed
            && sharedHasTarget
            && legacyPreserved
            && reloadSharedSeedSeen
            && reloadLegacySeedSeen
            && reloadTargetSeen
            && reloadSeenStoreCount >= sharedMap.Count
            && malformedLegacy.Ok
            && malformedShared.Ok;

        return new SharedSeenSmokeResult
        {
            Ok = ok,
            Message = ok ? "shared seen default path, legacy additive merge, shared-only write, reload, and malformed fail-safe passed" : "shared seen smoke did not meet expected policy",
            Folder = fullFolder,
            ProjectRoot = smokeRoot,
            SharedSeenPath = sharedSeenPath,
            LegacySeenPath = legacySeenPath,
            ResolvedSeenPath = resolvedSeenPath,
            SharedSeedName = sharedSeedName,
            LegacySeedName = legacySeedName,
            TargetName = targetName,
            InitialSeenStoreCount = initialSeenStoreCount,
            SeenStoreCountAfterSelection = seenStoreAfterSelection,
            SharedMapCountAfterSelection = sharedMap.Count,
            LegacyMapCountAfterSelection = legacyMap.Count,
            SharedHasSharedSeed = sharedHasSharedSeed,
            SharedHasLegacySeed = sharedHasLegacySeed,
            SharedHasTarget = sharedHasTarget,
            LegacyPreserved = legacyPreserved,
            ReloadSharedSeedSeen = reloadSharedSeedSeen,
            ReloadLegacySeedSeen = reloadLegacySeedSeen,
            ReloadTargetSeen = reloadTargetSeen,
            ReloadSeenStoreCount = reloadSeenStoreCount,
            MalformedLegacy = malformedLegacy,
            MalformedShared = malformedShared,
        };
    }

    private static async Task<MalformedSeenSmokeCaseResult> RunMalformedSeenSmokeCaseAsync(
        string fullFolder,
        string parentRoot,
        string caseName,
        string[] fixtureNames,
        bool malformedShared)
    {
        string caseRoot = Path.Combine(parentRoot, caseName);
        PrepareSharedSeenSmokeEnvironment(caseRoot);

        string sharedSeenPath = Path.Combine(caseRoot, ".cache", "seen.json");
        string legacySeenPath = Path.Combine(caseRoot, ".cache", "wpf-seen.json");
        string sharedSeedName = fixtureNames[0];
        string legacySeedName = fixtureNames[1];
        string targetName = fixtureNames[2];
        string sharedSeedPath = Path.Combine(fullFolder, sharedSeedName);
        string legacySeedPath = Path.Combine(fullFolder, legacySeedName);
        string targetPath = Path.Combine(fullFolder, targetName);
        const string malformedJson = "[";

        if (malformedShared)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(sharedSeenPath)!);
            File.WriteAllText(sharedSeenPath, malformedJson);
            WriteSeenSeed(legacySeenPath, legacySeedPath);
        }
        else
        {
            WriteSeenSeed(sharedSeenPath, sharedSeedPath);
            Directory.CreateDirectory(Path.GetDirectoryName(legacySeenPath)!);
            File.WriteAllText(legacySeenPath, malformedJson);
        }

        string sharedBefore = File.ReadAllText(sharedSeenPath);
        string legacyBefore = File.ReadAllText(legacySeenPath);

        var window = HiddenWindow();
        window.Show();
        window.SuppressStatePersistence();
        await window.LoadFolderAsync(fullFolder);
        window.SetSearchQuery("", persist: false);
        string resolvedSeenPath = window.SeenPathForSmoke;
        bool selectedTarget = window.SelectFileNameForSmoke(targetName);
        bool targetStillUnseen = window.IsFileUnseenForSmoke(targetName) == true;
        bool validSeedLoaded = malformedShared
            ? window.IsFileUnseenForSmoke(legacySeedName) == false
            : window.IsFileUnseenForSmoke(sharedSeedName) == false;
        int seenStoreCount = window.SeenStoreCountForSmoke;
        window.Close();

        string sharedAfter = File.ReadAllText(sharedSeenPath);
        string legacyAfter = File.ReadAllText(legacySeenPath);
        bool sharedPreserved = string.Equals(sharedBefore, sharedAfter, StringComparison.Ordinal);
        bool legacyPreserved = string.Equals(legacyBefore, legacyAfter, StringComparison.Ordinal);
        bool targetNotPersisted = malformedShared
            ? !ReadSeenFlag(legacySeenPath, targetPath)
            : !ReadSeenFlag(sharedSeenPath, targetPath);
        bool ok = string.Equals(Path.GetFullPath(resolvedSeenPath), Path.GetFullPath(sharedSeenPath), StringComparison.OrdinalIgnoreCase)
            && selectedTarget
            && targetStillUnseen
            && targetNotPersisted
            && validSeedLoaded
            && sharedPreserved
            && legacyPreserved;

        return new MalformedSeenSmokeCaseResult(
            ok,
            caseName,
            malformedShared,
            resolvedSeenPath,
            selectedTarget,
            targetStillUnseen,
            targetNotPersisted,
            validSeedLoaded,
            sharedPreserved,
            legacyPreserved,
            seenStoreCount);
    }

    private void CaptureScrollRealizationSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        string query = ArgValue(args, "--query") ?? "";
        int advanceCount = ArgInt(args, "--advance-count", 16);
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteScrollRealizationSmokeResult(
                resultPath,
                new ScrollRealizationSmokeResult(false, "missing required --folder", folder, query, advanceCount, 0, 0, 0, 0, 0, 0, 0, false, 0, 0, 0, 0, 0, false));
            Shutdown(1);
            return;
        }

        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        win.Show();
        win.SuppressStatePersistence();

        win.Dispatcher.InvokeAsync(async () =>
        {
            ScrollRealizationSmokeResult result;
            try
            {
                await win.LoadFolderAsync(folder);
                win.SetSearchQuery(query, persist: false);

                int total = win.FilteredCountForSmoke;
                int initialRealized = win.GridRealizedCountForSmoke;
                int initialDeferred = win.GridDeferredCountForSmoke;
                int initialStart = win.GridWindowStartIndexForSmoke;
                int initialEnd = win.GridWindowEndIndexForSmoke;
                int maxAllowed = win.GridMaxRealizationCountForSmoke;
                int maxObserved = initialRealized;
                int advancesMoved = 0;

                for (int i = 0; i < advanceCount; i++)
                {
                    if (win.RealizeNextGridBatchForSmoke())
                        advancesMoved++;
                    maxObserved = Math.Max(maxObserved, win.GridRealizedCountForSmoke);
                }

                int finalRealized = win.GridRealizedCountForSmoke;
                int finalDeferred = win.GridDeferredCountForSmoke;
                int finalStart = win.GridWindowStartIndexForSmoke;
                int finalEnd = win.GridWindowEndIndexForSmoke;
                bool movedBack = win.RealizePreviousGridBatchForSmoke();
                int afterBackStart = win.GridWindowStartIndexForSmoke;
                int afterBackRealized = win.GridRealizedCountForSmoke;

                bool bounded = maxObserved <= maxAllowed && finalRealized <= maxAllowed && afterBackRealized <= maxAllowed;
                bool ok = total > maxAllowed
                    && initialRealized < total
                    && advancesMoved > 0
                    && finalStart > initialStart
                    && finalEnd <= total
                    && finalDeferred > 0
                    && bounded
                    && movedBack
                    && afterBackStart < finalStart;

                result = new ScrollRealizationSmokeResult(
                    ok,
                    ok ? "scroll advance keeps grid realization bounded and moves the window forward/back" : "scroll realization guard did not stay bounded or did not move as expected",
                    folder,
                    query,
                    advanceCount,
                    total,
                    initialRealized,
                    initialDeferred,
                    initialStart,
                    initialEnd,
                    advancesMoved,
                    maxObserved,
                    bounded,
                    finalRealized,
                    finalDeferred,
                    finalStart,
                    finalEnd,
                    maxAllowed,
                    movedBack);
            }
            catch (Exception ex)
            {
                result = new ScrollRealizationSmokeResult(false, ex.Message, folder, query, advanceCount, 0, 0, 0, 0, 0, 0, 0, false, 0, 0, 0, 0, 0, false);
            }

            win.Close();
            WriteScrollRealizationSmokeResult(resultPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureGridRealizationSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        string query = ArgValue(args, "--query") ?? "";
        if (string.IsNullOrWhiteSpace(folder))
        {
            WriteGridRealizationSmokeResult(
                resultPath,
                new GridRealizationSmokeResult(false, "missing required --folder", folder, query, 0, 0, 0, false, 0, 0));
            Shutdown(1);
            return;
        }

        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        win.Show();
        win.SuppressStatePersistence();

        win.Dispatcher.InvokeAsync(async () =>
        {
            GridRealizationSmokeResult result;
            try
            {
                await win.LoadFolderAsync(folder);
                win.SetSearchQuery(query, persist: false);

                int total = win.FilteredCountForSmoke;
                int initial = win.GridRealizedCountForSmoke;
                int initialDeferred = win.GridDeferredCountForSmoke;
                bool moved = win.RealizeNextGridBatchForSmoke();
                int afterBatch = win.GridRealizedCountForSmoke;
                int afterDeferred = win.GridDeferredCountForSmoke;

                bool ok = total > initial
                    && initialDeferred > 0
                    && moved
                    && afterBatch > initial
                    && afterBatch <= total
                    && afterDeferred < initialDeferred;

                result = new GridRealizationSmokeResult(
                    ok,
                    ok ? "grid starts with a bounded realized batch and appends the next batch on demand" : "grid realization batch did not advance as expected",
                    folder,
                    query,
                    total,
                    initial,
                    initialDeferred,
                    moved,
                    afterBatch,
                    afterDeferred);
            }
            catch (Exception ex)
            {
                result = new GridRealizationSmokeResult(false, ex.Message, folder, query, 0, 0, 0, false, 0, 0);
            }

            win.Close();
            WriteGridRealizationSmokeResult(resultPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureModalNavigationSmoke(string resultPath, string[] args)
    {
        string? folder = ArgValue(args, "--folder");
        string? statePath = ArgValue(args, "--state-path");
        string selectName = ArgValue(args, "--select-name") ?? "";
        string query = ArgValue(args, "--query") ?? "";
        int selectIndex = ArgInt(args, "--select-index", 1);
        if (string.IsNullOrWhiteSpace(folder) || string.IsNullOrWhiteSpace(statePath))
        {
            WriteModalNavigationSmokeResult(
                resultPath,
                new ModalNavigationSmokeResult(false, "missing required --folder or --state-path", statePath, folder, query, selectName, selectIndex, false, null, null, false, null, null, false, null, null, false, null, null));
            Shutdown(1);
            return;
        }

        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        win.Show();

        win.Dispatcher.InvokeAsync(async () =>
        {
            ModalNavigationSmokeResult result;
            try
            {
                await win.LoadFolderAsync(folder);
                if (!string.IsNullOrWhiteSpace(query))
                    win.SetSearchQuery(query);

                bool selected = !string.IsNullOrWhiteSpace(selectName)
                    ? win.SelectFileNameForSmoke(selectName)
                    : win.SelectIndexForSmoke(selectIndex);
                win.ShowModalForShot();
                string? startName = win.SelectedFileNameForSmoke;
                string? startPath = win.SelectedPathForSmoke;
                bool movedNext = win.NavigateModalForSmoke(1);
                string? nextName = win.SelectedFileNameForSmoke;
                string? nextPath = win.SelectedPathForSmoke;
                bool movedPrevious = win.NavigateModalForSmoke(-1);
                string? previousName = win.SelectedFileNameForSmoke;
                string? previousPath = win.SelectedPathForSmoke;
                var persisted = ReadPersistedState(statePath);
                string? persistedName = persisted?.SelectedPath is null ? null : Path.GetFileName(persisted.SelectedPath);

                int filteredCount = win.FilteredCountForSmoke;
                bool selectedLast = filteredCount > 1 && win.SelectIndexForSmoke(filteredCount - 1);
                string? lastName = win.SelectedFileNameForSmoke;
                bool wrappedLastToFirst = selectedLast && win.NavigateModalForSmoke(1);
                string? wrappedFirstName = win.SelectedFileNameForSmoke;
                bool wrappedFirstToLast = wrappedLastToFirst && win.NavigateModalForSmoke(-1);
                string? wrappedLastName = win.SelectedFileNameForSmoke;

                bool ok = selected
                    && win.ModalVisibleForSmoke
                    && movedNext
                    && movedPrevious
                    && !string.IsNullOrWhiteSpace(startPath)
                    && !string.Equals(startPath, nextPath, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(startPath, previousPath, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(previousPath, persisted?.SelectedPath, StringComparison.OrdinalIgnoreCase)
                    && selectedLast
                    && wrappedLastToFirst
                    && wrappedFirstToLast
                    && !string.Equals(lastName, wrappedFirstName, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(lastName, wrappedLastName, StringComparison.OrdinalIgnoreCase);

                result = new ModalNavigationSmokeResult(
                    ok,
                    ok ? "modal navigation moved next/previous, wrapped both ends, and persisted selected path" : "modal navigation did not keep selection/state or wrap behavior in sync",
                    statePath,
                    folder,
                    query,
                    selectName,
                    selectIndex,
                    selected,
                    startName,
                    startPath,
                    movedNext,
                    nextName,
                    nextPath,
                    movedPrevious,
                    previousName,
                    previousPath,
                    win.ModalVisibleForSmoke,
                    persistedName,
                    persisted?.SelectedPath,
                    filteredCount,
                    lastName,
                    wrappedLastToFirst,
                    wrappedFirstName,
                    wrappedFirstToLast,
                    wrappedLastName);
            }
            catch (Exception ex)
            {
                result = new ModalNavigationSmokeResult(false, ex.Message, statePath, folder, query, selectName, selectIndex, false, null, null, false, null, null, false, null, null, false, null, null);
            }

            win.Close();
            WriteModalNavigationSmokeResult(resultPath, result);
            Shutdown(result.Ok ? 0 : 1);
        }, DispatcherPriority.ContextIdle);
    }

    private void CaptureModalInteractionSmoke(string resultPath)
    {
        string resultFullPath = Path.GetFullPath(resultPath);
        string smokeRoot = CreateManagedAutomationRoot();
        string folder = Path.Combine(smokeRoot, "images");
        string statePath = Path.Combine(smokeRoot, "state.json");
        string seenPath = Path.Combine(smokeRoot, "seen.json");
        string favoritesPath = Path.Combine(smokeRoot, "favorites.json");
        string jobsPath = Path.Combine(smokeRoot, "jobs.json");
        string? previousStatePath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH");
        string? previousSeenPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH");
        string? previousFavoritesPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH");
        string? previousJobsPath = Environment.GetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH");
        Directory.CreateDirectory(folder);
        const string firstName = "a-modal.png";
        const string secondName = "b-modal.png";
        const string thirdName = "c-modal.png";
        string firstPath = Path.Combine(folder, firstName);
        string secondPath = Path.Combine(folder, secondName);
        string thirdPath = Path.Combine(folder, thirdName);
        WriteSmokePng(firstPath, 48, 36, Color.FromRgb(80, 130, 210));
        WriteSmokePng(secondPath, 48, 36, Color.FromRgb(230, 100, 130));
        WriteSmokePng(thirdPath, 48, 36, Color.FromRgb(100, 200, 130));
        string enhancedOutputPath = Path.Combine(Path.GetDirectoryName(jobsPath)!, "outputs", "enhanced-a-modal.png");
        Directory.CreateDirectory(Path.GetDirectoryName(enhancedOutputPath)!);
        File.Copy(firstPath, enhancedOutputPath, overwrite: true);
        WriteEnhancedJobsFixture(
            jobsPath,
            firstPath,
            enhancedOutputPath,
            secondPath,
            Path.Combine(smokeRoot, "missing-enhanced.png"),
            thirdPath,
            Path.Combine(smokeRoot, "missing-source.png"));
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_STATE_PATH", statePath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_SEEN_PATH", seenPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_FAVORITES_PATH", favoritesPath);
        Environment.SetEnvironmentVariable("PHOTOVIEWER_WPF_ENHANCEMENT_JOBS_PATH", jobsPath);
        ShutdownMode = ShutdownMode.OnExplicitShutdown;

        var win = HiddenWindow();
        win.Show();
        win.Dispatcher.InvokeAsync(async () =>
        {
            ModalInteractionSmokeResult result;
            MainWindow? largeCatalogProbe = null;
            try
            {
                // This verifier owns the full-motion modal contract. Reduced-
                // motion behavior is exercised by the accessibility verifier.
                bool fullMotionMode = win.SetAccessibilityPreferencesForSmoke(
                        reducedMotion: false,
                        reducedTransparency: false,
                        persist: false)
                    && !win.ReducedMotionEffectiveForSmoke;
                await win.LoadFolderAsync(folder).WaitAsync(TimeSpan.FromSeconds(15));
                win.SetSortByForSmoke("name");
                bool selected = win.SelectFileNameForSmoke(secondName);
                bool opened = win.OpenModalForSmoke();
                bool positionCounter = win.ModalPositionCounterContractForSmoke;
                bool favoriteNeutralSurfaceInitial = win.ModalFavoriteNeutralSurfaceForSmoke;
                bool overlayDoesNotReduceImageArea = win.ModalOverlayDoesNotReduceImageAreaForSmoke();
                Rect windowedBoundsBeforeFullScreen = win.WindowBoundsForSmoke;
                bool fullScreenEnteredByF11 = win.InvokePreviewKeyForSmoke(Key.F11);
                bool fullScreenEnteredSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: true);
                bool fullScreenContract = fullScreenEnteredByF11
                    && fullScreenEnteredSettled
                    && win.ModalFullScreenContractForSmoke
                    && win.ModalVisibleForSmoke;
                bool fullScreenExitAction = win.InvokePreviewKeyForSmoke(Key.Escape);
                bool fullScreenExitSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: false);
                bool fullScreenExitedByEscape = fullScreenExitAction
                    && fullScreenExitSettled
                    && !win.ModalFullScreenForSmoke
                    && win.ModalVisibleForSmoke;
                Rect windowedBoundsAfterFullScreen = win.WindowBoundsForSmoke;
                bool fullScreenRestoredWindow = fullScreenExitedByEscape
                    && Math.Abs(windowedBoundsAfterFullScreen.Left - windowedBoundsBeforeFullScreen.Left) < 1
                    && Math.Abs(windowedBoundsAfterFullScreen.Top - windowedBoundsBeforeFullScreen.Top) < 1
                    && Math.Abs(windowedBoundsAfterFullScreen.Width - windowedBoundsBeforeFullScreen.Width) < 1
                    && Math.Abs(windowedBoundsAfterFullScreen.Height - windowedBoundsBeforeFullScreen.Height) < 1;
                bool fullScreenButtonEnterAction = win.ToggleModalFullScreenForSmoke();
                bool fullScreenButtonEnterSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: true);
                bool fullScreenButtonExitAction = win.InvokePreviewKeyForSmoke(Key.F11);
                bool fullScreenButtonExitSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: false);
                bool fullScreenButtonRoute = fullScreenButtonEnterAction
                    && fullScreenButtonEnterSettled
                    && fullScreenButtonExitAction
                    && fullScreenButtonExitSettled
                    && !win.ModalFullScreenForSmoke
                    && win.ModalVisibleForSmoke;
                bool fullScreenSwipeEnterAction = win.ModalSwipeForSmoke(0, -200);
                bool fullScreenSwipeEnterSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: true);
                bool fullScreenSwipeExitAction = win.InvokePreviewKeyForSmoke(Key.Escape);
                bool fullScreenSwipeExitSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: false);
                bool fullScreenSwipeUpRoute = fullScreenSwipeEnterAction
                    && fullScreenSwipeEnterSettled
                    && fullScreenSwipeExitAction
                    && fullScreenSwipeExitSettled
                    && !win.ModalFullScreenForSmoke
                    && win.ModalVisibleForSmoke;
                bool fullScreenBeforeCloseEnterAction = win.ToggleModalFullScreenForSmoke();
                bool fullScreenBeforeCloseEnterSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: true);
                bool fullScreenEnteredBeforeModalClose = fullScreenBeforeCloseEnterAction
                    && fullScreenBeforeCloseEnterSettled
                    && win.ModalFullScreenContractForSmoke;
                win.CloseModalForSmoke();
                bool fullScreenRetainedWhileModalHidden =
                    fullScreenEnteredBeforeModalClose
                    && win.ModalFullScreenForSmoke
                    && !win.ModalVisibleForSmoke;
                bool fullScreenHiddenExitAction = win.InvokePreviewKeyForSmoke(Key.F11);
                bool fullScreenHiddenExitSettled =
                    await win.WaitForModalFullScreenTransitionForSmokeAsync(enabled: false);
                bool reopenedAfterFullScreenExit = win.OpenModalForSmoke();
                bool fullScreenPreservedAfterModalClose =
                    fullScreenRetainedWhileModalHidden
                    && fullScreenHiddenExitAction
                    && fullScreenHiddenExitSettled
                    && !win.ModalFullScreenForSmoke
