                        options = new
                        {
                            prompt,
                            negativePrompt = "synthetic negative",
                            steps = 6,
                            cfgScale = 1.4,
                        },
                    },
                });
                totalFullPayloadBytes += Encoding.UTF8.GetByteCount(fullJson);
                position.Value = index;
                id.Value = jobId;
                status.Value = projection.status;
                readerPayload.Value = readerJson;
                payload.Value = fullJson;
                insert.ExecuteNonQuery();
            }
            transaction.Commit();
        }

        using var checkpoint = connection.CreateCommand();
        checkpoint.CommandText = "PRAGMA wal_checkpoint(TRUNCATE);";
        checkpoint.ExecuteNonQuery();
        return totalFullPayloadBytes;
    }

    private static bool VerifyMalformedEnhancementSqliteFixtures(
        string smokeRoot,
        out int caseCount)
    {
        string malformedRoot = Path.Combine(
            smokeRoot,
            ".cache",
            "enhance",
            "malformed-reader-cases");
        Directory.CreateDirectory(malformedRoot);
        string[] cases =
        [
            "non-object-payload",
            "id-mismatch",
            "status-mismatch",
            "duplicate-id",
            "duplicate-position",
            "negative-position",
            "duplicate-metadata",
            "oversized-payload",
            "terminal-minimal-projection",
        ];
        caseCount = cases.Length;
        foreach (string caseName in cases)
        {
            string path = Path.Combine(malformedRoot, caseName + ".sqlite3");
            WriteMalformedEnhancementSqliteFixture(path, caseName);
            byte[] before = File.ReadAllBytes(path);
            bool catalogRejected = false;
            try
            {
                global::PhotoViewer.Wpf.MainWindow
                    .ValidateEnhancementSqliteStoreForSmoke(path);
            }
            catch (Exception ex) when (ex is InvalidDataException or SqliteException)
            {
                catalogRejected = true;
            }
            bool workspaceRejected = false;
            try
            {
                global::PhotoViewer.Wpf.MainWindow
                    .ValidateEnhancementJobsWorkspaceSqliteForSmoke(path);
            }
            catch (Exception ex) when (ex is InvalidDataException or SqliteException)
            {
                workspaceRejected = true;
            }
            byte[] after = File.ReadAllBytes(path);
            bool catalogShouldReject = caseName != "terminal-minimal-projection";
            if (catalogRejected != catalogShouldReject
                || !workspaceRejected
                || !before.AsSpan().SequenceEqual(after))
                return false;
        }
        return true;
    }

    private static void WriteMalformedEnhancementSqliteFixture(
        string databasePath,
        string caseName)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(databasePath)!);
        using var connection = new SqliteConnection(
            new SqliteConnectionStringBuilder
            {
                DataSource = databasePath,
                Mode = SqliteOpenMode.ReadWriteCreate,
                Pooling = false,
            }.ToString());
        connection.Open();
        using (var schema = connection.CreateCommand())
        {
            // Constraints are intentionally absent: these fixtures prove the
            // reader rejects semantically malformed stores instead of relying
            // on a cooperative writer schema.
            schema.CommandText = """
                CREATE TABLE enhancement_store_metadata (
                    singleton INTEGER,
                    store_version INTEGER,
                    catalog_revision INTEGER
                );
                CREATE TABLE enhancement_jobs (
                    position INTEGER,
                    id TEXT,
                    status TEXT,
                    reader_payload_json TEXT,
                    payload_json TEXT
                );
                """;
            schema.ExecuteNonQuery();
        }

        int metadataRows = caseName == "duplicate-metadata" ? 2 : 1;
        using (var metadata = connection.CreateCommand())
        {
            metadata.CommandText = """
                INSERT INTO enhancement_store_metadata
                    (singleton, store_version, catalog_revision)
                VALUES (1, 1, 1)
                """;
            for (int index = 0; index < metadataRows; index++)
                metadata.ExecuteNonQuery();
        }

        static string ValidWorkspacePayload(
            string id,
            string status,
            string? padding = null)
        {
            var payload = new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["id"] = id,
                ["sourceId"] = "X:\\synthetic\\source.png",
                ["sourcePath"] = "X:\\synthetic\\source.png",
                ["presetId"] = "photo-detail-x4",
                ["adapterId"] = "realesrgan-ncnn",
                ["status"] = status,
                ["createdAt"] = "2026-08-22T00:00:00.000Z",
                ["updatedAt"] = "2026-08-22T00:00:01.000Z",
            };
            if (padding is not null)
                payload["padding"] = padding;
            return JsonSerializer.Serialize(payload);
        }

        var rows = new List<(long Position, string Id, string? Status, string Payload)>
        {
            (0, "job-A", "succeeded", ValidWorkspacePayload("job-A", "succeeded")),
        };
        switch (caseName)
        {
            case "non-object-payload":
                rows[0] = (0, "job-A", "succeeded", "[]");
                break;
            case "id-mismatch":
                rows[0] = (
                    0,
                    "job-A",
                    "succeeded",
                    ValidWorkspacePayload("job-B", "succeeded"));
                break;
            case "status-mismatch":
                rows[0] = (
                    0,
                    "job-A",
                    "succeeded",
                    ValidWorkspacePayload("job-A", "running"));
                break;
            case "duplicate-id":
                rows.Add((
                    1,
                    "job-A",
                    "succeeded",
                    ValidWorkspacePayload("job-A", "succeeded")));
                break;
            case "duplicate-position":
                rows.Add((
                    0,
                    "job-B",
                    "succeeded",
                    ValidWorkspacePayload("job-B", "succeeded")));
                break;
            case "negative-position":
                rows[0] = (-1, "job-A", "succeeded", "{\"id\":\"job-A\",\"status\":\"succeeded\"}");
                break;
            case "duplicate-metadata":
                break;
            case "oversized-payload":
                rows[0] = (
                    0,
                    "job-A",
                    "succeeded",
                    ValidWorkspacePayload(
                        "job-A",
                        "succeeded",
                        new string('x', 1_200_000)));
                break;
            case "terminal-minimal-projection":
                rows[0] = (
                    0,
                    "job-A",
                    "failed",
                    "{\"id\":\"job-A\",\"status\":\"failed\"}");
                break;
            default:
                throw new InvalidOperationException(
                    $"Unknown malformed SQLite fixture case: {caseName}");
        }

        using var insert = connection.CreateCommand();
        insert.CommandText = """
            INSERT INTO enhancement_jobs
                (position, id, status, reader_payload_json, payload_json)
            VALUES ($position, $id, $status, $payload, $payload)
            """;
        SqliteParameter position = insert.Parameters.Add("$position", SqliteType.Integer);
        SqliteParameter id = insert.Parameters.Add("$id", SqliteType.Text);
        SqliteParameter status = insert.Parameters.Add("$status", SqliteType.Text);
        SqliteParameter payload = insert.Parameters.Add("$payload", SqliteType.Text);
        foreach ((long rowPosition, string rowId, string? rowStatus, string rowPayload) in rows)
        {
            position.Value = rowPosition;
            id.Value = rowId;
            status.Value = rowStatus is null ? DBNull.Value : rowStatus;
            payload.Value = rowPayload;
            insert.ExecuteNonQuery();
        }
    }

    private static void WriteEnhancementOperationJobsFixture(
        string jobsPath,
        string upscaleSourcePath,
        string upscaleOutputPath,
        string photorealSourcePath,
        string photorealOutputPath,
        string videoSourcePath,
        string videoOutputPath,
        string olderVideoOutputPath,
        string invalidSourcePath,
        string missingOutputPath,
        string missingSourcePath)
    {
        // This private smoke helper has one call site. jobsPath is constructed
        // below CreateManagedAutomationRoot and is never accepted from the
        // image-folder argument.
        // codeql[cs/path-injection]
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(jobsPath))!);
        static Dictionary<string, object> SourceSignature(string sourcePath)
        {
            // Source paths are derived from fixture names enumerated by the
            // smoke harness. This branch only reads metadata and never writes
            // through sourcePath.
            // codeql[cs/path-injection]
            if (!File.Exists(sourcePath))
                return new Dictionary<string, object> { ["size"] = 0L, ["mtimeMs"] = 0d };

            // See the read-only smoke-fixture invariant above.
            // codeql[cs/path-injection]
            var info = new FileInfo(sourcePath);
            return new Dictionary<string, object>
            {
                ["size"] = info.Length,
                ["mtimeMs"] = new DateTimeOffset(info.LastWriteTimeUtc).ToUnixTimeMilliseconds(),
            };
        }

        Dictionary<string, object?> Succeeded(
            string id,
            string sourcePath,
            string outputPath,
            string? operation = null)
        {
            var job = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase)
            {
                ["id"] = id,
                ["sourceId"] = sourcePath,
                ["sourcePath"] = sourcePath,
                ["sourceSignature"] = SourceSignature(sourcePath),
                ["status"] = "succeeded",
                ["progress"] = 100,
                ["outputPath"] = outputPath,
                ["createdAt"] = DateTime.UtcNow.ToString("o"),
                ["updatedAt"] = DateTime.UtcNow.ToString("o"),
            };
            if (!string.IsNullOrWhiteSpace(operation))
                job["operation"] = operation;
            return job;
        }

